WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[8885] = { title = "The Ring of Mmmrrrggglll", description = "The Grimscale murlocs have not been scared off by your efforts. But, I think I know what will send them packing, as well as get me some personal retribution.\n\nThey have a murloc chieftain that calls itself Mmmrrrggglll. It wanders the Golden Strand south of the river inlet. The beast once slew a compatriot of mine, and now wears his ring in open defiance and mockery.\n\nSlay Mmmrrrggglll, and bring back my friend's ring. Then we shall see these monsters cowed!", objectives = "Retrieve the Ring of Mmmrrrggglll from the Grimscale chieftain's dead clutches. Return it to Hathvelion Sungaze in the Eversong Woods on the bluff overlooking the Tranquil Shore.", progress = "You are the instrument of my success and revenge, <class>. Have you the ring?", completion = "At last! Though the Grimscale did not route, as hoped, it was entertaining to watch them panic in confusion when you laid low their so-called chieftain. You have my thanks, and the gratitude of the sin'dorei of Silvermoon City!\n\nPlease, take one of these in thanks for the service that you have rendered." }
WordHunterWoW_QuestEN[8886] = { title = "Grimscale Pirates!", description = "Thank goodness for you, {class}! Those slimy Grimscale murlocs have pirated away my cargo! It's bad enough that the Wretched have stolen what little magical goods I had, but the murlocs took the rest! What has this land come to?\n\nCould you retrieve my cargo? I can't expect that you'd be able to get all of it back, but I'll be grateful for any of it at this point. It was the Grimscale murlocs in the huts, just to the west and south of the anchorage on the Golden Strand, I'm sure of it!\n", objectives = "Retrieve 6 of Captain Kelisendra's Cargo and return them to Captain Kelisendra at the defended camp just to the east of the Sunsail Anchorage in Eversong Woods.", progress = "I am grateful for the assistance of someone like you, <name>. It almost puts a smile on my face. But then I realize what these monsters have done to my ship and what's happening to Quel'Thalas.\n\nHave you managed to retrieve any of my cargo?", completion = "You did it! You've saved me from ruin and delivered my revenge upon those disgusting creatures!\n\nNow if I can just get these pretty rangers here to help me with this cargo, I'll finally get out of here! I'll have to come back when Velendris has retaken the shipyard.\n\nHere, take this coin. It's what little I can afford, and the least that I can do to reward your efforts." }
WordHunterWoW_QuestEN[8887] = { title = "Captain Kelisendra's Lost Rutters", description = "Interesting... what you have found here is a water-proofed, leather tube containing a number of sheets of parchment. By the markings upon them, the pages are clearly navigation rutters, and each bears the signature of one Captain Kelisendra.\n\nYou've heard of a small, defended camp just east of the nearby Sunsail Anchorage. Maybe the captain is there?", objectives = "Return Captain Kelisendra's Lost Rutters to Captain Kelisendra at the defended camp just to the east of the Sunsail Anchorage in Eversong Woods.", progress = "Hello, <class>, you're a sight for sore eyes. I know, it's crazy for me to be here, what with the anchorage overrun by the Wretched. Velendris and his rangers have sworn to protect me on the condition that I get out of here as soon as I've recovered my cargo.\n\nWhat's that you have there... it looks vaguely familiar?", completion = "Oh you sweet, sweet <class>! I had no idea that those disgusting Grimscale murlocs had also pirated away with my navigation rutters! Without them, I would have no chance of navigating the seas again once we retake the anchorage and repair the ship.\n\nThank you very much! Here, take this coin as a sign of my appreciation." }
WordHunterWoW_QuestEN[8888] = { title = "The Magister's Apprentice", description = "{class}, hear my request. For reasons that I cannot go into now, I decided to shut down my nearby school. A few days ago, I sent one of my pupils, Apprentice Loralthalis, there with this very task. I have not heard back from her since.\n\nWill you go to Duskwither Spire and check in on her, to make sure that she is well? You'll find it by heading north on the path out of Farstrider Retreat, then go to the right when the road branches.", objectives = "Speak with Apprentice Loralthalis near Duskwither Spire in Eversong Woods.", completion = "The magister was concerned for my wellbeing? How sweet; I wish that he had shown such an interest before, when we were at the Spire.\n\nThat doesn't matter now. Please listen carefully, <class>, as I have a favor to ask of you." }
WordHunterWoW_QuestEN[8889] = { title = "Deactivating the Spire", description = "As you may know, Magister Duskwither sent me back here to shut down the power sources that feed the Spire. There are three of them, each located in a different place inside.\n\nUnfortunately, I appear to be too late, and Duskwither Spire has been overrun with strange, magical creatures. While I haven't the expertise to accomplish this task, surely a {class}, such as yourself, could do so easily?", objectives = "Deactivate the 3 Duskwither Spire Power Sources inside Duskwither Spire. Then return the Deactivating Jewel to Apprentice Loralthalis in Eversong Woods.", progress = "I can't be certain from this distance... have you already shut down the power to Duskwither Spire?", completion = "I am grateful to you for your assistance, but saddened to hear that some of my fellow apprentices have fallen to their addiction.\n\nWith the power to the Spire cut off, I think I'll stay here a while and see if things calm down long enough for me to sneak in and retrieve their remains." }
WordHunterWoW_QuestEN[8890] = { title = "Word from the Spire", description = "{name}, I have one last favor to ask of you. Would you please relay what's transpired here to Magister Duskwither, back at the Farstrider Retreat? Let him know that I am well, but make certain that he is aware that some of the apprentices have become Wretched.\n\nThank you for your help!", objectives = "Return to Magister Duskwither at the Farstrider Retreat in Eversong Woods.", completion = "No! I was too late. It is all my fault.\n\nMy investigation into purifying alternative magical sources got out of hand before I could put a stop to it. If only I had gone myself... or that they had listened to me, and heeded my warnings!\n\nI have blood on my hands, <class>. I thank you, though, for putting to rest the tortured souls of my former apprentices. It is some small consolation that they will not linger in that state where a <race> is better off dead." }
WordHunterWoW_QuestEN[8891] = { title = "Abandoned Investigations", description = "You have discovered what appears to be an investigative journal left behind by Magister Duskwither. A brief scan of its contents reveal some shocking attempts at filtering corrupted magical flows, which might explain what has happened here at Duskwither Spire. The magister is sure to want this brought back to him.", objectives = "Return Magister Duskwither's Journal to Magister Duskwither at the Farstrider Retreat in Eversong Woods.", progress = "What's this? It looks familiar. Oh no, this journal... my investigations... this is what caused all of this in the first place.", completion = "Here it is, <name>, the proof of my crime. This journal contains all of my ill-conceived studies.\n\nHeedless of the warnings, I continued my research until it was almost too late. Then, when I grasped my error, I did what I could. But by then, some of my pupils had already gone too far. I evacuated the Spire to get them away from the corruption, but in my haste, forgot to shut down the power sources.\n\nI will burn this tome so that no one else falls prey to its contents. I only wanted to help the sin'dorei." }
WordHunterWoW_QuestEN[8892] = { title = "Situation at Sunsail Anchorage", description = "Sunsail Anchorage has been overrun by Wretched scum.  As soon as we manage to get reinforcements to the area we'll show those thugs who's boss, {name}.\n\nIn the meantime you can help by showing them a bit of discipline.  Go in there and show them we are not to be trifled with.  You will find Sunsail Anchorage just to the west of Fairbreeze Village.", objectives = "Kill 5 Wretched Thugs and 5 Wretched Hooligans and report to Ranger Degolien in Eversong Woods.", completion = "That'll teach them not to mess with us.  Good work, <name>." }
WordHunterWoW_QuestEN[8893] = { title = "The Super Egg-O-Matic", description = "", objectives = "" }
WordHunterWoW_QuestEN[8894] = { title = "Cleaning up the Grounds", description = "It's horrible, I tell you! Strange things happening in the spire, the magister and his apprentices run off, and then the next thing that you know, the whole grounds are overrun with these magical beasties! And who told Wyllithen? No one, that's who!\n\n{class}, you've got to help me clear some of these things out... I cannot maintain the grounds while these 'anomalies' are running amok!", objectives = "Kill 6 Mana Serpents and 6 Ether Fiends and return to Groundskeeper Wyllithen at Duskwither Grounds in Eversong Woods.", progress = "Have you taken care of it then? Did you deal with a good number of those magical anomalies? What would I do if Magister Duskwither were to reappear with all of these things lurking about?", completion = "Well, I suppose that will have to do, now won't it? Thanks for the help, <class>. I can only hope to get this mess completely cleaned up before the Magister returns to Duskwither Spire.\n\nTake this pocket change; it's not much but it's all that I have at the moment. Feel free to dispatch a few more of the beasties on your way out, if you'd be so kind." }
WordHunterWoW_QuestEN[8895] = { title = "Delivery to the North Sanctum", description = "I'm pleased to discover that you're at least somewhat competent, {name}.  I'll give you another task since you seem so eager to prove yourself.\n\nThis is a letter to Ley-Keeper Caidanis, the arcanist in charge of the upkeep of the North Sanctum.  Go southwest of Falconwing Square  and you will find him.  He is a very important person, so I hope you don't bother him too much with trivial chatter.", objectives = "Deliver the Unmarked Letter to Ley-Keeper Caidanis at the North Sanctum in Eversong Woods.", progress = "Yes, <class>?", completion = "Thank you, <name>.  I've been expecting this letter." }
WordHunterWoW_QuestEN[8896] = { title = "The Dwarven Spy", description = "Are you sure you found these notes on a Night Elf, then?  Most of them are written in the Dwarven...\n\nProspector Anvilward!  He was sent here from Ironforge on a diplomatic mission.  I should've known his interest in our Arcane Sanctums was a bit excessive.  <name>, find the dwarf in the North Sanctum and take care of him.  Oh, and be discrete about it.", objectives = "Find and kill Prospector Anvilward in the North Sanctum and report back to Aeldon Sunbrand in Eversong Woods.Are you sure you found these notes on a Night Elf, then?  Most of them are written in the Dwarven...\n\nProspector Anvilward!  He was sent here from Ironforge on a diplomatic mission. I should've known his interest in our Arcane Sanctums was a bit excessive. <name>, find the dwarf in the North Sanctum and take care of him. Oh, and be discrete about it." }
WordHunterWoW_QuestEN[8897] = { title = "Dearest Colara,", description = "I've got to keep watch here at the gate, but I'm always worrying about my sweetheart, Colara. I only get to see her for a few hours, if I'm lucky, and well, just look at me. I've got a minor officer's pay and I could be called to the front any day now.\n\nWould she just forget about me? There are a lot of men in the city. A lot of rich ones.\n\nAnyways, I've scribbled some things down... nothing much, but if you could take it to her for me, that'd be great.", objectives = "Deliver Lieutenant Heldric's Carefully Penned Note to Colara Dean outside the bank in Stormwind." }
WordHunterWoW_QuestEN[8898] = { title = "Dearest Colara,", description = "I met a lass in Stormwind when I was last there on the bank's business. She stole my heart away. Now, I can't stop thinking about her! I'd like to send her this message - I've rewritten it twelve times!\n\nThe mail is so full now, and I want to make sure it gets there.\n\nIf you're heading that way, could you help me?", objectives = "Deliver the Creased Letter to Colara Dean outside the bank in Stormwind." }
WordHunterWoW_QuestEN[8899] = { title = "Dearest Colara,", description = "How to describe her beauty? Thousands of years of words and I am at a loss.\n\nThese mortals confound the mind and leave us babbling fools.\n\nI've stared at these words too long. No more eloquent meaning can I squeeze from them. No, she must have it now, or some other suitor will surely steal her eye.", objectives = "Deliver the Immaculate Letter to Colara Dean outside the bank in Stormwind." }
WordHunterWoW_QuestEN[8900] = { title = "Dearest Elenia,", description = "She was so sad. I could see that, once I saw past her state. I mean, she seemed sad - wouldn't you?\n\nBut after talking to her, there was a connection. I didn't think anyone could understand what I was thinking, but she could.\n\nWhen I told the others, they laughed at me, so I never spoke with her again. But I miss her. Can you take this letter to her for me? I want to be sure it finds her hands.", objectives = "Deliver the Slightly Creased Note to Elenia Haydon near the bank in the Undercity." }
WordHunterWoW_QuestEN[8901] = { title = "Dearest Elenia,", description = "Have you ever known love, young one? It was a thing foreign to me until lately, when I met a girl from the Undercity, Elenia. It is rare enough for one of my kind to look outside our own, let alone one of the Forsaken.\n\nBut now thoughts of her occupy my mind both days and nights.\n\nIf you can, could you take this letter to her? I want her to come here to Mulgore. I hope that she will say yes.", objectives = "Deliver the Carefully Written Letter to Elenia Haydon near the bank in the Undercity." }
WordHunterWoW_QuestEN[8902] = { title = "Dearest Elenia,", description = "A lifetime ago, I was betrothed to marry Elenia, my childhood sweetheart. It's been years since I thought about her last, but of late, she frequently occupies my thoughts.\n\nPerhaps, even with everything that has passed, there can be some room in each other's lives for our love.\n\nI'm sure she has changed, also. Can you deliver this letter to her for me? I am too nervous to give it in person.", objectives = "Deliver the Lovingly Composed Letter to Elenia Haydon near the bank in the Undercity." }
WordHunterWoW_QuestEN[8903] = { title = "Dangerous Love", description = "There's something unnatural about this epidemic of love. It's not proper, it's an eyesore, and at worst, it could be a threat to the safety of the Alliance itself.\n\nJust think: what if the guards have been taken in by this strange affliction? Something must be done.\n\nGo to one of the guards here in Stormwind and see if they've been caught up in this foolishness.", objectives = "Get a Stormwind Guard's Card and return it to Aristan Mottar in Stormwind." }
WordHunterWoW_QuestEN[8904] = { title = "Dangerous Love", description = "There's something unnatural about this epidemic of love. It's disgusting, and as it lowers our defenses, it could be a threat to the all of us.\n\nIt's bad enough that so many of our people are caught up in this ridiculous behavior. But I think that it has spread even to our guardians, who should be immune to such things.\n\nFind one of our guardians and see if they've been caught up in this foolishness.", objectives = "Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity." }
WordHunterWoW_QuestEN[8905] = { title = "An Earnest Proposition", description = "Well met, <class>.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.You will receive:", objectives = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Wildheart Bracers to Deliana in Ironforge." }
WordHunterWoW_QuestEN[8906] = { title = "An Earnest Proposition", description = "Well met, <class>.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.You will receive:", objectives = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Beaststalker's Bindings to Deliana in Ironforge." }
WordHunterWoW_QuestEN[8907] = { title = "An Earnest Proposition", description = "Well met, <class>.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", objectives = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Magister's Bindings to Deliana in Ironforge.", progress = "Have you brought me what I requested of you, <name>?", completion = "Excellent!  Let's perform the trade then.  It's hard to part with this excellent armor, but I'm afraid I won't be needing it any time soon.\n\nIf you're interested in performing more work for me, I might be willing to give up the rest of the pieces." }
WordHunterWoW_QuestEN[8908] = { title = "An Earnest Proposition", description = "Well met, <class>.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.You will receive:", objectives = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Lightforge Bracers to Deliana in Ironforge." }
