WordHunterWoW_QuestEN[9023] = { title = "The Perfect Poison", description = "My brother and I run the poison operations out of the manor Ravenholdt.\n\nLord Ravenholdt tasked me to track down a new and extremely effective poison compound that can be crafted from the venom sacs of the inhabitants of Zul'Gurub and the Ruins of Ahn'Qiraj.\n\nThere are two particularly venomous beasts residing in those blasted ruins that possess what it is that we might be looking for, <class>. Bring me a venom sac from the beasts Kurinnaxx and Venoxis and we would be eternally grateful.", objectives = "Dirk Thunderwood at Cenarion Hold wants you to bring him Venoxis's Venom Sac and Kurinnaxx's Venom Sac.", progress = "This ain't no smash and grab job, <name>. You're gonna need to bring friends.", completion = "Ravenholdt thanks you, hero! Take your pick!" }
WordHunterWoW_QuestEN[9024] = { title = "Aristan's Hunch", description = "I've got it! Have you smelled the new fragrance on the wind? The new colognes and perfumes that have come into fashion? Our guards wouldn't neglect their duties so easily.\n\nThat is, unless their thinking has been clouded by some foul alchemy.\n\nThere is only one way to be sure - bring a bottle of cologne and perfume to Morgan Pestle, and tell him my suspicions. I will reimburse you for their purchase when you return.", objectives = "Bring 1 Cologne Bottle and 1 Perfume Bottle to Morgan Pestle in the Trade District of Stormwind." }
WordHunterWoW_QuestEN[9025] = { title = "Morgan's Discovery", description = "Well, I'll be. It looks like Aristan might be on to something after all. I found traces of substances used in love potions and insidious mind-altering draughts.\n\nIt isn't unheard of for perfumes to have some of them, but a few of the ingredients I detected... Smells funny.", objectives = "Return to Aristan Mottar outside the bank in Stormwind's Trade District.Well, I'll be. It looks like Aristan might be on to something after all. I found traces of substances used in love potions and insidious mind-altering draughts.\n\nIt isn't unheard of for perfumes to have some of them, but a few of the ingredients I detected... Smells funny.You will receive:" }
WordHunterWoW_QuestEN[9026] = { title = "Tracing the Source", description = "We've got to find the source. I've seen a lot more people than usual - guards included - going in and out of The Gilded Rose. Talk to Allison. If she's selling them, she can tell you where they came from.", objectives = "Speak with Innkeeper Allison at The Gilded Rose in Stormwind's Trade District.We've got to find the source. I've seen a lot more people than usual - guards included - going in and out of The Gilded Rose. Talk to Allison. If she's selling them, she can tell you where they came from." }
WordHunterWoW_QuestEN[9027] = { title = "Tracing the Source", description = "Something funny about the cologne? It's possible. I've never seen so many people after one product like this.\n\nLook, if there's something wrong with it, I want to know, too. I bought my supply from a merchant named Evert Sorisam. He's new in town.\n\nHe mentioned he had some goods he was going to deliver to The Finest Thread.", objectives = "Speak with Evert Sorisam at The Finest Thread along Stormwind's Canals.Something funny about the cologne? It's possible. I've never seen so many people after one product like this.\n\nLook, if there's something wrong with it, I want to know, too. I bought my supply from a merchant named Evert Sorisam. He's new in town.\n\nHe mentioned he had some goods he was going to deliver to The Finest Thread." }
WordHunterWoW_QuestEN[9028] = { title = "The Source Revealed", description = "What? Treason? No, no. I assure you, my intentions are completely harmless.\n\nIs it so wrong to help those who wish to ease the painful ritual of courtship? Come, that is no crime.\n\nAnd to prove that I mean no harm, I will even tell you my source.\n\nThey were shipped to me by a Staffron Lerent, an apothecary of some sort. I never spoke with him.\n\nOur goblin middle man said that he worked in the foothills over Hillsbrad past that mysterious Ravenholdt Manor. I wish you luck in finding him.", objectives = "Find Apothecary Staffron Lerent in the Hillsbrad Foothills behind Ravenholdt Manor.What? Treason? No, no. I assure you, my intentions are completely harmless.\n\nIs it so wrong to help those who wish to ease the painful ritual of courtship? Come, that is no crime.\n\nAnd to prove that I mean no harm, I will even tell you my source.\n\nThey were shipped to me by a Staffron Lerent, an apothecary of some sort. I never spoke with him.\n\nOur goblin middle man said that he worked in the foothills over Hillsbrad past that mysterious Ravenholdt Manor. I wish you luck in finding him." }
WordHunterWoW_QuestEN[9029] = { title = "A Bubbling Cauldron", description = "", objectives = "You will be able to choose one of these rewards:" }
WordHunterWoW_QuestEN[9030] = { title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.\n\nI, for once, shall rest in peace.  I wish you the best of luck, and you shall need it!You will receive:", objectives = "Speak to Deliana in Ironforge.\n\nProvided item:" }
WordHunterWoW_QuestEN[9032] = { title = "Bodley's Unfortunate Fate", description = "The medallion contained Valthalak's soul?  It's no surprise it was guarded by such a powerful curse.\n\nLocating Bodley presents a bit of a problem.  Last time I heard of him, he was preparing to venture back into Blackrock Spire.  He was never heard of again.\n\nSeek him out in Blackrock Mountain, though I'm afraid to say he's probably dead by now.  I suggest taking the goblin's device with you, friend.Upon completion of this quest you will gain:", objectives = "Travel to Blackrock Mountain and use the Extra-Dimensional Ghost Revealer to find Bodley near Blackrock Spire." }
WordHunterWoW_QuestEN[9033] = { title = "Echoes of War", description = "Five years since the last war...\n\nTens of thousands of lives were lost and for what? The threat was never fully extinguished.\n\nAnd so the Lich King stirs once more... His yes-man, Kel'Thuzad, amassing for another attack upon our lands.\n\nWe will not allow it! Prove your dedication. Prove that you are willing to risk life and limb to stop this madness and the combined might of the Dawn and the Crusade will be at your beck and call.\n\nEnter Naxxramas and destroy the Scourge within...", objectives = "Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands wants you to slay 5 Living Monstrosities, 5 Stoneskin Gargoyles, 8 Deathknight Captains and 3 Venom Stalkers.", completion = "A job well done! You will be rewarded via the services of the men and women at Light's Hope." }
WordHunterWoW_QuestEN[9034] = { title = "Dreadnaught Breastplate", description = "During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes.You will receive:", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands will make a Dreadnaught Breastplate if you bring him the following items: 1 Desecrated Breastplate, 25 Wartorn Plate Scraps, 4 Arcanite Bars and 2 Nexus Crystals." }
WordHunterWoW_QuestEN[9035] = { title = "Roadside Ambush", description = "You, there!  You must help me, please!\n\nA fellow apprentice and I were attacked by the Wretched!  In their mad hunger for magic, they took everything they could get their hands on: mana crystals, wands, spellbooks... everything!\n\nMeledor gave chase after them; I had to stay behind and look after what they didn't take.  Continue down the road and see if you can lend him a hand.", objectives = "Speak to Apprentice Meledor in Eversong Woods along the road heading south from Silvermoon City.", completion = "They're gone now.  Scared the breeches out of them with a well-placed fireball!  Unfortunately for me, they threw our precious cargo into the river." }
WordHunterWoW_QuestEN[9036] = { title = "Dreadnaught Legplates", description = "During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes.You will receive:", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands will make Dreadnaught Legplates if you bring him the following items: 1 Desecrated Legplates, 20 Wartorn Plate Scraps, 4 Arcanite Bars and 3 Cured Rugged Hides." }
