WordHunterWoW_QuestEN[9062] = { title = "Soaked Pages", description = "Those blasted Wretched sure can run fast at the sight of someone who'll stand up to them.  But let's not worry about that now.  I need to find my instructor's elemental grimoire.\n\nI'm certain I saw one of those cowards throw it into the river but I cannot seem to be able to locate it.  I could use another set of eyes.  I'll throw in a bit of coin if you spot it.", objectives = "Apprentice Meledor in Eversong Woods wants you to search the water beneath the bridge nearby and bring him Antheol's Elemental Grimoire.", progress = "No luck?  Well, keep looking.  The book is of utmost importance, <class>.", completion = "The book is completely soaked.  Instructor Antheol's not going to like this at all.\n\nHere, take this money.  I have an idea." }
WordHunterWoW_QuestEN[9063] = { title = "Torwa Pathfinder", description = "A hunter by the name of Torwa Pathfinder has requested the help of a druid.  He said only we would possess the necessary skills and respect for nature to help him.\n\nThere is a road that connects the Un'Goro Crater and the desert of Tanaris.  As that road enters the crater, you will find Torwa close by.Upon completion of this quest you will gain:", objectives = "Speak with Torwa Pathfinder in Un'Goro Crater." }
WordHunterWoW_QuestEN[9064] = { title = "Taking the Fall", description = "Antheol is going to fly off his rocker when he finds out his book is ruined.  I've got a little proposal for you; don't worry, I'll make it worth your while.\n\nTake this book to him and tell him nothing of this incident.  If he asks, just tell him you dropped the book into a puddle.  He has no direct authority over you, so there's not much he can do.\n\nAntheol delivers his lectures at Stillwhisper Pond, southeast of Silvermoon.  You'll do this for us, right?  I'll reward you handsomely for this favor!", objectives = "Bring Antheol's Elemental Grimoire to Instructor Antheol at Stillwhisper Pond in Eversong Woods.", progress = "What calls for this interruption to my lecture, <class>?", completion = "You say those two incompetent fools bribed you to lie to me?  You've done very well in coming to me, <name>." }
WordHunterWoW_QuestEN[9065] = { title = "The Pattymac Special", description = "Hey <class>t, knock down that tower! Otherwise $vn will get you... $vghe:she; is very angry!You will receive:", objectives = "Make sure you destroy that tower!" }
WordHunterWoW_QuestEN[9066] = { title = "Swift Discipline", description = "I hope you learn a valuable lesson today, {name}.  Never trust someone else to lie for you.\n\nNow I want you to go back to my two dimwitted students and discipline them using this wand.  My magic tells me that you'll find them along the road to the west on the other side of the Dead Scar.\n\nCome back to me after you've done this.  I'll give you a small reward for your troubles.", objectives = "Use Antheol's Disciplinary Rod on his two students: Apprentice Ralen and Apprentice Meledor. Return to Antheol at Stillwhisper Pond in Eversong Woods with the rod after this.", progress = "Did you do what I asked of you, <name>?", completion = "Excellent job, <name>.  Don't worry, they're not stuck in that form permanently.  Their apprenticeship, however, won't be restored until they earn it back." }
WordHunterWoW_QuestEN[9067] = { title = "The Party Never Ends", description = "I like to throw parties... just a little something to celebrate the magnificence that is Quel'Thalas!\n\nBut, I'm in a bit of a bind.  I need you to gather up more party supplies.\n\nFrom Vinemaster Suntouched at the Silvermoon City inn, bring me a bottle of Suntouched Special Reserve.  From Zalene Firstlight at Farstrider Retreat acquire more of those delicious Springpaw Appetizers.  And you can pick up my delivery of fireworks from Halis Dawnstrider at Fairbreeze Village.\n\nBe quick about it!", objectives = "Acquire a bottle of Suntouched Special Reserve, Springpaw Appetizers and a Bundle of Fireworks, and return them to Lord Saltheril at Saltheril's Haven in Eversong Woods.", progress = "Didn't I just send you out to gather up more party supplies?  Was that you?  Oh, I can't be expected to remember everyone's face, now can I?  I meet so many... interesting people.\n\nWhat is it that you want?", completion = "You're quite the energetic young $g, aren't you?\n\nThis all looks very adequate. You certainly deserve compensation for gathering up all of this for me, and something a little extra I think./n/nOh, I almost forgot, here's an invitation to the party.  And, <class>, next time that you drop in make sure to dress up in something a little more... festive." }
WordHunterWoW_QuestEN[9068] = { title = "Earthshatter Tunic", description = "Would you honor me by returning the armor of those that fell in the defense of these lands?\n\nThe armor has been desecrated and is undoubtedly being used for evil; however, with wartorn armor scraps, the desecrated armor can be renewed and worn for battle once more.\n\nBring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don.\n\nSearch Naxxramas.You will receive:", objectives = "Rimblat Earthshatter at Light's Hope Chapel in the Eastern Plaguelands will make an Earthshatter Tunic if you bring him the following: 1 Desecrated Tunic, 25 Wartorn Chain Scraps, 4 Arcanite Bars and 3 Cured Rugged Hides." }
