WordHunterWoW_QuestEN[9076] = { title = "Wretched Ringleader", description = "The Wretched are so oblivious, gorging on foul magic, that they haven't realized we've recovered most of our weapons.  We can't expect them to remain in their stupor, though.  Now is the time for a decisive attack.  Let us make an example of their leader, Aldaron.  He was spotted on the top floor of the building by the anchorage.  Bring me his head; I'll reward you suitably.", objectives = "Bring Aldaron's Head to Velendris Whitemorn near Sunsail Anchorage in Eversong Woods.", progress = "Well, do you have his head or not?  I've no time to waste, <name>.", completion = "You defeated him after all!  Undoubtedly my men softened him up for you.\n\nI jest, <class>.  You've done well.  You'll make a name for yourself if you keep your nose clean." }
WordHunterWoW_QuestEN[9077] = { title = "Bonescythe Breastplate", description = "If you want Bonescythe made, you're going to have to supply the materials.\n\nEnter Naxxramas, the big floating city of death in the sky up there, and find desecrated armor and wartorn armor scraps. Bring those back along with the materials to put everything together and you'll have your Bonescythe. Oh, and you'll need to pay me for my troubles... I'll supply the bones.You will receive:", objectives = "Rohan the Assassin at Light's Hope Chapel in the Eastern Plaguelands will make a Bonescythe Breastplate if you bring him the following: 1 Desecrated Breastplate, 25 Wartorn Leather Scraps, 2 Arcanite Bars and 6 Cured Rugged Hides." }
