WordHunterWoW_QuestEN[9197] = { title = "Craftsman's Writ - Gnomish Battle Chicken", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order EN-0:\n\n4 Gnomish Battle Chickens.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 4 Gnomish Battle Chickens and the Craftsman's Writ - Gnomish Battle Chicken - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9198] = { title = "Craftsman's Writ - Thorium Tube", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order EN-558:\n\n14 Thorium Tubes.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 14 Thorium Tubes and the Craftsman's Writ - Thorium Tube - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9199] = { title = "Troll Juju", description = "The corpses of trolls buried inside the Amani Catacombs have been rising from the dead! I want you to go there and bring back proof of their final demise. Some of these mummy trolls, and their living counterparts, carry juju; glowing objects that house an unknown power source.  It's probably what is animating them!\n\nThe catacombs lie within Sungraze Peak, directly to the east. I am told that the easiest way in lies on the north face of the mountain. See to it, {class}!", objectives = "Collect 8 Troll Juju and return them to Apothecary Venustus at Farstrider Enclave in the Ghostlands.", progress = "I don't have to remind you that we can ill afford this trouble with the troll dead rising in our very backyard! We have enough trouble with Deatholme to the south!", completion = "Mummies being raised by troll priests... clever! The Shadowpine trolls must be trying to bolster their numbers through necromantic means. I'd wager that these oracles were using the juju in their reanimation ritual.\n\nOnce again you perform your duty as befits a <class> of your growing reputation. Take this with our gratitude." }
WordHunterWoW_QuestEN[9200] = { title = "Craftsman's Writ - Major Mana Potion", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order AL-473:\n\n10 Major Mana Potions.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent Dawn", objectives = "Deliver 10 Major Mana Potions and the Craftsman's Writ - Major Mana Potion - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.", progress = "Filling a work order, <class>?", completion = "The utility of these should go without saying." }
WordHunterWoW_QuestEN[9201] = { title = "Craftsman's Writ - Greater Arcane Protection Potion", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order AL-1420:\n\n15 Greater Arcane Protection Potions.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 15 Greater Arcane Protection Potions and the Craftsman's Writ - Greater Arcane Protection Potion - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands." }
