WordHunterWoW_QuestEN[9203] = { title = "Craftsman's Writ - Potion of Petrification", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order AL-90:\n\n1 Potion of Petrification.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 1 Potion of Petrification and the Craftsman's Writ - Potion of Petrification - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9204] = { title = "Craftsman's Writ - Stonescale Eel", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order FS-5:\n\n40 Stonescale Eel.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 40 Stonescale Eel and the Craftsman's Writ - Stonescale Eel - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9205] = { title = "Craftsman's Writ - Plated Armorfish", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order FS-12:\n\n30 Plated Armorfish.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 30 Plated Armorfish and the Craftsman's Writ - Plated Armorfish - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9206] = { title = "Craftsman's Writ - Lightning Eel", description = "The bearer of this writ is entitled to payment in the form of an insignia of their choice upon completion of the contracted work order.\n\nWork Order FS-9:\n\n30 Lightning Eel.\n\nAll filled orders should be delivered to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands.\n\nContract is null and void if tampered with or damaged.\n\n-Dispatch Commander Metz, The Argent DawnYou will be able to choose one of these rewards:", objectives = "Deliver 30 Lightning Eel and the Craftsman's Writ - Lightning Eel - to Packmaster Stonebruiser at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9207] = { title = "Underlight Ore Samples", description = "I was sent here from the Sanctum of the Sun to collect some ore samples, but the gnolls have overrun the place! It's going to be my head on a platter if I don't get those samples to the magister soon. Maybe you could help, {class}?\n\nYou can find the ore in the tin and copper veins here, and the gnolls are carrying it around, too. When you have enough, take it to Magister Quallestis at the Sanctum of the Sun directly to the east. Go across the Dead Scar and you'll find the sanctum just south of Sungraze Peak.", objectives = "Collect 6 Underlight Ore and deliver them to Magister Quallestis at the Sanctum of the Sun in the Ghostlands.", progress = "How may I help you, <class>?", completion = "My apprentice was unable to take care of this herself?  I shall have a word with her when she returns then, gnolls or not.  Speaking of which, why didn't she return with you?\n\n<The magister sighs.>\n\nThat one is a handful, and is going to be quite a challenge to properly train.  Thank you, <class>, for bringing these samples to me.  We are hoping that we can uncover some special property from them that will help in the fight against the Scourge.\n\nPlease take this coin as a token of my appreciation." }
WordHunterWoW_QuestEN[9208] = { title = "The Savage Guard - Arcanum of Protection", description = "Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.\n\nBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.", objectives = "Zanza the Restless in Zul'Gurub wants an Arcanum of Protection.", progress = "Do you have the arcanum?", completion = "The worthless magic in these enchantments fuels my anger. My anger gives me strength.\n\nBring me more and you shall receive another Savage Guard." }
WordHunterWoW_QuestEN[9209] = { title = "The Savage Guard - Arcanum of Rapidity", description = "Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.\n\nBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.", objectives = "Zanza the Restless in Zul'Gurub wants an Arcanum of Rapidity.", progress = "Do you have the arcanum?", completion = "The worthless magic in these enchantments fuels my anger. My anger gives me strength.\n\nBring me more and you shall receive another Savage Guard." }
WordHunterWoW_QuestEN[9210] = { title = "The Savage Guard - Arcanum of Focus", description = "Zanza can create many ancient troll enchantments with proper components! Have you heard of the Savage Guard? No, of course you haven't. Your mind is addled with the inferior elven magic.\n\nBring me an arcanum of elven creation so that I may destroy the aberration. Do this and the Savage Guard will be yours.You will receive:", objectives = "Zanza the Restless in Zul'Gurub wants an Arcanum of Focus." }
WordHunterWoW_QuestEN[9211] = { title = "The Ice Guard", description = "Ah, the Ice Guard. It is a thin sheen of protective magic that covers certain pieces of equipment. Those that do battle with creatures of frost and ice will gain increased protection from their attacks by using the Ice Guard.\n\nAs with all things the Wrathcaster creates, there is a price - a price that I will not lower, regardless of how much you whimper. Interested?You will receive:", objectives = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold." }
WordHunterWoW_QuestEN[9212] = { title = "Escape from the Catacombs", description = "These trolls ambushed me and have been keeping me in this cage.  I think they're planning to sacrifice me!  Help me get out of here!\n\nThe lock on the cage isn't that complex... I just can't get to it from this side.  Please escort me back to the Farstrider Enclave.  I'm sure Captain Helios will reward you, and you'll have my undying gratitude!", objectives = "Escort Ranger Lilatha to Captain Helios at Farstrider Enclave in the Ghostlands.", progress = "You're the one that rescued my ranger?", completion = "You're quite the hero, <class>, to get her out of there alive.  I suppose we'll have to mount an offensive to clear out those catacombs too.  As if we didn't have enough trouble with the living trolls!\n\nYou've done a great thing today, I should reward you.  Take your pick from any of these." }
WordHunterWoW_QuestEN[9213] = { title = "The Shadow Guard", description = "A creation of genius! Much like the Ice Guard, the Shadow Guard employs a thin sheen of protective magic that covers certain pieces of equipment. And like the Ice Guard, the Shadow Guard is going to cost you a good amount of money.\n\n<Mataus holds his hand out and rubs his fingers together.>\n\nInterested?", objectives = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold.", progress = "<Mataus yawns.>\n\nBe gone, insect, lest you have something for me.", completion = "<Mataus stuffs the gold into his robe.>\n\nWhat are you still standing around for, <race>? Our business is done." }
WordHunterWoW_QuestEN[9214] = { title = "Shadowpine Weaponry", description = "{class}, I want you to kill as many Shadowpine trolls as you can. We need their numbers greatly reduced before we can shift our attention toward Deatholme. And while you're at it, we might as well kill two birds with one stone, so bring me back a load of their weapons. Better that they not go to waste, and we can use them in the fight against the Scourge.\n\nHit their camps hard to the east and the south at Zeb'Tela and Zeb'Nowa.", objectives = "Collect 3 Headhunter Axes, 3 Shadowcaster Maces, 3 Catlord Claws and 3 Hexxer Staves. Return them to Captain Helios at Farstrider Enclave in the Ghostlands.", progress = "Have those weapons yet? With the Shadowpine numbers decimated we'll finally be able to turn our attention to the fight against the Scourge.", completion = "I'll immediately send a few rangers out to survey the damage that you wreaked upon the Shadowpine trolls. I've no doubt that we'll be able to mop up after your offensive and launch an attack on the Scourge soon if these weapons are any indication of your success.\n\nHere, I want you to take this coin in payment. It's burning a hole in my pouch anyway." }
WordHunterWoW_QuestEN[9215] = { title = "Bring Me Kel'gash's Head!", description = "WANTED: Bring the head of Kel'gash the Wicked, chieftain of the Shadowpine trolls, to Captain Helios. No questions asked. Kel'gash is known to dwell somewhere to the south in Zeb'Nowa.\n\n\n\nREWARD: Yes, but no advances!", objectives = "Return the Head of Kel'gash the Wicked to Captain Helios at the Farstrider Enclave in the Ghostlands.", progress = "What is that awful smell?", completion = "Ah, Kel'gash's head is what smelled so bad. That's a nice piece of work there, <class>!\n\nWith their chieftain dead, the Shadowpine trolls should be in total disarray. Combined with your recent efforts to decimate their numbers, this should be the perfect opportunity to launch our counter-offensive against them and wipe them out for good.\n\nYou have my thanks, <name>. Might I interest you in one of these?" }
WordHunterWoW_QuestEN[9216] = { title = "Rotting Hearts", description = "I hear the Amani trolls eat their enemies' hearts to steal their strength.  They might just be on to something, {name}.  With the proper treatment, the hearts of the unliving can produce potent elixirs.\n\nHunt down the zombies that roam the Dead Scar and bring me their hearts.  I'll show you the kind of enhancement we can perform to your physical prowess against the undead.", objectives = "Bring back 10 Rotting Hearts to Magistrix Aminel in Tranquillien.", progress = "Do you have the zombie hearts I requested, <name>?", completion = "Take this draught, <name>.  After you drink it, your physical strength against the Scourge will receive a boost. If you need more than this sample bring me more hearts." }
WordHunterWoW_QuestEN[9217] = { title = "More Rotting Hearts", description = "", objectives = "You've brought more ghoul hearts?  I can use as many as you can collect, <name>.", progress = "You've brought more ghoul hearts?  I can use as many as you can collect, <name>.", completion = "This will provide you with greater power against the Scourge.   Bring more hearts if you find them, <name>." }
WordHunterWoW_QuestEN[9218] = { title = "Spinal Dust", description = "The dark energy that flows through the bodies of reanimated skeletons tends to accumulate primarily in their spine.  I've discovered a method of instilling this energy into a potion that boosts our magical abilities against the undead.\n\nBring me some spinal dust and I'll be glad to provide you with a sample.  You'll find an ample number of skeletons wandering the Dead Scar, west of here.", objectives = "Bring back 10 Spinal Dusts to Magistrix Aminel in Tranquillien.", progress = "Do you have the samples I requested, <name>?", completion = "Take this, <name>.  You'll feel the difference immediately!\n\nFeel free to bring more spinal dust; I can use as much of it as you can provide.  Side effects?  You might start feeling your joints acting up a bit.  Nothing permanent, I assure you!" }
WordHunterWoW_QuestEN[9219] = { title = "More Spinal Dust", description = "", objectives = "You've procured more spinal dust?  I can use as much of it as you bring me.", progress = "You've procured more spinal dust?  I can use as much of it as you bring me.", completion = "This dust is as potent as ever, <name>.  Keep bringing it to me if you're in need to boost your magical powers against the Scourge." }
WordHunterWoW_QuestEN[9220] = { title = "War on Deatholme", description = "If you seek to aid our cause there is no better place to start than here and no better time to do it than now.\n\nBy rebuilding the Sanctum of the Sun we've raised a banner of defiance in front of our enemy's seat of power: Deatholme.\n\nGo forth and fight the hordes of undead that inhabit the vile Scourge fortress.", objectives = "Slay 5 Eyes of Dar'khan, 6 Nerubis Centurions and 6 Wailers in Deatholme and return to Magister Idonis at the Sanctum of the Sun in the Ghostlands.", completion = "The Scourge has felt our wrath, <name>.  It won't be long before their cursed citadel lies in ruins.\n\nWith their numbers weakened, it is time to launch an attack on more strategic targets." }
WordHunterWoW_QuestEN[9221] = { title = "Superior Armaments of Battle - Friend of the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nI must warn you; purchases made at a friendly reputation with the Dawn come with a hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.You will be able to choose one of these rewards:", objectives = "For 30 Insignias of the Dawn and 30 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache." }
WordHunterWoW_QuestEN[9222] = { title = "Epic Armaments of Battle - Friend of the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", objectives = "For 110 Insignias of the Dawn and 110 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, <name>. It was a pleasure doing business with you." }
WordHunterWoW_QuestEN[9223] = { title = "Superior Armaments of Battle - Honored Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nI must warn you; purchases made at honored reputation with the Dawn come with a fairly prohibitive surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.You will be able to choose one of these rewards:", objectives = "For 20 Insignias of the Dawn and 20 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache." }
WordHunterWoW_QuestEN[9224] = { title = "Epic Armaments of Battle - Honored Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; purchases made at honored reputation with the Dawn come with an extremely hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.", objectives = "For 75 Insignias of the Dawn and 75 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, <name>. It was a pleasure doing business with you." }
WordHunterWoW_QuestEN[9225] = { title = "Epic Armaments of Battle - Revered Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nI must warn you; epic purchases made at revered reputation with the Dawn are still quite expensive. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.You will be able to choose one of these rewards:", objectives = "For 45 Insignias of the Dawn and 45 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache." }
WordHunterWoW_QuestEN[9226] = { title = "Superior Armaments of Battle - Revered Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nItems offered to those revered amongst the Dawn are priced quite reasonably. I encourage you to make a purchase!", objectives = "For 7 Insignias of the Dawn and 7 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, <name>. It was a pleasure doing business with you." }
WordHunterWoW_QuestEN[9227] = { title = "Superior Armaments of Battle - Exalted Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?\n\nItems offered to those exalted amongst the Dawn are discounted. I encourage you to make a purchase!", objectives = "For 6 Insignias of the Dawn and 6 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache.", progress = "Choose carefully. There are no refunds.", completion = "Good day, <name>. It was a pleasure doing business with you." }
WordHunterWoW_QuestEN[9228] = { title = "Epic Armaments of Battle - Exalted Amongst the Dawn", description = "Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?\n\nThose exalted amongst the Dawn receive our greatest discounts! I encourage you to make a purchase.You will be able to choose one of these rewards:", objectives = "For 27 Insignias of the Dawn and 27 Insignias of the Crusade you may choose an item from the Argent Dawn's treasure cache." }
WordHunterWoW_QuestEN[9229] = { title = "The Fate of Ramaladni", description = "Ramaladni was a warrior of the Brotherhood - a pupil of Highlord Mograine before the Dawn even existed! When news of Mograine's death reached him, hatred and anger took over.\n\nUnderstand this, <name>, when rage and retribution take the reins, a man ceases to be a man. The man personifies the emotions that control him instead. And so it would be that Ramaladni, the spirit of retribution, would enter Naxxramas to exact vengeance... and never return.\n\nEnter Naxxramas and find what became of Ramaladni.Upon completion of this quest you will gain:", objectives = "Enter Naxxramas and uncover the Fate of Ramaladni." }
WordHunterWoW_QuestEN[9230] = { title = "Ramaladni's Icy Grasp", description = "Fixing this band may prove to be quite challenging, <name>. You see, it was made from the very runes that form inside Scourge structures - like Naxxramas. Additional materials are also required but your main concern should be getting those frozen runes. Bring me what I need and I will restore the ring to its former glory.You will receive:", objectives = "Korfax at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 1 Frozen Rune, 1 Blue Sapphire and 1 Arcanite Bar." }
WordHunterWoW_QuestEN[9231] = { title = "reuse", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[9232] = { title = "The Only Song I Know...", description = "You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?\n\n<Wilhelm sighs.>\n\nBah, what choice do I got? You're the best I can do; I may as well help you.\n\nOmarion left me with one recipe. It's the only song I know... I can make a few variations of these pants; you just gotta supply the materials.Upon completion of this quest you will gain:", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 2 Frozen Runes, 2 Essence of Water, 2 Blue Sapphires and 30 gold pieces." }
WordHunterWoW_QuestEN[9233] = { title = "Omarion's Handbook", description = "Wilhelm,\n\nIf you are reading this, I have perished - finally. I want you to know that my dying thoughts revolved around you and your ineptitude when it comes to tradeskills. Unfortunately, the bearer of this handbook is in even worse shape than you in regards to crafting.\n\nAbout the book: These are the rest of my recipes. Make the bearer of this book whatever they request. I'm sure you will charge a hefty fee for your services because you are, after all, a crook.\n\nIn Disdain,\n\nOmarion", objectives = "Take Omarion's Handbook to Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9234] = { title = "Icebane Gauntlets", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create Icebane gauntlets. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 5 Frozen Runes, 12 Thorium Bars, 2 Arcanite Bars, 2 Essences of Water and 200 gold.", progress = "Have you brought the materials?", completion = "Here is your order, <name>. Delivered as promised!" }
WordHunterWoW_QuestEN[9235] = { title = "Icebane Bracers", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create Icebane bracers. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 4 Frozen Runes, 12 Thorium Bars, 2 Arcanite Bars, 2 Essence of Water and 200 gold.", progress = "Have you brought the materials?", completion = "Here is your order, <name>. Delivered as promised!" }
WordHunterWoW_QuestEN[9236] = { title = "Icebane Breastplate", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create an Icebane breastplate. All you need to do is bring me the materials and pay a small crafting fee.", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 8 Frozen Runes, 16 Thorium Bars, 2 Arcanite Bars, 4 Essence of Water and 300 gold. You will also need to be of Exalted reputation with the Argent Dawn.", progress = "Have you brought the materials?", completion = "Here is your order, <name>. Delivered as promised!" }
WordHunterWoW_QuestEN[9237] = { title = "Glacial Cloak", description = "Thanks to you and Omarion, may he rest in peace, I am now able to create a Glacial cloak. All you need to do is bring me the materials and pay a small crafting fee.You will receive:", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 5 Frozen Runes, 4 Bolts of Runecloth, 2 Essences of Water, 4 Ironweb Spider Silks and 200 gold. You must also be of Exalted reputation with the Argent Dawn." }
