WordHunterWoW_QuestEN[9246] = { title = "Icy Scale Breastplate", description = "Thanks to you and Omarion (May he rest in peace), I am now able to create an Icy Scale breastplate. All you need to do is bring me the materials and pay a small crafting fee.You will receive:", objectives = "Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands wants 8 Frozen Runes, 24 Heavy Scorpid Scale, 7 Essence of Water, 5 Cured Rugged Hides and 300 gold. You must also be of Exalted reputation with the Argent Dawn." }
WordHunterWoW_QuestEN[9247] = { title = "The Keeper's Call", description = "{name},\n\nIn times past you have served the interests of the Argent Dawn, always to the best of your abilities. Now, once again, we sound the clarion call in our time of greatest need.\n\n{name}, please report to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands if you are willing to aid us once more.", objectives = "Take the Letter from the Keeper of the Rolls to him at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9248] = { title = "A Humble Offering", description = "Ishnu-alah, <race>. Show me proof of the demise of a Lord of the Abyssal Council and I shall reward you with an item that should aid you in your battles against the Qiraji.", objectives = "Aurel Goldleaf at Cenarion Hold in Silithus wants you to bring her 1 Abyssal Scepter. You must also be Honored with the Cenarion Circle.", progress = "Fandu-dath-belore? Oh, pardon me, <name>. I did not recognize you. Have you the scepter?", completion = "Ande'thoras-ethil. It means; 'May your troubles be diminished,' in my native tongue.\n\nWear the band proudly and in good health, <name>." }
WordHunterWoW_QuestEN[9249] = { title = "40 Tickets - Schematic: Steam Tonk Controller", description = "", objectives = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", progress = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", completion = "Here you go, here you go!  A prize fit for a king!  Congratulations to you, my friend!\n\nIf you have more tickets you'd like to turn in, then please let me know!  For as long as the Darkmoon Faire is here, I'll redeem your tickets." }
WordHunterWoW_QuestEN[9250] = { title = "Frame of Atiesh", description = "With the frame formed, Atiesh is nearly whole. Only the head and base of the staff are now missing. There is also a minor issue regarding the staff being a conduit for Sargeras's evil.\n\nFind someone that can assist you in locating the remaining pieces and exorcising the evil from the staff.", objectives = "Find someone that will help you in recovering the last two pieces of the staff and ridding it of evil." }
WordHunterWoW_QuestEN[9251] = { title = "Atiesh, the Befouled Greatstaff", description = "You question why you are still alive. After all, you have in your possession an item of great evil. The answer is not clear, {name}. I only do as I must.\n\nKel'Thuzad sits atop his throne in Naxxramas, plotting... He seeks that which you hold and holds that which you seek.\n\nAs for the base of the staff; the dwarf, Brann Bronzebeard, held it when he entered Ahn'Qiraj. He has left Ahn'Qiraj but the base of Atiesh remains.\n\nShould you succeed in recovering the pieces, return them to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants the Staff Head of Atiesh and the Base of Atiesh." }
WordHunterWoW_QuestEN[9252] = { title = "Defending Fairbreeze Village", description = "We've experienced a marked increase in Scourge attacks, {name}.  Our defenses are barely holding and there's no sign of reinforcements from Silvermoon City.  Lend us a hand in defending the village by thinning the numbers of the undead roaming the Dead Scar nearby.", objectives = "Slay 4 Rotlimb Marauders and 4 Darkwraiths and return to Ranger Sareyn at Fairbreeze Village in Eversong Woods.", completion = "Many thanks, <name>.  Our job is a thankless one, but today you helped make it a bit easier." }
WordHunterWoW_QuestEN[9253] = { title = "Runewarden Deryan", description = "This increase in Scourge attacks leads me to believe there might be a malfunction at one of the protective runestones at the border with the Ghostlands.\n\nWe used these ancient stones to protect us against the undead.  Most of them were destroyed or lost after the attack on the Sunwell. \n\nFollow the road south, towards the Ghostlands, and look to the west for a small path.  You will find Runewarden Deryan by the runestone nearby; he will know whether anything's wrong.", objectives = "Speak to Runewarden Deryan in Eversong Woods, near the border with the Ghostlands.", completion = "You must've been sent by someone at Fairbreeze Village.  I knew it would just be a matter of time until help arrived." }
WordHunterWoW_QuestEN[9254] = { title = "The Wayward Apprentice", description = "Thank you for your help, {name}.  While I get things back in order here, I'd like to ask you for a favor.  One of my former apprentices embarked in a very dangerous line of research.  She journeyed to the East Sanctum, in the middle of the Dead Scar.\n\nI worry for her well-being.  See if you can find her and convince her to return to her senses.", objectives = "Speak to Apprentice Mirveda at the East Sanctum in Eversong Woods.", completion = "It's so nice of my old mentor to check on me.  It's too bad she lost faith in my research long ago.\n\nDon't waste your time trying to get me to return to her; you can either help me with my research or leave." }
WordHunterWoW_QuestEN[9255] = { title = "Research Notes", description = "As discouraging as my research results are, they still contain valuable data. I must have a Magister review my work before it is taken seriously. Please, take these notes to Magistrix Landra Dawnstrider at Fairbreeze Village, west of here.", objectives = "Deliver the Research Notes to Magistrix Landra Dawnstrider at Fairbreeze Village in Eversong Woods.", progress = "You've something for me?", completion = "These notes... are shocking.  If they're correct it means the damage to the land on the Dead Scar is irreversible.\n\nI'll notify the grand magister right away.  More reason for our race to escape this world and find our true fate in Outland." }
WordHunterWoW_QuestEN[9256] = { title = "Fairbreeze Village", description = "I have another task for you, {name}.  Ranger Degolien was sent to Fairbreeze Village to find out more about a Wretched attack on a nearby shipyard.  He has requested reinforcements which we cannot yet provide.  Seek him out and grant him whatever aid you can.\n\nFairbreeze Village can be reached by following the road out of Falconwing Square all the way towards the south.  Good luck, {name}.", objectives = "Speak to Ranger Degolien at Fairbreeze Village in Eversong Woods.", completion = "Thanks for coming, <name>.  Things are worse than we had anticipated.  The Wretched have taken over Sunsail Anchorage in its entirety." }
WordHunterWoW_QuestEN[9257] = { title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him." }
WordHunterWoW_QuestEN[9258] = { title = "The Scorched Grove", description = "A foul taint in the soil precedes the expansion of the Scourge into a new area.  The protective runestones along the border with the Ghostlands have warded the land against this taint in the past.\n\nThe westernmost runestone was destroyed during a Scourge attack, which forced us to burn the ground around it to prevent the taint from spreading.\n\nMy sister, Larianna Riverwind, watches over the Scorched Grove.  Go find her; she might have some work for you.", objectives = "Find Larianna Riverwind near the Scorched Grove in the southwest of Eversong Woods.", completion = "Ah, my brother sent you.  I do have a task I could use assistance with." }
WordHunterWoW_QuestEN[9259] = { title = "Traitor to the Bloodsail", description = "", objectives = "That mangy dog, Revilgaz, has offered to pardon any former Bloodsails willing to turn on their cap'n! That bilge sucker asked me to go an' off me ole' mates and to bring back their bandannas as proof.\n\nI don't have it in me heart to do that, nor will I ask ye to. Bring me some silk cloth and red dye and I'll make suitable replicas. I'll tell the Baron you went turncoat, but be warned... the Bloodsails are not gonna like it!", progress = "That mangy dog, Revilgaz, has offered to pardon any former Bloodsails willing to turn on their cap'n! That bilge sucker asked me to go an' off me ole' mates and to bring back their bandannas as proof.\n\nI don't have it in me heart to do that, nor will I ask ye to. Bring me some silk cloth and red dye and I'll make suitable replicas. I'll tell the Baron you went turncoat, but be warned... the Bloodsails are not gonna like it!", completion = "Let us observe a minute of silence for our fallen mates, <name>.\n\n<The Bloodsail Traitor grins at you and winks.>\n\nBeing a traitor is one thing, murdering yer own buckos... that'd be just downright despicable, aye!" }
WordHunterWoW_QuestEN[9260] = { title = "Investigate the Scourge of Stormwind", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Stormwind from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside Stormwind and investigate the glowing runic circles near their encampment." }
WordHunterWoW_QuestEN[9261] = { title = "Investigate the Scourge of Ironforge", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Ironforge from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside Ironforge and investigate the glowing runic circles near their encampment." }
WordHunterWoW_QuestEN[9262] = { title = "Investigate the Scourge of Darnassus", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Darnassus from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside Darnassus and investigate the glowing runic circles near their encampment." }
WordHunterWoW_QuestEN[9263] = { title = "Investigate the Scourge of Orgrimmar", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Orgrimmar from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside Orgrimmar and investigate the glowing runic circles near their encampment." }
WordHunterWoW_QuestEN[9264] = { title = "Investigate the Scourge of Thunder Bluff", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend Thunder Bluff from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside Thunder Bluff and investigate the glowing runic circles near their encampment." }
WordHunterWoW_QuestEN[9265] = { title = "Investigate the Scourge of the Undercity", description = "The Lich King has sent his undead upon our very doorstep; we cannot remain idle! Surely you will step up to defend the Undercity from these accursed invaders? \n \nThere are strange runic circles outside, glowing with the same energy that surrounds the undead and the Necropolis above. They have significance, I'm certain, and I want you to find out what. Thin the numbers of those aberrations while you're at it; bring me proof of their death along with your results, and I will reward you.  Go!", objectives = "Collect three Dim Necrotic Stones from the Scourge outside the Undercity and investigate the glowing runic circles near their encampment." }
WordHunterWoW_QuestEN[9266] = { title = "Making Amends", description = "", objectives = "You must've done something really bad to us or our friends, <name>. At any rate, I'm here to offer you a way to get our good graces back.\n\nAs you know, Winterspring is quite cold. With so many of us goblins coming from other cities, we could use a hand keeping warm. Bring me some runecloth and coal and I'll put in the good word for ya. Be warned though, our enemies are not going to take kindly to your helping us.", progress = "You must've done something really bad to us or our friends, <name>. At any rate, I'm here to offer you a way to get our good graces back.\n\nAs you know, Winterspring is quite cold. With so many of us goblins coming from other cities, we could use a hand keeping warm. Bring me some runecloth and coal and I'll put in the good word for ya. Be warned though, our enemies are not going to take kindly to your helping us.", completion = "Thank you, <name>. You're on a quick path to redeeming yourself with our fair town." }
WordHunterWoW_QuestEN[9267] = { title = "Mending Old Wounds", description = "", objectives = "You'd better think twice before setting foot in Ratchet, <name>!  Word's been getting around of your dirty deeds.\n\nYou're in luck though, a ship just arrived with many wounded from an encounter with the Bloodsail Buccaneers.  This is your chance to prove you're not a complete scoundrel.  Lend us a hand by bringing linen cloth for bandages and empty vials for potions.", progress = "You'd better think twice before setting foot in Ratchet, <name>!  Word's been getting around of your dirty deeds.\n\nYou're in luck though, a ship just arrived with many wounded from an encounter with the Bloodsail Buccaneers.  This is your chance to prove you're not a complete scoundrel.  Lend us a hand by bringing linen cloth for bandages and empty vials for potions.", completion = "I'm happy you're seeing the error of your ways, <name>.  Keep the supplies coming; we're not going to forget about you so easily!" }
WordHunterWoW_QuestEN[9268] = { title = "War at Sea", description = "", objectives = "You seek to befriend the goblins of Tanaris once again, <name>?  We're in need of materials for sails and guns to fight off our old enemies, the Bloodsail Buccaneers.  Bring me mageweave and strong flux and we'll be on our way to pardoning your trespasses.", progress = "You seek to befriend the goblins of Tanaris once again, <name>?  We're in need of materials for sails and guns to fight off our old enemies, the Bloodsail Buccaneers.  Bring me mageweave and strong flux and we'll be on our way to pardoning your trespasses.", completion = "Keep it coming, <name>.  Us goblins don't forget that easily!" }
WordHunterWoW_QuestEN[9269] = { title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him." }
WordHunterWoW_QuestEN[9270] = { title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him." }
WordHunterWoW_QuestEN[9271] = { title = "Atiesh, Greatstaff of the Guardian", description = "This final task will be the most difficult of all, {name}. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras.\n\nTake the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", objectives = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him." }
WordHunterWoW_QuestEN[9272] = { title = "Dressing the Part", description = "", objectives = "Yarrr... if ye be keen on enjoying the company of us experienced sea dogs, you'd best belay dressing like a blaggard!  Here, put on something proper 'fore I keelhaul yer hide.\n\nThese'll fit ye better than they ever fit that old dog, Red-Eyed Ben.  Lost him in a devil of a storm at sea.\n\nWear 'em with pride, mate!" }
WordHunterWoW_QuestEN[9273] = { title = "Redeem iCoke Prize Voucher", description = "", objectives = "" }
WordHunterWoW_QuestEN[9274] = { title = "Spirits of the Drowned", description = "The lake to the north has been haunted by the ghosts of my ancestors for as long as I can remember, {name}.  The poor souls were victims of a tragic incident in which scores of them drowned at the bottom of the lake.\n\nThe details of the event are mostly forgotten, but their haunting cries serve as a constant reminder of their curse.\n\nIf you're up to the task, I want you to go to the lake and put an end to their suffering, {name}.  You will have my gratitude as well as theirs... I'm sure.", objectives = "Ranger Krenn'an, at the Farstrider Enclave in the Ghostlands, wants you to kill 8 Vengeful Apparitions and 8 Ravening Apparitions in the nearby lake.", completion = "I appreciate your help, <name>.  It pains me to see the spirits of my ancestors in their pitiful state.  May they finally get the rest they deserve." }
WordHunterWoW_QuestEN[9275] = { title = "A Little Dash of Seasoning", description = "I'm on loan to the Farstriders in an attempt to help with their troll difficulties. I believe that I have a solution to their problem.\n\nAt my disposal are a number of potent poisons. The trolls, as you know, are living creatures and therefore must eat. If we combine my poison with their food... well, I'm sure that the results will be entertaining!\n\nCare to help rid us of the Shadowpine trolls at Zeb'Nowa to the south? The camp straddles both the north and south sides of the road to Zul'Aman.", objectives = "Poison the Troll foodstuff at the camps in Zeb'Nowa and then return to Apothecary Venustus at the Farstrider Enclave in the Ghostlands.", progress = "Isn't this exciting? I really do take great pride in my work; I hope you appreciate it, <class>.\n\nSo, I trust that you have 'seasoned' the food at the troll camps in Zeb'Nowa?", completion = "Ah, excellent! I knew that a <race>-delivery system would make for the most efficient application of the poison. With any luck the Shadowpine trolls will get fat on it before keeling over. That should get them off of the backs of the Farstriders, and me back to Tranquillien.\n\nIt has been a pleasure working with you, <class>!" }
WordHunterWoW_QuestEN[9276] = { title = "Attack on Zeb'Tela", description = "Our resources are spread pretty thin here, {class}, so your help is going to be invaluable.  The captain has tasked me with overseeing the harassment of the local Shadowpine troll camps. We have a policy of keeping them off balance until the day when we can launch a brutal offensive to wipe them out.\n\nUntil then, we need all of the volunteers that we can get so that those Shadowpine troll numbers are decreased.\n\nThink you could head east to Zeb'Tela and hurt them a little?", objectives = "Kill 8 Shadowpine Shadowcasters and 8 Shadowpine Headhunters, and return to Farstrider Solanna at Farstrider Enclave in the Ghostlands.", completion = "Good, good! You handled that very well! Let's see if you're up to something a little more difficult now." }
WordHunterWoW_QuestEN[9277] = { title = "Assault on Zeb'Nowa", description = "Time for something a little more challenging. Zeb'Nowa, to the south, is where the more powerful Shadowpine trolls make their home. In our continuing effort to keep the troll numbers to a minimum I'm dispatching you to go down there and assail them by whatever means you have at your disposal.\n\nWhat do you say, {name}? Ready to deal with some more trolls?", objectives = "Kill 10 Shadowpine Catlords and 10 Shadowpine Hexxers, and return to Farstrider Solanna at the Farstrider Enclave in the Ghostlands.", completion = "Unbelievable! You really should talk to the captain about joining up as a Farstrider.\n\nAlright, <name>, you've given us the breathing room that we need to continue building up our forces here. Actually, by your account there aren't many of those trolls left at all! Maybe now we can join with Tranquillien and attack Deatholme?\n\nI think you've earned a little something. Take your pick." }
WordHunterWoW_QuestEN[9278] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Jaeleil in Azure Watch.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!\n", objectives = "Bring the Azure Watch Gift Voucher to Jaeleil in Azure Watch." }
WordHunterWoW_QuestEN[9279] = { title = "You Survived!", description = "Nevermind my injuries, brother. It's a miracle that any of us are alive!\n\nIt didn't look like you'd pull through; you've been in suspension for weeks.\n\nSomething happened and the Exodar crashed. Many have died.\n\nBut I'm relieved that you are alive, {name}. With you leading our efforts, I'm sure we'll get to safety soon! Proenitus asked me to send you to him when you awoke. He's waiting for you at the bottom of the hill. Just follow the path southwest.", objectives = "Speak with Proenitus at the Crash Site in Ammen Vale.", completion = "<name>, by my eternal soul, it is good to see you!  I don't know why the Exodar crashed.  Only those of us that were in this part of the ship remain.\n\nThere's not much time if we're to save everyone that we can!" }
WordHunterWoW_QuestEN[9280] = { title = "Replenishing the Healing Crystals", description = "Our immediate concern is the depleted state of our healing crystals.  We must replenish them quickly!\n\nUnfortunately, the only way to do this at this point is to extract the blood from the local vale moths.  Their blood will make for a suitable substitute.\n\nThe moths can be found in many places around the vale, but they are mostly concentrated in the northwest.", objectives = "Acquire 6 Vials of Moth Blood from the nearby Vale Moths and give them to Proenitus at the Crash Site in Ammen Vale.", progress = "<name>, have you harvested the necessary moth blood for the healing crystals yet?  With survivors scattered all over the vale, time is of the essence!", completion = "Regrettable that those creatures had to die so that we might live - indiscriminate killing is not the <race> way.  However, the blood you gathered will replenish our healing crystals, so their deaths will not be in vain." }
WordHunterWoW_QuestEN[9281] = { title = "Clearing the Way", description = "Magister Kaendris sent me down here to clear the area of any hostile wildlife.  Once this area is secured, the magisters plan to turn it into some sort of advance outpost against the Scourge.\n\nNow if there's one thing I've learned as an apprentice it's to delegate responsibility - especially in matters that endanger one's life!\n\nIf you're interested, I'll pay you well to kill the greater spindlewebs and ghostclaw ravagers to the west and south of here.", objectives = "Apprentice Vor'el at Andilien Estate in the Ghostlands wants you to slay 10 Greater Spindlewebs and 10 Ghostclaw Ravagers.", completion = "Thanks for giving me a hand, <name>.  I was dreading the thought of venturing into the woods this close to Deatholme." }
WordHunterWoW_QuestEN[9282] = { title = "The Farstrider Enclave", description = "Magisters and Farstriders may not see eye to eye all the time, {name}.  When it comes to Dar'Khan, however, we're all in agreement that a way must be found to defeat him and his legions.\n\nRanger Vynna, at the Farstrider Enclave northeast of here, has come across important information regarding our enemy.  Speak to her and see if you can be of assistance.  ", objectives = "Magister Kaendris, at the Sanctum of the Sun, wants you to talk to Ranger Vynna at the Farstrider Enclave in the Ghostlands.", completion = "Kaendris sent you?  I might have a task for you, <class>." }
WordHunterWoW_QuestEN[9283] = { title = "Rescue the Survivors!", description = "The healing crystals are replenished, but that is not the only way we can help the injured. All draenei can tap the gift of the Naaru to heal. You must use this ability to heal one of the crash survivors.\n\nYou'll find most of the survivors in the areas to the west and northwest, but the crash scattered us all over the vale.\n\nThe survivors have suffered from exposure to the irradiated power crystals, so you should be able to find them by the red glow that surround them.\n\nYou must save them, {name}.", objectives = "Use your Gift of the Naaru ability on one of the Draenei Survivors spread throughout Ammen Vale, then return to Zalduun at the Crash Site in Ammen Vale.", progress = "We'll survive this yet with your help.", completion = "The Light be praised! You've done what only a true hero could have done, <name>! The <race> you saved owes their continued life to your selflessness!\n\nPlease, take this supply pouch. You look like you can use it more than I." }
WordHunterWoW_QuestEN[9284] = { title = "Aldor Faction Test", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9285] = { title = "Consortium Faction Test", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9286] = { title = "Scryers Faction Test", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9287] = { title = "Paladin Training", description = "", objectives = "I am heartened by your initiative to speak with me.  In the past I was responsible for the training of young paladins as they entered our order.  This is a duty and privilege that I humbly take up once more.  Your name has been mentioned as one who seeks to do good in the name of the Light.  It would be my honor to guide you in your first steps as a <class>.\n\nShall we begin?Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9288] = { title = "Hunter Training", description = "", objectives = "I'm glad that you have come to me.  For quite some time now I have been responsible for the training of our young hunters, a responsibility that I intend to continue on this new world.  I've had my eye upon you for a while now and it would be my honor to help train you in the ways of the <class>.\n\nShall we begin?Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9289] = { title = "Warrior Training", description = "", objectives = "It is good that you seek my guidance.  For centuries I have taught young <race> warriors, so I may know a thing or two on how you should begin.  I see in you the makings of a great <class>, but only if you listen carefully to what I have to teach.\n\nAre you ready to learn, young <class>?Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9290] = { title = "Mage Training", description = "", objectives = "I am pleased that you have come seeking my knowledge. We have much to do if your magical skills are to be honed.\n\nFor over a hundred years I have taught the arcane, frost and fire magics, and I can feel them just as strongly on this world.  Would you like me to impart some of what I know to you?" }
WordHunterWoW_QuestEN[9291] = { title = "Priest Training", description = "", objectives = "It gives me great hope for our future that you come seeking my wisdom.  While I have my hands full here with our injured, I am not so busy that I cannot spare a moment to aid you in your first steps as a <class>.  To walk in the Light is the highest of callings, and one that I am certain you are more than ready to undertake!\n\nSpeak with me again when you feel that you are ready to begin your training." }
WordHunterWoW_QuestEN[9292] = { title = "Cracked Necrotic Crystal", description = "On the corpse of the fallen abomination, you discover a cracked crystal, slowly pulsing with necrotic energy.", objectives = "Bring the Cracked Necrotic Crystal to Lieutenant Orrin outside the gates of Stormwind." }
WordHunterWoW_QuestEN[9293] = { title = "What Must Be Done...", description = "The nearby lake has been contaminated by one of the ship's power crystals.  Many of the plants and animals of Ammen Vale have been mutated because of this.\n\nI have a theory on how to heal the lake, but I must have samples from the mutated lashers for analysis.  They can be found to the west in the Ammen Fields.\n\nWill you help me, {class}?", objectives = "Gather 10 Lasher Samples and return them to Botanist Taerix at the Crash Site in Ammen Vale.", progress = "I'll need all of the samples in good condition if we're to have a chance of cleansing the lake.\n\nWe don't have much time, <class>!", completion = "These will do. Thank you, <class>!\n\nWhile you were out, I managed to gather some equipment together to make an analysis of the samples.  This should only take a moment." }
WordHunterWoW_QuestEN[9294] = { title = "Healing the Lake", description = "Thank goodness, I think it'll work!  I have an agent for you to spread at Silverline Lake to the south.  It will neutralize the effects of the irradiated ship's power crystal that fell there.\n\nSwim out and scatter the neutralizing agent near it.  Don't worry, you won't be exposed long enough to become irradiated.", objectives = "Disperse the Neutralizing Agent at the Irradiated Power Crystal, then return to Botanist Taerix at the Crash Site in Ammen Vale.", progress = "The sooner you disperse the agent at the lake, the fewer native creatures that will be mutated by drinking the water, including ourselves!\n\nI'm sorry that we can't do anything to help the poor creatures that have already been infected.  If only my lab equipment were intact.", completion = "From what you describe, the neutralizing agent worked! I just wish that I knew how long it will last; we really need to remove that power crystal from the lake entirely.\n\nThank you, <name>! I will tell Tedon to try the neutralizing agent on one of the captured beasts at once." }
WordHunterWoW_QuestEN[9295] = { title = "Letter from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Torn Letter to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9296] = { title = "reuse", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", objectives = "Deliver the Dim Necrotic Stone to SOMEONE." }
WordHunterWoW_QuestEN[9297] = { title = "reuse", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", objectives = "Deliver the Dim Necrotic Stone to SOMEONE." }
WordHunterWoW_QuestEN[9298] = { title = "reuse", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", objectives = "Deliver the Dim Necrotic Stone to SOMEONE." }
WordHunterWoW_QuestEN[9299] = { title = "Note from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Careworn Note to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9300] = { title = "Page from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Ragged Page to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9301] = { title = "Envelope from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Bloodstained Envelope to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9302] = { title = "Missive from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Crumpled Missive to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9303] = { title = "Inoculation", description = "Zhanaa needs our help to salvage parts from the Exodar.  Taerix prepared an inoculum that can be given to the Nestlewood owlkin that live in the area of a lot of the salvage.\n\nJust get close to the unaffected ones and use the crystal on them.  Unfortunately, you'll have to kill the others.  You'll find the owlkin at Nestlewood Thicket and Nestlewood Hills to the southeast.", objectives = "Use the Inoculating Crystal on 6 Nestlewood Owlkin. Then return to Vindicator Aldar at the Crash Site in Ammen Vale.", progress = "The more we can do to clear up Nestlewood, the faster Zhanaa can get back to work.", completion = "With many of the owlkin now inoculated, we can focus on getting out of here and not have to worry about wiping out the owlkin population in the area.\n\nHere, choose from these.  You've done good work, and you deserve to be rewarded!" }
WordHunterWoW_QuestEN[9304] = { title = "Document from the Front", description = "You found this letter on one of the many Scourge minions you've slain. From its appearance and smell, it has been with the undead for some time. Perhaps someone at Light's Hope Chapel would be interested in examining it further...", objectives = "Take the Smudged Document to the Keeper of the Rolls at Light's Hope Chapel in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9305] = { title = "Spare Parts", description = "We managed to recover a damaged holographic emitter from the crash. If we repair it, we'll have a chance to find other survivors outside of Ammen Vale.\n\nThere were devices from the ship that could be salvaged for spare parts in the area, but the local owlkin carried them off before we could get to them. \n\n{name}, you must go south to Nestlewood Thicket and Hills to find the spare parts.", objectives = "Collect 4 Emitter Spare Parts and then return to Technician Zhanaa at the Crash Site in Ammen Vale.", progress = "When we have those spare parts, I know that we'll get this emitter repaired. With any luck there will be someone else out there left to talk to.", completion = "Let me take a look at those.\n\nYes, I think that these will do nicely; good job, <name>. The emitter is rather complex so it may take some time to finish the repairs. I'll let you know when it's ready.\n\nIn the meantime, you might see if Vindicator Aldar has anything he could use you for." }
WordHunterWoW_QuestEN[9306] = { title = "<DEPRECATED>Speak with Vindicator Aldar", description = "<name>, Vindicator Aldar has been looking for someone to take care of a problem that we're having with the mutated owlkin at Nestlewood Thicket.  We must deal with an unfortunate side effect of our unintended arrival here.\n\nYou'll find him outside to the south in the crash site. Please, speak with him as soon as you can.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Vindicator Aldar at the Crash Site in Ammen Vale.<name>, Vindicator Aldar has been looking for someone to take care of a problem that we're having with the mutated owlkin at Nestlewood Thicket. We must deal with an unfortunate side effect of our unintended arrival here.\n\nYou'll find him outside to the south in the crash site. Please, speak with him as soon as you can.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9307] = { title = "<DEPRECATED>Compassion", description = "Nearby Silverline Lake was contaminated by a piece of the ship that fell into it.  This in turn has caused the mutation of most of the creatures in the area, some of which have turned hostile.  The worst of these are the mutated owlkin.\n\nGo south into Nestlewood Thicket and put down as many of these pitiful creatures as you can.  It's a mercy killing, <class>, so please make it quick and painless.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 14 Mutated Owlkin and then return to Vindicator Aldar at the Crash Site in Ammen Vale." }
WordHunterWoW_QuestEN[9308] = { title = "<DEPRECATED>Blood Elf Remains?", description = "You believe that these are the remains of one of the sin'dorei -- a blood elf -- laying dead here on the ground.  By the look of it he fell victim to the savage claws of at least a few of the mutated owlkin in the thicket.\n\nSearching the body, you uncover an amulet on a chain around his neck.  Perhaps this would be of interest to Vindicator Aldar?Upon completion of this quest you will gain:", objectives = "Take the Blood Elf Amulet to Vindicator Aldar at the Crash Site in Ammen Vale." }
WordHunterWoW_QuestEN[9309] = { title = "The Missing Scout", description = "We now have several separate confirmations of unusual activity up on the Shadow Ridge.\n\nThis is disturbing; we thought that the scouting missions already undertaken had been thorough. One of my scouts hasn't reported back yet.\n\n{class}, I need you to head southwest to the other side of Silverline Lake and find Tolaan, and see what has delayed him.", objectives = "Find and speak with Tolaan at Shadow Ridge in Ammen Vale.", completion = "Help... blood elves!  They... ambushed... me.  Don't have... long." }
WordHunterWoW_QuestEN[9310] = { title = "Faint Necrotic Crystal", description = "On the corpse of the fallen wight, you find a crystal faintly radiating necrotic energy.", objectives = "Bring the Faint Necrotic Crystal to Lieutenant Rukag in the courtyard of the Undercity." }
WordHunterWoW_QuestEN[9311] = { title = "Blood Elf Spy", description = "I have a plan. We must kill their leader. Without their master, perhaps they will retreat to regroup. We just need to buy time until the repairs are completed.\n\nThen Vindicator Aldar must know of this. Kill the surveyor, then return and tell him what we've found.", objectives = "Slay Surveyor Candress and then inform Vindicator Aldar at the Crash Site in Ammen Vale.", completion = "I thank you for dealing with the blood elf surveyor.  Surely she was their leader.  Rest assured, we will deal with whatever remnant of them is still nearby.\n\nPlease, take one of these weapons as a sign of my gratitude." }
WordHunterWoW_QuestEN[9312] = { title = "The Emitter", description = "{name}, while you were out investigating the Shadow Ridge, Zhanaa here has been going on about the holographic emitter.  You might want to speak with her.", objectives = "Speak with Technician Zhanaa at the Crash Site in Ammen Vale.", completion = "I got it, I got it!  I think I managed to fix the emitter!  Here, I'll just activate this last crystal and that should do it.\n\nTake a look at the emitter, <name>.  It looks like it's beginning to work... someone is appearing!" }
WordHunterWoW_QuestEN[9313] = { title = "Travel to Azure Watch", description = "By all that is good, {name}, you must go at once to this Azure Watch and speak with Dyvuun!\n\nThere is a path that leads west off of this tiny isle.  Follow it and cross the Crystalbrook River to arrive on the larger part of the isle.  Continue to follow the path and you should find Azure Watch.\n\nSee if you can convince them to send us some aid and supplies.  The rest of us will follow when we can.\n\nThank you, we wouldn't have made it without you!", objectives = "Speak with Technician Dyvuun at Azure Watch on Azuremyst Isle.", completion = "Ah, good to see you again!  I'm glad that we were both able to get our emitters fixed or we might never have found one another.  And don't worry, we'll see to it that Ammen Vale gets help and supplies.\n\nSpeaking of assistance, now that you're here, go around and introduce yourself to the others.  I know that there's plenty to do." }
WordHunterWoW_QuestEN[9314] = { title = "Word from Azure Watch", description = "{class}! A couple mutated beasts jumped me and my leg is injured.\n\nI was sent on a scouting mission from Azure Watch after we received word from Zhanaa. Please, could you go speak with Caregiver Chellan in my stead? She needs to know how many people to expect in Azure Watch. Just cross the Crystalbrook River here and continue following the road until you get to Azure Watch.\n\nBe sure to ask her for a place for yourself to stay in.", objectives = "Speak with Caregiver Chellan at Azure Watch on Azuremyst Isle.", completion = "Oh, you must be one of the survivors we've been hearing about!\n\nI'm glad that you came. Don't worry, we will send someone to see to Aeun's injured leg.\n\nI'm most interested in hearing all about your harrowing story of survival. You're a brave one to have made it all the way here." }
WordHunterWoW_QuestEN[9315] = { title = "Anok'suten", description = "Come closer, I am ... dying.\n\nI was sent here ... to slay these Nerubians, but Vandril didn't ... know that they have a leader.\n\n<The dying blood elf coughs up a good amount of blood.>\n\nYou must find and ... slay Anok'suten.  Get help.  She wanders around ... Suncrown Village.", objectives = "Slay Anok'suten and return to Arcanist Vandril at Tranquillien in the Ghostlands.", completion = "I apologize for the shoddy intelligence, <class>.  Had I known of this Anok'suten ahead of time, I surely would have told you.\n\nWe're spread too thin and things are slipping through the cracks!" }
WordHunterWoW_QuestEN[9317] = { title = "Consecrated Sharpening Stones", description = "", objectives = "" }
WordHunterWoW_QuestEN[9318] = { title = "Blessed Wizard Oil", description = "", objectives = "" }
WordHunterWoW_QuestEN[9319] = { title = "A Light in Dark Places", description = "We are not the only ones who celebrate this holiday, {name}. All creatures, all cultures, are touched by the flame. Even in the darkest places, the fires are being lit.\n\nIf you wish to see them for yourself, travel into the depths. Seek out the bonfires burning within Stratholme, Scholomance, among the ogres of Dire Maul, and the halls of Blackrock Spire itself; I will await your return.", objectives = "Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then return to the Festival Flamekeeper." }
WordHunterWoW_QuestEN[9320] = { title = "Super Mana Potion", description = "", objectives = "" }
WordHunterWoW_QuestEN[9321] = { title = "Super Healing Potion", description = "", objectives = "" }
WordHunterWoW_QuestEN[9322] = { title = "Wild Fires in Kalimdor", description = "The Midsummer Fire Festival is celebrated everywhere in Azeroth, and the diverse land of Kalimdor is no exception. You look fit to travel -- perhaps a journey is in order.\n\nMidsummer cannot be truly appreciated unless you've seen the blistering blue fires abroad. The celebrants have lit fires in chilly western Winterspring, northeastern Azshara, near Valor's Rest in the wastes of Silithus, and by the entrance to lush Un'Goro. Return once your journey is complete.", objectives = "Visit the Midsummer camps located in Azshara, Silithus, Un'Goro Crater, and Winterspring, then return to the Festival Flamekeeper." }
WordHunterWoW_QuestEN[9323] = { title = "Wild Fires in the Eastern Kingdoms", description = "Our celebration of the flame is spread throughout the land, {class}. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue. Seek them out.\n\nYou'll find one just north of Blackrock Spire. The others are located deep within the Eastern Plaguelands near a decrepit town, along the road to the cliffs within the mountainous Hinterlands, and on the way to the Dark Portal within the Blasted Lands.\n\n Return once your journey is done.", objectives = "Visit the Fire Festival camps located in Blasted Lands, Eastern Plaguelands, the Hinterlands and Searing Gorge, then speak with the Festival Flamekeeper." }
WordHunterWoW_QuestEN[9324] = { title = "Stealing Orgrimmar's Flame", description = "This flame, stolen from the heart of Orgrimmar itself, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", objectives = "Return the Flame of Orgrimmar to the Festival Loremaster.", progress = "You're practically glowing, <race>. What do you have there?", completion = "What's this? Unless I'm mistaken, this flame has been taken from the heart of Orgrimmar itself! The fierce hearts of the orcs and trolls are reflected in its searing heat. What a fine addition to our collection--how brave you are, stealing into the enemy's lair to retrieve the sacred flame!\n\nI wonder what power lurks in the other cities..." }
WordHunterWoW_QuestEN[9325] = { title = "Stealing Thunder Bluff's Flame", description = "This flame, stolen from the shaman of Thunder Bluff, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", objectives = "Return the Flame of Thunder Bluff to the Festival Loremaster.", progress = "You're practically glowing, <race>. What do you have there?", completion = "Unless I miss my guess, this fire has been taken from the cliffs of Thunder Bluff! How it sings with the power of the spirits! You are quite the thief, <name>. Take this as just payment for your skill. Now, if only we had the flames of all four cities..." }
WordHunterWoW_QuestEN[9326] = { title = "Stealing the Undercity's Flame", description = "This flame, stolen from the ruins above the Undercity, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", objectives = "Return the Flame of the Undercity to the Festival Loremaster.", progress = "You're practically glowing, <race>. What do you have there?", completion = "Hm... what a strange fire! It is subdued, nearly smoldering, but the heat is intense. And you received this from the Undercity, you say? Fascinating. With the flames of all four cities, who knows what we could accomplish?" }
WordHunterWoW_QuestEN[9327] = { title = "The Forsaken", description = "I know it seems strange, but these Forsaken are here to help. You should speak with their leader, High Executor Mavren. He's in the tower on the west side of town.\n\nAnd, {class}, when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!", objectives = "Speak with High Executor Mavren at Tranquillien in the Ghostlands.", completion = "I know that we Forsaken appear monstrous to your eyes, but I assure you we mean your people no harm. We are here because of a common enemy: Dar'Khan the traitor! He has returned and now commands the Scourge that are invading this land from his steadfast, Deatholme, to the south.\n\nOur leader, Lady Sylvanas Windrunner, originally hails from these lands, and in fact used to be an elf. She has a history with Dar'Khan and wants him dead as much as your people do.\n\nWe will defeat him together, <class>!" }
WordHunterWoW_QuestEN[9328] = { title = "Hero of the Sin'dorei", description = "This is the beginning of a new chapter in the history of our race, {name}.  Our lands will be reclaimed and we shall cement our bond with Sylvanas and her allies.\n\nTake the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City.  He'll be eager to hear the news.", objectives = "Take Dar'Khan's Head to Lor'themar Theron in Silvermoon City.", progress = "You seek audience with me, <class>?  I do not recall hearing of an appointment.", completion = "Now that's one face I was not expecting to see so soon.\n\nThis is quite the good news, <name>, in more ways than you can imagine." }
WordHunterWoW_QuestEN[9329] = { title = "The Forsaken", description = "I know it seems strange, but the Forsaken are here to help. You should speak with their leader, High Executor Mavren.  He's in the tower on the west side of town.\n\nAnd, {class}, when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!", objectives = "Speak with High Executor Mavren at Tranquillien in the Ghostlands.", completion = "We Forsaken are here because of a common enemy with the blood elves: Dar'Khan!  He has returned and now commands the Scourge that are invading this land from his steadfast, Deatholme, to the south.\n\nLady Sylvanas Windrunner, who originally hails from these lands, and used to be an elf, has a history with Dar'Khan and wants him dead!\n\nWe will defeat him, <class>, and you will help us do it!" }
WordHunterWoW_QuestEN[9330] = { title = "Stealing Stormwind's Flame", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", objectives = "Return the Flame of Stormwind to the Festival Talespinner.", progress = "You're practically glowing, <race>. What do you have there?", completion = "And this brightly-burning fire... you say it came from Stormwind? Remarkable! That must have been quite an adventure! I'll pay you for this, of course. If you find anything else like this, be sure to speak with me again." }
WordHunterWoW_QuestEN[9331] = { title = "Stealing Ironforge's Flame", description = "This flame, stolen from the heart of Ironforge itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", objectives = "Return the Flame of Ironforge to the Festival Talespinner.", progress = "You're practically glowing, <race>. What do you have there?", completion = "This hearty flame must be from the halls of Ironforge; it's as stalwart as the dwarves themselves. A fine catch, <name>. If I had the fires of the other cities... ah, but never mind. Here is your payment." }
WordHunterWoW_QuestEN[9332] = { title = "Stealing Darnassus's Flame", description = "This flame, stolen from the shores of Teldrassil, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", objectives = "Return the Flame of Darnassus to the Festival Talespinner.", progress = "You're practically glowing, <race>. What do you have there?", completion = "This fire aches of ancient sorrow, <name>. You pulled this from the roots of Teldrassil, you say? Fascinating! Here is a reward for your skill. Return to me should you find anything else like this; I may have a use for it." }
WordHunterWoW_QuestEN[9333] = { title = "Argent Dawn Gloves", description = "", objectives = "" }
WordHunterWoW_QuestEN[9334] = { title = "Blessed Wizard Oil", description = "", objectives = "" }
WordHunterWoW_QuestEN[9335] = { title = "Consecrated Sharpening Stones", description = "", objectives = "" }
WordHunterWoW_QuestEN[9336] = { title = "Super Healing Potion", description = "", objectives = "" }
WordHunterWoW_QuestEN[9337] = { title = "Super Mana Potion", description = "", objectives = "" }
WordHunterWoW_QuestEN[9338] = { title = "Allegiance to Cenarion Circle", description = "", objectives = "Even if you have no need for the material rewards we offer, these badges still mark our mutual trust and friendship.\n\nBring them to me.  I'll make due note of your service should your performance go above and beyond the call of duty.", progress = "Even if you have no need for the material rewards we offer, these badges still mark our mutual trust and friendship.\n\nBring them to me.  I'll make due note of your service should your performance go above and beyond the call of duty.", completion = "You honor us, <name>.  With your continued efforts we will overcome all obstacles." }
WordHunterWoW_QuestEN[9339] = { title = "A Thief's Reward", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more...", objectives = "You've proven yourself, today, <name>.\n\nWhile I have little else to give you, I do have this crown; a fitting gift for a conqueror. May it light your way." }
WordHunterWoW_QuestEN[9340] = { title = "The Great Fissure", description = "We're dangerously close to becoming fenced in by Alliance forces.  With the influx of sin'dorei pilgrims from Azeroth, we must establish a route that's safe from our enemies' prying eyes.\n\nI've given it some thought and have arrived at a solution.  We're to establish a secret path through the Great Fissure.\n\nYes, even though the area is crawling with brutal rock flayers, they are merely beasts and can be taught to fear us.  I want you to go and kill a good number of them.  They shall learn fear.", objectives = "Ranger Captain Venn'ren at Falcon Watch wants you to slay 8 Stonescythe Whelps and 3 Stonescythe Alphas at the Great Fissure, east of Falcon Watch.", completion = "Good job, <name>.  That should teach the rock flayers to stay far away from us." }
WordHunterWoW_QuestEN[9341] = { title = "Tabard of the Argent Dawn", description = "", objectives = "" }
WordHunterWoW_QuestEN[9342] = { title = "Marauding Crust Bursters", description = "As if the gan'arg that overran the mines aren't bad enough, now we've got gigantic worms encroaching on us from the other direction!\n\nWith Thrallmar's garrison pinned down defending against the Legion and tending to their wounded, it leaves me and the miners to deal with the problems.\n\n<The foreman gestures at the sleeping peons.>\n\nAnd you can see how useful they are...\n\nI'd gladly pay you their wages to clear out some of those worms.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Foreman Razelcraz at the mines near Thrallmar wants you to kill 15 Marauding Crust Bursters. The worms have a tendency to attack suddenly from their tunnels below ground." }
WordHunterWoW_QuestEN[9343] = { title = "Tabard of the Argent Dawn", description = "", objectives = "" }
WordHunterWoW_QuestEN[9344] = { title = "A Hasty Departure", description = "Greetings, <name>. Outland is a perilous place, as many of our expedition quickly learned. I'm afraid young Grelag may have learned that lesson firsthand.\n\nGrelag is a promising student, but he lacks patience! He eagerly studies the history of his people, but he sometimes forgets the threats of the present day.\n\nHe departed for the Spinebreaker Post, ignorant of the Legion and fel orc presences. I fear something may have happened to him.You will receive:", objectives = "Far Seer Regulkut wants you to track down her student Grelag.Greetings, <name>. Outland is a perilous place, as many of our expedition quickly learned. I'm afraid young Grelag may have learned that lesson firsthand.\n\nGrelag is a promising student, but he lacks patience! He eagerly studies the history of his people, but he sometimes forgets the threats of the present day.\n\nHe departed for the Spinebreaker Post, ignorant of the Legion and fel orc presences. I fear something may have happened to him.You will receive:" }
WordHunterWoW_QuestEN[9345] = { title = "Preparing the Salve", description = "Just as Zeth'Gor came into view, a Legion patrol caught sight of me. I ran, hoping to duck into one of the towers in the distance, but one of their felhounds caught up with me and nearly hamstrung me!\n\nI managed to escape, but my leg is in terrible shape. Stone Guard Ambelan found me and brought me here.\nNow, I have to find a way to tend to my leg. Spineleaf grows in and around the Valley of Bones to the north . A salve made from it will dull the pain enough for me to travel.", objectives = "Gather 12 Hellfire Spineleaf plants for a salve and return to Grelag at Spinebreaker Post.", progress = "Have you brought the plants?", completion = "These should do the job. I'm going to prepare the salve and finish my splint before making my way back to Thrallmar. Why do I have the feeling that I know what Far Seer Regulkut will say when she sees me?\n\n<Grelag sighs half-heartedly.>\n\nThank you for your help, <name>. I have some of the spineleaf left over. You're welcome to take it with you. Who can tell when it will prove useful?" }
WordHunterWoW_QuestEN[9346] = { title = "When Helboars Fly", description = "Have you ever seen a helboar fly? They don't even need wings!\n\n<Watch Commander Krunk laughs.>\n\nThe fight against the Legion camps to the north has depleted our supplies, including catapult ammunition. This is the perfect opportunity to try something new.\n\nInstead of using boulders, I want to try igniting the corpses of the starving helboars I've seen around the eastern ruins and use them to bombard the Legion's camps.\n\nAre you going to volunteer, or do I have to order you?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Watch Commander Krunk in Thrallmar wants you to bring him 10 Plump Helboar Carcasses from Starving Helboars." }
WordHunterWoW_QuestEN[9347] = { title = "Voidwalkers Gone Wild", description = "Examining the essence reveals violent swirls of energy sealed within a vessel made of unidentifiable material. As you consider it, you can feel it beginning to tug at your mind, inviting you to come closer and to look deeper.\n\nFeeling your will begin to slip away, you break your gaze immediately. Its presence remains at the edge of your consciousness as you determine what to do with it.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Pulsating Voidwalker Essence to Mahuram Stouthoof in Thrallmar." }
WordHunterWoW_QuestEN[9348] = { title = "Ravager Roundup", description = "Outland is rife with fascinating creatures. Fascinating -- and extremely dangerous.\n\nThe area is rich with predators, which seems strange for such a barren land, but a closer look reveals something of a hierarchy.\n\nThe rock flayers seem to have domesticated another predator, the ravager, and breed them as hunting companions and guard animals. I need to know more about how they're training these ravagers. We must shut down and examine their breeding site to the southwest, near the Terokkar Forest.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay 10 Captive Ravager Hatchlings and retrieve 12 Ravager Eggs for Mahuram Stouthoof in Thrallmar." }
WordHunterWoW_QuestEN[9349] = { title = "Ravager Egg Roundup", description = "I'm starving!\n\nThere's irony in that, wouldn't you say?  A starving cook?\n\n<Legassi laughs half-heartedly and taps a folded piece of parchment he has in his pocket.>\n\nAccording to this tourist map we were following - before we were so rudely shot down - there's an area to the southwest, near Terokkar Forest.  It's called the Razorthorn Trail, and supposedly it's brimming with delicious ravager eggs!\n\nI could cook up quite a feast if only someone were brave enough to go down there and get me some!", objectives = "Retrieve 12 Ravager Eggs for Legassi at the Zeppelin Crash in Hellfire Peninsula.", progress = "You have those eggs yet?\n\n<Legassi's stomach grumbles in anticipation.>", completion = "In order to have great cuisine, you need to have great ingredients.  And these eggs look great!\n\nI've just finished cleaning off my frying pan, so you're more than welcome to join me for a meal!" }
WordHunterWoW_QuestEN[9350] = { title = "A Peon's Work is Never Done", description = "The Legion's constant assaults take a heavy toll on our defenses. If the palisade falls, so will Thrallmar. I've assigned peons to reinforce and repair the walls, but we're running out of materials.\n\nGrelag, one of the Far Seer's students, is well versed in the old ways and suggested returning to an ancient practice. Long ago, the clefthoof hunt supplied us with meat, hides, and bones. Taking up the hunt again, with the clefthoof to the southeast, would provide what's needed and honor the ancestors.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Gather 8 Clefthoof Hides and 8 sets of Clefthoof Bones from the Raging Clefthoof. Return to Watch Commander Krunk in Thrallmar once you have all the materials." }
WordHunterWoW_QuestEN[9351] = { title = "Voidwalkers Gone Wild", description = "Even if I can get the zeppelin's frame repaired, I'll have to find something else to power the engine. I'm all out of fuel and there's no place to fill up around here!\n\nTo the south of us is an area of broken land called the Warp Fields. It's full of rogue and uncontrolled voidwalkers, but I like to think of them as walking batteries.\n\nIf you can bring me enough of their essence, I can convert the zeppelin's engine to run on it. Five gold says I'll even get better mileage out of it, too!", objectives = "Bring 10 Condensed Voidwalker Essences to \"Screaming\" Screed Luckheed at the Zeppelin Crash.", progress = "Were you able to get the essence?", completion = "This is perfect! In fact, I think it's going to work so well, I might just have to redesign the engine to take advantage of all this extra power. If, I mean, when we get out of here, I'll have to show my design to everyone back at Area 52!" }
WordHunterWoW_QuestEN[9352] = { title = "Darnassian Intrusions", description = "Besides the constant threat that the Wretched represent, I also have to deal with all kind of fictitious reports of night elf sightings.\n\nThough most reports are unfounded, one recent incident demands further investigation.  The West Sanctum, one of our primary energy sources, has suffered a terrible malfunction and rumors of Darnassian sabotage are rampant.\n\nTravel there and deal with anyone that looks suspicious.  Report back to Ley-Keeper Velania, who watches over the sanctum.", objectives = "Travel to the West Sanctum, southwest of Falconwing Square and defeat any intruders present there. Report your findings to Ley-Keeper Velania.", completion = "Night elves?  Here?  Those rats!\n\nDo you suppose they had anything to do with the malfunction in my sanctum?  If you have any information, you'd better take it to Captain Sunbrand at once!" }
WordHunterWoW_QuestEN[9353] = { title = "Redeem iCoke Gift Box Voucher", description = "", objectives = "" }
WordHunterWoW_QuestEN[9354] = { title = "Searching for New Materials", description = "<The dwarf looks up from his work expectantly.>\n\nIf you're looking to commission a piece, get in line, <class>. I've got my hands full maintaining the Sons' equipment and preparing us for the day when we'll take the battle to the enemy again.\n\nOur metal stocks are getting very low since crust borers invaded the mines. I've been experimenting with natural materials from the raging clefthoof that graze in the areas northeast of the Hold, and while they're no substitute for iron, I'm learning to make do.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Gather 8 Clefthoof Hides and 8 Clefthoof Sinews from the Raging Clefthoof. When you have the materials, bring them to Humphry in Honor Hold." }
WordHunterWoW_QuestEN[9355] = { title = "A Job for an Intelligent Man", description = "Well met, {class}. Now that reinforcements are finally arriving, we can recapture some semblance of a normal life.\n\nOne of our first goals is to restore the flow of men and goods along the road to the southwest, but it must be reclaimed from the crust bursters that've overrun the area.\n\nIf you're willing to help us deal with this menace, you would have the gratitude of the Sons. Watch carefully for the disturbed ground they leave in their wake.", objectives = "Kill 15 Marauding Crust Bursters and return to Foreman Biggums at Honor Hold.", progress = "Were you able to clear the road?", completion = "Well done, <name>. We shouldn't be too quick to congratulate ourselves, though. I'm certain we haven't seen the last of those worms. If they show their hideous heads around these parts again, the Sons'll be ready for them!" }
WordHunterWoW_QuestEN[9356] = { title = "Smooth as Butter", description = "Screed likes to say his flying is as \"smooth as butter.\" I think \"butterfingered\" is more like it!\n\nTake a look at the wreckage over there. He calls it a \"rough\" landing.\n\nSure, we got shot at, but I'd be willing to cut him a little more slack if he didn't brag about his piloting skills so often!\n\nI think I'm going to make him a batch of wings to drive the point home. To the east, in the Valley of Bones, you'll find bonestripper buzzards. Their wings are plump, juicy, and perfect for my needs.", objectives = "Bring 12 Plump Buzzard Wings to Legassi at the Zeppelin Crash.", progress = "I can't wait to see the look on his face when he digs in. Ever since the crash, he's been complaining that all I can think of is food. Well, someone's got to feed us while he tinkers with the zeppelin!", completion = "Ravager Eggs.  Bam!\n\nHellboar Bacon. Bam!\n\nBuzzard Wings. Bam!  Bam!\n\nWhat a great meal.  You've really got to try it." }
WordHunterWoW_QuestEN[9357] = { title = "Report to Aeldon Sunbrand", description = "If you're looking for work, you'll find Captain Sunbrand inside the Inner Elf Gate, through the doors behind me.\n\nNow leave me be, I must question this scoundrel.Upon completion of this quest you will gain:", objectives = "Report to Aeldon Sunbrand at the Inner Elf Gate in Eversong Woods.If you're looking for work, you'll find Captain Sunbrand inside the Inner Elf Gate, through the doors behind me.\n\nNow leave me be, I must question this scoundrel.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9358] = { title = "Ranger Sareyn", description = "Don't take the safety of this village for granted.  We're under siege by the Scourge on the east and the Wretched to the west.\n\nRanger Sareyn keeps our borders safe from the undead that pour in from the Dead Scar.  Follow the road eastwards out of town and see if you can lend her a hand.", objectives = "Report to Ranger Sareyn outside Fairbreeze Village in Eversong Woods.", completion = "You're here to help us?  Why didn't you say so earlier?  We can always use a hand!" }
WordHunterWoW_QuestEN[9359] = { title = "Farstrider Retreat", description = "Your help in subduing the Wretched has been invaluable.  The Farstriders would surely have use for someone like you in their fight against the Amani trolls.\n\nLook for the Farstrider Retreat to the northeast of here, speak to Lieutenant Dawnrunner and see what assistance she might need.", objectives = "Report to Lieutenant Dawnrunner at the Farstrider Retreat in Eversong Woods.", completion = "You're here to help?  Excellent!\n\nThe battle against the Amani trolls has taken its toll on us and capable fighters such as yourself are always welcome." }
WordHunterWoW_QuestEN[9360] = { title = "Amani Invasion", description = "Though you don't understand the language in these battle plans, you clearly make out a map marking the positions of the Farstrider Retreat and Fairbreeze Village.\n\nYou'd best let Lieutenant Dawnrunner at the Farstrider Retreat know about this.", objectives = "Deliver the Amani Invasion Plans to Lieutenant Dawnrunner at Farstrider Retreat.", progress = "What do you want to show me?", completion = "The trolls have been keeping us pinned here while planning an attack on Fairbreeze Village.  We were not expecting this at all." }
WordHunterWoW_QuestEN[9361] = { title = "Helboar, the Other White Meat", description = "Those eggs are superb, but what do you say we kick it up another notch?\n\nA side of bacon would round out the meal perfectly and I know just where to get it.\n\nThis place is littered with helboars. Of course, there's no one here to inspect and tenderize the meat, but we're in luck!\n\n<Legassi rummages around in his pack and produces a flask.>\n\nThis wasn't made for use on pork, but cooking is as much about improvisation as anything else!", objectives = "Legassi at the Zeppelin Crash wants you to gather 8 Purified Helboar Meat. To purify the meat, use the Purification Mixture on the Tainted Helboar Meat you gather from Helboars.", progress = "Were you successful in purifying the helboar meat?", completion = "Hmm...\n\nThis looks edible, if spiced properly. Just don't tell Screed where his breakfast came from, ok?" }
WordHunterWoW_QuestEN[9362] = { title = "Warlord Krellian", description = "There isn't much time, {name}!  My scrying spells have revealed a powerful source of magic.  I cannot leave the tower, and would ask you to kill the vile creature in possession of this artifact.\n\nThe pathetic little cretin is known as Warlord Krellian, hiding behind his guards in the Temple of Zin-Malor.  Burn him to ashes and take the prismatic shell he covets so dearly.", objectives = "Retrieve the Prismatic Shell for Archmage Xylem. The Archmage resides in a tower atop the cliffs of Azshara.", progress = "There is not time to waste!  Have you the shell?", completion = "I must say, this shell has a strange aura.  It seems only fitting that part of your reward for retrieving it would be to test its magical capabilities..." }
WordHunterWoW_QuestEN[9363] = { title = "Warning Fairbreeze Village", description = "Go to Fairbreeze Village and notify Ranger Degolien of the Amani plans.  Even with Zul'Marosh dead, Fairbreeze must prepare for a troll attack.  Tell Degolien I will send him reinforcements as soon as possible.", objectives = "Travel to Fairbreeze Village in Eversong Woods and speak to Ranger Degolien.", completion = "The information you've brought is of vital importance, <name>.  Now that we know of the trolls' plans we can prepare for an attack.\n\nWe won't be caught with our guard down." }
WordHunterWoW_QuestEN[9364] = { title = "Fragmented Magic", description = "My research has revealed a unique purpose for the prismatic shell.\n\nCarry the shell and cast your polymorph spell on the Spitelash in Azshara.  If you wait a few moments, the chaotic aura of the shell will cause them to split into several smaller clones for a few moments.  Kill these clones as quickly as possible, and the shell will collect their essence.\n\nWhen the shell is full, return it to me.", objectives = "Polymorph the Spitelash of Azshara and kill the clones that appear several seconds later. When you have slain 50 Polymorph Clones, return to Archmage Xylem in Azshara.", progress = "Have you collected the magic?", completion = "Splendid!  Splendid!\n\nNow we are able to reform this magic into a new spell.  Behold!" }
WordHunterWoW_QuestEN[9365] = { title = "A Thief's Reward", description = "This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more...", objectives = "You've proven yourself, today, <name>.\n\nWhile I have little else to give you, I do have this crown; a fitting gift for a conqueror. May it light your way." }
WordHunterWoW_QuestEN[9366] = { title = "In Need of Felblood", description = "Northeast of here lie the Pools of Aggonar.  Once a sacred site to the draenei, their waters were corrupted after the blood from the demon Aggonar was spilled into them.\n\nThat blood, though old and diluted, still possesses tremendous power.  Terrorfiends now walk the area, empowered by the pure demonic energies of the original blood.  Slay them and retrieve as much felblood as you can.  I'll make it worth your while.", objectives = "Ryathen the Somber at Falcon Watch in Hellfire Peninsula wants you to bring him 6 Felblood Samples from the Terrorfiends that inhabit the Pools of Aggonar.", progress = "The felblood... did you obtain it, <name>?", completion = "The energy contained in these samples is tremendous, <name>.  Now we just need to ensure that our access to this felblood continues uninterrupted." }
WordHunterWoW_QuestEN[9367] = { title = "The Festival of Fire", description = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!", objectives = "Touch the bonfires within Stormwind, Ironforge, and Darnassus, then speak to a Festival Loremaster within the capital cities." }
WordHunterWoW_QuestEN[9368] = { title = "The Festival of Fire", description = "Midsummer is upon us once again!\n\nEach year, as tradition dictates, Flamekeepers are chosen to tend the bonfires within our capitals. While fires are burning throughout Azeroth, it is imperative that ours be the hottest and brightest, to properly pay homage to the season.\n\nIn fact, I have a task for you, if you don't mind. I've not yet heard if the fires in all capitals are properly burning. Travel there yourself and warm yourself by the fires--make sure they're hot!", objectives = "Touch the bonfires within Orgrimmar, Thunder Bluff, and the Undercity, then speak to a Festival Talespinner within the capital cities." }
WordHunterWoW_QuestEN[9369] = { title = "Replenishing the Healing Crystals", description = "We are the draenei.  Our ship crashed and, since we have many wounded, our immediate concern is the depleted state of our healing crystals.  We must replenish them quickly!\n\nUnfortunately, the only way to do this at this point is to extract the blood from the local vale moths.  Their blood will make for a suitable substitute.\n\nThe moths can be found in many places around the vale, but mostly in the northwest.", objectives = "Acquire 6 Vials of Moth Blood from the nearby Vale Moths and bring them to Proenitus at the Crash Site in Ammen Vale.", progress = "Have you harvested the necessary moth blood for the healing crystals yet?  With survivors scattered all over the vale, time is of the essence!", completion = "Regrettable that those creatures had to die so that we might live - indiscriminate killing is not the draenei way.  However, the blood you gathered will replenish our healing crystals, so their deaths will not be in vain." }
WordHunterWoW_QuestEN[9370] = { title = "The Cleansing Must Be Stopped", description = "Our scouts captured a draenei paladin at the Pools of Aggonar.  He was to take part in a cleansing ritual to purify the pools.  We must stop the draenei from succeeding or we will lose our supply of felblood!\n\nHe was carrying this signaling gem, looking to mark a spot where a priest - or \"anchorite\" as they call themselves - could perform their rituals in safety.  Place the gem near the Altar of Aggonar and be ready to ambush any approaching draenei.\n\nI suggest that you take a friend or two along.", objectives = "Place the Signaling Gem near the Altar of Aggonar at the Pools of Aggonar and defeat any Draenei Anchorites that respond to your summons. Return to Ryathen the Somber at Falcon Watch with the Signaling Gem after completing this task.", progress = "You've returned, <name>.  Did you put an end to the draenei's folly?", completion = "That'll show those holy fanatics to mind their own business." }
WordHunterWoW_QuestEN[9371] = { title = "Botanist Taerix", description = "{name}, Botanist Taerix is in need of your assistance. You'll find her with her apprentices to the west, outside the ship.", objectives = "Speak with Botanist Taerix at the Crash Site in Ammen Vale.", completion = "Oh, thank goodness you've come.  We have much to do." }
WordHunterWoW_QuestEN[9372] = { title = "Demonic Contamination", description = "Welcome to the Cenarion Post, {class}. We don't often get company out here, but I'm grateful for the visit. My work with the creatures of this desolate land requires me to travel to many remote places.\n\nThe Cenarion Expedition has dispatched me to study some of the most dangerous wildlife in Outland, and I've made a startling discovery. While many creatures here have already undergone radical changes, they continue to mutate. I'm collecting blood samples to document the changes, and any help would be welcome.", objectives = "Thiah Redmane, at the Cenarion Post in Hellfire Peninsula, has asked you to gather 6 Helboar Blood Samples from Hulking Helboars.", progress = "Were you able to collect the blood samples?", completion = "Well done, <name>. These blood samples will prove helpful in my research and in the Expedition's wider studies of Outland's creatures.\n\nIf I could isolate what causes these creatures to change continuously, perhaps I could concoct an antidote." }
WordHunterWoW_QuestEN[9373] = { title = "Missing Missive", description = "Upon examining the battered leather case, it becomes apparent that the container's damage must've been caused by the caustic fluid of the worm's digestive tract. The leather appears to have been intricately tooled at one time, but the details of its adornment can no longer be made out.\n\nThe only recognizable feature of the case is a worn logo of the Cenarion Circle. Knowing nothing about the contents of the case, you decide the best course of action would be to deliver it to a Circle member.", objectives = "Return the Eroded Leather Case to Thiah Redmane, camped near the Ruins of Sha'naar in western Hellfire Peninsula.", progress = "Good day, <class>. What brings you to my encampment?", completion = "Thank you for bringing this to me, <class>. I was wondering why I hadn't heard from the Expedition in so long. I wonder how long ago this message was dispatched and what befell its carrier.\n\nHere's a bit of coin for your trouble." }
WordHunterWoW_QuestEN[9374] = { title = "Arelion's Journal", description = "My husband, Arelion, had been fascinated with the Pools of Aggonar ever since we arrived in Outland.  He spent much of his time studying slimes, of all things!\n\nHe went missing in there a few days ago.  They say he's dead and there's nothing I can do about it.\n\nOne thing I can do is try to ensure that his research doesn't die with him.  Go northeast to the pools and look for his journal.  He always carried it inside a brown knapsack.", objectives = "Magistrix Carinda at Falcon Watch in Hellfire Peninsula wants you to go to the Pools of Aggonar and retrieve Arelion's Journal.", progress = "Any luck, <name>?  You'll find the Pools of Aggonar north of Hellfire Citadel.", completion = "My husband's journal... it's not about research at all!\n\nHow could I've been such a fool?  \"Magical properties of fel-infused slime forms,\" he really had me going there." }
WordHunterWoW_QuestEN[9375] = { title = "The Road to Falcon Watch", description = "<The battered blood elf's face displays relief at your presence.>\n\nPlease, {class}, get me out of this cage! I foolishly set out from Thrallmar ahead of the main group, despite Martik Tor'seldori's warnings.\n\nI was set upon by horrible creatures that could only be the ravagers he talked about. I managed to drive them off, but that was only the beginning of my troubles.\n\nAs I bound my wounds, those bird men found me, dragged me back to this cave, and locked me in this cage! I must get to Falcon Watch!", objectives = "Protect the Wounded Blood Elf Pilgrim on her way to Falcon Watch, then speak with Taleris Dawngazer.", completion = "<Taleris shouts to several of the blood elves at the outpost.>\n\nGet her inside and see to her wounds!\n\n<Taleris turns back to you.>\n\nShe's fortunate that you found her when you did, <class>. I don't think she'd have lasted much longer out there.\n\nCan you make out what she was saying?" }
WordHunterWoW_QuestEN[9376] = { title = "A Pilgrim's Plight", description = "That wounded pilgrim seems to be shouting something about a pack.\n\nWhen you encountered her, did you see a pack nearby? Hmm...\n\nShe must've left it when fleeing from her attackers. The quillfang ravagers, in their ravine to the south, are known to attack solitary travelers.\n\nIf she doesn't calm down, I won't be able to tend her wounds. Her stubbornness may just cost her her life.\n\nGo to Dustquill Ravine and see if you can find her campsite. I'm willing to bet she left it there.", objectives = "The Wounded Blood Elf Pilgrim was attacked by Quillfang Ravagers while camped in Dustquill Ravine. Find her camp and search it for the missing pack.", progress = "Things aren't going well. At this rate, she'll never make it back onto the road. Were you able to find that pack?", completion = "Thank you for returning this, <name>. I'm not sure what significance it holds for the wounded pilgrim, but she refuses to let anyone get near her until it's in her hands again." }
WordHunterWoW_QuestEN[9377] = { title = "Thirsting For Power", description = "Falcon Watch serves as a stop for pilgrims on their long journey into Outland. Although we are an early stop on the way, many of the pilgrims reach us exhausted and wracked by their addictions.\n\nIn a world such as this, many find it necessary to relearn mastery of their magical addiction. Food and drink help, {class}, but magical energy is their greatest need. The remains of Outland's voidwalkers provide a potent source of energy, but they grow rare and can only be found in the Warp Fields to the southwest.", objectives = "Retrieve a Potent Voidwalker Essence from the Vengeful Voidwalkers and return to Taleris Dawngazer at Falcon Watch." }
WordHunterWoW_QuestEN[9378] = { title = "DND FLAG The Dread Citadel - Naxxramas", description = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.\n\nWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations.Upon completion of this quest you will gain:", objectives = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn." }
WordHunterWoW_QuestEN[9379] = { title = "Fortifying the Felhunter", description = "Greetings, <class>. Say hello to Jir'see here, too. Don't worry, he won't bite unless I tell him to.\n\n<Angela makes a cooing sound at the felhunter.>\n\nHe's so tiny in comparison to the warp hounds that live in Outland. But we're going to fix that right up, yes we are, aren't we, Jir'see?\n\nI think I've figured out a way to do it. I'll need plenty of blood from the warp hounds and that's where you come in. While you're hunting them in the southeast, I'll get ready for the experi... err, treatment.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Gather 6 Warp Hound Blood and bring them to Angela \"The Claw\" Kestrel in Thrallmar." }
WordHunterWoW_QuestEN[9380] = { title = "Hounded for More", description = "I swear, if I get one more letter from Ironforge...\n\nHave you ever tried to explain something to someone who just wouldn't listen, <class>? I sent the boys in Ironforge the warp hound they asked for, and they had the gall to write back saying they wanted a \"pack\" of the things! A pack!\n\nSo, I tried to tell 'em that warp hounds are solitary creatures, but they'd have none of it. I've given up on setting 'em straight. Grab 6 of the best ones from the area east of the hold, and brimg 'em back here?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 6 Undamaged Warp Hound Corpses and bring them to Prospector Murantus in Honor Hold." }
WordHunterWoW_QuestEN[9381] = { title = "Trueflight Arrows", description = "With the influx of pilgrims and the encroachment of Alliance forces, things around Falcon Watch have gotten quite busy lately. In my spare time, I usually help prepare batches of arrows for the rangers, but I haven't had the chance to gather feathers for the fletching in a long time.\n\nI could offer you a bit of coin if you'd be willing to gather the tail feathers of the bonestripper vultures. In the past, I've found them circling the bones of large beasts to the north of Falcon Watch.", objectives = "Gather 8 Bonestripper Tail Feathers from Bonestripper Vultures and bring them to Falconer Drenna Riverwind at Falcon Watch.", progress = "Were you able to get all the feathers?", completion = "These should do the job. I was concerned that the rangers might be short on arrows for a while, but that's one less thing I have to worry about. Thank you for your help, <class>." }
WordHunterWoW_QuestEN[9382] = { title = "The Fate of the Clefthoof", description = "Greetings, <class>.\n\nI'm certain your travels in Outland have shown you something of the corruption in this world. It is so pervasive that it has transformed the very creatures who dwell here - the ones that survived, that is.\n\nThe clefthoof to the south and west were once docile grazers, but the corruption has created an unquenchable rage in them. They only find release from their torment in death, though it grieves us to spill their blood. Will you help me end the suffering of the bristlehide clefthoof?You will be able to choose one of these rewards:", objectives = "Kill 15 Bristlehide Clefthoof and return to Amaan the Wise at the Temple of Telhamat." }
WordHunterWoW_QuestEN[9383] = { title = "An Ambitious Plan", description = "The blood elves epitomize the irresponsible use of magic, {class}. They do not control magical energy. Rather, they are slaves to it and will suffer nothing to stand between them and their addiction. They consume the energies of Outland's voidwalkers to power their demonic magics.\n\nI've prepared a crystal charged with a spell that will allow us to neutralize a voidwalker and sever its link to this world when destroyed. I've mostly seen the voidwalkers in the Warp Fields to the southeast of Hellfire Citadel.", objectives = "Use the Sanctified Crystal against a wounded Uncontrolled Voidwalker and return to Elsaana at the Temple of Telhamat.", progress = "Have you used the crystal's magic against an uncontrolled voidwalker?", completion = "You've done well, <name>. It seems the containment crystal is holding for now, but how long it will last remains a mystery. We'll keep an eye on it and prepare more of the crystals in the meantime." }
WordHunterWoW_QuestEN[9385] = { title = "Rampaging Ravagers", description = "So Honor Hold sends us to deal with the arakkoa and we set up camp here thinking hey isn't this a great spot.  Little did we know how close we were to the quillfang ravagers.\n\nThey are relentless predators and have made any sort of work on our part impossible.  There's a bit of coin in it for you if you can deal with them for us.  Do you feel up to it?", objectives = "Kill 10 Quillfang Ravagers and return to Gremni Longbeard in Hellfire Peninsula.", completion = "Well done, <name>.  That should teach those beasts who's boss!" }
WordHunterWoW_QuestEN[9386] = { title = "A Light in Dark Places", description = "An eager one, aren't you? If you're willing to enter the depths once more, I'll gladly reward you.\n\nSeek out the bonfires burning within Stratholme, Scholomance, Dire Maul, and the halls of Blackrock Spire itself; I look forward to your return, <name>.You will receive:", objectives = "Find and touch the bonfires located within Blackrock Spire, Dire Maul, Scholomance, and Stratholme, then speak with the Festival Flamekeeper." }
WordHunterWoW_QuestEN[9387] = { title = "Source of the Corruption", description = "Uncorrupted draenei, like this unlucky fellow here, are virtuous champions of the Light.  What corruption caused their great race to devolve into the Broken and Lost Ones?\n\nI've heard a theory that exposure to fel energies is what caused the mutation.  I would like to put that theory to the test.\n\nNorthwest of here lie the Ruins of Sha'naar.  There you will find lowly Broken commanded by Illidari taskmasters.  Bring me demonic essences from the taskmasters so that I can test them on this draenei.", objectives = "Travel to the Ruins of Sha'naar in Hellfire Peninsula and obtain 5 Demonic Essences from the Illidari Taskmasters. Return to Apothecary Azethen at Falcon Watch after you've completed the task.", progress = "Have you obtained the samples?", completion = "You've been most helpful, <name>.  Now let's see what we can learn from our blue friend." }
WordHunterWoW_QuestEN[9388] = { title = "Flickering Flames in Kalimdor", description = "There are many flames burning throughout the world today, {name}. The trickiest fires to tend are those that burn green; they do not stay lit long without supervision. Make certain the emerald fires still burn on Kalimdor for our Flamekeeper, eh?\n\nYou will find them near Ratchet in the Barrens, close to the Master's Glaive in Darkshore, in the forest of Ashenvale by the bridge near Silverwing Outpost, and near the road to Windshear Crag along the main road in Stonetalon Mountains.", objectives = "Visit the bonfires within Ashenvale, the Barrens, Darkshore, and Stonetalon Mountains, then speak with the Festival Flamekeeper." }
WordHunterWoW_QuestEN[9389] = { title = "Flickering Flames in the Eastern Kingdoms", description = "The Midsummer Fire Festival traditionally lights up the land with a myriad of flames. Some argue that the green fires are the finest, as they are the hardest to maintain and have such a distinctive hue.\n\nMake sure they still burn in the Eastern Kingdoms for our Flamekeeper. They sit near Dun Modr in the Wetlands, close to Pyrewood Village within Silverpine Forest, on the cliffs overlooking the lighthouse in Westfall, and by the ruined tower in Hillsbrad Foothills.", objectives = "Visit the bonfires within Hillsbrad Foothills, Silverpine Forest, Westfall, and the Wetlands, then speak with the Festival Flamekeeper." }
WordHunterWoW_QuestEN[9390] = { title = "In Search of Sedai", description = "Hear my plight, {class}.  My brother, Sedai, left long ago to contact the orcs of Mag'har Post.  Ever the idealist, he thought the time was ripe to set our differences aside and negotiate a peace with them.\n\nHe's been missing for days and I fear for the worst.\n\nWould you set my mind to rest and look for him?  Sedai must be somewhere nearby to the east.", objectives = "Anchorite Obadei wants you to look for his brother, Sedai, nearby to the east in Hellfire Peninsula.", completion = "You've found the body of a young draenei paladin.  He appears to have been slain by a blow to his back." }
WordHunterWoW_QuestEN[9391] = { title = "Marking the Path", description = "With the rock flayer population thinned, all that's left is to signal the safe path to our pilgrims.  Return to the Great Fissure with this torch and seek the three beacons that mark the path from the east.\n\nLight the three beacons and return to me.  Be warned that the beacons will attract any nearby rock flayers when you first light them.", objectives = "Ranger Captain Venn'ren at Falcon Watch wants you to go to the Great Fissure in Hellfire Peninsula and light the Southern Beacon, Western Beacon and Central Beacon. Return to him with the Lit Torch after you've completed this task.", progress = "Have you done what I asked of you, <name>?", completion = "The Great Fissure, though still dangerous, will prove to be a useful path for our pilgrims.\n\nWith the Alliance watching all the roads in and out of Falcon Watch this is the manner of desperate act that is required of us." }
WordHunterWoW_QuestEN[9392] = { title = "Rogue Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young rogues here on Sunstrider Isle, your trainer is Pathstalker Kariel.  Speak with Kariel and see what training he has available for you.  The things he will teach do have a cost, so bring some coin with you.\n\nKariel - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", objectives = "Speak with Pathstalker Kariel - the Rogue class trainer - inside the Sunspire on Sunstrider Isle.", completion = "I've heard your name whispered from the shadows, <name>.  It's said that you're looking for someone experienced to show you the ropes - someone like me.  I can do that, but it'll cost you a small cut of your take every time I've got something to teach you.  So yes, I will train you in what it means to be a <class>.\n\nBut remember, if you get caught stealing something, this conversation never took place.  Now get out there and show me what you're made of!" }
WordHunterWoW_QuestEN[9393] = { title = "Hunter Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young hunters here on Sunstrider Isle, your trainer is Ranger Sallina.  Speak with Sallina and see what training she has available for you.  The things she will teach do have a cost, so bring some coin with you.\n\nSallina - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", objectives = "Speak with Ranger Sallina - the Hunter class trainer - inside the Sunspire on Sunstrider Isle.", completion = "<name>, are your eyes keen as a hawk's, your motions as fluid as a monkey's, or your speed that of a cheetah?  Mine are, and yours can be too with the proper training.  The way of the <class> is one of mastery over the beasts of the world, an unparalleled precision in marksmanship, and the knowledge of how to survive in situations where others would perish.\n\nIf these are the things that you seek to learn, then I will train you - for a small fee, of course.  Shall we begin?" }
WordHunterWoW_QuestEN[9394] = { title = "Where's Wyllithen?", description = "The Duskwither groundskeeper has gone missing! Someone must have forgotten to tell him to leave when the magister and everyone else did.  I know that he's still somewhere around here on the grounds, but I dare not go looking for him myself with all of these magical creatures roaming about.\n\nWill you find him for me, {class}, and make sure that he's alright?", objectives = "Find Groundskeeper Wyllithen on the Duskwither Grounds in Eversong Woods.", completion = "Who are you?  You're not one of the magister's apprentices, that's for certain!\n\nSent here to help me clean up this mess, no doubt!" }
WordHunterWoW_QuestEN[9395] = { title = "Saltheril's Haven", description = "I swear that I'm going to fireball someone if I get one more request from Lord Saltheril concerning supplies for his party!  Do I look like a party planner?!  Between you and me, that fool and his sycophants are living in denial that we're under attack here!\n\nSome of us are actually busy with, oh, I don't know, defending what's left of Quel'Thalas!  {class}, would you please head over to Saltheril's Haven and see if you can shut him up?  It's just down the road to the west.", objectives = "Speak with Lord Saltheril at Saltheril's Haven in Eversong Woods.", completion = "Ah, good of Magistrix Dawnstrider to finally respond to my simple requests.  I should take up the matter of her attitude with the regent lord in Silvermoon. She's quite rude!\n\nNothing for you to concern yourself with though. Now that you're here, maybe I'll finally be able to get those party supplies that I've been waiting for?" }
WordHunterWoW_QuestEN[9396] = { title = "Magic of the Arakkoa", description = "Outland holds many secrets, {name}.  It's only a matter of time before we uncover them all.\n\nThe half-bird, half-man species of the arakkoa possesses ancient arcane knowledge that would aid us greatly in our exploration of this world.  Travel to the Den of Haal'esh, south of here.  Obtain any magical scrolls that the Haal'eshi might be carrying on them and bring them to me.", objectives = "Bring 4 Haal'eshi Scrolls to Arcanist Calesthris Dawnstar at Falcon Watch in Hellfire Peninsula.", progress = "Have you obtained the scrolls yet, <name>?", completion = "Good work, <name>.  Outland's secrets will not stay hidden from us for very long.\n\nIt's our destiny to become the masters of this world." }
WordHunterWoW_QuestEN[9397] = { title = "Birds of a Feather", description = "The Haal'eshi arakkoa have domesticated a beautiful bird species called the kaliri.\n\nI've managed to capture a young male and they appear to be trainable.  The females are much rarer, but if I had one I could attempt to breed them.  She has to be young, though... a hatchling.  An older wild bird wouldn't survive in captivity.\n\nTake this cage and travel south, to the Den of Haal'esh.  Search the nests for eggs that are ready to hatch.  If you bring me back a female hatchling, I'll reward you handsomely.", objectives = "Travel to the Den of Haal'esh in Hellfire Peninsula and search the Kaliri Nests for a Female Kaliri Hatchling. Use the Empty Birdcage to capture it and bring it to Falconer Drenna Riverwind at Falcon Watch.", progress = "You've returned.  Did you bring me the kaliri female?", completion = "You did it!  You caught a female hatchling!\n\nShe's precious.  You have my thanks, <name>." }
WordHunterWoW_QuestEN[9398] = { title = "Deadly Predators", description = "The Broken that live in Outland have endured endless violence.  It is of little surprise that as soon as the Dark Portal opened they flocked to it in droves with hopes of escaping this land.\n\nUnfortunately for our confused brothers and sisters coming from the south, the rock flayers that inhabit the Great Fissure see them as easy prey.  Go there and thin the rock flayer population, so that our kin might have a chance.", objectives = "Scout Vanura at the Temple of Telhamat in Hellfire Peninsula wants you to slay 8 Stonescythe Whelps and 4 Stonescythe Alpha.", completion = "You've done well, <name>.  It is always unfortunate to have to resort to taking a life, even when it's that of a dangerous beast such as the rock flayer.\n\nYou have my thanks for carrying out this grim task." }
WordHunterWoW_QuestEN[9399] = { title = "Cruel Taskmasters", description = "You probably think most Broken are evil, don't you?  In reality many just lack guidance.\n\nBefore I met the Omenai, I too was lost.\n\nOur minds suffered terrible pain from the orcs' demonic magic.  We are easily confused and taken advantage of.\n\nDemons allied with Illidan raid Hellfire daily and capture our kind as slaves.  With the Omenai we now have hope.  Travel to the Ruins of Sha'naar, southwest of here, and slay the Illidari taskmasters so my people may be free!", objectives = "Slay 4 Illidari Taskmasters at the Ruins of Sha'naar and return to Ikan at the Temple of Telhamat in Hellfire Peninsula.", completion = "You did it!  I'm in your debt, <name>.  Look at all the Dreghoods that are showing up.\n\nUnder my guidance they'll learn all about the old ways, you'll see." }
WordHunterWoW_QuestEN[9400] = { title = "The Assassin", description = "{name}, we recently uncovered a plot to assassinate our envoy to Falcon Watch.  Hellfire Citadel learned of our plans to send an expedition there earlier this morning and set up an ambush.\n\nOur scouts have informed me that an assassin known as Krun Spinebreaker waits along the road north of the Citadel.  Go there and slay this assassin.  Show the fel orcs we're not to be trifled with!", objectives = "Nazgrel wants you to travel to the road north of Hellfire Citadel and look for an assassin named Krun Spinebreaker.", completion = "The corpse matches the description of Krun Spinebreaker, Hellfire Citadel's assassin.  As you turn the body over, you notice a stone axe protruding from his back." }
WordHunterWoW_QuestEN[9401] = { title = "A Strange Weapon", description = "You pull the stone axe out of the body to examine it more closely.  There's something unusual about the craftsmanship of the weapon.\n\nIts origin appears orcish, though the materials aren't like anything you've seen before.  Nazgrel might be interested in seeing the weapon.", objectives = "Bring the Heavy Stone Axe to Nazgrel in Thrallmar in Hellfire Peninsula.", progress = "Tell me, is the assassin dead?", completion = "He was killed by this weapon?  It can't be!\n\nHave we... found them?" }
WordHunterWoW_QuestEN[9402] = { title = "Fetch!", description = "So... {name} is it?  Don't be flattered I know your name, one of my students has been fawning over you and won't shut up.\n\nHmm... if you'd like to impress her, why don't you do something for me?  There's an azure phial at the bottom of the pond behind me.  Dive in, retrieve it, and bring it here.", objectives = "Dive to the bottom of Stillwhisper Pond and retrieve the Azure Phial for Instructor Antheol.", progress = "How's the water?", completion = "Oh, well done...  I told you to jump in a pond, and you did.  I can only imagine what you'd do if one of your good friends asked it of you.\n\nIf you want a reward for your efforts, it is this: never lift a finger without first knowing what's in it for you.  The <class>'s mind is his greatest weapon.  Remember that and try to use yours a bit more." }
WordHunterWoW_QuestEN[9403] = { title = "The Purest Water", description = "Now that you've learned a little lesson, I'll offer you something more substantial.  It concerns your ability to defend yourself in close combat.  Of course, you should only resort to melee in the most dire of circumstances, but that is no excuse to be unprepared.\n\nI can assist you in creating a staff befitting a mage of your learning.  Simply take the phial you retrieved for me and fill it at the base of Elrendar Falls.  Just follow the river southeast from here.", objectives = "Instructor Antheol wants you to fill the Azure Phial at Elrendar Falls.", progress = "Only water from the Elrendar Falls has the purity required for use with magic.  Do you have it?", completion = "Let's see what you've brought me...\n\n<He holds the phial up to the light and examines it closely.>\n\nYes, this will do.  Well done, <name>." }
WordHunterWoW_QuestEN[9404] = { title = "Recently Living", description = "You may have noticed the walking trees near Elrendar Falls.  As the keepers of nature, they are infused with a primal magic we can reform to our own purposes using the pure water you have already brought to me.\n\nUnfortunately, the green keepers are gnarled and twisted creatures, so you may need to kill a few before you find a useable branch.", objectives = "Slay the Eversong Green Keepers until they yield a Living Branch for Instructor Antheol.", progress = "Do you have the living branch?  Hand it over quickly!", completion = "You've done as I've asked, <name>, and you may take your reward now." }
WordHunterWoW_QuestEN[9405] = { title = "The Warchief's Mandate", description = "As you know, the warchief put his power behind this expedition for one reason.  This is the world we came from.  This is where our roots lie.\n\nThis journey means different things to orcs and blood elves.  To them it's a search for the promised land.  To us it's more like returning home.\n\nWhoever made this axe is familiar with the old ways and we must contact them.  This is too important for us to use ordinary tracking methods.  Show the weapon to Far Seer Regulkut; she will know what to do.", objectives = "Bring the Heavy Stone Axe to Far Seer Regulkut at Thrallmar in Hellfire Peninsula.", progress = "Tell me what you seek, so that I may help you find it.", completion = "I understand Nazgrel's request, <class>.  Say no more." }
WordHunterWoW_QuestEN[9406] = { title = "The Mag'har", description = "This news you bring from beyond the Dark Portal...  you want us to believe the son of Durotan ruled over the lands beyond it... free from any demonic taint?  And that now his people have returned to this world?\n\nI hope for your sake that this isn't some manner of joke, {class}.  What this means to my people... cannot be described.  I must send word to Nagrand at once!  Hellscream must hear about this.\n\nTake this letter back to your leader in Thrallmar.  Tell him the Mag'har welcome them!", objectives = "Deliver the Letter from the Mag'har to Nazgrel at Thrallmar in Hellfire Peninsula.", progress = "What do you bring us, <name>?", completion = "You're certain of this?  This is big news, <name>.  These orcs can surely help our cause both here and at home!" }
WordHunterWoW_QuestEN[9407] = { title = "Burning Crusade: Through the Dark Portal", description = "For years the Dark Portal loomed silent... forgotten.  But it is silent no longer.\n\nAfter stopping the demonic assault here, our forces breached the portal and met the demons on their own ground!\n\nNow, we are locked in a savage war, and there are some who think we might not win.  So it is our duty, our grim pleasure, to battle the fiends of Outland and ensure our victory, {name}.\n\nIf you would help us, then report to Lieutenant General Orion at once. He awaits you in the Outland...\n", objectives = "Travel through the Dark Portal and find Lieutenant General Orion. He awaits your arrival on the other side, in Outland.", completion = "Our Expedition made it safely through the Portal and set up a new base called Thrallmar. Yet as you can see, the Burning Legion moved in and cut us off from our brothers. Clearly, the demons hope to retake the Dark Portal and prevent us from gathering reinforcements from Azeroth." }
WordHunterWoW_QuestEN[9408] = { title = "Forgotten Heroes", description = "While it pains me to know that we have lost so many soldiers in our efforts to breach the portal, my heart swells with pride to know that the original expeditionary force is still alive.\n\nI can hardly believe it; but here they stand - a testament to the resolve of the Alliance.\n\nInside that keep stands one of our greatest heroes: Danath Trollbane! Seek him out, {class}. He has already met and addressed all of our soldiers. He will surely want to meet you.", objectives = "Speak with Force Commander Danath Trollbane at Honor Hold.While it pains me to know that we have lost so many soldiers in our efforts to breach the portal, my heart swells with pride to know that the original expeditionary force is still alive.\n\nI can hardly believe it; but here they stand - a testament to the resolve of the Alliance.\n\nInside that keep stands one of our greatest heroes: Danath Trollbane! Seek him out, <class>. He has already met and addressed all of our soldiers. He will surely want to meet you.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9409] = { title = "Urgent Delivery!", description = "Now that you've gathered all that we need to replenish our healing crystals, I need you to deliver the vials to Zalduun, our priest.  You'll find him tending to our wounded inside the central chamber of the ship.", objectives = "Deliver the Bundle of Vials to Zalduun at the Crash Site in Ammen Vale.", progress = "Hello, <class>.  What have you there? Is it for me?", completion = "Good work!  This will do nicely to replenish our depleted healing crystals.\n\nBut now that you're here, I think I have another use for you, if you're willing?" }
WordHunterWoW_QuestEN[9410] = { title = "A Spirit Guide", description = "Even our best tracking wolves' senses can fail them, {name}.  The spirits have a way of seeing the world differently than ours.  The being you will call forth will find the person you seek, for they'll be drawn not to their scent but their essence.\n\nGo now, {class}, take this totem with you and use it at the location you found the stone axe.", objectives = "Use the Wolf Totem at the location where you found Krun Spinebreaker's body and follow the Ancestral Spirit Wolf.", progress = "You are lucky to be alive.", completion = "Who are you to walk in here unannounced?  I ordered my men to stay their hand only because Ryga sensed that the spirits were with you.  \n\nSpeak freely, but choose your words wisely.  We rarely trust strangers this close to the Citadel." }
WordHunterWoW_QuestEN[9415] = { title = "Report to Marshal Bluewall", description = "Are you Marshal Bluewall's new recruits? Of course you are.\n\nWhat are you waiting for? Good soldiers are dying in the desert. Aren't you excited to join them?\n\nNow, get going and don't dry out on the way.", objectives = "Speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.", completion = "The Alliance needs every able body they can get. The Horde has been receiving a steady supply of reinforcements from the northern part of the continent, and it's been a struggle to keep up.\n\nLet me explain the situation to you." }
WordHunterWoW_QuestEN[9416] = { title = "Report to General Kirika", description = "You must be one of General Kirika's new recruits. It's about time you showed up. Bodies wear down quick in the desert.\n\nThe dwarves have been getting reinforcements daily, and we can't afford to lose ground in our struggle for resources in Silithus.\n\nGet your instructions from the General. It's not my job to train you, just find you.", objectives = "Speak with General Kirika at the Horde encampment near Hive'Regal.", completion = "It's good that you're here, but there's no time to waste making small talk. You need instructions, and then you need to get out there.\n\nListen up." }
WordHunterWoW_QuestEN[9417] = { title = "The Arakkoa Threat", description = "The arakkoa are smart creatures... smart as any gnome you ever met.  They have this way with magic and a violent temper, however. \n\nLately they've taken to attacking Honor Hold patrols, which is why we were sent here.  See, Mirren and I are world-famous marksmen, we are!  But fowl and game are what we specialize in... not these... lightning-invoking birdmen.\n\nSo what do you say you give us a hand in this one assignment?  You'll find the Den of Haal'esh to the southeast.", objectives = "Gremni Longbeard in Hellfire Peninsula wants you to slay 4 Haal'eshi Windwalkers and 6 Haal'eshi Talonguards.", completion = "Great job, <name>!  I hereby proclaim you an honorary Longbeard.\n\nStick around and have a drink with us, won't you?" }
WordHunterWoW_QuestEN[9418] = { title = "Avruu's Orb", description = "<As you hold the orb closer to you, you hear a voice address you.>\n\nI sense you're not of the arakkoa, so I will attempt to barter for my freedom.  My name is Aeranas. I once ruled over the eastern winds.  The Haal'eshi mage, Avruu, trapped me inside this orb.\n\nFind the altar the arakkoa used to enslave me.  It is hidden to the southeast of the arakkoa's den.  Approach it with the orb and give it to me once I'm free.  In exchange for my liberty I'll reward you with powerful treasure!", objectives = "Take Avruu's Orb to the Haal'eshi Altar southeast of the Den of Haal'esh in Hellfire Peninsula and give it to Aeranas once he's free.", progress = "The freedom I've yearned for is finally mine!", completion = "With this orb I regain my liberty.  Take your reward, mortal, so that our debt may be settled." }
WordHunterWoW_QuestEN[9419] = { title = "Scouring the Desert", description = "We recently found out that the Horde has been scavenging the Silithus desert for resources, but paid them little mind. We thought it could not be worth it to station large numbers in this sweltering desert.\n\nHowever, it was discovered the importance of the resources, and now we are scrambling to catch up.\n\nIf I have your assistance, you must go into the desert and recover the silithyst and return it here.", objectives = "Find and deliver Silithyst to the Silithyst Extractor, then speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.", completion = "Thank the Light you were successful.\n\nNow if we could only have started this sooner, our need would not be so desperate. We must keep the bounty of the desert from falling into the hands of the Horde." }
WordHunterWoW_QuestEN[9420] = { title = "The Finest Down", description = "The arakkoa at the Den of Haal'esh, south of here, breed a magnificent species of birds called kaliri.  Their feathers would fetch a bundle at the trading posts back in Azeroth.  Just think of all the ale I could buy then!\n\nTell you what, you bring me a stack of kaliri feathers and I'll give you my very own hat.  What do you say?  You'll never find a hat like this one!  Do we have a deal?", objectives = "Mirren Longbeard in Hellfire Peninsula wants you to bring him 8 Kaliri Feathers from the various kaliri found in the Den of Haal'esh.", progress = "Did you bring me the kaliri feathers, <class>?", completion = "You did your part.  I guess a deal is a deal!\n\nHere you go, friend.  Treat it well." }
WordHunterWoW_QuestEN[9421] = { title = "Shaman Training", description = "", objectives = "I am Firmanvaar and you are wise to seek me out.  It is my calling to provide instruction to <class>, especially those who are just beginning to learn.\n\nShamanism is only now being relearned amongst the <race>, <name>.  You are brave to follow its path as it is not popular amongst your kind.\n\nI will be here when you feel you are ready for further training." }
WordHunterWoW_QuestEN[9422] = { title = "Scouring the Desert", description = "For some time now, we have been tapping the crystal resources of the Silithus desert. The only dangers we faced were from the creatures that made this place their home and the oppressive sand and dust and heat.\n\nBut now the Alliance seems to have caught on to what we have found here. It is now a race between us to capture the natural resources, and keep them from the other.\n\nI need every set of hands that is available. I hope I have yours.", objectives = "Find and deliver Silithyst to the Silithyst Extractor then speak with General Kirika at the Horde encampment near Hive'Regal.", completion = "You've done well, <name>. These resources will be added to our stockpiles, and every bit is to our gain and our enemy's loss." }
WordHunterWoW_QuestEN[9423] = { title = "Return to Obadei", description = "With Sedai's death confirmed, you're left with the unpleasant task of returning to Obadei with the grim news.", objectives = "Return to Anchorite Obadei at the Temple of Telhamat in Hellfire Peninsula and inform him of Sedai's death.", completion = "Sedai, dear brother...\n\nThose cowardly orcs!  He was unarmed, how could they?\n\nLeave me be, <name>.  I thank you for your assistance but I wish to be alone with my thoughts now." }
WordHunterWoW_QuestEN[9424] = { title = "Makuru's Vengeance", description = "Sedai was like a brother to Makuru.   We owe him our lives and more!  They call Makuru crazy but if the Omenai are not going to do anything about his death then they're the crazy ones!\n\nMakuru doesn't have much to call his own in this world, but he will give you his only possession if you avenge Sedai.  \n\nI've seen the brown orc Mag'har grunts before, up in the hills to the northeast.  They hate us!  They don't deserve our mercy!  Go, avenge Sedai!  Bring me their ancestral beads as proof!", objectives = "Makuru at the Temple of Telhamat in Hellfire Peninsula wants you to bring him 10 Mag'har Ancestral Beads.", progress = "Did you avenge Sedai for Makuru?", completion = "Yes... revenge!  You did good.\n\nYou take this now.  It was a gift from Sedai.  It only makes Makuru sad to see it." }
WordHunterWoW_QuestEN[9425] = { title = "Report to Tarren Mill", description = "Ah, good to see you here, <class>!  I've a task that you are perfectly suited to.\n\nAs new members of the Horde, we need to make sure that we support their efforts and help them with their problems.  That way they'll be more receptive to helping us with ours.\n\nTravel to the Forsaken town, Tarren Mill, in the Hillsbrad Foothills to the southeast.  Check in with Advisor Duskingdawn when you arrive.", objectives = "Travel to Tarren Mill in the Hillsbrad Foothills and speak with Advisor Duskingdawn.Ah, good to see you here, <class>!  I've a task that you are perfectly suited to.\n\nAs new members of the Horde, we need to make sure that we support their efforts and help them with their problems. That way they'll be more receptive to helping us with ours.\n\nTravel to the Forsaken town, Tarren Mill, in the Hillsbrad Foothills to the southeast. Check in with Advisor Duskingdawn when you arrive.", completion = "My, my!  Another of my brothers arrives to pitch in.  Good!  There is much to be done in support of our new Forsaken friends, <class>.  Ask around to see who you can help out.\n\nI know that you will support them to your utmost ability!" }
WordHunterWoW_QuestEN[9426] = { title = "The Pools of Aggonar", description = "Much has changed since the days when we called this land Draenor.  Parts of the land have been forever changed by the demons' taint.\n\nOne such place is known as the Pools of Aggonar.  It was once the location of our people's sacred springs.  The blood of the demon Aggonar fouled the very essence of the holy waters.  This fel blood has spawned foul beings that must be cleansed if we're ever to reclaim the pools.  Travel east of here and slay the Terrorfiends and slimes that wander the pools.", objectives = "Amaan the Wise wants you to go to the Pools of Aggonar and slay 6 Terrorfiends and 6 Blistering Rots.", completion = "Yes, I feel the fel presence in the pools weakening.\n\nYou've done well, <name>." }
WordHunterWoW_QuestEN[9427] = { title = "Cleansing the Waters", description = "I must ask that you finish what we've set in motion.  Now that the demonic influence has weakened you must take this cleansing vial and pour it at the very source of the taint - Aggonar's own corpse.\n\nYou will find the demon's bones at the northern end of the pools.  Beware, I sense that Aggonar's essence has not quite left this world.", objectives = "Amaan the Wise wants you to travel to the Pools of Aggonar and use the Cleansing Vial at Aggonar's corpse. Return to him when Aggonar's essence is cleansed from the water.", progress = "You return, <name>.  Are the waters cleansed?", completion = "The essence of Aggonar lived on in the form of his foul offspring Aggonis.  With your success in defeating the demon, we can begin to work towards restoring the pools to their former purity.\n\nYou have our thanks, <name>.  Your work will have a deep impact in this world." }
WordHunterWoW_QuestEN[9428] = { title = "Report to Splintertree Post", description = "<The ambassador keeps her voice low as she leans in close.>\n\nYour reputation precedes you, <name>.  I want you to travel to Splintertree Post in Ashenvale.  The easiest way to get there on foot is to travel west through Durotar and the Barrens, and then turn north at the fork in the road.\n\nWhen you arrive, speak with Advisor Sunsworn.  Travel carefully; Ashenvale can be a very dangerous place!", objectives = "Travel to Splintertree Post in Ashenvale and speak with Advisor Sunsworn.<The ambassador keeps her voice low as she leans in close.>\n\nYour reputation precedes you, <name>. I want you to travel to Splintertree Post in Ashenvale. The easiest way to get there on foot is to travel west through Durotar and the Barrens, and then turn north at the fork in the road.\n\nWhen you arrive, speak with Advisor Sunsworn. Travel carefully; Ashenvale can be a very dangerous place!", completion = "The ambassador sent word ahead, so I've been expecting you.\n\nThe ambassador simply wants you to do as much as you can to help out around here.  She said something about making sure to cement our relationship with the rest of the Horde.\n\nAsk around - there are others in need of help further back in the Post.  And I hear that there's another Horde outpost called Zoram'gar Outpost on the coast all the way to the west." }
WordHunterWoW_QuestEN[9429] = { title = "Travel to Darkshire", description = "I am told that there is a thorn in the side of the kingdom of Stormwind.  It is known as Duskwood, and it is a place that is filled with evil and the vile stench of undeath.\n\nAs we're trying to help as much as we can, I would like for you to travel southeast to the main human settlement there, named Darkshire.  Anchorite Delan will be awaiting your arrival.", objectives = "Travel to Darkshire in Duskwood and speak with Anchorite Delan.", completion = "Greetings, <class>.  I trust that your journey here was uneventful?\n\nThese poor souls are beset upon all sides by the creatures of the night.  It is our wish that you lend them what aid you can in pushing back the darkness.\n\nTravel about the town and get to know its inhabitants.  Please, <name>, help them in any way that you can." }
WordHunterWoW_QuestEN[9430] = { title = "Sha'naar Relics", description = "As I've told you before, I do not require eyes to see what others cannot.  I will not pass judgment on what you did on Makuru's behalf, yet I think you need to see beyond what your eyes show you.\n\nTravel southwest to the Ruins of Sha'naar and salvage any relics you find.  If fate wills it you will find what we need.\n\nThe meaning of my request might not be immediately apparent.  Have faith though, {name}.  Clarity comes to those with patience.", objectives = "Amaan the Wise at the Temple of Telhamat in Hellfire Peninsula wants you to travel to the Ruins of Sha'naar and retrieve 10 Sha'naar Relics.", progress = "Did you retrieve the Sha'naar relics, <name>?", completion = "You're very fortunate.  Just as I had hoped, you've found a special relic among these other ones." }
WordHunterWoW_QuestEN[9431] = { title = "A Different Approach", description = "What's a sin'dorei doing standing on the top of a windswept butte in Thousand Needles instead of the halls of Silvermoon?\n\nIt's simple. My brethren will no longer have me. Every copy of my treatise on natural cures for our magical addiction was burned.\n\nI can safely pursue my research here, but I am without my reagents. If you'd be willing to gather purifying earth from the thundering boulderkin near the western end of the Needles and deliver it to my associate at Whitereach Post, I'd appreciate it.", objectives = "Gather 2 handfuls of Purifying Earth from Thundering Boulderkin and take them to Wizlo Bearingshiner at Whitereach Post.", progress = "Magistrix Elosai's note was a bit cryptic, but I think I understand what she wants me to do. If you have the earth she talked about, I can put it into the vessel you'll need for the moonwell water.", completion = "What? She didn't mention the moonwell? That's what she had in mind all along. I admit the whole thing's a bit wacky, but who am I to turn away a client, especially when she's the only one I've got?\n\nMaybe trying to sneak into a night elf settlement and steal water from their moonwell isn't the most prudent thing I've ever helped a customer do, but her money is as gold as anyone else's!" }
WordHunterWoW_QuestEN[9432] = { title = "Travel to Astranaar", description = "I am glad that you are here to help.  In fact, there is something that you can do.\n\nAs part of our inclusion within the Alliance, I would like for you to travel to the night elf town, Astranaar.  It is located in Ashenvale, a large forest that is south of Darkshore on the continent of Kalimdor.\n\nPlease speak with Vindicator Palais when you arrive to see if there's anything that you can do to help the inhabitants.", objectives = "Travel to Astranaar in Ashenvale and speak with Vindicator Palais.I am glad that you are here to help. In fact, there is something that you can do.\n\nAs part of our inclusion within the Alliance, I would like for you to travel to the night elf town, Astranaar. It is located in Ashenvale, a large forest that is south of Darkshore on the continent of Kalimdor.\n\nPlease speak with Vindicator Palais when you arrive to see if there's anything that you can do to help the inhabitants.", completion = "Always good to see a semi-familiar face.  You must be <name>.  Emissary Valustraa sent me word to expect you.\n\nThe people of Ashenvale need our assistance, <class>.  Speak with the citizens of Astranaar to see how you can help." }
WordHunterWoW_QuestEN[9433] = { title = "A Dip in the Moonwell", description = "Stop looking at me like that! I didn't say I was going to send you to Thalanaar's moonwell out in the open with dipper and a flask!\n\nI've been, err... tinkering with a product I was transporting for a client. In fact, I've already set up a portable control console for the Robotron out near Thalanaar. You'll need to bring this control unit with you and use it in the vicinity of my concealed console.\n\nIf my client ever heard that I so much as removed Robotron from its packaging, he'd hang me by my ears!", objectives = "Use the Robotron Control while standing near the Concealed Command Console hidden in a small cluster of bushes on the rim of the needle closest to Thalanaar to take command of a Robotron 3000. Pilot the robot to the western edge of Thousand Needles where the Alliance outpost of Thalanaar is located. Use the robot to collect a sample of the moonwell's water and return it to Wizlo Bearingshiner at Whitereach Post.", progress = "Did it do the job?", completion = "That worked better than I expected! Chalk up another one for good old goblin ingenuity!\n\nThe only problem is that it's hopelessly covered in dust! It's going to take me forever to get this thing cleaned up and replaced in its crate.\n\nOf course, time is the one thing I have in ample supply." }
WordHunterWoW_QuestEN[9434] = { title = "Testing the Tonic", description = "<Wizlo retrieves the water sample from the robot and places it in a crate with the boulderkin earth and several other items.>\n\nThere you go, that's everything on Magistrix Elosai's list. Tell her that it's been a pleasure working with her and that I wish her luck in her research.", objectives = "Deliver the Crate of Reagents to Magistrix Elosai at Freewind Post.", progress = "Were you and Wizlo able to gather the reagents?", completion = "Excellent, it appears everything is here. Now, all I have to do is mix everything together and give it a try. If this tonic does what my research indicates it should do, I may have discovered a way to lessen the effects of my people's magic addiction.\n\nYou're about to witness history in the making, <name>. Just think, without your help, this wouldn't have been possible." }
WordHunterWoW_QuestEN[9435] = { title = "Missing Crystals", description = "If there's one great truth about Hillsbrad, it's that this region is destined to live under the shadow of war. Even something as innocuous as a cartload of stone is a target.\n\nNormally the loss of building materials is no great setback, but the most recent shipment from the Azurelode mine contained a crate of rare crystals I was eager to study. Forsaken raiders intercepted the cart and drove it northeast to a tower they're attempting to rebuild. It's imperative that we retrieve those crystals, <class>!", objectives = "Retrieve the Shipment of Rare Crystals from the Forsaken and return it to Huraan in Southshore.", progress = "Were you able to retrieve the crystals from the Forsaken?", completion = "Thank the Light! From the tone of the foreman's letter, it sounded as if that box of crystals contained the only known samples from the mine. If we had lost them, <name>, we may never have seen another like them.\n\nI can't thank you enough for your help." }
WordHunterWoW_QuestEN[9436] = { title = "Bloodscalp Insight", description = "Well met, {class}. I've made a habit of studying the fighting techniques of the various troll tribes in my travels, and I've noticed a trend. The Bloodscalp trolls at the Tkashi Ruins and Bal'lal Ruins to the north use some of the same tactics as the Amani of the northern forests.\n\nTheir magic seems to have diverged in an interesting direction and they've used it to become the strongest tribe in the area. It could form the core of a powerful weapon against the Amani, but first I must find out more about it.", objectives = "Nemeth Hawkeye at Grom'gol Base Camp wants you to bring him a Bloodscalp Totem from a Bloodscalp Shaman.", progress = "Do not fail me, <name>. If we can bend this Bloodscalp magic to our will, my people may yet eliminate the Amani threat.", completion = "Well done. Now, this is curious...\n\nThe inscription on this totem is in a language no troll could ever hope to learn, but one that is known to us. It names the bearer as an ally of a water elemental named Naias and marks him as one worthy to channel his power.\n\nThis is most unexpected, but not entirely bad, <name>. With your help, I'd like to pursue this further." }
WordHunterWoW_QuestEN[9437] = { title = "Twilight of the Dawn Runner", description = "The ogres here are useful for little more than crude jokes, sour ale, and bouts of headbutting. When my ship, the Dawn Runner, ran aground, those curs from Theramore made off with my cargo and last surviving crewman. I made my way here searching for help, but those good-for-nothing ogres stared blankly at me when I told them my story.\n\nI could use the help of a reliable {race} in recovering what remains of my cargo and freeing Ithania from North Point Tower, to the northeast, where they're being held.", objectives = "Balandar Brightstar in Brackenwall Village wants you to reclaim the Dawn Runner Cargo and rescue his first mate Ithania from forces of Theramore at North Point Tower.", progress = "Have you freed Ithania and reclaimed my cargo from those glorified privateers?", completion = "Well done, <name>! As soon as Ithania has had time to rest and my preparations are complete, we'll depart this sodden wasteland and head back to civilization." }
WordHunterWoW_QuestEN[9438] = { title = "Messenger to Thrall", description = "The warchief has been waiting for word of this ever since we set foot on Outland.  Now you get the honor of giving him the news of the Mag'har yourself.\n\nGo quickly, <name>.  Take this letter with you; it bears my personal seal.  There is nothing that Thrall wants to hear more than the message you bear.Upon completion of this quest you will gain:", objectives = "Travel to Orgrimmar and give Thrall the Letter from Nazgrel." }
WordHunterWoW_QuestEN[9439] = { title = "Unclaimed Baggage", description = "This is Kargath? Oh, dear. I expected a, a... well, some kind of settlement, some sign of civilization here in the wilderness.\n\nThere must be a mistake; surely this hovel full of uncouth, unwashed, sniggering savages can't be the headquarters of the Expeditionary Force. The loutish barbarians had the gall to laugh at me when I told them about how the Dark Iron dwarves robbed me and then disappeared into the Angor Fortress. I can count on you to help me recover my possessions and my dignity, can't I?", objectives = "Retrieve the Advisor's Pack and Advisor's Rapier from their holding places in the Angor Fortress and return them to Advisor Sarophas at Kargath.", progress = "For Sunstrider's sake, don't stare at me! It's bad enough I'm forced to endure out here in my soiled clothing! After all I've been through, the last thing I need is to be gawked at. Did you manage to collect my possessions from that hole-in-the-ground those Dark Irons call a fortress?", completion = "You're a miracle worker, <name>! I tell you, I've never been so eager for a change of clothes in my life.\n\nAnd my rapier! I felt positively naked without my blade.\n\nYou are to be commended and rewarded for your efforts. Never let it be said that Sarophas failed to acknowledge the little people who've helped him along the way!" }
WordHunterWoW_QuestEN[9440] = { title = "ittle Morsels", description = "I'm perfecting a weapon to use against the draenei and you're going to help me!\n\nThe Lost Ones are the backward cousins of the draenei, and I've been experimenting on them.  I just need you to feed some fel-tainted morsels to their captured livestock.  In turn, when they slaughter and eat the animals, they'll be cursed!  That'll show that stuffy Anchorite Avuun at the Harborage!\n\nGo now, hurry!  You'll find the Lost Ones and their caged animals to the northeast at the Fallow Sanctuary.", objectives = "Feed the Fel-Tainted Morsels to the Lost Ones' captured animals. Then return the leftovers to Cersei Dusksinger at Stonard in the Swamp of Sorrows.", progress = "Did you feed their captured animals all of the morsels?  Wait!  You didn't give any to that stupid human they have out there in the cage, did you?\n\nOh, good!  That would have been a waste!", completion = "Oh, excellent! I can't wait to measure the effects from this latest batch!\n\nWell, you did an admirable job, sweetie.  Wish I could give you more than this for the entertainment you've provided, but you know how it is.  There's not much money to be made out here in the swamp.\n\nI'm sure it was worth it just for the fun!" }
WordHunterWoW_QuestEN[9441] = { title = "Envoy to the Mag'har", description = "I'd leave for Outland this very minute after hearing the news you brought.  Important matters require my attention in Durotar, however.\n\nI will arrange for a fitting tribute to be sent to the Mag'har immediately.  I will send my most trusted diplomats as well.  This will all take time... I need someone to represent us there right now.\n\nI must place my trust on you, <name>.  Go to the Mag'har Post in Hellfire and render whatever services you can to my kin.  Do not fail me, <name>.  Too much depends on this.Upon completion of this quest you will gain:", objectives = "Thrall wants you to return to Gorkan Bloodfist at Mag'har Post in Hellfire Peninsula and offer him your services.I'd leave for Outland this very minute after hearing the news you brought. Important matters require my attention in Durotar, however.\n\nI will arrange for a fitting tribute to be sent to the Mag'har immediately. I will send my most trusted diplomats as well. This will all take time... I need someone to represent us there right now.\n\nI must place my trust on you, <name>. Go to the Mag'har Post in Hellfire and render whatever services you can to my kin. Do not fail me, <name>. Too much depends on this.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9442] = { title = "A Debilitating Sickness", description = "It is good that you've offered to aid us, {name}.  Our grunts have fallen sick from drinking contaminated water and I'm missing an ingredient to produce a healing salve.  I'm in need of a rare mushroom called drycap.\n\nOur foremost orders are to keep our location secret and not risk being spotted while looking for it, or I would go myself.  The only place in Hellfire Peninsula where drycap grows is a cave at the Great Fissure, south of here.\n\nBe extremely careful if you choose to seek it.", objectives = "Earthcaller Ryga at Mag'har Post in Hellfire Peninsula wants you to bring her 1 Drycap Mushroom from a cave inside the Great Fissure.", progress = "Did you obtain the mushroom I need, <name>?", completion = "Gorkan said good things about you.  They're all turning out to be true.\n\nThanks for your help." }
WordHunterWoW_QuestEN[9443] = { title = "The So-Called Mark of the Lightbringer", description = "I was once a pupil of Uther Lightbringer, founder of the Knights of the Silver Hand. I saw how he mishandled Prince Arthas's training. It led to the destruction of my homeland, Quel'Thalas, and I blame Uther and his incompetence for all of it! And now he has a tomb in his honor - how lovely.\n\nMy sources tell me that the scarlet fools are keeping one of his 'holy' relics atop their guard tower near the gates of Hearthglen.\n\nGo to the Western Plaguelands and retrieve it for me.", objectives = "Obtain the Mark of the Lightbringer and return it to Mehlar Dawnblade at the Bulwark in the Western Plaguelands.", progress = "When you've managed to retrieve his 'mark', we're going to change it a bit; make it better.", completion = "The first step is complete. Hand me the Mark of the Lightbringer and I will transform it into something more suitable.\n\nThen my revenge will begin in earnest, <class>!" }
WordHunterWoW_QuestEN[9444] = { title = "Defiling Uther's Tomb", description = "There, that's better.  I've added a little fel magic to it.\n\nNow, you must take it to his resting place in the Western Plaguelands.  Use the corrupted holy symbol in the presence of Uther's statue to defile his tomb!  You'll have to get close for it to work.\n\nTo find the tomb go southeast of the Ruins of Andorhal.  Return to me when the deed is done.\n\nBe quick about it, <class>!", objectives = "Defile Uther's Tomb and return to Mehlar Dawnblade at the Bulwark in the Western Plaguelands.", progress = "It is done, then?  Uther's Tomb is defiled?", completion = "Forgives me?  He FORGIVES ME?!!!\n\nI don't care what that old ghost had to say - it was his fault!  Everything that's happened to Quel'Thalas was a result of his incompetence!\n\nIt is clear that the defiling did not work.  Go, be gone from my sight!  I must think this through." }
WordHunterWoW_QuestEN[9446] = { title = "Tomb of the Lightbringer", description = "Now that you've recovered the Mark of the Lightbringer, all that is left is to return it to Uther's Tomb.\n\nWould you be willing to accompany me there to do this?  It's not far and I would enjoy your company.  Afterward you can come back here and relate the experience to High Priestess MacDonnell.\n\nWhat say you, <name>?", objectives = "Escort Anchorite Truuen to Uther's Tomb in the Western Plaguelands. Afterward, speak with High Priestess MacDonnell at Chillwind Camp in the Western Plaguelands.", completion = "The Lightbringer appeared before you?  That is amazing!  And you made it all possible through your selfless help to the anchorite.\n\nIf even half of the stories are to be believed, Uther was a great man.  And, like him, you are a true hero to all of the good people of Azeroth, <name>!" }
WordHunterWoW_QuestEN[9447] = { title = "Administering the Salve", description = "I've prepared a simple salve that should restore our grunts' strength with the herbs you brought me.  Take it and administer it to any debilitated grunts you see in the vicinity.  Return to me when you're done.", objectives = "Earthcaller Ryga wants you to administer the Healing Salve to 10 Debilitated Mag'har Grunts nearby Mag'har Post in Hellfire Peninsula.", progress = "You've returned, <name>.  Is your task complete?", completion = "May the spirits bless you, <name>.  The Mag'har are in your debt." }
WordHunterWoW_QuestEN[9448] = { title = "ercy for the Cursed", description = "That blood elf witch, Cersei Dusksinger, has been cursing the Lost Ones, I just know it!  I don't know why or how, but the results are tragic.  Several of the Lost Ones have now been further corrupted - cursed with even more fel energies!\n\n<class>, can you find it in you to take pity on these poor creatures?  They should not have to live out the rest of their lives in such a horrible condition.\n\nYou'll find these cursed Lost Ones at the Fallow Sanctuary, east down the path.", objectives = "Slay 3 Cursed Lost Ones and then return to Anchorite Avuun at the Harborage in the Swamp of Sorrows.", completion = "It is done then.  I thank you for showing your compassion.  Once corrupted by whatever Cersei was feeding them, there is nothing else that could be done.\n\nThey are now at peace and hopefully my studies of the others will bear fruit so that they can be rehabilitated." }
WordHunterWoW_QuestEN[9449] = { title = "Call of Earth", description = "The time has come, <name>.  You have grown to the point where you are ready to commune directly with the elemental spirits of this world.\n\nBut be warned.  I can sense that the manner of our entry into this world, and its unfortunate side effects, have angered the earth spirits and caused an imbalance of the elements.\n\nIf you are to create your earth totem, you must first speak with the Spirit of the Vale.  You will find it in the Sacred Grove, nestled in the hills to the northwest.Upon completion of this quest you will gain:", objectives = "Speak with the Spirit of the Vale at the Sacred Grove in Ammen Vale.The time has come, <name>. You have grown to the point where you are ready to commune directly with the elemental spirits of this world.\n\nBut be warned. I can sense that the manner of our entry into this world, and its unfortunate side effects, have angered the earth spirits and caused an imbalance of the elements.\n\nIf you are to create your earth totem, you must first speak with the Spirit of the Vale. You will find it in the Sacred Grove, nestled in the hills to the northwest.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9450] = { title = "Call of Earth", description = "The balance of the elements has been disrupted by the violent intrusion of the draenei to the Vale.  Your crash has caused the spirits of earth to be enraged and turn upon the other elements who have come to quell them.  You will learn that an understanding of the elements can only come when all are in harmony.\n\nThus, it falls to you to seek a balance.  Behind me in the grove you will find the restless spirits of earth warring upon the other three elements.  Help restore the balance.Upon completion of this quest you will gain:", objectives = "Slay 4 Restless Elements of Earth and then return to the Spirit of the Vale at the Sacred Grove in Ammen Vale." }
WordHunterWoW_QuestEN[9451] = { title = "Call of Earth", description = "I will now give you a piece of my physical being that you may create your earth totem.  Return it to he who sent you here.\n\nYou and I will be bound together for all time.  Throughout your life the forces of earth will be at your disposal.  The balance will come when your bones return to us at the end of your days.\n\nUse our power wisely.Upon completion of this quest you will gain:", objectives = "Deliver the Earth Crystal to Firmanvaar at the Crash Site in Ammen Vale." }
WordHunterWoW_QuestEN[9452] = { title = "Red Snapper - Very Tasty!", description = "I've found that these waters are bustling with red snapper, a very tasty fish. With a fishing net, I can catch enough to feed dozens of draenei! Unfortunately, I was recently attacked by a creature known as a murloc while netting in the river and have suffered some injuries that prevent me from doing my job. I need help!\n\nUse this fishing net near schools of red snapper, found in the Crystalbrook river to the east, to catch the fish.\n\nWhat do you say? Remember to return the net when you are finished.", objectives = "Use the Draenei Fishing Net to catch 10 Red Snappers. Return both the fish and the net to Diktynna on Azuremyst Isle when the task is complete.", progress = "Watch out for murlocs: Strange and extremely annoying little creatures.", completion = "I hope the murlocs didn't cause too much trouble, <name>. I owe you a great debt of gratitude for all that you've done.\n\nPerhaps I could teach you how to fish? I'll even supply the fishing pole and a bauble." }
WordHunterWoW_QuestEN[9453] = { title = "Find Acteon!", description = "You did a wonderful job, {name}. Our people will be thankful for this bounty. With that said, would you mind taking this haul of red snapper to Acteon at Azure Watch?\n\nHe shouldn't be hard to find as he is awaiting this catch.", objectives = "Deliver the Crate of Red Snapper to Acteon at Azure Watch.", progress = "What do you think of my armor? Crafted it myself! It's a little different than what we'd traditionally wear but extremely comfortable.", completion = "Poor Diktynna... That murloc gave her quite a scare.\n\n<Acteon sighs.>\n\nHopefully she will recover from the injuries soon...\n\nSo I presume you're looking for work. Well there's plenty of that to be found at Azure Watch!" }
WordHunterWoW_QuestEN[9454] = { title = "The Great Moongraze Hunt", description = "You're starting to make a name for yourself, {name}. How about trying your hand at hunting?\n\nBack on Draenor, our greatest hunters would hunt a beast that resembled the moongraze stag of this region known as a talbuk.\n\nIf you think yourself draenei enough, go out into the wilds and kill enough stags to fill your pack with meat.\n\nYou will find them grazing south of Azure Watch. Watch out for their horns!", objectives = "Bring 6 Moongraze Stag Tenderloins to Acteon at Azure Watch.", progress = "The stag hides are frail which tend to make for tender, succulent flesh.", completion = "Well done, <name>, well done!\n\nHere, I cooked up some tenderloins while you were gone. Maybe you'd like the recipe, too?" }
WordHunterWoW_QuestEN[9455] = { title = "Strange Findings", description = "The crystal you found on the nightstalker runt's body appears to be a piece of the Exodar. This may help explain the unusual appearance and demeanor of some of the animals in this region.\n\nTake the crystal back to Azure Watch. The exarch will surely want to know about this discovery.", objectives = "Deliver the Faintly Glowing Crystal to Exarch Menelaous at Azure Watch.", progress = "You found what? Where?", completion = "How did such a thing end up in the stomach of a nightstalker? Could the debris from the crash have contaminated more beasts?" }
WordHunterWoW_QuestEN[9456] = { title = "Nightstalker Clean Up, Isle 2...", description = "I'm not going to make any excuses for what you've found. This is clearly our fault. We had gotten reports of crushed crystal fragments showing up in the river to the east but chose to ignore the implications. Now we can either sit around on this island and cry about the tragedy that has befallen this land or we can do something about it and prevent it from spreading.\n\nIf you've got the stomach for it, I want you to go back into the wilds and kill as many of the infected nightstalkers as you can find.", objectives = "Exarch Menelaous at Azure Watch has asked that you slay 8 Infected Nightstalker Runts.", progress = "We can't risk this contamination spreading. The reports I've heard come from Blood Watch are bad enough. This has to be stopped now!", completion = "I just hope it's not too late..." }
WordHunterWoW_QuestEN[9457] = { title = "An Unusual Patron", description = "So this Naias is the mastermind behind the Bloodscalp and their exotic magic? I'll admit, this is the last place I expected my inquiry to lead, but no matter, our findings may still prove useful.\n\nOff the coast to the northwest is an island inhabited by lesser water elementals. There's a crude stone slab there that might serve as an altar for the likes of the trolls. Take the totem you found to that altar. Let's see if we can draw this Naias out and distill his power into a more agreeable form.", objectives = "Use the Gift of Naias near the Altar of Naias to summon the water elemental Naias. Defeat him and return to Nemeth Hawkeye at Grom'gol Base Camp with the Heart of Naias.", progress = "What news of Naias, <name>?", completion = "I can feel the raw power contained in this gem, <name>. I'll send it to Silvermoon for our magisters to study further, but I am sure it will prove useful in our struggle against the Amani.\n\nYour help has been invaluable in procuring this gem, and I will see to it that the Farstriders know the name of the <race> who made this find possible." }
WordHunterWoW_QuestEN[9460] = { title = "Combining Forces", description = "Keltus Darkleaf reporting for duty!\n\nOh... who are you, anyhow?  If you are here for my report, I insist you help me first.\n\nI am planning to attack the sentinel spies, but I intend to send in my faithful Whisper as a first strike.  She just needs a scent to hone in on them.\n\nSurely someone of your skill could sneak in and steal something from the sentinel leader?You will receive:", objectives = "Keltus Darkleaf wants you to pickpocket the Lacy Handkerchief from the Sentinel Leader and bring it to him." }
WordHunterWoW_QuestEN[9461] = { title = "Call of Fire", description = "You should know that The Prophet has been asking for you, having heard of your success in your trial. The creation of your fire totem will have to wait until you have spoken with him.\n\nThis is a rare honor; you must hurry to the Exodar to see him at once!Upon completion of this quest you will gain:", objectives = "Seek out Prophet Velen at the Vault of Lights in the Exodar.You should know that The Prophet has been asking for you, having heard of your success in your trial. The creation of your fire totem will have to wait until you have spoken with him.\n\nThis is a rare honor; you must hurry to the Exodar to see him at once!Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9462] = { title = "Call of Fire", description = "<name>! It is time for you to receive further training in the ways of the spirits. You should seek out Tuluun, the shaman at Azure Watch. He can begin your introduction to understanding and harnessing the power of flame.Upon completion of this quest you will gain:", objectives = "Speak with Tuluun at Azure Watch on Azuremyst Isle." }
WordHunterWoW_QuestEN[9463] = { title = "Medicinal Purpose", description = "I have found that lashers milling about on the island hold restorative medicinal properties in their vines. Through proper treatment, the vines can be broken down into a powerful healing ointment. Unfortunately, with so many injured draenei passing through Azure Watch, we are always in short supply.\n\nOur delicate guest was found injured and unconscious by the Crystalbrook only yesterday. If you bring me vines, we may be able to save her.\n\nYou will find root trappers both south and east of Azure Watch.", objectives = "Anchorite Fateema at Azure Watch wants you to bring her 8 Root Trapper Vines.", progress = "I fear that her health is in steady decline.", completion = "Let us hope that this ointment will strengthen her spirit!" }
WordHunterWoW_QuestEN[9464] = { title = "Call of Fire", description = "Once again you are to be tested, and this time the chaotic element of fire must be understood if you're to create a totem to harness its energies.\n\nTo the northeast on the coast is a sacred place of fire known as Emberglade. Amidst its burned trees stands Temper, a fire elemental of great power, and the one that you must speak with.\n\nGo to him now and may the elemental spirits of Azeroth go with you.Upon completion of this quest you will gain:", objectives = "Speak with Temper at Emberglade on Azuremyst Isle.Once again you are to be tested, and this time the chaotic element of fire must be understood if you're to create a totem to harness its energies.\n\nTo the northeast on the coast is a sacred place of fire known as Emberglade. Amidst its burned trees stands Temper, a fire elemental of great power, and the one that you must speak with.\n\nGo to him now and may the elemental spirits of Azeroth go with you.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9465] = { title = "Call of Fire", description = "One of my brethren, Hauteur, has gone insane, no doubt because of the crash of your ship.  He's begun demanding that the local owlbeasts worship him.\n\nThis will not continue!  None of us would ever impersonate a god!  It falls to you to restore the balance.\n\nFirst, you must retrieve their ritual torch, which has been taken by the crazed wildkin inside Stillpine Hold to the west.\n\nReturn the torch to me.Upon completion of this quest you will gain:", objectives = "Retrieve the Ritual Torch and return it to Temper at Emberglade on Azuremyst Isle." }
WordHunterWoW_QuestEN[9466] = { title = "WANTED: Blacktalon the Savage", description = "By order of the Ranger Captain, a reward is hereby offered for the slaying of the vicious rockflayer matriarch known as Blacktalon the Savage.\n\nBlacktalon was last sighted inside a cave in the Great Fissure.  Individuals seeking the reward are to present the creature's claws as proof of the deed.", objectives = "Bring Blacktalon's Claws to Ranger Captain Venn'ren at Falcon Watch in Hellfire Peninsula.", progress = "You have news regarding Blacktalon?", completion = "You're a brave <class>, <name>.  That savage beast took many of my best hunters' lives.\n\nTake this reward, you've earned it." }
WordHunterWoW_QuestEN[9467] = { title = "Call of Fire", description = "The owlbeasts of Moonwing Den on Silvermyst Isle, far to the southwest, have been deluded into thinking that Hauteur is a god to be worshipped.  What he truly is, is a fallen elemental who needs to be put out of his misery.  That torch is the key to his downfall.\n\nHauteur regularly demands that these owlbeasts burn an effigy in his honor.  So, when you light it, he will come.  Slay him and bring me the ashes.  Then use the orb in the satchel that I will give you to return to me here.Upon completion of this quest you will gain:", objectives = "Retrieve Hauteur's Ashes and then return them and the Ritual Torch to Temper at Emberglade on Azuremyst Isle. Remember that you can use the Orb of Returning to teleport back to Temper once you have the ashes." }
WordHunterWoW_QuestEN[9468] = { title = "Call of Fire", description = "You have done a great thing here today in your pursuit of understanding your relationship to the flame.  Remember to always treat it with the utmost respect lest you get burned.\n\nI saved a portion of Hauteur's ashes for you.  Use them in the creation of your fire totem and remember all that you have learned in their attainment.\n\nNow, return to Tuluun.Upon completion of this quest you will gain:", objectives = "Deliver Hauteur's Ashes to Tuluun at Azure Watch on Azuremyst Isle." }
WordHunterWoW_QuestEN[9469] = { title = "Featherbeard's Endorsement", description = "When I am finally granted an audience with Falstad Wildhammer, I hope to have our strongest advocate among the Wildhammer dwarves at my side, <name>.\n\nFeatherbeard is revered among his people, both for his legendary gryphon training skills and for his wisdom. If anyone can sway Falstad Wildhammer, it is he.\n\nI would go to see him myself, except that I cannot leave the confines of Aerie Peak while awaiting my audience. Visit Featherbeard at his residence to the south and ask if he will speak with me.", objectives = "Go to Featherbeard's Hovel and visit the dwarf if he is at home. If he is not at home, search for evidence of where he can be found.", completion = "Featherbeard's journal appears to have a large number of recent entries. Leafing back to the beginning of the latest ones, you begin searching for clues about where he might have gone." }
WordHunterWoW_QuestEN[9470] = { title = "A Gesture of Goodwill", description = "The rugged terrain of the Hinterlands is not only home to the Wildhammer dwarves and their gryphons, but also to a number of forest troll tribes.\n\nThe trolls view the Wildhammers as squatters on their ancestral lands and spare no opportunity to accost the dwarves by attacking the gryphon aeries. One way to prove ourselves in the eyes of the Wildhammer is to help staunch these attacks by killing a Witherbark leader, Witch Doctor Mai'jin, who shelters in a cave at Bogen's Ledge, to the west of Shadra'Alor.", objectives = "Ambassador Rualeth at Aerie Peak wants you to slay Witch Doctor Mai'jin and his pet spider Tcha'kaz.", completion = "Well done, <name>. The Wildhammers will be heartened to know that they don't stand against the Witherbark trolls alone. Showing them that the Alliance can prove a reliable partner in protecting the gryphons should lend more weight to our proposition." }
WordHunterWoW_QuestEN[9471] = { title = "Preying on the Predators", description = "The Wildhammer dwarves act as companions, caretakers, and trainers to the gryphons. The gryphons have no shortage of enemies, especially among the forest troll tribes.\n\nSometimes, though, the threat comes from natural predators, such as wolves. A single animal is no match for a gryphon, but packs have taken to targeting gryphons more often because normal prey is scarce. Culling the wolves can help to reduce their impact on the gryphons and ingratiate us to the Wildhammer.", objectives = "Ambassador Rualeth at Aerie Peak wants you to kill 10 Mangy Silvermane and 5 Silvermane Wolves.", completion = "<Ambassador Rualeth nods as you give your report.>\n\nYou have done well. The culling of the silvermane will not go unnoticed by the Wildhammer. When I meet with their leaders, I am certain that your deeds will reflect well upon the Alliance. Please accept this coin as a small token of my thanks, <name>." }
WordHunterWoW_QuestEN[9472] = { title = "Arelion's Mistress", description = "With all the important matters at hand Arelion still found time in his schedule to see a mistress!\n\nIt's all becoming perfectly clear.  Viera Sunwhisper, that filthy wench... we'll show her to never cross a magistrix again.\n\nTake this scroll and find Viera.  Find a way to lure her away from town and use the scroll on her.\n\nArelion mentioned she couldn't resist a particular wine harvested by the cenarion druids.  You might find some at Cenarion Refuge, just inside Zangarmarsh, west of here.", objectives = "Magistrix Carinda at Falcon Watch wants you to lure Viera Sunwhisper away from the settlement and then use Carinda's Scroll of Retribution on her.", completion = "Excellent!  That little backstabber won't be running off with anyone's husband any time soon.\n\nHere's a little something for your troubles.  I trust we can keep this incident between us, <name>." }
WordHunterWoW_QuestEN[9473] = { title = "An Alternative Alternative", description = "The girl is too far gone for mere ointments to be effective. There may be another way...\n\nThe forest of Azuremyst holds many secrets, one of those being a rare plant known as the azure snapdragon that some claim to be a panacea - a cure all.\n\nYou can identify the plant by its stark contrast to the other plants of Azuremyst and its need to grow at the base of the azure pine trees. Make haste!\n\nAnd {name}, be wary of the root threshers of the region as they consume snapdragon for sustenance.", objectives = "Daedal at Azure Watch wants you to bring him 5 Azure Snapdragon Bulbs.", progress = "Do not waste time, boy.", completion = "Watch as the plant works its magic." }
WordHunterWoW_QuestEN[9474] = { title = "The Mark of the Lightbringer", description = "In the short time that I have been on Azeroth I have studied many of its heroes.  Of them all, Uther Lightbringer stands above the rest.  A hero for the ages, in the end Uther was betrayed by his most promising pupil, Arthas.\n\nIn his honor, I would like to return something he lost to his nearby tomb.  It is rumored that the Scarlet Crusade is keeping one of his holy relics atop their guard tower near the gates of Hearthglen.\n\nPlease, <class>, go and retrieve it.", objectives = "Obtain the Mark of the Lightbringer and return it to Anchorite Truuen at Chillwind Camp in the Western Plaguelands.", progress = "The Mark of the Lightbringer is a powerful symbol of Uther's faith in the Light.", completion = "Thank you, <class>!  The recovery of this holy symbol means a great deal to myself and others that honor the memory of Uther Lightbringer." }
WordHunterWoW_QuestEN[9475] = { title = "Reclaiming the Eggs", description = "Looking over the remains, you surmise that this broken and battered skeleton must be all that is left of Featherbeard. Clutched in one skeletal hand is a torn and stained sheaf of paper. You gently remove and unroll it, revealing a hand-drawn map and a few hastily scrawled notes.\n\nThe map appears to be a rendering of Shadra'Alor and its three temples with 'x' marks in several places, presumably the locations of the stolen eggs. You place the map in your pack for inspection at a safer location.", objectives = "Gather 5 Gryphon Eggs and return them to Ambassador Rualeth at Aerie Peak.", progress = "The look on your face marks you as the bearer of bad news. What have you discovered?", completion = "<Handing the eggs to the ambassador, you describe the findings at Featherbeard's Hovel and Shadra'Alor.>\n\nThe Witherbark killed Featherbeard?\n\n<Rualeth's face contorts in horror at your description of the dwarf's death and the implications for Rualeth's mission.>\n\nI understand why he felt he had to go in search of the eggs, but I wish he'd thought to bring others along. His death will no doubt enrage Falstad Wildhammer, triggering retaliation against the trolls, and delaying my audience indefinitely." }
WordHunterWoW_QuestEN[9476] = { title = "In Pursuit of Featherbeard", description = "The journal's most recent entries detail Featherbeard's concern about a growing number of Witherbark troll raids on the Wildhammer gryphon aeries and a rash of egg thefts. A search of the smaller Witherbark settlements in the area appears to have yielded no information.\n\nThe last entry describes Featherbeard's suspicion that a Witherbark witch doctor named Mai'jin is behind the raids. The last, hastily written sentence states the dwarf's intention to travel to Shadra'Alor in search of the eggs.", objectives = "Travel to Shadra'Alor and search for traces of Featherbeard.", completion = "Upon the altar is a heap of bones that appear to have belonged to a dwarven male. No identifying features remain, but you decide to search the body for confirmation that these are the remains of Featherbeard." }
WordHunterWoW_QuestEN[9483] = { title = "Life's Finer Pleasures", description = "", objectives = "Just because we're on this pilgrimage doesn't mean we have to give up all of life's pleasures.  It's been ages since I had a good wine.\n\nI'd literally kill for a bottle of cenarion spirits!\n\nI know, I know, how unfashionable of me to enjoy a drink brewed by night elves.", progress = "Just because we're on this pilgrimage doesn't mean we have to give up all of life's pleasures.  It's been ages since I had a good wine.\n\nI'd literally kill for a bottle of cenarion spirits!\n\nI know, I know, how unfashionable of me to enjoy a drink brewed by night elves.", completion = "You know, maybe we can become friends after all.  Follow me; we don't want to have to share this with the others now, do we?" }
WordHunterWoW_QuestEN[9484] = { title = "Taming the Beast", description = "You have undoubtedly hunted and slain beasts for both your defense and sustenance, yet to befriend them and harness their strengths is only now within your grasp.  This I can teach you.\n\nTake this magical taming rod that allows a wild animal to temporarily bond and fight beside you.  Begin with the crazed dragonhawk, a nearly docile bird found just outside of Farstrider Retreat.  Return to me when this is done.Upon completion of this quest you will gain:", objectives = "Use the Taming Rod to tame a Crazed Dragonhawk, and then return to Lieutenant Dawnrunner." }
WordHunterWoW_QuestEN[9485] = { title = "Taming the Beast", description = "You have done well, <name>.  Your understanding of the wild grows quickly.\n\nThe mistbat is a clever hunter, combining the swiftness of the dragonhawk and the ferocity of the springpaw.  Mistbats are found just across the Elrendar River to the south, preying on hapless travelers who wander into the Ghostlands.\n\nUse this final taming rod to befriend a mistbat and return to me when you have finished.You will learn:", objectives = "Use the Taming Rod to tame a Mistbat, and then return to Lieutenant Dawnrunner." }
WordHunterWoW_QuestEN[9486] = { title = "Taming the Beast", description = "The elder springpaw is an efficient and swift hunter.  In attempting to befriend one, it sees you as prey.  Do not be dissuaded.\n\nUse the taming rod to bring the great cat to your side and hunt beside it.  They are found throughout Eversong Woods, some very close to the lodge.  When you have learned enough, return to me.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Taming Rod to tame an Elder Springpaw, then return to Lieutenant Dawnrunner." }
WordHunterWoW_QuestEN[9487] = { title = "Arcane Reavers", description = "Arcane reavers are magical creations of brute strength.  They are heavily armored and deliver stunning blows.  You, however, can bypass their defenses and avoid their attacks.  Your spellcraft is not without many advantages, {name}.\n\nTravel to Dawnstar Spire and blast apart the arcane reavers.  From their remains, collect the crystallized fragments of magical energy and return to me.  Dawnstar Spire is found to the east, across the lake.", objectives = "Arcanist Vandril wants you to collect 10 Arcane Fragments for him.", progress = "Didn't get too close to the brutes, I hope?", completion = "Such a waste, using magic to construct beings of physical strength.  I always thought that's why we allied with the lesser races, after all.\n\nYou were good to destroy them so we can use what remains for a more suitable purpose." }
WordHunterWoW_QuestEN[9488] = { title = "A Simple Robe", description = "The arcane fragments you collected will do nicely.\n\nNicely for what, you ask?  For making a splendid robe fit for a {class} like yourself!\n\nAll we need now is some linen cloth and a spindleweb silk gland.  You can find the silk gland from any spindleweb spider, preferably after killing them.", objectives = "Arcanist Vandril wants you to bring him 15 Linen Cloth and a Spindleweb Silk Gland.", progress = "The robe cannot be completed without the necessary supplies.  But you knew that, didn't you?", completion = "You really don't need to know the intricacies of crafting a magical robe, <name>, you just need to know what to bring me.\n\nAnd let me be honest, you brought enough for several robes.  The profit I'll make should more than cover the costs to make your robe, and even enough to buy myself something nice.  Looks like the thanks belong to you!" }
WordHunterWoW_QuestEN[9489] = { title = "Cleansing the Scar", description = "<name>, it is good you are here.  The Scourge attack our city with such endless hate that I fear the morale of our guard is breaking.\n\nHurry to the Dead Scar just south of the city where Jaela and her rangers stand ready.  Fill them with the power of the Light through your blessings.You will receive:", objectives = "Cast Power Word: Fortitude on 6 Eversong Rangers in the Dead Scar." }
WordHunterWoW_QuestEN[9490] = { title = "The Rock Flayer Matriarch", description = "Rock flayers are mean, nasty, violent creatures.  But the plain ones are like tame beasts when compared to their matriarch, Blacktalon the Savage.\n\nMy cousin got eaten by her and it wasn't pretty.  I swore that one day Blacktalon would pay for that.  You bring back proof of that monster's death and I will give you my life's savings.  Deal?\n\nYou'll find her inside a cave in the Great Fissure.  Good luck!", objectives = "Obtain Blacktalon's Claws from Blacktalon the Savage at the Great Fissure and bring it to Ikan at the Temple of Telhamat in Hellfire Peninsula.", progress = "Did you bring back proof of Blacktalon's death, <name>?", completion = "Yes, I remember these sharp claws!\n\nTake this reward, <name>.  That was a dangerous task you just did.  You deserve every bit of this reward." }
WordHunterWoW_QuestEN[9491] = { title = "Greed", description = "A rich, and I mean filthy rich, merchant came through here yesterday talking about some ring of \"immense archeological importance\" locked in one of the countless burial chests found in the Amani Catacombs.  When he wasn't talking about the ring, he was talking about how much he'd pay for it.\n\nTell you what, I'll front the thieves' tools, and if you manage to bring the ring back, I'll pay you enough to buy ten rings of your own!You will receive:", objectives = "Eralan in Tranquillien wants you to retrieve the Pitted Gold Band from the Amani Catacombs." }
WordHunterWoW_QuestEN[9492] = { title = "Turning the Tide", description = "The permanence of the orcish threat is one of the sad truths of Outland. There was a time when we Sons of Lothar believed we'd purchased Honor Hold's safety with our blood, but there was to be no peace.\n\nThe Sons will yield to no orc - green, brown, and now red - we will overcome them or die trying. If we are to have any expectation of victory, we must take the fight to them in Hellfire Citadel. Bring me the weapon of their self-styled 'Warchief' Kargath Bladefist and you will be well rewarded.", objectives = "Bring Warchief Kargath's Fist to Force Commander Danath Trollbane in Honor Hold.", progress = "Have you returned with proof of 'Warchief' Kargath Bladefist's demise?", completion = "Well done, <name>. With your victory in Hellfire Citadel, we have struck a major blow against the orcs.\n\nI must speak with Field Commander Romus about following up and ensuring that the orcs stay on the defensive. Now that we've been reinforced, we can do far more than simply defend Honor Hold." }
WordHunterWoW_QuestEN[9493] = { title = "Pride of the Fel Horde", description = "We know precious little about the Fel Horde presence in Hellfire Citadel and our information has come at the cost of many lives.\n\nFel Horde troops under the command of Kargath Bladefist are a brutal, battle-hardened lot fortified by foul magics. The elite of this force, the Shattered Hand legionnaires, champions, and centurions are feared by the regulars and serve as an officer corps.\n\nTargeting and eliminating them is a necessary first step in any successful assault on the Fel Horde's leadership.", objectives = "Field Commander Romus at Honor Hold wants you to kill 8 Shattered Hand Legionnaires, 4 Shattered Hand Centurions, and 4 Shattered Hand Champions.", completion = "That is excellent news, indeed, <name>. With progress to report from Hellfire Citadel, perhaps we can afford to turn our attention to the Fel Horde presence other parts of the peninsula and Outland as a whole." }
WordHunterWoW_QuestEN[9494] = { title = "Fel Embers", description = "The stuffy academics of Azeroth have cowered in their towers for too long and it's fallen to me to show them what cutting edge research is! They're afraid to play with fire and that's exactly what I intend to do, once I get my hands on the fire, that is.\n\nWithin Hellfire Citadel's Shattered Halls, Grand Warlock Nethekurse performs unrivaled magical feats augmented by the powers of a pair of strange braziers. Using the vessel he uses to contain these fel embers, capture one and bring it back to me, <name>.", objectives = "Magus Zabraxis at Honor Hold wants you to bring her a Fel Ember.", progress = "<Magus Zabraxis glances over at Amythiel Mistwalker and lowers her voice.>\n\nDid you bring the, err, ember?", completion = "Well done! I can't hope to replicate the feats of Grand Warlock Nethekurse, nor should I aspire to, but we would be fools to ignore the power of the fel embers.\n\nHowever, there are those who would forbid the type of research I'm about to embark upon, and for that reason, I must keep my efforts secret. Please do not speak of this to anyone, <name>." }
WordHunterWoW_QuestEN[9495] = { title = "The Will of the Warchief", description = "The struggle to free the orcish people from our tainted blood has not been easy, <name>. Warchief Thrall has seen too many orcish heroes laid low by fate's hand. Now, it seems Kargath Bladefist numbers among them.\n\nIn the Shattered Halls of Hellfire Citadel, Kargath has claimed the title of 'Warchief' of the Fel Horde. With an army of crazed, bloodthirsty fel orcs at his back, he won't rest until Thrallmar is destroyed. Warchief Thrall has commanded us to defeat Kargath and his forces at all costs.", objectives = "Bring Warchief Kargath's Fist to Nazgrel in Thrallmar.", progress = "Have you proof of Kargath Bladefist's defeat?", completion = "You have done well, <name>. In his prime, Kargath Bladefist was a fine warrior, a hero and example to his people.\n\nHis death is a blow to us all, but especially to Warchief Thrall. Whatever happened to him in his final days, we should not forget the orc Kargath once was, nor the lessons to be learned from his downfall.\n\nFor your service to the Horde, <name>, you are to be rewarded with your choice from among these weapons." }
WordHunterWoW_QuestEN[9496] = { title = "Pride of the Fel Horde", description = "Overlord Maimfist's insults aside, <name>, this Fel Horde is nothing to be trifled with.\n\nFrom what we know, Fel Horde troops under the command of Kargath Bladefist are a brutal, battle-hardened lot fortified by foul magics. The elite of this force, the Shattered Hand legionnaires, champions, and centurions are feared by the Fel Horde regulars and serve as an officer corps.\n\nTargeting and eliminating them is a necessary first step in any successful assault on the Fel Horde's leadership.", objectives = "Shadow Hunter Ty'jin at Thrallmar wants you to kill 8 Shattered Hand Legionnaires, 4 Shattered Hand Centurions, and 4 Shattered Hand Champions.", completion = "Excellent job, <name>. With the legionnaires broken, it will be easier to face the Fel Horde on the battlefield, though they remain a formidable enemy." }
WordHunterWoW_QuestEN[9497] = { title = "Emblem of the Fel Horde", description = "When word of the so-called 'Fel Horde' reached the Warchief's ears, he was both furious and greatly saddened. Like Rend's pretenders before them, this false Horde too will fall, and its banner will adorn the wall of Grommash Hold as a testament to the Warchief's might.\n\nIt falls to you to carry out the Warchief's will in this matter, <name>. It will not be an easy task, for the banner is guarded by a champion of this Fel Horde, known as Warbringer O'mrogg, and he will not yield his charge without a fight.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay Warbringer O'mrogg and capture the Fel Horde Banner, then return it to Overlord Hun Maimfist at Thrallmar." }
WordHunterWoW_QuestEN[9498] = { title = "Falcon Watch", description = "My people recently finished building Falcon Watch, a base of operations in the southwestern region of Hellfire Peninsula - beyond Hellfire Citadel.  You are welcome there as an ally, {name}.\n\nIf you're looking for work, go there and tell Ranger Captain Venn'ren that I sent you.  He will see to it that you're given tasks worthy of someone of your caliber.", objectives = "Report to Ranger Captain Venn'ren at Falcon Watch in Hellfire Peninsula.", completion = "Welcome to Falcon Watch, <race>.  All our Horde allies are welcome here, especially those recommended by Martik." }
WordHunterWoW_QuestEN[9499] = { title = "Falcon Watch", description = "What are you still doing here, {name}?  Didn't you hear we built a proper sin'dorei outpost here in Hellfire Peninsula?\n\nSurely you'd rather be among fellow blood elves and away from all this... smell.  You'll find Falcon Watch in the southwest, beyond Hellfire Citadel.  Report to Ranger Captain Venn'ren; he will take care of you.\n\nThe road ahead is dangerous and heavily patrolled by Alliance scouts.  I would recommend travelling with companions.  Blood elves, preferably.", objectives = "Travel to Falcon Watch in the southwest of Hellfire Peninsula and report to Ranger Captain Venn'ren.", completion = "Welcome to Falcon Watch, brother.  Many other blood elves haven't been fortunate enough to make it this far.\n\nIt's a terrible shame; our work in Outland has just begun." }
WordHunterWoW_QuestEN[9500] = { title = "Call of Water", description = "It's been a while since last you were tested.  Farseer Nobundo has been asking for you.  You must have grown greatly in wisdom because you are being called to learn the mysteries of the element of water.\n\nYou remember where to find him at the Crystal Hall inside of the Exodar, right?", objectives = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", completion = "We meet again. I have been watching your progress from afar, <class>, and I am pleased.\n\nThe time has come for you to commune with the element of water, to learn its mysteries and give yourself over to the water so that you might in turn learn to master it." }
WordHunterWoW_QuestEN[9501] = { title = "Call of Water", description = "A powerful water elemental named Aqueous has requested your presence.  It would seem that there is a great imbalance occurring in the water element on Bloodmyst Isle.  Not surprising given the unnatural predilections of the blood elves.\n\nYou will find Aqueous in a hidden reef under the waves off the northern shore of Bloodmyst Isle.\n\nTake this potion; it can help you to get to her once you get into the water near the reef.Upon completion of this quest you will gain:", objectives = "Speak with Aqueous in the Hidden Reef at Bloodmyst Isle.\n\nProvided item:" }
WordHunterWoW_QuestEN[9502] = { title = "Call of Water", description = "It's been a while since last you were tested.  Farseer Nobundo has been asking for you.  You must have grown greatly in wisdom because you are being called to learn the mysteries of the element of water.\n\nYou remember where to find him at the Crystal Hall inside of the Exodar, right?Upon completion of this quest you will gain:", objectives = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle." }
WordHunterWoW_QuestEN[9503] = { title = "Call of Water", description = "In balance with the other elements, water is the source and sustenance of all living things.  It gives and nurtures life, and all rely upon it for their existence.  Yet, when polluted, it also brings life to an end.\n\nWe must determine the extent of the damage that has been done.  To the southwest is one such contaminated body of water that has come to be known as the Foul Pool.  Travel there and extract the foul essence from the water spirits that inhabit the pool.Upon completion of this quest you will gain:", objectives = "Collect 6 Foul Essences and return them to Aqueous in the Hidden Reef at Bloodmyst Isle." }
WordHunterWoW_QuestEN[9504] = { title = "Call of Water", description = "It is worse than I feared. The corruption is very potent and if unchecked it could spread to the ocean currents and be carried throughout all of Azeroth!\n\nWe are going to need a sample of the purest water to counter this malignancy. There are ruins on the untainted portion of this island, to the southeast. Go there, where the Wrathscale naga reside, and take from their fountain.\n\nUse this bota bag to gather the sample. Hurry, <name>!Upon completion of this quest you will gain:", objectives = "Fill the Empty Bota Bag and then return to Aqueous in the Hidden Reef at Bloodmyst Isle." }
WordHunterWoW_QuestEN[9505] = { title = "The Prophecy of Velen", description = "The Prophet spoke of this day: That on this island, in this new world, our allies would find us.\n\n\"We will be tested. They will ask that we pay for the sins of our fathers...\"\n\nAt the time, I did not understand the meaning behind his words, but seeing this creature and her reaction to us, it is now coming into focus. The corruption of our people has been felt even here.\n\nVenture south. It is there that we found this being. Find its kin and tell them of our people.", objectives = "Daedal wants you to travel south and seek out the people that the injured creature mentioned.", completion = "You say that you've found one of our crew and that she is injured? I will send one of my crewmen to your village immediately!" }
WordHunterWoW_QuestEN[9506] = { title = "A Small Start", description = "I am Admiral Odesyus of Alliance Naval Command. Our ship was forced to port on your island due to an infestation of sorts. It's embarrassing to even talk about, but goblins somehow managed to stow away in the holds of both of my ships.\n\nLast night, while most of the ship's crew was asleep below deck, they struck!\n\nStranger still, they took our navigation gear and jumped ship!\n\nThey disappeared into the thicket, east of here. Will you go in search of our gear? It will make for a strong gesture.", objectives = "Admiral Odesyus at Odesyus' Landing wants you to recover the Nautical Compass and Nautical Map stolen by the Venture Co.", progress = "Any luck, stranger?", completion = "You're a resourceful one! With our navigation gear, we can figure out just how far we've veered off course.\n\nBut wait, what's this? There's something rolled up in the map. Let me see...\n\nThese are orders from Mogul Razdunk of the Venture Company. According to these plans, they're here to strip-mine the island of the crystal wreckage, then hijack our ships once they're finished.\n\nBy Bronzebeard's bushy brow! This is why they forced us to land? How could they know of our plans?\n\nI smell a traitor..." }
WordHunterWoW_QuestEN[9507] = { title = "<DEPRECATED>From the Desk of Mogul Razdunk", description = "According to these plans, the goblins are here for the crystal wreckage of the Exodar. It would appear that the goblins are intent on strip-mining the island of the crystals and hijacking the two Alliance ships docked off-shore once their task is complete.\n\nYou should probably take these plans to Admiral Odesyus.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the Top Secret Venture Co. Plans to Admiral Odesyus at Odesyus' Landing." }
WordHunterWoW_QuestEN[9508] = { title = "Call of Water", description = "I have determined where the corruption is coming from.  It is the by-product of some demented research and you're going to put an end to it!\n\nJust to the southwest of the Foul Pool is a small camp.  There you will find the 'research' of Tel'athion the Impure.  This is where he produces the filth that has been seeping into the island's water.\n\nUse the pure water you obtained from Ashenvale to destroy his cache of barrels.  That will be sure to bring him out.\n\nWe will have an end to this!Upon completion of this quest you will gain:", objectives = "Bring the Head of Tel'athion to Aqueous in the Hidden Reef at Bloodmyst Isle." }
WordHunterWoW_QuestEN[9509] = { title = "Call of Water", description = "I held back a little of the water from Ashenvale, not because I doubted your ability to deal with the situation.  Rather, I knew that you would succeed, and I wanted to make sure that you had something special to take back to Nobundo.\n\nHere, <name>, take this flask of pure water.  It will ensure that you receive a very powerful water totem.\n\nFarseer Nobundo awaits your return at the Exodar.You will learn:", objectives = "Take the Flask of Purest Water to Farseer Nobundo inside the Exodar on Azuremyst Isle." }
WordHunterWoW_QuestEN[9510] = { title = "Bristlehide Clefthoof Hides", description = "So you're looking to make yourself useful?  We're in very short supply of clefthoof hides, <name>.\n\nIf you go southwest of here you'll find bristlehide clefthoof in abundance near a place called Falcon Watch.  Their hides are ideal for leatherworking.  Bring me a stack of them and I'll reward you appropriately.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Provisioner Braknar at Mag'har Post in Hellfire Peninsula wants you to bring him 5 Bristlehide Clefthoof Hides." }
WordHunterWoW_QuestEN[9511] = { title = "Kargath's Battle Plans", description = "<TXT>The documents you found on Kargath's body detail plans on what appears to be a massive invasion on Honor Hold.", objectives = "<TXT>The documents you found on Kargath's body detail plans on what appears to be a massive invasion on Honor Hold." }
WordHunterWoW_QuestEN[9512] = { title = "Cookie's Jumbo Gumbo", description = "The Admiral be right, ye are a resourceful one. Mayhap ye could help Cookie out?\n\nIf I serve the crew chicken for dinner again, I'll be sent to the brig fer sure.\n\nI noticed that thar be crawlers all along the coastline - lots o' crawlers! Bring me crawler meats and I'll be forever indebted to ya.\n\nHelp a reformed pirate out?", objectives = "\"Cookie\" McWeaksauce at the Odesyus' Landing wants you to bring him 6 Skittering Crawler Meat.", progress = "Arrr... Yarr... Shiver me timbers... Er, sorry lad, I gotta practice me pirate lest I forget it...", completion = "Bless yer heart, stranger. This'll go a long ways in liftin' the morale o' the crew." }
WordHunterWoW_QuestEN[9513] = { title = "Reclaiming the Ruins", description = "While some may look at our current predicament as an unfortunate turn of events, I sense that we are here for a reason. The invisible hand of fate has pushed us in this direction. The reason why will become evident in time.\n\nTo the west lies an ancient night elf city, now in ruin and overrun with naga. It would be remiss of me to sit idly by as the naga tainted my ancestral lands.\n\nYou have shown yourself a capable {class}. Honor my people and cleanse the ruins of their unwelcome inhabitants.", objectives = "Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle wants you to kill 5 Wrathscale Myrmidons, 5 Wrathscale Naga and 5 Wrathscale Sirens.", completion = "Elune be praised! The restless spirits may find tranquility after all." }
WordHunterWoW_QuestEN[9514] = { title = "Rune Covered Tablet", description = "You cannot make out any of the symbols on the tablet. Perhaps the priestess would be able to decipher the mysterious runes.", objectives = "Take the Rune Covered Tablet to Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle.", progress = "You've found something?", completion = "I can't read these runes but I know someone who can..." }
WordHunterWoW_QuestEN[9515] = { title = "Warlord Sriss'tiz", description = "A naga invasion would be disastrous, {name}. I've seen what naga can do and I would not want to see such a catastrophe befall any being. If I were to guess, this Warlord Sriss'tiz will be hidden in a cave - probably along the coast to the west.\n\nFind Warlord Sriss'tiz and put an end to his reign.", objectives = "Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle wants you to kill Warlord Sriss'tiz.", completion = "With Warlord Sriss'tiz dead, the possibility of a naga invasion is now only a distant memory. We are safe, for the time being...\n\nI must admit, I was wrong to think badly of you, <name>. You have shown that you are nothing like the filth that was Archimonde. Accept this as a gift from the night elves." }
WordHunterWoW_QuestEN[9516] = { title = "Destroy the Legion", description = "I will not tolerate their existence on this world! The Burning Legion all but destroyed our race and we fell back to settle a new home on a new world. Then they came again and we retreated, over and over.\n\nNo more!\n\nThere is a remnant of the Legion to the south and west in the regions known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge. They are what is leftover from a force that once long ago invaded this world.\n\nGo and destroy as many as you can before it is too late!", objectives = "Slay any 15 demons at Felfire Hill, Demon Fall Canyon, and Demon Fall Ridge.", completion = "You have my respect and thanks, <class>.  Perhaps we'll be able to create a new home here without having to worry about the Burning Legion yet again." }
WordHunterWoW_QuestEN[9517] = { title = "A Shameful Waste", description = "Welcome to Forest Song, <class>. Where you see tents, there will one day be buildings, but such ambition requires a steady stream of materials. I cannot bring myself to order our workers to fell any of the ancient trees of this grove, but our neighbors to the west have no such reverence for the forest.\n\nWe shall reclaim the tainted wood from Satyrnaar to the west. Take the wood to Gnarl at the Warsong Lumber Camp. He is an Ancient who will purify it for our use.", objectives = "Collect 5 Satyrnaar Fel Wood.", progress = "<The ancient creaks as it turns toward you.>\n\nArchitect Nemos said that you might be bringing wood salvaged from the deforesters' encampment and befouled Satyrnaar.", completion = "Wood cut with orcs' crude blades is warped as surely as that exposed to elemental extremes. Nothing sound can be built with it, but I shall purify it and return it to Architect Nemos and his men for their use. Some good will come from this tragedy, after all." }
WordHunterWoW_QuestEN[9518] = { title = "Agents of Destruction", description = "The Warsong Lumber Camp is a blight upon an embattled landscape. Every time we make progress in halting their operations, Overseer Gorthak orders his loggers to redouble their efforts!\n\nNow, the orcs are cutting more wood than they can possibly use, leaving it to rot while their blades bite into fresh trees! This is an affront to all we stand for, <name>, and we will show them that we'll not suffer further destruction of our lands!\n\nGo, and do not rest until Overseer Gorthak and his minions are dead!", objectives = "Slay Overseer Gorthak and any other 12 Horde at the Warsong Lumber Camp.", completion = "At last we have sent a message that the orcs won't dare ignore. Any overseer or foreman who sets foot within the camp to replace Gorthak will feel my wrath!\n\nWe must press our advantage, <name>, and never rest until the Warsong Lumber Camp is a distant memory and a glade of trees stands upon that ground." }
WordHunterWoW_QuestEN[9519] = { title = "The Lost Chalice", description = "The area to our west, now called Satyrnaar, was once a prominent shrine built by my people. It housed a priceless relic, the Chalice of Elune, entrusted to the shrine's keepers by the priests of Elune. Pilgrims once traveled to the shrine to experience the healing powers the chalice was rumored to hold.\n\nThese stories might be nothing but old wives' tales, but if there is any truth to them, the relic may hold the key to rejuvenating the wounded forest. I must know, <name>.", objectives = "Obtain the Chalice of Elune.", progress = "Can you feel it, <name>, the touch of corruption upon the wind? If we do nothing, it will continue to advance. That is why I seek the Chalice of Elune. Were you able to find it?", completion = "Excellent work, <name>. There is certainly a latent power here, one that not even constant exposure to the corruption of the satyr can dim. Do you see how it still shines, after all these years?" }
WordHunterWoW_QuestEN[9520] = { title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Common tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Forest Song to the north; the location where a new draenei settlement is being established.\n\nPerhaps Vindicator Vedaar at the Warsong Lumber Camp would be interested in these?", objectives = "Deliver the Diabolical Plans to Vindicator Vedaar at the Warsong Lumber Camp in Ashenvale.", progress = "What do you have there, sir?", completion = "By the Seven Crystals of Ata'mal, this cannot be!  They plan to attack us here at Forest Song?!\n\nNot on my watch!\n\n<Vindicator Vedaar crumples the demon-scrawled plans in his fist.>\n\nNo.  We will not allow this to happen!" }
WordHunterWoW_QuestEN[9521] = { title = "Report from the Northern Front", description = "The battle against the Horde isn't being waged from Raynewood Tower alone, <name>. There's a more substantial Silverwing Sentinel presence at Silverwing Grove to the southeast, near the border with the Barrens. From the grove, Sentinel Farsong directs our efforts against those who would destroy our lands.\n\nI'm a bit late in sending my latest report to her, but also hesitant to leave the tower unattended.\n\nI am in dire need of your help in getting this report to her as soon as possible!", objectives = "Deliver Sentinel Melyria's report to Sentinel Farsong at Silverwing Grove in Ashenvale.", progress = "What's that you have there, <class>?", completion = "Thank you for delivering this report, <class>. From what Sentinel Luciel writes, it seems our worst fears have come to pass. With each advance we make, the Horde appears more determined to do as much damage as possible.\n\nWe can't afford to back down; the fate of our ancestral lands hangs in the balance. With more people like you on the frontlines, I'm certain we could triumph. Will you join our fight?" }
WordHunterWoW_QuestEN[9522] = { title = "Never Again!", description = "<name>, it falls to you to see that this attack by the Burning Legion never comes to pass. You must go and slay their leaders.  Without them the demons will be mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge. To find the ridge, look for a ramp up from Demon Fall Canyon near the Horde's monument to Grom Hellscream.\n\nBring me their weapons.", objectives = "Obtain Gorgannon's Flaming Blade and the Seeker's Fel Spear.", completion = "Never again will the Burning Legion threaten us here!  You have delivered us from a fight we very likely would have lost, <class>.\n\nI give you thanks and the deepest gratitude of the Hand of Argus.  It honors me to have you at our side." }
WordHunterWoW_QuestEN[9523] = { title = "Precious and Fragile Things Need Special Handling", description = "The priestess tells me that the ruins to the west are what's left of a night elf civilization. That got me thinking about what my pappy used to always say about night elf ruins, \"Sonny, whenever you see night elf ruins, night elf relics are sure to be close by.\"\n\nNow what kind of a dwarf would I be if I didn't hire the first person I saw to go digging up night elf relics for me? Now get going!", objectives = "Archaeologist Adamant Ironheart at Odesyus' Landing on Azuremyst Isle wants you to bring him 8 Ancient Relics.", progress = "Don't come back without some ancient relics.", completion = "My pappy would be proud! His boy strikes it big at the first set of night elf ruins he comes across... With your help, of course. Yes, don't worry, I won't leave you out of the discovery. Your name is <name>, right? They'll learn all about you in Ironforge." }
WordHunterWoW_QuestEN[9524] = { title = "Imprisoned in the Citadel", description = "Alliance, here?!  Listen carefully, <class>.\n\nKargath has captured several of our soldiers.  Captain Alina, an important officer is among them.  You must try to save her before she is executed.\n\nDon't worry about me, I'll find a way out as soon as I catch my breath.", objectives = "Rescue Captain Alina inside Hellfire Citadel before she is executed.\n\nThis quest must be completed in Heroic dungeon difficulty.", completion = "I thank you, <name>.  I must admit I didn't expect a rescue party to be on its way.\n\nI will round up the remaining prisoners and lead them back to Honor Hold." }
WordHunterWoW_QuestEN[9525] = { title = "Imprisoned in the Citadel", description = "I was fortunate to escape Kargath's prison today, <name>.  Several prisoners are scheduled to be executed, an important officer among them.\n\nIt would be a huge blow against our forces if Captain Boneshatter was slain.  You must do what you can to rescue him.  I'm too weak to go on...", objectives = "Rescue Captain Boneshatter inside Hellfire Citadel before he is executed.\n\nThis quest must be completed in Heroic dungeon difficulty.", completion = "You've brightened my day, <class>.  When I die, I will make sure it's in the battlefield... covered in the blood of my opponents and taking them down with me." }
WordHunterWoW_QuestEN[9526] = { title = "Reclaiming Felfire Hill", description = "Little one, to the southwest is an area of Nightsong Woods that has in recent times come to be called Felfire Hill. It is very sad to see the demons crawling over it, spreading their corruption.\n\nWould you do something to help take back the land?\n\nI have a number of seeds that I have been saving for such a purpose. Take them to Felfire Hill and plant them in the fertile dirt mounds.", objectives = "Plant 8 Tree Seedlings in the Fertile Dirt Mounds.", completion = "Good.  Though it may take a great deal of your years for the seedlings to grow into ancients, in the fullness of time they will aid us in our fight against the demons at Felfire Hill.\n\nGo in peace, little brother." }
WordHunterWoW_QuestEN[9527] = { title = "All That Remains", description = "We had lived peacefully among the Owlbeasts of this island for many years. You can imagine my surprise when they stormed the beach and attacked us.\n\nI fought tooth and nail but was easily overpowered. As I blacked out from the vicious blows that I had been dealt, I prayed that my family not suffer.\n\nWhen I awoke, all was quiet. The sand was soaked red with blood - their blood. They were devoured whole.\n\nI care not for vengeance, {name}. I only ask that their remains be returned to me for proper burial.", objectives = "Cowlen on Azuremyst Isle wants you to recover the Remains of Cowlen's Family.", progress = "My wife was named Thalrisa and my daughter, Magwin.", completion = "Thank you, <name>. Their spirits will be at peace now." }
WordHunterWoW_QuestEN[9528] = { title = "A Cry For Help", description = "My family was attacked by the murlocs and owlkin of this island several weeks ago. I managed to escape but I think that both my mother and father have been slain. I don't know what I'm going to do now, but I must try and get back to my home - or what's left of it... Will you help me get through the forest?", objectives = "Escort Magwin through the island to her home.", completion = "<Tears of joy stream down Cowlen's face.>\n\nHow can I ever repay you for this, <name>? Please, take this heirloom. It symbolizes a sacred bond of friendship, trust and love amongst night elves. You are a brother to me - from this day until the end of time..." }
WordHunterWoW_QuestEN[9529] = { title = "The Stone", description = "While I'm certain your imp has proven a useful and sometimes entertaining servant, it is time you mastered a more powerful demon: the voidwalker.\n\nTravel down the Dead Scar until it is crossed by the Elrendar River.  Just south of the river, locate one of the blue glowing stones and take it.  Your path will be revealed there.", objectives = "Obtain a Voidstone from the Dead Scar.", completion = "As you gaze into the stone, your vision begins to swirl..." }
WordHunterWoW_QuestEN[9530] = { title = "I've Got a Plant", description = "I've wondered about this for some time now, but this proves it to be true.\n\nThere is a traitor among us.\n\nThe plans left behind by the goblins document the conspiracy. Since I don't know who it could be, I'm going to need your help in finding the traitor. None of my crew can be trusted.\n\nIf this is going to work, I'm going to need a hollowed out tree and leaves. Search near the loggers north of us for the tree. You'll need to find the leaves by yourself. Check the forest.", objectives = "Admiral Odesyus at Odesyus' Landing on Azuremyst Isle wants you to bring him a Hollowed Out Tree and 5 Piles of Leaves.", progress = "I love it when a plan comes together...", completion = "I must warn you, what I ask of you next will be dangerous. I won't think less of you if you decide not to help me out, <name>." }
WordHunterWoW_QuestEN[9531] = { title = "Tree's Company", description = "According to the plans, the traitor and the leader of the goblins, Geezle, are to meet at a cove on the western island. I need you to be at that meeting, {name}.\n\nRemember the tree and leaves? You're going to wear them! It's a perfect disguise.\n\nGo to the cove and look for a naga flag. If the flag is there, it means a meeting is planned. Use the disguise kit when you see the flag and wait. Eventually the traitor will show up. Let the meeting finish then return to me with the identity of the scoundrel.", objectives = "Admiral Odesyus at Odesyus' Landing on Azuremyst Isle wants you to observe the meeting that is to take place between Geezle and the traitor.\n\nReturn to him when you know the identity of the traitor.", progress = "That traitor is going to wish he never messed with Alliance Naval Command!", completion = "I can't believe it! It was the gnome all along... I should have known!" }
WordHunterWoW_QuestEN[9532] = { title = "Find Keltus Darkleaf", description = "<name>, one of our scouts has taken too strong an interest in his duties.  He surveys our enemies relentlessly, but sends no reports of his findings.\n\nYou must find this spy, Keltus Darkleaf, convince him to hand over his report and return it to me as swiftly as possible.  He can be found far to the southwest, where the Elrendar River forks and flows around Goldenmist Village.  The night elves of An'daroth are his quarry, and he won't be far from them.Upon completion of this quest you will gain:", objectives = "Locate Keltus Darkleaf.<name>, one of our scouts has taken too strong an interest in his duties. He surveys our enemies relentlessly, but sends no reports of his findings.\n\nYou must find this spy, Keltus Darkleaf, convince him to hand over his report and return it to me as swiftly as possible. He can be found far to the southwest, where the Elrendar River forks and flows around Goldenmist Village. The night elves of An'daroth are his quarry, and he won't be far from them.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9533] = { title = "A Helping Hand", description = "Under the supervision of Architect Nemos and Vindicator Vedaar, my people are revitalizing an old night elf outpost in the eastern part of Ashenvale.\n\nThe task of building won't be easy, <name>, for the challenges and enemies they face are many. I know Architect Nemos and his compatriots at Forest Song would appreciate any help they can get, and he has asked me to send any interested <men/women> his way.\n\nSpeak to me again and I will arrange for fast transport for you to their location.", objectives = "Speak with Architect Nemos at Forest Song in Ashenvale.\n\nVindicator Palanaar can offer you a ride to get you there more swiftly.Under the supervision of Architect Nemos and Vindicator Vedaar, my people are revitalizing an old night elf outpost in the eastern part of Ashenvale.\n\nThe task of building won't be easy, <name>, for the challenges and enemies they face are many. I know Architect Nemos and his compatriots at Forest Song would appreciate any help they can get, and he has asked me to send any interested <men/women> his way.\n\nSpeak to me again and I will arrange for fast transport for you to their location.", completion = "It's good to see another new arrival here at Forest Song.\n\nVindicator Palanaar is sending as much help as she can muster and each set of hands is appreciated.\n\nTake a look around, <class>. It may not be much now, but with time and help from our night elf allies, we'll build a settlement worthy of calling home. There is much to be done here and any help you can provide would be welcome." }
WordHunterWoW_QuestEN[9534] = { title = "Destroy the Legion", description = "The remains of the demonic Burning Legion have been a thorn in our side for far too long!\n\nNo more!\n\nThe demons are attacking from the areas known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge to the east.\n\nGo and destroy as many as you can to bring glory to both yourself and the Horde!", objectives = "Slay 15 of any demon type at Felfire Hill, Demon Fall Canyon, or demon Fall Ridge and then return to Valusha at Splintertree Post in Ashenvale.", completion = "That's better!  There's nothing quite like ridding our world of a demon.  And they make for worthy opponents as well, unlike the weak races of the Alliance." }
WordHunterWoW_QuestEN[9535] = { title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Orcish tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Splintertree Post to the northwest.\n\nYou're certain that Valusha at Splintertree Post would be interested in these.", objectives = "Deliver the Diabolical Plans to Valusha at Splintertree Post in Ashenvale.", progress = "What do you have there, scout?", completion = "Dreadlords!  They plan to attack us here at Splintertree Post?!\n\nNot while I still draw breath!\n\n<Valusha crumples the demon-scrawled plans in her fist.>\n\nNo.  We will not allow this to happen!  They are a blight upon our world!" }
WordHunterWoW_QuestEN[9536] = { title = "Never Again!", description = "<name>, you will see to it that this attack by the Burning Legion never comes to pass!  Go and slay these dreadlords!  Without them the rest of the demons are essentially mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge.\n\nReturn to me with their weapons as proof of your deeds.", objectives = "Obtain Gorgannon's Flaming Blade and the Seeker's Fel Spear.", completion = "Never again will the Burning Legion make slaves of the orcs, or any other race of the Horde!\n\nBravely fought, <class>!  You have the true heart of the Horde beating inside of you!  You give us much honor!" }
WordHunterWoW_QuestEN[9537] = { title = "Show Gnomercy", description = "Spark must be brought to justice!\n\nI need you to go down to the beach and find that deceitful gnome. Once you find him, get whatever information you can out of him!\n\nIf a high ranking official of the Alliance has committed treasonous acts, who knows how many others are corrupt?\n\nAnd {name}, use force if you have to...\n", objectives = "Admiral Odesyus at Odesyus' Landing wants you to recover the Traitor's Communication from Engineer \"Spark\" Overgrind.", progress = "Did you find the lying dog?", completion = "Incredible! This was all part of their master plan!\n\nThis information must reach the king and your own leaders. The implications are staggering." }
WordHunterWoW_QuestEN[9538] = { title = "Learning the Language", description = "I think I've cracked it, {name}!\n\n<Aurren points to the totem.>\n\nAll that we need to know about the Stillpine furbolg language is imprinted on their totems. With just a rudimentary understanding of how their symbols work, we can study the totems and learn to communicate with the furbolgs.\n\nI've written down the basics of the symbol matrix on this parchment. Study it and then examine the totem. It should lead you to the next language totem.\n\nSpeak to Arugoo when you return an educated {race}!", objectives = "Read the Stillpine Furbolg Language Primer that Aurren gave you and interact with the Totem of Akida at Azure Watch.", progress = "You can hear a low-pitched hum emanating from the totem.", completion = "The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface.\n\nYou note a strange collection of symbols that makes your mouth form the word A-K-I-D-A." }
WordHunterWoW_QuestEN[9539] = { title = "Totem of Coo", description = "You begin to read the totem, barely able to pronounce the awkward words and phrases. Slowly, words start to form in your head. You think that the totem is telling you to go up the nearby hill, to the northeast.", objectives = "Find the Totem of Coo using the clues provided to you.", completion = "The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface of the totem.\n\nYou note a strange collection of symbols that makes your mouth form the word C-O-O." }
WordHunterWoW_QuestEN[9540] = { title = "Totem of Tikti", description = "You begin to read the totem, better able to pronounce the words and phrases. Words start to form in your head. You think that the totem is telling you to go across the Crystalbrook river to the east. Perhaps your destination is on the other side of the river.", objectives = "Find the Totem of Tikti using the clues provided to you.", completion = "The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface of the totem.\n\nYou note a strange collection of symbols that makes your mouth form the word T-I-K-T-I." }
WordHunterWoW_QuestEN[9541] = { title = "Totem of Yor", description = "The symbols on this totem seem to translate much faster. The patterns and imagery all seem to blend into familiar words. You are fairly certain the totem is pointing you south, down the river. Something is at the bottom of the river itself.", objectives = "Find the Totem of Yor using the clues provided to you.", completion = "The totem has various primal markings. You see owls, bears, wolves and stags carved into the surface of the totem.\n\nYou note a strange collection of symbols that makes your mouth form the word Y-O-R." }
WordHunterWoW_QuestEN[9542] = { title = "Totem of Vark", description = "You no longer see unrecognizable symbology in the totems. The totem of Yor reads to you just as easily as your native tongue.\n\nThe markings identify another furbolg den, due west of here. You are able to expertly decipher the language on the totem and know that your destination is Bristlelimb Village. Yor will guide you but if you get lost, you know that you are able to take the ancient elven road in the forest leading west to reach your destination.", objectives = "Find the Totem of Vark using the clues provided to you.", completion = "As you read the totem, your mouth forms the word V-A-R-K. You understand this to mean justice." }
WordHunterWoW_QuestEN[9543] = { title = "Atonement", description = "Our history with the orcs is one of constant conflict, {name}.  We were once near driven to extinction due to their bloodlust and have since then avoided them even when not under demonic influence.\n\nYet, this retaliation... it's not what Sedai would've wanted.  Speak with our elder, Amaan the Wise.  He will help shed light on these events.", objectives = "Speak to Amaan the Wise at the Temple of Telhamat in Hellfire Peninsula.", completion = "Can I offer you any assistance, <name>?  You sound troubled." }
WordHunterWoW_QuestEN[9544] = { title = "The Prophecy of Akida", description = "The images on this totem depict a war between the Stillpine and the Bristlelimb furbolg tribes. The etchings show that the Bristlelimb have done unconscionable things to the furbolgs of Stillpine.\n\nAmidst the chaos, a prophecy has begun to unfold: A hero will rise - not of furbolg blood - and save the Stillpine tribe.\n\nSlay Bristlelimb furbolgs at Bristlelimb Village for their keys. Use the keys to free the Stillpine captives. Return to Arugoo of the Stillpine when you have freed them all!\n", objectives = "Free 8 Stillpine Captives from cages found in Bristlelimb Village. Return to Arugoo of the Stillpine at Azure Watch when you have completed this task.", completion = "[Furbolg] The prophecy spoke of one that would rise and deliver us from the oppressive grasp of Bristlelimb -- that the spirits themselves would herald the arrival of this hero.\n\nAnd now, you have come.\n\nI humble myself before you, great one." }
WordHunterWoW_QuestEN[9545] = { title = "The Seer's Relic", description = "The stubborn close their mind and convince themselves of one truth.  The wise keep an open mind to the different possibilities leading to and stemming from the present.\n\nTake this relic with you to where you found Sedai.  See not with your eyes, {name}, but with your mind.", objectives = "Amaan the Wise at the Temple of Telhamat in Hellfire Peninsula wants you to return to Sedai's Corpse, northeast of the Temple of Telhamat, and use the Seer's Relic at that location. Return to him after you've completed this task.", progress = "Have you seen the vision yet, <name>?", completion = "I hope the vision you witnessed helped you gain some perspective on Sedai's death.  The relic showed you a likely series of events leading up to the present.  The truth may have been different, we'll never know for sure.\n\nWould you act differently knowing what you know now?\n\nWho can say whether our conflict with the orcs will continue?  What's important is to remain open to the possibilities." }
WordHunterWoW_QuestEN[9546] = { title = "Fulfilling a Promise", description = "The prophecy spoke of one that would rise and deliver us from the oppressive grasp of Bristlelimb -- that the spirits themselves would herald the arrival of this hero.\n\nAnd now, you have come.\n\nI humble myself before you, great one. I beg of you, save our younglings. They were taken by the Bristlelimb while our guard was down. You will find them in cages at Bristlelimb Village, to the southwest. The Bristlelimb furbolgs hold the keys to the cages. Strike them down and take their keys. Release my kin.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Arugoo of the Stillpine has asked that you free 8 Stillpine Captives from cages found in Bristlelimb Village." }
WordHunterWoW_QuestEN[9547] = { title = "Call of Air", description = "<name>, Farseer Nobundo has been asking for you.  It must be time for you to learn the secrets of air, the last of the elements!\n\nI want you to know that I'm very proud of all that you have accomplished thus far.  I know that you have great things ahead of you.", objectives = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", completion = "And finally we come to it, the last of the four great elements: air. Do you think yourself wise enough to continue, <name>?" }
WordHunterWoW_QuestEN[9548] = { title = "Pilfered Equipment", description = "Shh! Keep your voice down and don't call attention to me.\n\nIf the murlocs detect my presence, the experiment will be ruined! I've already come perilously close to contaminating my data.\n\nWhile I was foraging yesterday, one of them must've wandered too close and discovered my camp. I returned just in time to see two of them carrying off a crate with most of my equipment! It's bound to be in one of their settlements around here, but I can't risk revealing my presence. Are you willing to help?", objectives = "Bring Clopper's Equipment back to Clopper Wizbang, who is hiding in a beached turtle shell.", progress = "Did you manage to find my equipment?", completion = "This is fantastic! The theft of my equipment has given me more insight into the nature of these murlocs than I could have possibly gained in weeks of observations!\n\nI know what I'm going to say in my report already.\n\n'When faced with the products of a technologically superior culture, the Blacksilt displayed none of the curiosity characteristic of emerging cultures in humanoid species.'\n\nIt's brilliant! The gentlemen in Ironforge are going to love it! I can't thank you enough, <name>." }
WordHunterWoW_QuestEN[9549] = { title = "Artifacts of the Blacksilt", description = "My observations and writings about the Blacksilt murlocs are quite illuminating, {name}, but they are just the beginning. I plan to return to Ironforge with items produced by the Blacksilts' rudimentary crafting skills.\n\nThe problem is that the Blacksilt carry these items with them at all times, and I can't have their blood on my conscience. If you're willing to help me gather the idols carried by Blacksilt seers and crude knives of the Blacksilt warriors and shorestrikers, I won't ask how you came by them.", objectives = "Bring 3 Crude Murloc Idols and 6 Crude Murloc Knives to Clopper Wizbang, who is hiding in a beached turtle shell.", progress = "Do you have those samples for me to send back to Ironforge?", completion = "Astounding, simply astounding! These are perfect, <name>. I can already see them under the glass in the museum in Ironforge. The text for the display is virtually writing itself in my head!\n\nYour help has been invaluable in getting my studies back on track. How do you spell your name? I'll make sure it appears in my report as co-author.\n\nOne of the chaps on the ship gave me this 'treasure map' to cover a gambling debt, but mythology isn't my area of study. Superstitious lot, sailors." }
WordHunterWoW_QuestEN[9550] = { title = "A Map to Where?", description = "The crudely-drawn map reveals nothing of its maker, but it appears to have been drawn with an unsteady hand. Wavering lines and symbols depict a small pavilion with broken columns located to the west of a partially submerged tower. \n\nIf the map is to be believed, this cluster of ruins appears to be located on the eastern coast of the island. You have no idea what you'll find, but it was important enough for the map's creator to record.", objectives = "Locate the pavilion described by the map and search for what the map's maker was trying to record.", progress = "Perhaps this old journal is what the map is referencing.", completion = "Examining the book carefully, you conclude that it must be a journal. Its pages are filled with an elegant script differing from that of the map. The text of many of the pages is obscured by drawings and writing in the mapmaker's hand.\n\nIt's nearly impossible to make out the text beneath the mapmaker's tales of drunken carousing during shore leave." }
WordHunterWoW_QuestEN[9551] = { title = "Call of Air", description = "<name>, Farseer Nobundo has been asking for you.  It must be time for you to learn the secrets of air, the last of the elements!\n\nI want you to know that I'm very proud of all that you have accomplished thus far.  I know that you have great things ahead of you.Upon completion of this quest you will gain:", objectives = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.<name>, Farseer Nobundo has been asking for you. It must be time for you to learn the secrets of air, the last of the elements!\n\nI want you to know that I'm very proud of all that you have accomplished thus far. I know that you have great things ahead of you.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9552] = { title = "Call of Air", description = "The great spirit of air calls out to you, <name>, and it is time for you to take heed.\n\nI wish for you to travel up the Wildwind Path on the north facing of the mountain that the Exodar has crashed into.  At its peak you will find a cave and within will be one of my most accomplished pupils, Velaada.\n\nPlease, listen to her wisdom and do as she bids.  When you return you will have a greater understanding of the element of air.Upon completion of this quest you will gain:", objectives = "Speak with Velaada at Wildwind Peak on Azuremyst Isle.The great spirit of air calls out to you, <name>, and it is time for you to take heed.\n\nI wish for you to travel up the Wildwind Path on the north facing of the mountain that the Exodar has crashed into. At its peak you will find a cave and within will be one of my most accomplished pupils, Velaada.\n\nPlease, listen to her wisdom and do as she bids. When you return you will have a greater understanding of the element of air.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9553] = { title = "Call of Air", description = "While air may seem ethereal, it is an all pervasive force, covering and permeating everything around us.\n\nThough you cannot see it, the rocks of this cave are composed mostly of air, the waters of the oceans are saturated in it and without it, fire cannot be sustained.  Just don't let those elements hear you repeat that!\n\nWho you really wish to speak with for such wisdom is nearby.  At the northern edge of the precipice, Susurrus awaits you.  It is from him that you will gain understanding.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Susurrus at Wildwind Peak on Azuremyst Isle.While air may seem ethereal, it is an all pervasive force, covering and permeating everything around us.\n\nThough you cannot see it, the rocks of this cave are composed mostly of air, the waters of the oceans are saturated in it and without it, fire cannot be sustained. Just don't let those elements hear you repeat that!\n\nWho you really wish to speak with for such wisdom is nearby. At the northern edge of the precipice, Susurrus awaits you. It is from him that you will gain understanding.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9554] = { title = "Call of Air", description = "While my brothers and sisters of the other elements have demanded that you perform various tasks, I will not ask anything further of you.  I think that you have done enough to 'atone' for the accident of your ship falling to this place from my skies.  I can see that you have all the wisdom within you already to use the element of air wisely.\n\nTake this portion of my being back to Farseer Nobundo so that he might help you fashion your totem.  And when you're ready, I will fly you back down to the Exodar.You will receive:", objectives = "Return to Farseer Nobundo at the Exodar on Azuremyst Isle with the Whorl of Air." }
WordHunterWoW_QuestEN[9555] = { title = "Call of Fire", description = "I am thankful that you have chosen the difficult path of the shaman. Few enough do, but I foresee it as critical to our future that we learn shamanism from the Broken.\n\nThey are called that, but once they were draenei. Fel magics transformed them, and that is why they cannot call upon the power of the Light. Some disapprove of them and the shamanism they teach, but they are not evil.\n\nI wish you to speak with Farseer Nobundo. He is the wisest shaman I know and you will learn much with his guidance.You will learn:", objectives = "Speak with Farseer Nobundo at the Crystal Hall in the Exodar.I am thankful that you have chosen the difficult path of the shaman. Few enough do, but I foresee it as critical to our future that we learn shamanism from the Broken.\n\nThey are called that, but once they were draenei. Fel magics transformed them, and that is why they cannot call upon the power of the Light. Some disapprove of them and the shamanism they teach, but they are not evil.\n\nI wish you to speak with Farseer Nobundo. He is the wisest shaman I know and you will learn much with his guidance.You will learn:" }
WordHunterWoW_QuestEN[9556] = { title = "To The Victor...", description = "You've no doubt been fighting long and hard among the towers, <race>. We would like to give something back to you in return for your defense of these lands, but first, you must prove to us you understand the weight of the tragedies that took place here.\n\nWalk the streets of Stratholme and find a vial of the holy water. Once you have it, travel to the mage quarter of Stormwind or the Undercity... There, if you are victorious within these lands, you will find my colleague.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect a bottle of Stratholme Holy Water from within the city of Stratholme and deliver it to the Lordaeron Mage within the Mage Quarter of Stormwind or the Undercity when your side is victorious in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[9557] = { title = "Deciphering the Book", description = "Lacking the means to read the book's contents, you think about who might be able to help you separate the author's words from the mapmaker's scrawl.\n\nRemembering Anchorite Paetheus's collection of artifacts from countless cultures, you wonder if his experienced eye might be able to help you decipher the book's contents.", objectives = "Take the Ancient Journal to Anchorite Paetheus in Blood Watch.", progress = "The Light shine upon you in all your endeavors, <class>. What is it you have there?", completion = "Hmm... this is most intriguing. Yes, I should be able to make out what the original author wrote in the pages of this book.\n\nI should have everything I need for the process. This should only take a moment." }
WordHunterWoW_QuestEN[9558] = { title = "The Longbeards", description = "We were having a problem with arakkoa bandits raiding many of our supply caravans, so I hired some dwarves to take care of them.\n\nThey were brothers; Gremni Longbeard was the oldest.\n\nI'm a little worried about them.  Those crazy dwarves packed more ale than food or ammunition!  Maybe you can go check up on them?\n\nThe arakkoa's hideout, the Den of Haal'esh, can be found to the far west of here - beyond the Great Fissure.  They set up camp northwest of there, south of Dustquill Ravine.", objectives = "Look for Gremni Longbeard northwest of the Den of Haal'esh, to the far west of Honor Hold in Hellfire Peninsula.", completion = "How'd you find us, <class>?  No matter, I imagine you were sent here to give us a hand.  Let's get to work then!" }
WordHunterWoW_QuestEN[9559] = { title = "Stillpine Hold", description = "Promised one, you must travel north to the home of my people - Stillpine Hold. It is there that you will face your most daunting challenge.\n\nGo now, High Chief Stillpine awaits your arrival.", objectives = "Speak with High Chief Stillpine at Stillpine Hold.", completion = "For centuries, we lived in relative peace with the creatures of the land. Several months ago, Kurz began to see dark omens. The peace that we enjoyed for so long was to be lost. The extent of the catastrophe could not be known!\n\nSo it would be that the gods would shatter our land - turning both friend and foe against us. But there was something else... Amidst the chaos, a hero would rise: A hero not of Stillpine blood. The Promised One would deliver us from devastation.\n\nThat prophesied hero was you." }
WordHunterWoW_QuestEN[9560] = { title = "Beasts of the Apocalypse!", description = "My brother and I were hunting in the woods to the east when we were ambushed by strange, insect-like beasts. Such aberrations have never before been seen in Azuremyst! Could they be a sign of the coming apocalypse? The apocalypse that YOU are destined to prevent?\n\nIf you truly are the Promised One, you will strike the creatures of the apocalypse down... and bring me their hides. From their hides, I can fashion armor of great power!\n\nFind them to the east, beyond the road.", objectives = "Moordo at Stillpine Hold on Azuremyst Isle wants you to bring him 8 Ravager Hides.", progress = "They are ugly little creatures. Even the Blind Watcher could see them... and he's blind.", completion = "Not only is the prophecy true, this armor is also amazing! Surely it is armor fit for a champion! And I will sell it to you at discounted prices, furless one.\n\nI jest... The first piece is complimentary." }
WordHunterWoW_QuestEN[9561] = { title = "Nolkai's Words", description = "The translation is ready now, {name}.\n\n<Anchorite Paetheus points out a block of text at the end of his translation.>\n\n'The enemy is nearly upon us. We've gathered up all the survivors and retreated to the temple to the east. It's the last ground we truly hold on the island, and there is a sense among the survivors that we will make our last stand here. I've taken care to bury my last few possessions on the grounds of the temple, with the hope that someone will find them and know what happened here.'", objectives = "Find the location described in Nolkai's journal and discover his long-buried possessions.", completion = "Grasses and shrubs cover an unnatural bulge in the earth.\n\nA few minutes spent digging reveals an old box, almost certainly the one mentioned in Nolkai's journal." }
WordHunterWoW_QuestEN[9562] = { title = "Murlocs... Why Here? Why Now?", description = "These are dark days, Promised One. Even the murlocs are kicking our tails - literally. Unfortunately, more than just my ego has been bruised.\n\nWhile our relationship with the Siltfin murlocs had always been tenuous, never could we have imagined that they would have the gall to attack us and steal from our food stores! Travel west to the Silting Shore and recover our stolen food-stuffs!\n\nAnd if you see a dark-skinned murloc with a patch of white fur stuck in between his webbed toes... ", objectives = "Gurf at Stillpine Hold on Azuremyst Isle wants you to recover 5 sacks of Stillpine Grain.", progress = "A murloc kicked me in the behind and spit on me... in broad daylight!", completion = "Mmmmm... Delicious grain... Parkat will be delighted!" }
WordHunterWoW_QuestEN[9563] = { title = "Gaining Mirren's Trust", description = "So you want to gain our trust?  I don't trust many people these days.\n\nWe lost one of our own not long ago to the arakkoa.  It's got me a bit on edge.\n\nTell you what, if you can prove your loyalty to Honor Hold and... bring me a mug of Nethergarde Bitter... yes, that sounds rather good about now... I'll have a deal to offer you then.\n\nBernie at Nethergarde Keep keeps the bitter in stock.", objectives = "Mirren Longbeard wants you to bring him 1 Nethergarde Bitter. You must also attain Friendly reputation with Honor Hold to complete this quest.", progress = "Having trouble finding the bitter?  Good old Bernie at Nethergarde Keep should stock barrels of it.\n\nUnless he's run out... that would be disastrous!", completion = "Why, yes!  You seem to be quite an OK <race>.  I suppose I can trust you." }
WordHunterWoW_QuestEN[9564] = { title = "Gurf's Dignity", description = "You recover the piece of fur that Gurf had \"lost\" in his struggle with the murlocs. Return the fur to Gurf and let him know that the fearsome Murgurgula has been slain.", objectives = "Return Gurf's Dignity to Gurf at Stillpine Hold on Azuremyst Isle.", progress = "Is that what I think it is?", completion = "<Gurf spits on the clump of fur and tries to affix it to the hairless patch on his backside.>\n\nThis will have to do for now! Hopefully one of the shaman will be able to repair the damage." }
WordHunterWoW_QuestEN[9565] = { title = "Search Stillpine Hold", description = "As High Chief, my immediate concern is the root of the corruption in Stillpine Hold.\n\nWhy did the wildkin - once our allies - attack us? Why have they taken residence in Stillpine Hold?\n\nPerhaps something inside will hold the answer. Search Stillpine Hold for clues as to the source of corruption.", objectives = "Search Stillpine Hold for clues.", completion = "The blood crystal radiates a sickly aura that seeps into the water of the cave." }
WordHunterWoW_QuestEN[9566] = { title = "Blood Crystals", description = "On the surface, the crystal appears to be a piece of the Exodar. Something has gone terribly wrong with this crystal, however, as it is blood red and rapidly dissolving into the water supply of the cave.\n\nThis may explain the unusually aggressive behavior of the creatures in Azuremyst. Return to High Chief Stillpine with this information.\n", objectives = "Speak with High Chief Stillpine at Stillpine Hold.", completion = "These blood crystals that you saw; my scouts have seen many more to the north.\n\nI thank you for aid but now ask that you leave me to confer with the elders. I will call for you once I have spoken with the other elders of the village." }
WordHunterWoW_QuestEN[9567] = { title = "Know Thine Enemy", description = "It's good to see another new face here in Blood Watch, {class}. Although the blood elves are the most immediate threat, there are other sinister creatures that call Bloodmyst Isle home.\n\nThe Nazzivus satyr are of particular concern. They are foul, demonic creatures, commanding dark magics and feeding on the corruption created by the Exodar's crash.\n\nWe must hold them in check, but first we must learn more about them. Go southwest to Nazzivian and learn what you can from their grotesque monument.", objectives = "Find the Nazzivus Monument in Nazzivian and retrieve a Nazzivus Monument Glyph. Return to Vindicator Aalesia in Blood Watch when you have one of the glyphs.", progress = "Were you successful in obtaining knowledge of the Nazzivus satyr?", completion = "Well done, <name>. Let me see what I can learn from this glyph, so we can plan our next move." }
WordHunterWoW_QuestEN[9568] = { title = "On the Offensive", description = "It's worse than I had imagined, <name>. We draenei know well what comes of selling one's soul to the Burning Legion in return for promises of power and immortality.\n\nThe satyr on this island, the Nazzivus, are descendents of that first, twisted creature who allied with the Legion. I fear that they will find a way to use the power of the Exodar's crystals against us.\n\nYou've seen what they've done to the land. Imagine what the satyr could do with them. Go southwest to Nazzivian and begin our offensive!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Vindicator Aalesia at Blood Watch wants you to kill 10 Nazzivus Satyr, 5 Nazzivus Rogues, and 5 Nazzivus Felsworn." }
WordHunterWoW_QuestEN[9569] = { title = "Containing the Threat", description = "Now that we have made our presence known to the satyr, we must send a message that we will not tolerate the Burning Legion's hounds in these lands.\n\nToo long have the draenei fled in the wake of the Legion and its minions, {name}. Wherever they have found us, they have shown no mercy.\n\nWe must not permit the satyr to exploit the Exodar's crash and use the corrupted crystals as weapons. Go north to where their leader resides in Axxarien, destroy him, and recover the corrupted crystals he has been gathering!", objectives = "Kill 5 Axxarien Shadowstalkers, 5 Axxarien Hellcallers, and Zevrax, then gather 5 Corrupted Crystals and return to Vindicator Aalesia in Blood Watch.", progress = "<Vindicator Aalesia seems to look through you rather than at you, her mind fixed on dealing with the satyr.>\n\nHave you moved against the satyr leader as I have asked?", completion = "Without their leader, and with the recovery of the corrupted crystals underway, we can safely keep the satyr in check. Light knows how many more of these wretched creatures are out there.\n\nHarbinger Mikolaas and I are grateful for the help you've provided in dealing with the satyr before they could become a larger threat. Your work stands as a reminder that vigilance is the key to victory against the Legion and its minions." }
WordHunterWoW_QuestEN[9570] = { title = "The Kurken is Lurkin'", description = "After the crystal storm had subsided, a beast of myth appeared in our village. Brought here by the invading wildkin, this beast, the Kurken, laid waste to our village. Many Stillpine were slain in defense of our lands by this fiend and many have since lost their lives attempting to subdue the beast.\n\nIn my visions, I have seen one defeat the Kurken. The one must be you, {name}. You are our only hope. Enter Stillpine Hold and slay the Kurken. Bring me his hide as proof of deed.\n", objectives = "Kurz the Revelator at Stillpine Hold on Azuremyst Isle wants you to kill the Kurken and bring back the Kurken's Hide.", progress = "<Kurz grunts at you.>", completion = "The Promised One has emerged victorious!\n\nThe prophecy is nearly complete. Now about that hide..." }
WordHunterWoW_QuestEN[9571] = { title = "The Kurken's Hide", description = "Take the Kurken's hide to Moordo, on the other side of the village. He will fashion the hide into an item of your choice.\n", objectives = "Deliver the Kurken's Hide to Moordo at Stillpine Hold.", progress = "Hello, hero!", completion = "This is the strongest armor I've ever made! Make good use of it, <name>." }
WordHunterWoW_QuestEN[9572] = { title = "Weaken the Ramparts", description = "Quick, there isn't much time.  Thrallmar's existence balances on the razor's edge!\n\nWe're caught between Hellfire Citadel in the west and the Burning Legion to the east.  With the Legion's attention turned toward the Dark Portal we must take this opportunity to strike at the fel orcs of Hellfire Citadel.  The key to this is to first break through their ramparts!\n\nGo there, slay their leaders, and then bring back proof to Caza'rez across the room from me!", objectives = "Slay Watchkeeper Gargolmar, Omor the Unscarred and the drake, Nazan. Return Gargolmar's Hand, Omor's Hoof and Nazan's Head to Caza'rez at Thrallmar in Hellfire Peninsula.", progress = "<name>, right?  Stok'ton told me to be expecting your report.\n\nI trust that you bring good news?", completion = "It's a good start.  With those three dead their forces should be in disarray.  And with their artillery up there silenced we'll have an easier time getting close enough to take the citadel!\n\nBut there's more to this than meets the eye - I can feel it - so I'm going to have something else for you to do.\n\nFor the time being, though, you've done well.  Take your pick of any of these from the Thrallmar armory." }
WordHunterWoW_QuestEN[9573] = { title = "Chieftain Oomooroo", description = "I am Stillpine the Younger, heir to the Stillpine legacy. As you can see, my defenders have set up a death trap for the raving wildkin that attack from inside Stillpine Hold. While we are able to hold them off out here, none of my defenders have been able to infiltrate the hold. If you could get inside and slay their leader, it might give us an opportunity to strike!\n\nFind Chieftain Oomooroo and destroy him. Slay any crazed wildkin that you encounter inside as well.", objectives = "Stillpine the Younger at Stillpine Hold on Azuremyst Isle wants you to slay Chieftain Oomooroo and 9 Crazed Wildkin.", completion = "This may very well be the opportunity that we needed! I will send an attack at once! The Stillpine thank you for your service, <name>!" }
WordHunterWoW_QuestEN[9574] = { title = "Victims of Corruption", description = "Bloodmyst Isle was forever changed by our arrival. The Exodar's crash scattered debris all over the islands and I think it's beginning to have an adverse effect on the wildlife.\n\nBefore I can be certain of my conclusion, I'll need to get a closer look. The crystals seem to have affected the trees the fastest, so it seems that the treants would be the most likely to show symptoms. If you bring me samples of bark from corrupted treants, I can begin my in-depth studies.", objectives = "Bring 6 pieces of Crystallized Bark to Morae in Blood Watch.", progress = "Were you able to get the samples I need?", completion = "There's more than enough here for my research. Thank you, <name>. If you find any other evidence that the crystals are corrupting Bloodmyst's native creatures, let me know right away." }
WordHunterWoW_QuestEN[9575] = { title = "Weaken the Ramparts", description = "Quick, <class>, there isn't much time.  Honor Hold's existence balances on the razor's edge!\n\nWe're caught between Hellfire Citadel in the west and the forces of the Burning Legion to the east.  With the Legion's attention turned toward the Dark Portal we must take this opportunity to strike at the fel orcs of Hellfire Citadel.  The key to this is to first break through their ramparts!\n\nGo there, slay their leaders, and then bring back proof to Gunny across the hall here from me!", objectives = "Slay Watchkeeper Gargolmar, Omor the Unscarred and the drake, Nazan. Return Gargolmar's Hand, Omor's Hoof and Nazan's Head to Gunny at Honor Hold in Hellfire Peninsula.", progress = "<name>, right?  Chadwick told me to be expecting your report.\n\nWHAT are you doing in my presence?!  Is your assignment complete?  Are you a complete and utter lackwit?  You make me want to vomit!\n\nNow get your worthless hide up on those ramparts and do what you were instructed to do!  Do you hear me?!", completion = "Do you know what I hate worse than being wrong? Losing gold on a bet that you couldn't pull it off, sweetheart.\n\nOutstanding!  With those three dead their forces should be in disarray.  And with their artillery up there silenced we'll have an easier time getting close enough to take the citadel!\n\nI have a feeling there's more to this than meets the eye, though - so I'm going to have something else for you to do.  Here, take one of these from the armory." }
WordHunterWoW_QuestEN[9576] = { title = "Cruelfin's Necklace", description = "Examining the crudely constructed pendant, you notice the crystal pulsating softly. Though it emits little light, you can almost feel the crystal radiating a sense of wrongness.\n\nYou're not quite sure what might have possessed Cruelfin to create this pendant, but the find is too important to ignore. You should probably show it to someone at Blood Watch.", objectives = "Bring the Red Crystal Pendant to Morae at Blood Watch.", progress = "What is it you have there?", completion = "This is most curious, <class>. I don't believe we've ever seen the murlocs wearing any kind of adornment before.\n\nGiven the corrupting influence that the crystal shards are known to have, the murloc that wore this pendant must have believed it granted him power over his fellows. I wouldn't be surprised if he had rapidly outgrown his fellow murlocs and gained in strength." }
WordHunterWoW_QuestEN[9577] = { title = "DAILY TEST QUEST (PVP)", description = "<NYI>Seek <QUESTGIVER> in <LOCATION>.  S/he wishes for you to aid them in a difficult task.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with <QUESTGIVER> in the <AREA>.<NYI>Seek <QUESTGIVER> in <LOCATION>. S/he wishes for you to aid them in a difficult task.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9578] = { title = "Searching for Galaen", description = "Do you think often of your family, {name}? There were a number of families aboard the Exodar, but I've heard of very few being reunited.\n\nI, myself, am looking for traces of my husband Galaen, who was a technician in the Cryo-Core. The wreckage of it is located to the west, and it's swarming with blood elves!\n\nI must find out what became of Galaen! Even news of his death is better than never knowing. My husband will be wearing a pendant identical to my own; they were a gift from my sister.", objectives = "Search for Morae's husband Galaen.", completion = "The corpse appears to be dressed in the manner of an Exodar technician, but the pendant described by Morae is absent." }
WordHunterWoW_QuestEN[9579] = { title = "Galaen's Fate", description = "You have no means of identifying the corpse as Galaen with the information Morae gave you, but the clothing appears to have been torn in search of valuables.\n\nThe blood elves in the area would've claimed anything of value from the wreckage, including Galaen's jeweled amulet.\n\nAlthough her husband did not survive the crash, you believe that Morae would be grateful if you recovered her husband's amulet from the blood elves.", objectives = "Bring Galaen's Amulet to Morae at Blood Watch.", progress = "<Morae looks at you hopefully.>\n\nDid your search turn up any trace of Galaen?", completion = "<You tell Morae of your findings in the wreckage of the Cryo-Core.>\n\nSo... he's...\n\nI guess I knew on some level, but just wouldn't let myself believe it. It's not the news I was hoping for, but you have my deepest thanks for finding Galaen." }
WordHunterWoW_QuestEN[9580] = { title = "The Bear Necessities", description = "As I'm sure you've seen in your time on Bloodmyst Isle, very little remains unchanged by our arrival. My training and experience has taught me that even the products of an environment like this one can be put to use.\n\nWith so few resources, we must rely on our ingenuity to provide for us. I've been supplementing our stores with meat from the bears that wander this island. With the proper preparation, it can safely be eaten. If you're going to be out in the field, why not help replenish our stocks?", objectives = "Bring 8 Elder Brown Bear Flanks to Tracker Lyceon in Blood Watch.", progress = "How goes the hunt, <name>?", completion = "This will keep us supplied for quite a while, and preparing it for consumption will certainly keep me busy. Thank you for your help, <name>." }
WordHunterWoW_QuestEN[9581] = { title = "Learning from the Crystals", description = "Welcome to Blood Watch, {class}. Seeing to the defenses of the outpost is my primary concern, but I've also been tasked with a variety of other duties by our leaders at the Exodar.\n\nThe problem is that it's hardly safe to send out large amounts of researchers when the island is this dangerous. I need someone to gather a series of crystal samples from various sites on the island.\n\nThe first sample I need must come from the ravager infested ship debris south of the town and across the bridge.", objectives = "Get an Impact Site Crystal Sample using the Crystal Mining Pick on the Impact Site Crystal and bring it to Harbinger Mikolaas in Blood Watch.", progress = "Were you able to gather the first crystal sample?", completion = "This crystal shard will give our researchers a baseline to compare against samples from other parts of the island, since it comes from one of Bloodmyst's less corrupted regions.\n\nI won't be able to send it off until we have a full set of samples, but this is a great start. If you're willing to help gather the other samples, I'll see to it that you're rewarded for your efforts." }
WordHunterWoW_QuestEN[9582] = { title = "Strength of One", description = "When the ship crashed, our menagerie was scattered on the northeast beaches of this isle.  I have been handed a key that unlocks the cage holding one of the deadlier specimens, a death ravager.  The creature is little armored but resistant to most magic.  It must be killed by a simple blade.\n\nTake this key and release the creature from both its prison and its pain.  We cannot afford to have it escape and cause even more damage to the ecology than we already have.", objectives = "Unlock the Ravager Cage and kill the Death Ravager, then return to Ruada at Azure Watch in Azuremyst.", progress = "Have you put down the beast?", completion = "<Ruada nods solemnly.>\n\nThen it is done.\n\nYou are ready for your next lesson, <name>, but I will not be the one to teach it to you." }
WordHunterWoW_QuestEN[9583] = { title = "Omar's Test Quest bk", description = "An honorable person gives me clothYou will receive:", objectives = "Get Omar some cloth" }
WordHunterWoW_QuestEN[9584] = { title = "The Second Sample", description = "Now that we have the baseline crystal, we're going to need samples from more dangerous areas of the island to complete the set I'll be sending to the Exodar.\n\nThe next sample must come from the crystals controlled by the blood elves in the Bladewood area to the northwest of Blood Watch. I have heard reports that they alter and harvest the crystals for use in some magical apparatus. See if you can find one that has not yet been incorporated into one of their devices, and mine a sample from it.", objectives = "Get an Altered Crystal Sample using the Crystal Mining Pick on the Altered Bloodmyst Crystal and bring it to Harbinger Mikolaas in Blood Watch.", progress = "Do you have the second crystal sample?", completion = "<Harbinger Mikolaas examines the crystal shard.>\n\nThis shard is much different from the initial sample.\n\n<Harbinger Mikolaas holds the crystal up to catch the light.>\n\nDo you see how it pulsates like that? That's worrisome. I'll make a note in my report of the alterations the blood elves appear to have made to this crystal. Thank you again for your help, <name>." }
WordHunterWoW_QuestEN[9585] = { title = "The Final Sample", description = "There's just one sample remaining before I can send this set of crystals to the Exodar, {name}. The final sample must come from the satyr stronghold of Axxarien to the northwest.\n\nI'm not certain what to expect from this crystal sample, but I'm sure there will be some signs of corruption. Take care to mine your shard from the crystal that looks like the ones you took your previous samples from, or else our researchers cannot make a valid comparison.", objectives = "Get an Axxarien Crystal Sample using the Crystal Mining Pick on the Axxarien Crystal and bring it to Harbinger Mikolaas in Blood Watch.", progress = "Have you returned with the last sample for my set?", completion = "<Harbinger Mikolaas accepts the last crystal from you.>\n\nThat rounds out the set. All that remains to be done is to box them and send them to the Exodar.\n\n<The harbinger seems glad to be done with the task.>\n\nDon't get me wrong, <name>, I'm sure the research is valuable, but we're faced with a number of other pressing problems out here." }
WordHunterWoW_QuestEN[9586] = { title = "Help Tavara", description = "Tavara, one of our herbalists, has been gone far too long in her search for herbs.  I fear she is hurt and in need of help, yet I cannot look for her myself.\n\nPlease find her and lend your healing if needed, fellow <class>.  She was heading east towards some hot springs when she left Azure Watch.You will receive:", objectives = "Guvan at Azure Watch wants you to find Tavara and heal her wounds." }
WordHunterWoW_QuestEN[9587] = { title = "Dark Tidings", description = "Giving the lifeless form of Vazruden the Herald the once-over, you discover a rolled letter, its seal yet unbroken.  An elaborate \"I\" is pressed within the blood-red ink.  Cracking the note open, the message that you read is most disturbing.\n\nForce Commander Danath Trollbane back at Honor Hold will definitely want to take a look at this!", objectives = "Take the Ominous Letter to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.", progress = "What's that you have there, son?", completion = "It's signed by Illidan you say?! Let me have that.\n\n<The commander reads the letter, and then again a second time, thinking a moment before going on.>\n\nThis news that you bring is ominous indeed. Knowing this, we must accelerate our plans against Hellfire Citadel and this Blood Furnace. Because you have shown that you can get the job done, I want you to head up those plans.\n\nGunny will give you your next mission, though I suspect it will be far deadlier than your first.\n\nLight be with you, <name>!" }
WordHunterWoW_QuestEN[9588] = { title = "Dark Tidings", description = "Giving the lifeless form of Vazruden the Herald the once-over, you discover a rolled letter, its seal yet unbroken.  An elaborate \"I\" is pressed within the blood-red ink.  Cracking the note open, the message that you read is most disturbing.\n\nNazgrel back in Thrallmar will definitely want to take a look at this!", objectives = "Take the Ominous Letter to Nazgrel at Thrallmar in Hellfire Peninsula.", progress = "What is that letter you have there, <class>?", completion = "It's signed by Illidan you say?! Let me have that.\n\n<Nazgrel reads the letter, and then again a second time, thinking a moment before going on.>\n\nThis news that you bring is ominous indeed. Knowing this, we must accelerate our plans against Hellfire Citadel and this Blood Furnace. Because you have shown that you can get the job done, I want you to head up those plans!\n\nCenturion Caza'rez will give you your next mission, though I suspect it will be far deadlier than your first.\n\nLok'tar ogar, <name>!" }
WordHunterWoW_QuestEN[9589] = { title = "The Blood is Life", description = "That letter is going to get folks all riled up around here.  They'll think there's something we might do about all those new fel orcs being created if only we knew how it was being done.  It's bad enough that we have to fight the Burning Legion to the east.\n\nSo, it's your lucky day, sweetness!  You get to take a stroll into what they call the Blood Furnace inside Hellfire Citadel.  Sounds hot!\n\nGet in there, kill some fel orcs and bring back samples of their blood.\n\nYou think you can handle that?", objectives = "Collect 10 Fel Orc Blood Vials and return them to Gunny at Honor Hold in Hellfire Peninsula.", progress = "You have that blood, darlin'?  Might be kind of important if we asked you to get it, you know?", completion = "Out-frikkin-standing!  As of right now Private <name>, you are my favorite person on the sorry remains of this sorry planet!\n\nI'm sure that the eggheads are going to wet themselves when I hand that blood over to them for study.  Who knows, maybe we'll find a new weapon in the fight against those damned fel orcs?" }
WordHunterWoW_QuestEN[9590] = { title = "The Blood is Life", description = "That letter is disturbing, and not just because it comes from the Betrayer.  We must know how they are creating these new fel orcs if we're to defeat them!  It's bad enough that we must fight the Burning Legion on our eastern flank, but now a new army of fel orcs to the west!\n\nYou must infiltrate this Blood Furnace inside Hellfire Citadel.  Bring back samples of blood from the fel orcs that you find in there.", objectives = "Collect 10 Fel Orc Blood Vials and return them to Centurion Caza'rez at Thrallmar in Hellfire Peninsula.", progress = "Surely you have not collected all of the blood so quickly?", completion = "I am impressed with your abilities, <name>.  Not once, but twice now you have infiltrated Hellfire Citadel for us and accomplished what was asked of you.\n\nI will see to it that this blood is delivered to those who can unlock its mysteries.  Who knows, perhaps we can find a way to reverse the process?" }
WordHunterWoW_QuestEN[9591] = { title = "Taming the Beast", description = "When the <class> first begins <his/her> path, <he/she> learns only to kill.  Now it seems you are ready for more.\n\nThe Stillpine furbolgs have provided a means to master the skill of taming without months of study.  They are able to carve a totem into the likeness of an animal, which you can use to temporarily bond with a creature of that type.\n\nFor your first lesson, take this totem and use it on the barbed crawlers found along the western coast of the isle.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Taming Totem to befriend a Barbed Crawler and return to Huntress Kella Nightbow when you have succeeded." }
WordHunterWoW_QuestEN[9592] = { title = "Taming the Beast", description = "The crawler was undoubtedly mean, but the timberstrider will test your resolve.  More powerful allies require more tenacity from the hunter.\n\nTake this taming totem and befriend a greater timberstrider.  They are found in the northern reaches of Azuremyst Isle.Upon completion of this quest you will gain:", objectives = "Use the Taming Totem to befriend a Greater Timberstrider and return to Huntress Kella Nightbow." }
WordHunterWoW_QuestEN[9593] = { title = "Taming the Beast", description = "You probably noticed the big cats known as nightstalkers when you tamed the timberstrider.  They are efficient and deadly hunters... and allies.\n\nUse this taming totem to befriend a nightstalker.  Hunt with the vicious cat and keep it from harm.  When you are finished, return to me.You will learn:", objectives = "Use the Taming Totem to befriend a Nightstalker and return to Huntress Kella Nightbow." }
WordHunterWoW_QuestEN[9594] = { title = "Signs of the Legion", description = "The armor scrap is forged from a deep black metal that seems to absorb light. Although it doesn't appear to be enchanted, there is an unmistakable sense of wrongness about it.\n\nSuch armor is only used by one force - the Burning Legion. The Legion's presence here can only mean that they're intending to mobilize the island's satyr against the draenei.\n\nTake action against the local satyr, then return to Blood Watch and show this armor scrap to Vindicator Aalesia. ", objectives = "Kill 8 Nazzivus Satyr and 8 Nazzivus Felsworn, then bring Tzerak's Armor Plate to Vindicator Aalesia in Blood Watch.", progress = "Yes, <class>? What is it you have there?", completion = "You've done well in bringing this to me, <name>. This is, without a doubt, an armor fragment from a felguard.\n\nThen, it is as I feared. The Nazzivus satyr are renewing their contacts with the Burning Legion. If we don't stop them, the satyrs and their demonic allies will overrun us. I will notify Harbinger Mikolaas right away." }
WordHunterWoW_QuestEN[9595] = { title = "Control", description = "You have chosen the path of the {class}, and so you must learn control. Magic, when unchecked, can corrupt souls and destroy worlds.\n\nTo fully understand, you must face one who has been consumed by magic. Travel to the beaches on the northwest coast of Azuremyst Isle and use your spells to decimate the murlocs. The display of power will attract the attention of the evil force lurking there, a Quel'dorei magewraith. Defeat it.\n\nWhen you have finished, seek out Bati at the Vault of Lights in the Exodar.", objectives = "Kill Murlocs of the Silting Shore to summon a Quel'dorei Magewraith, then destroy it. Afterwards, speak with Bati at the Vault of Lights in the Exodar.", completion = "With every spell you must steel yourself against its seductive lure, using it only as needed for the purposes of good.  Hopefully the wraith granted a glimpse of what you might turn into should you become careless--a mindless slave to magic." }
WordHunterWoW_QuestEN[9596] = { title = "<DEPRECATED>Control", description = "<NYI>Do something else, <class>!You will receive:", objectives = "<NYI>Log description." }
WordHunterWoW_QuestEN[9598] = { title = "Redemption", description = "I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend our people from threats.\n\nThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a tome of divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Study the Tome of Divinity and speak with Jol." }
WordHunterWoW_QuestEN[9600] = { title = "Redemption", description = "Your task then, <name>, is to aid our new allies, the Stillpine furbolgs.\n\nSeveral of the younger Stillpine shaman stumbled across a Bristlelimb camp and were slaughtered to the last.  Take this Symbol of Life and resurrect one of the shaman.\n\nBristlelimb Enclave is located to the east of the road just after you cross the bridge spanning Azuremyst and Bloodmyst Isle.  Speak with me when you have done this.You will learn:", objectives = "Jol wants you to resurrect a Young Furbolg Shaman with the Symbol of Life and return to her." }
WordHunterWoW_QuestEN[9601] = { title = "To The Bulwark", description = "The blood knight Mehlar Dawnblade has requested an audience with you, <name>.  Mehlar can be found at the Bulwark, guarding the passage between Tirisfal Glades and the Western Plaguelands.\n\nHe is not known for his patience.  It would not be wise to keep him waiting.Upon completion of this quest you will gain:", objectives = "Speak with Mehlar Dawnblade at the Bulwark.The blood knight Mehlar Dawnblade has requested an audience with you, <name>. Mehlar can be found at the Bulwark, guarding the passage between Tirisfal Glades and the Western Plaguelands.\n\nHe is not known for his patience. It would not be wise to keep him waiting.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9602] = { title = "Deliver Them From Evil...", description = "You must get this information to your people, {name}. While your brave acts have certainly slowed down the plans of Kael'thas and his dark master, the attacks will undoubtedly continue.\n\nTake the traitor's communication to your leaders. They must see this for themselves. Perhaps they will be able to better understand some of what was written.", objectives = "Deliver the Traitor's Communication to Exarch Menelaous at Azure Watch.", progress = "You have returned!", completion = "<Exarch Menelaous takes the letter from you and begins to read it.>\n\nDamn them... Damn them all to the Nether. They've had a spy watching everything that we've done! And for how long?\n\nI will notify Velen at once!\n\nYou've done us a great service, <name>. Be on guard as I will be contacting you once the Prophet has given me instruction as to what to do." }
WordHunterWoW_QuestEN[9603] = { title = "Beds, Bandages, and Beyond", description = "Welcome to Azure Watch, {class}. Please excuse the disorder you see around you. It's easy to take simple things for granted, like a fully furnished and stocked inn, until you're forced to build one from nothing.\n\nWe've managed to salvage this pod for a building, but without the proper furnishings and first aid supplies, the inn is little more than a glorified tent. Nurguni at the Exodar has offered to put together a package to help with our most immediate needs, but I need someone to deliver this list to him.", objectives = "Take Chellan's List to the hippogryph master Zaldaan at Azure Watch.", progress = "Good day, <name>. Are you interested in renting a hippogryph?", completion = "So you need to go to the Exodar?\n\nThat's going to be a bit of a trip, but don't worry, I have a way to get you there very quickly." }
WordHunterWoW_QuestEN[9604] = { title = "On the Wings of a Hippogryph", description = "For a small fee, you can rent one of my hippogryphs to fly you to the Exodar.\n\nTaking the hippogryph is a faster, not to mention safer, alternative for someone carrying an important message. If you'd like to take a ride, speak to me again and I'll make the arrangements.", objectives = "Purchase a hippogryph ride to the Exodar from Zaldaan. When you land, take Chellan's List to Nurguni in the Seat of the Naaru at the Exodar.", progress = "Greetings, friend. You look like you've come a long way. How can I help you?", completion = "So you've brought Chellan's list. Excellent! I was hoping to receive this today. Let's see what she needs.\n\n<Nurguni reads over the list and begins placing various items in a box.>\n\nThat's most of what she requested. The pieces for the beds are simply too large to be delivered by hippogryph, but I'll make arrangements to have them sent by wagon." }
WordHunterWoW_QuestEN[9605] = { title = "Hippogryph Master Stephanos", description = "Here's the box, {name}. That should be enough for Chellan to get the inn up and running. Let her know that she can keep sending in orders as the need arises. Azure Watch urgently needs a place to care for the wounded and put up any travelers they receive.\n\nWhen you're ready to return to Azure Watch, seek out Stephanos near the Seat of the Naaru in the Exodar.", objectives = "Find Stephanos at the Seat of the Naaru inside the Exodar and purchase a hippogryph ride back to Azure Watch.", progress = "Where are you headed, <class>?", completion = "So you're headed back to Azure Watch with this package? No problem at all, <class>. Just speak with me again and we'll get you on your way with those supplies." }
WordHunterWoW_QuestEN[9606] = { title = "Return to Caregiver Chellan", description = "If I remember correctly, Azure Watch's hippogryph master is Zaldaan.  If you've spoken to him before, then you can take one of my hippogryphs to him.\n\nThat's a good lesson to know: hippogryphs are always trained to fly to their capital city, but they'll only take you to a remote hippogryph master after you've already been there.\n\nSince you arrived on one of Zaldaan's hippogryphs, you can also use that route to return to Azure Watch with the caregiver's supplies.", objectives = "Speak with Stephanos to purchase a hippogryph ride back to Azure Watch. Once you have arrived, deliver Nurguni's Supplies to Caregiver Chellan.", progress = "Welcome back, <name>. Was Nurguni able to gather everything on the list?", completion = "<Handing over the box, you tell the caregive that Nurguni is making arrangements to have the larger items delivered by wagon.>\n\nSplendid! Now, I'll finally be able to set up some beds and a first aid station so that we can better treat the wounded and any survivors we encounter.\n\nI can't thank you enough for your help, <name>. You have my thanks and that of the Azure Watch's vindicators." }
WordHunterWoW_QuestEN[9607] = { title = "Heart of Rage", description = "<class>, put together a force to investigate the Blood Furnace inside Hellfire Citadel at once!  And that means today, princess!\n\nThe magic we have at our disposal indicates that something unnatural is occurring in there.  But something more powerful inside is blocking any detailed arcane investigations.  It figures!\n\nYou can expect heavy resistance - no other mission that we've sent in there has yet to return!\n\nScout it entirely and then report back to the force commander with what you witness.", objectives = "Fully investigate the Blood Furnace and then report to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.", completion = "THEY HAVE A PIT LORD?!\n\n<The force commander looks around at the stares of the others and then lowers his voice to a whisper.>\n\nThat seals it.  They must be using the blood from this pit lord to create new fel orcs that are somehow not aligned with the Burning Legion.  And if they can do this to the brown orcs, they can do it to the green ones too.  With all of the new Horde orcs streaming in through the Dark Portal, that's not good!\n\nWe must strike at the heart of their military might, and soon!" }
WordHunterWoW_QuestEN[9608] = { title = "Heart of Rage", description = "<class>, you must gather a group to investigate the Blood Furnace inside Hellfire Citadel at once!\n\nThe magical scrying that we have at our disposal indicates that something unnatural is occurring in there.  But a powerful force inside is blocking any detailed arcane investigations, so it must be very important.\n\nYou should expect heavy resistance - no other mission that we've sent in there has ever returned!\n\nScout it entirely and then report back to Nazgrel, advisor to Thrall, with what you witness.", objectives = "Fully investigate the Blood Furnace and then report to Nazgrel at Thrallmar in Hellfire Peninsula.", completion = "THEY HAVE A PIT LORD?!\n\n<Nazgrel notices the glances of the others assembled and lowers his voice to a whisper.>\n\nThat seals it.  They must be using the blood from this pit lord to create new fel orcs that are somehow not aligned with the Burning Legion.  And if they can do this to the Mag'har brown orcs, they can do it to us!\n\nWe'll have to strike at the heart of their military might, and soon!" }
WordHunterWoW_QuestEN[9609] = { title = "elp Watcher Biggs", description = "Magtoor has informed me that there's a stranded watcher nearby.  Apparently the caravan he was escorting from Darkshire was attacked by Lost Ones.  It sounds as if he's the sole survivor.\n\nHe's somewhere to the south.  Please, <class>, lend him your aid.", objectives = "Find Watcher Biggs in the Swamp of Sorrows.Magtoor has informed me that there's a stranded watcher nearby. Apparently the caravan he was escorting from Darkshire was attacked by Lost Ones. It sounds as if he's the sole survivor.\n\nHe's somewhere to the south. Please, <class>, lend him your aid.", completion = "What?  A draenei sent you here from the Harborage?  How odd.\n\nWell, I'm not one to turn down assistance.  Thanks for coming, <class>!" }
WordHunterWoW_QuestEN[9610] = { title = "ool of Tears", description = "I am interested in studying Azeroth's past and I'm wondering if you'd be willing to help?\n\nThere is a nearby place of historical significance within the swamp that I would like for you to venture to.  The Pool of Tears lies to the southeast.  It is said that upon its shores and within its depths are buried artifacts of the Atal'ai troll civilization.\n\nBut beware, it is guarded by Somnus, an ancient green dragon, and his dragonkin, as well as carnivorous fish in the pool itself!", objectives = "Obtain 5 Atal'ai Artifacts and return them to Holaaru at the Harborage in the Swamp of Sorrows.", progress = "I look forward to you gathering enough of the Atal'ai artifacts so that I might begin to study them.  I'm eager to discover what happened to their once-great civilization.", completion = "I thank you, <class>.  The study of these artifacts should keep me occupied for some time.  How else are we Broken and <race> to fit in if we do not come to understand the history of your world?" }
WordHunterWoW_QuestEN[9611] = { title = "Azuremyst: aa - A - Quest Flag 000", description = "", objectives = "" }
WordHunterWoW_QuestEN[9612] = { title = "A Hearty Thanks!", description = "You saved my life, {name}! Thank you so much! That beast would have torn me to shreds if it weren't for you.\n\nIf you see the exarch at Azure Watch, tell him of what you did. I'm sure he'll be pleased to hear such news!", objectives = "Speak with Exarch Menelaous at Azure Watch.", completion = "Well done, <name>. Well done indeed! You are turning out to be a special <race> - a cut above the others of your age. Take this as a reward!" }
WordHunterWoW_QuestEN[9613] = { title = "Deprecated: Keanna's Will", description = "<As you touch the sword, you hear a female voice address you>\n\nOuch!  Don't do that!  Can't you see I'm in pieces?  It really hurts.\n\nI see that Karazahan hasn't trapped you.  You must know about Kadghar and the Violet Eye then.\n\nYou're going to need to find someone who can put me back together.  Koren... he was our agent once... he's nearby.  I hope you're on our good side.  If so, he can help!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "The Shattered Blade you found in Karazhan wants you to ask Koren to repair it. You'll also need to attain Honored reputation with the Violet Eye to complete this quest." }
WordHunterWoW_QuestEN[9614] = { title = "Deprecated: Reforge a Short Blade", description = "This weapon has been broken into so many pieces... putting it back together won't be easy.\n\nI'm going to need khorium.  Lots of it.  I'll also need a void crystal and some primal fire.You will receive:", objectives = "Bring 40 Khorium Bars, 1 Void Crystal and 8 Primal Fires to Koren inside Karazhan." }
WordHunterWoW_QuestEN[9615] = { title = "Deprecated: Reforge a Long Blade", description = "This weapon has been broken into so many pieces... putting it back together won't be easy.\n\nI'm going to need khorium.  Lots of it.  I'll also need a void crystal and some primal fire.You will receive:", objectives = "Bring 40 Khorium Bars, 1 Void Crystal and 8 Primal Fires to Koren inside Karazhan." }
WordHunterWoW_QuestEN[9616] = { title = "Bandits!", description = "This appears to be a bounty ledger. You cannot understand the blood elf language but you note that there is a picture depicting a dead draenei, a smiling blood elf standing over the corpse, and a symbol of what you think is some sort of blood elf currency.\n\nThey've put a hit out on draenei! You must inform the exarch.", objectives = "Take the Blood Elf Communication to Exarch Menelaous at Azure Watch.", progress = "Yes? I'm very busy, <name>.", completion = "By the beardless, geometric head of O'ros! It is good you brought this to me, <name>. These blood elves are out for... well, blood. Velen will be informed at once! Take this as a reward." }
WordHunterWoW_QuestEN[9617] = { title = "Seek the Farstriders", description = "Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters.  It would greatly benefit you to seek her out, <name>.  She is a beacon of wisdom for those of our calling.\n\nFarstrider Retreat lies south of Silvermoon City.", objectives = "Speak with Lieutenant Dawnrunner at Farstrider Retreat.", completion = "<name>, it is good you have come.  Our list of allies grows thin, and even those who share our cause are not completely trusted.  It is because of this that we, the rangers, turn to nature for aid.\n\nIn the allies of the forest we find a deep bond that does not know deceit." }
WordHunterWoW_QuestEN[9618] = { title = "Return the Reports", description = "Your sleight of hand was most impressive.  There's no question that I can trust you to take these reports to Zelanis.You will receive:", objectives = "Bring Keltus Darkleaf's Reports to Zelanis in Silvermoon City." }
WordHunterWoW_QuestEN[9619] = { title = "The Rune of Summoning", description = "The voidstone reveals a vision of a multi-story building haunted by ghostly figures.  As the scene sharpens and blurs, other buildings come into view, leading you to believe it is Goldenmist Village.\n\nRooftops and tree canopies suddenly flash by, revealing the way to Goldenmist by following the Elrendar River to the west.\n\nOnce there, use the voidstone near the rune of summoning atop the center building and defeat the summoned voidwalker.  Only then can you return to your teacher.", objectives = "Use the Voidstone to summon a Voidwalker in Goldenmist Village, defeat it, and return to Talionia in Silvermoon City.", progress = "Have you followed the path revealed by the voidstone?", completion = "I'm impressed you are standing here, <name>.  Many an apprentice has perished to the voidwalker, or even the voidstone itself.\n\nThe voidwalker is now yours to command.  Use your new servant well." }
WordHunterWoW_QuestEN[9620] = { title = "The Missing Survey Team", description = "As we've gotten ourselves established here at Blood Watch, I've been sending out survey teams to create more reliable maps of the island. In most cases, they returned unharmed with the data we need, but the team I sent east to the ruins hasn't reported back.\n\nI worry about what might have happened to them, but I can't spare the men to send another mission after them. Find them, {name}, and lend them any assistance they require to return with their survey data.", objectives = "Harbinger Mikolaas wants you to find the Survey Team he sent to the Ruins of Loreth'Aran and assist them in any way you can.", completion = "The bodies of the draenei survey team are scattered all over the ground here, pierced by naga weaponry. The area is littered with the remains of their supplies and survey equipment, but their data crystals are nowhere to be seen." }
WordHunterWoW_QuestEN[9621] = { title = "Envoy to the Horde", description = "There were doubts about our capabilities among our potential new allies.  Of what use could we be to them when perceived as unable to deal with our problems at home?\n\nThis changes everything.  No longer will our power be questioned.  We'll be able to join the Horde as equals.\n\nTake this letter to Sylvanas, ruler of the Forsaken.  She's already on our side but the news of Dar'Khan's death will be music to her ears.  Prepare for a long trip, {name}.  If all goes well she will send you to Orgrimmar.", objectives = "Bring the Letter from Lor'themar Theron to Lady Sylvanas Windrunner in Undercity, the Forsaken capital in Tirisfal Glades.", progress = "Ah, a visitor from Quel'Thalas!  What news do you bring?", completion = "It is done then.  The foul traitor got what he deserved.\n\nYou did this yourself?  An impressive feat that proves that your race remains worthy, <name>.\n\nI see that Lor'themar has additional news that will greatly improve his relations with the trolls and their Warchief." }
WordHunterWoW_QuestEN[9622] = { title = "Warn Your People", description = "The Hold is saved and soon my people will make their way back to the ancestral home. The prophecy has come to pass and a new age of prosperity begins for the Stillpine.\n\nBut I fear that darkness looms ahead for your own people. There are questions left unanswered - visions of prophecy unseen.\n\nReturn to your leaders and tell them of what you have seen here.\n\nAnd Promised One, should you ever require the aid of Stillpine, you have merely to ask.", objectives = "Speak with Exarch Menelaous at Azure Watch.", completion = "Visions you say? Interesting... And this prophecy has come to pass?\n\nBut you say they saw the power core of the Exodar? And O'ros was also in the vision? What can it mean?" }
WordHunterWoW_QuestEN[9623] = { title = "Coming of Age", description = "You have survived the wilds of our new home and shown yourself a cut above the others. I believe that you have come of age to assist those battling on the front lines of Bloodmyst. The Hand of Argus could use a {race} like you. \n\nReport to Torallius the Pack Handler. You will find him outside the Exodar, tending to the elekk. Give him these orders so that he may direct you towards your new duties on Bloodmyst.", objectives = "Exarch Menelaous at Azure Watch has asked that you deliver the Exarch's Orders to Torallius the Pack Handler, standing outside of the Exodar.", progress = "<Torallius adjusts his eyepatch to look at you.>\n\nThis is the best we can offer the Hand of Argus?", completion = "<Torallius sighs.>\n\nAlright, let me have a look at those orders." }
WordHunterWoW_QuestEN[9624] = { title = "A Favorite Treat", description = "I've made a wonderful discovery, {class}. On the uncorrupted part of the island grows a remarkable fruit called the sand pear. They're found near the bottoms of the trees.\n\nI've been preparing pies from them, but if I'm not careful, the elekk will start to wander over and steal my fruit. I've taken to gathering enough to share with the animals, but my stores are gone and the craving for pie has returned. Would you be willing to help gather the fruit I need for another batch of pies? I promise I'll share!", objectives = "Aonar at Kessel's Crossing wants you to bring him 10 Sand Pears.", progress = "The sand pears are getting harder to find and, of course, that means less pie and fewer treats for the elekk here. Were you able to gather all the fruit I'll need?", completion = "Did you have a difficult time finding enough? It's been taking me longer with each trip.\n\nSoon, I'll have to stop altogether since I won't be able to spare the time. Thank you for gathering the pears for me, <name>. It gives me a chance to make a last pie or two before the season's out." }
WordHunterWoW_QuestEN[9625] = { title = "Elekks Are Serious Business", description = "Is he crazy? Entrusting something like this to some no-named {race} youngling!\n\nJust remember this kid: You'll never make it as a Hand of Argus! You don't have the guts!\n\nI guess I'll have to humor him this time. Speak with Vorkhan at Kessel's Crossing on Bloodmyst Isle. Just follow the road north from here, and when it forks, just keep on going north.", objectives = "Speak with Vorkhan the Elekk Herder on Bloodmyst Isle.", completion = "Well ya made it this far! Let's put ya to work before you get too bloodied up." }
WordHunterWoW_QuestEN[9626] = { title = "Meeting the Orcs", description = "I haven't lost any love for my homeland or its people, as you know. I've fought tooth and nail for Silvermoon to be allowed a place beside Undercity and Orgrimmar at the negotiating table.\n\nThis should silence any opposition. Take this letter to Saurfang in Orgrimmar. As leader of the orcs, he must have a say in accepting the sin'dorei's pledge.\n\nI've added my own seal to the letter as a personal endorsement. Go northwest of the city and board the zeppelin bound for Durotar at the tower.", objectives = "Lady Sylvanas Windrunner wants you to take the Letter Sealed by Sylvanas to High Overlord Saurfang in Orgrimmar, capital of Durotar.", progress = "You've come to see me, <race>?  Speak and be quick, young lady.  I've no time for the formalities of your race.", completion = "<The Warchief begins to read the letter.>\n\nSylvanas is a persistent one.  So she's sent one of Silvermoon's own champions... how does this change anything?" }
WordHunterWoW_QuestEN[9627] = { title = "Allegiance to the Horde", description = "Your people suffered a great betrayal by the Alliance. You succeeded in fighting off the Darnassian attacks and the spies from Ironforge. Now you defeated a powerful Scourge leader at the footsteps of your home. Your worthiness is no longer in question.\n\nIt is clear now that we need each other. Return to Lor'themar. Tell him I have heard your message and accept. \n\n<Saurfang crushes the letter inside his palm.> \n\nWelcome to the Horde, elf.", objectives = "Return to Silvermoon City and report back to Lor'themar Theron.", completion = "Your work has helped advance our race's cause a tremendous deal.\n\nBrace yourself for great changes, <name>.  We are now officially part of the Horde." }
WordHunterWoW_QuestEN[9628] = { title = "Salvaging the Data", description = "It's too late to assist the cartographers in completing their mission, but it appears they collected the data Harbinger Mikolaas was expecting. The crystal storing their survey information was not among their ransacked packs, so it must be in the hands of the Wrathscale naga.\n\nYou know that Harbinger Mikolaas will be saddened by the loss of the survey crew, but would want to salvage the survey data.", objectives = "Obtain the Survey Data Crystal from the Wrathscale near the dead cartographers and return it to Harbinger Mikolaas at Blood Watch.", progress = "Were you able to find out what was keeping the survey team from returning?", completion = "<You tell Harbinger Mikolaas of the survey team's fate. He accepts the crystal from you, but remains silent for a long moment.>\n\nThey were good men, <name>, and they knew their mission would be dangerous. I'm grateful for your help in locating the team and recovering the crystal.\n\n\n\nWe've lost too many good men already, and our mission has only just begun." }
WordHunterWoW_QuestEN[9629] = { title = "Catch and Release", description = "The Blacksilt murlocs on the southwestern coast are curious creatures. In some ways, they act barely sentient, yet in others, they show a remarkable degree of organization.\n\nI have a few theories about that, but no real way to test them until recently. I've devised a method that will allow me to track the murlocs I'm interested in without doing any lasting harm or interfering with their natural behavior. If you're willing to help with the marking, I'll gladly pay you for your assistance.", objectives = "Morae at Blood Watch wants you to 'mark' 6 Blacksilt Scouts using the Murloc Tagger.", progress = "Did the device work? Have you marked the murlocs for my research?", completion = "Well done, <name>. I was worried that the marking device might malfunction, but it seems like everything went according to plan." }
WordHunterWoW_QuestEN[9630] = { title = "Medivh's Journal", description = "Your name is getting around, <name>.  You've made your way into and out of Karazhan - more than most mortals can claim.\n\nI need to ask a special favor of you.  As part of our research, the Violet Eye has been trying to track down Medivh's own journal.\n\nUnfortunately, none of the agents we've sent inside have come out.  Wravien was the last to be sent; see if you can find him and see about any leads on the journal.", objectives = "Archmage Alturus at Deadwind Pass wants you to go into Karazhan and speak to Wravien.", completion = "A vast wealth of information... I could spend years here!  I'm sure Dalaran will understand..." }
WordHunterWoW_QuestEN[9631] = { title = "A Colleague's Aid", description = "There is a small detail I've forgotten to take into account.  The residue of Medivh's essence contained in this bone fragment is completely devoid of life - just like Arcanagos.\n\nThere is a way, however.  And I know just the person to help us.\n\nTravel to Area 52 in Netherstorm and show the bone fragment to Kalynna Lathred.  She will know just what to do.", objectives = "Take the Charred Bone Fragment to Kalynna Lathred at Area 52 in Netherstorm.", progress = "Alturus sent you.  The stars spoke of your arrival.", completion = "Alturus wants to raise a whole dragon back from the dead?  Not an easy task by any stretch of the imagination.\n\nLet us discuss how we can be of mutual assistance, <name>." }
WordHunterWoW_QuestEN[9632] = { title = "Newfound Allies", description = "Harbinger Mikolaas has done a commendable job of safeguarding Blood Watch, {class}, but our enemies are many and our resources few.\n\nOur weakness is well known to our enemies, but your contact with the forces of the Alliance is something they haven't accounted for. I have prepared a letter of introduction to the people of Auberdine, the closest Alliance settlement, proposing cooperation in the fight against our foes. Take it with you and seek out Huntress Kella Nightbow near the docks west of the Exodar.", objectives = "Take the Letter of Introduction to Huntress Kella Nightbow in Azuremyst Isle.", progress = "Greetings, <class>. What have you there?", completion = "I can help you get to Auberdine. Fortunately, it's only a short boat trip away!" }
WordHunterWoW_QuestEN[9633] = { title = "The Way to Auberdine", description = "If you wait out on the dock, you'll see the boat arriving from the port of Auberdine in Darkshore. Once it has offloaded its passengers, you'll be able to board.\n\nAfter a short journey, the boat will put in at Auberdine and you'll be able to deliver your message.\n\nIt's probably best to take this to Thundris Windweaver, an old friend of mine and a well-respected citizen of the town.", objectives = "Take the boat from the dock near Huntress Kella Nightbow to Auberdine. Once you have arrived in Auberdine, take the Letter of Introduction to Thundris Windweaver.", progress = "Welcome to Auberdine, friend. What brings you to Darkshore?", completion = "<Thundris accepts the letter from you and reads it quickly, nodding.>\n\nThe isles the <race> call Azuremyst and Bloodmyst were inhabited long ago by my people. Some of the threats faced by Anchorite Paetheus and his brethren are ancient enemies of the night elves.\n\nI am certain that the people of Auberdine are willing to provide what aid we can to our new allies. As soon as I have spoken with the townspeople and the sentinels, I will send word to Paetheus." }
WordHunterWoW_QuestEN[9634] = { title = "Alien Predators", description = "One thing we've learned in our travels is that extreme care must be taken when introducing wildlife from one world to another. When the Exodar crashed, it was carrying specimens of various Outland species, including an insectoid predator called the ravager.\n\nSome of the specimens were lost, but many others survived and took to the wild. If we don't keep them in check, they will upset the natural balance here on the islands.\n\nYou'll find these ravagers to the west of Kessel's Crossing, near the coast.", objectives = "Kill 10 Bloodmyst Hatchlings then return to Vorkhan the Elekk Herder at Kessel's Crossing on Bloodmyst Isle.", completion = "Well done, <name>. The ravager population will bear watching for some time to come, but we've made a good start." }
WordHunterWoW_QuestEN[9635] = { title = "The Zapthrottle Mote Extractor!", description = "The swamp gas is truly amazing, and can be very useful, mon!  But first, you gotta be able to suck it up, and that, my friend, requires a Zapthrottle Mote Extractor.\n\nNow, I could just give you the schematics, but I'll need something in return first.  How about some spare parts?  Last time I checked, there were plenty lying around near the broken steam pump at the Dead Mire, far to the northeast.\n\nI heard that the withered giants spread the pieces all over that dried-out lake bed.", objectives = "Bring 15 Steam Pump Parts to Mack Diver at Zabra'jin in Zangarmarsh.", progress = "You got those parts yet?  I've got some diving to do.", completion = "Alright!  Now if we only had a stretchy loop, a parchment clamp, a guzzle tube and some sticky duck ribbon.  Then we could really make something!\n\nOk, ok, I guess you've earned this, <name>.  Have fun!" }
WordHunterWoW_QuestEN[9636] = { title = "The Zapthrottle Mote Extractor!", description = "Have you seen the swamp gas?  Isn't it just shiny?\n\nIt takes a Zapthrottle Mote Extractor to suck 'em dry though.  I could give you the plans to make one, but I really need some spare parts to fix stuff 'round here.\n\nLast time I checked, there were plenty of parts lying around near the steam pump at the Dead Mire to the northeast.  I think the withered giants broke the pump out there.\n\nShall we help each other out?", objectives = "Bring 15 Steam Pump Parts to K. Lee Smallfry at Telredor in Zangarmarsh.", progress = "You got those parts yet?  I've got a compression coil to fix before Anchorite Ahuurn starts breathing down my neck!", completion = "Shiny!  And really, what engineer ever has enough spare parts just hanging around?  Ooh, maybe I could sell off the extra and buy me some of that Tigule and Foror's Strawberry Ice Cream?!  I just love strawberries!  Do you think they have any around here?\n\nOk, ok, I guess you've earned this, <name>.  Have fun!" }
WordHunterWoW_QuestEN[9637] = { title = "Kalynna's Request", description = "I left the Kirin Tor in pursuit of knowledge forbidden by those of my order; it is beyond ironic that I am now asked to assist them with that very same knowledge.\n\nIf I'm to perform this favor for you, you will have to do something for me first.  I want you to obtain two of the tomes I've been searching for.\n\nThe first one is called the Tome of Dusk and is owned by the orc warlock known as Nethekurse.  The second, known as the Book of Forgotten Names, belongs to the arakkoa known as Darkweaver Syth.", objectives = "Kalynna Lathred wants you to retrieve the Tome of Dusk from Grand Warlock Nethekurse in the Shattered Halls of Hellfire Citadel and the Book of Forgotten Names from Darkweaver Syth in the Sethekk Halls in Auchindoun.\n\nThis quest must be completed in Heroic difficulty.", progress = "Have you obtained the tomes I seek, <name>?", completion = "Excellent, <name>.  I've been trying to obtain these books for a very long time.  It is fortunate that we were able to be of mutual assistance." }
WordHunterWoW_QuestEN[9638] = { title = "In Good Hands", description = "Was I supposed to be looking for this journal?  It can't be... I don't quite recall...\n\nOf course!  It is Gradav you're thinking of.  He was looking for the book when I got here.  Surely he must've found it by now; why don't you go ask him about it?\n\nI'd lend you a hand... but these books are just so... interesting!", objectives = "Speak to Gradav at the Guardian's Library in Karazhan.", completion = "Can't you see I'm in the middle of something here?  What do you want?" }
WordHunterWoW_QuestEN[9639] = { title = "Kamsis", description = "Journal, what journal?  You're thinking of Kamsis, surely.\n\nGo and ask her about it.  I can't leave my project right now or all my work will be wasted!", objectives = "Speak to Kamsis at the Guardian's Library in Karazhan.", completion = "The journal you speak of... I was sent here to look for it wasn't I?" }
WordHunterWoW_QuestEN[9640] = { title = "The Shade of Aran", description = "Let me think for a second.  The Violet Eye... Medivh's Journal...  Why yes, it's all coming back to me now.\n\nI believe I had the journal you're looking for before I started to read these scrolls...\n\nAran... yes, Aran asked me for the book.  So nicely too.  I just had to give it to him.  He's Medivh's father after all, did you know?", objectives = "Obtain Medivh's Journal and return to Kamsis at the Guardian's Library in Karazhan.", progress = "Weren't you looking for a journal or something?", completion = "Did you find what you were looking for?  You were looking for something, weren't you?" }
WordHunterWoW_QuestEN[9641] = { title = "Irradiated Crystal Shards", description = "The Exodar's crash scattered pieces of fouled crystals all over Bloodmyst Isle, corrupting the water and the landscape.\n\nWe've even begun finding pieces of the crystals inside the flesh of animals taken for meat. I've uncovered a way to purify the shard and turn them into functional crystals, so if you bring me enough shards, I'll trade one of my completed crystals for them. So far I've found the shards in the bodies of bears, ravagers, flutterers, and treants inhabiting the corrupted part of the island.", objectives = "Vindicator Boros at Blood Watch wants you to bring him 10 Irradiated Crystal Shards.", progress = "Have you gathered crystal shards from the creatures of Bloodmyst?", completion = "Well done. These will provide the raw materials for another batch of enhancement crystals.\n\nYou're welcome to choose from among the three kinds of crystals I can make. I find each of them useful for stalking different kinds of prey." }
WordHunterWoW_QuestEN[9642] = { title = "More Irradiated Crystal Shards", description = "", objectives = "If you have more of the irradiated crystal shards, I'd be happy to exchange them for another of my crystals.", progress = "If you have more of the irradiated crystal shards, I'd be happy to exchange them for another of my crystals.", completion = "Very well, here are the crystals that I have, <name>. Use them well." }
WordHunterWoW_QuestEN[9643] = { title = "Constrictor Vines", description = "A good woodsman makes use of every available resource, {class}. Even the most bizarre creatures possess attributes we can use to our advantage.\n\nWith Blood Watch under constant assault from the Sunhawks, we're looking to a variety of natural defenses including traps. The lasher's thorny vines are perfectly suited to the construction of the traps I have in mind. The combination of sharp spines and deadly toxin will fell unwary attackers. Bring me the vines of mutated constrictors so that I can begin my work.", objectives = "Tracker Lyceon at Blood Watch wants you to bring him 6 Thorny Constrictor Vines.", progress = "Did you manage to get the constrictor vines?", completion = "These seem sturdy enough to do the job. Thank you for your help, <name>. Your contribution to Blood Watch's defense will not be forgotten." }
WordHunterWoW_QuestEN[9644] = { title = "Nightbane", description = "You fulfilled your end of the deal.  I will now bind your essence to that of the dead blue dragon.\n\nThere is an urn in the Master's Terrace, should you touch that urn, you'll now release its energy and bring life back to the charred remains of Arcanagos.  Defeat the creature and retrieve its essence immediately!  You will need to take it to Alturus.\n\nShould you fail, the stars predict you will have let a great terror loose upon the skies.\n\nA terror known as Nightbane!", objectives = "Go to the Master's Terrace in Karazhan and touch the Blackened Urn to summon Nightbane. Retrieve the Faint Arcane Essence from Nightbane's corpse and bring it to Archmage Alturus.", progress = "What news do you bring, <name>?", completion = "This is astounding!  Not only have you brought back Medivh's Journal, but you've also retrieved a fragment of his very essence.\n\nAs faint as this lingering essence is, it will reveal to us vital information about Medivh.  We will not forget this, <class>." }
WordHunterWoW_QuestEN[9645] = { title = "The Master's Terrace", description = "Journal?  What journal?\n\nOh, right.  That journal!  The Violet Eye sent me here for it.  It's all coming back now.\n\n<Kamsis points to a page in the journal.>\n\nThis is the page that Alturus is interested in.  Did you know that while other people's journals serve as a record of their memories, Medivh's is literally just that?\n\nTry it.  Go to the Master's Terrace and read the page; you'll see just what I mean.  Might as well report to Alturus while you're at it.  I'm afraid I'll be here for a while.", objectives = "Go to the Master's Terrace in Karazhan and read Medivh's Journal.", progress = "You've returned!  What news do you bring?", completion = "It is a shame that the agents we sent succumbed to Karazhan's magic.  At least you managed to obtain what they were after." }
WordHunterWoW_QuestEN[9646] = { title = "WANTED: Deathclaw", description = "By order of Harbinger Mikolaas: A bounty to be paid to the brave soul who returns with proof of the marauding bear Deathclaw's demise.\n\nDeathclaw should be considered extremely dangerous and is responsible for the killing of a survey team on the coast to the northwest of Blood Watch. Travelers are advised to avoid the area.", objectives = "Bring Deathclaw's Paw to Harbinger Mikolaas in Blood Watch.", progress = "How can I help you, <class>?", completion = "Well done. From what I've heard, it couldn't have been an easy fight. You've more than earned your reward, <name>." }
WordHunterWoW_QuestEN[9647] = { title = "Culling the Flutterers", description = "When we first encountered flutterers, they showed few signs of mutation. As the corruption got progressively worse, the moths and other species began to show signs of contamination.\n\nIt has progressed to the point where they damage nearly everything they come in contact with. They're amplifying the damage being done by the crystal shards scattered by the Exodar's crash. We have no choice but to begin culling their population in the lands north of Blood Watch.", objectives = "Tracker Lyceon at Blood Watch wants you to kill 10 Royal Blue Flutterers.", completion = "In time, we'll have to devise a plan for returning the species to its native state, but for now, periodically culling their numbers is about the best we can hope for. Thank you for your help, <name>." }
WordHunterWoW_QuestEN[9648] = { title = "Maatparm Mushroom Menagerie", description = "Did you know mushroom hunting is far more dangerous than mushroom consumption? Mushroom hunters expose themselves to many unknowns - not including potential wildlife dangers!\n\nWhat would life be without a little danger? I am in need of mushrooms for my collection. Scattered throughout these unexplored wilds you will find four different types: An aquatic stinkhorn, a blood mushroom, a ruinous polyspore, and a fel cone fungus. They are each unique to various regions in Bloodmyst. Bring them to me.", objectives = "Maatparm at Blood Watch wants 1 Aquatic Stinkhorn, 1 Blood Mushroom, 1 Ruinous Polyspore, and 1 Fel Cone Fungus.", progress = "Remember, the mushrooms I requested are each unique to the different environments of Bloodmyst.", completion = "Well, I did warn you - did I not? Hopefully this payment more than makes up for the mild discomfort that you may have suffered. Return to me when you have gained strength and perhaps I will have another job for you - mushrooms of course!" }
WordHunterWoW_QuestEN[9649] = { title = "Ysera's Tears", description = "Good to see you again, {name}! You were exceptionally efficient in completing the last task that I offered you. Perhaps you would be interested in another?\n\nTo the northeast lies Wyrmscar Island, home to a rare species of mushroom known as Ysera's tear - named after the green dragonlings that inhabit the island. I only require a small sampling of the mushroom, but I must warn you that the denizens of the island do not welcome visitors. Tread carefully.\n", objectives = "Maatparm at Blood Watch wants 2 Ysera's Tears.", progress = "Back so soon?", completion = "I hope this wasn't too strenuous a task, <name>. Once again you have proven yourself a competent and considerate <race>. I offer my gratitude and a small bit of monetary compensation." }
WordHunterWoW_QuestEN[9650] = { title = "Deprecated: Magical Augmentation", description = "<TXT>Yes, let's enhance my magical properties.  That makes sense.  I was, after all, a wizard in life.\n\nJust because one's physical vessel is a weapon does not automatically make someone a brute.\n\nI will need you to collect some materials.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "<TXT><TXT>Yes, let's enhance my magical properties. That makes sense. I was, after all, a wizard in life.\n\nJust because one's physical vessel is a weapon does not automatically make someone a brute.\n\nI will need you to collect some materials.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9651] = { title = "Deprecated: Magical Augmentation", description = "<TXT>Yes, let's enhance my magical properties.  That makes sense.  I was, after all, a wizard in life.\n\nJust because one's physical vessel is a weapon does not automatically make someone a brute.\n\nI will need you to collect some materials.You will receive:", objectives = "<TXT><TXT>Yes, let's enhance my magical properties. That makes sense. I was, after all, a wizard in life.\n\nJust because one's physical vessel is a weapon does not automatically make someone a brute.\n\nI will need you to collect some materials.You will receive:" }
WordHunterWoW_QuestEN[9652] = { title = "Deprecated: Physical Enhancement", description = "I wouldn't mind that.  We might as well make the best of our situation... in my case, being a weapon.  Might as well become the best weapon I can be.\n\nYes, let's do that.  A sharper edge, a sturdier hilt... I like the sound of that.\n\nI'll need you to gather a few things for me.You will receive:", objectives = "" }
WordHunterWoW_QuestEN[9653] = { title = "Deprecated: Physical Enhancement", description = "I wouldn't mind that.  We might as well make the best of our situation... in my case, being a weapon.  Might as well become the best weapon I can be.\n\nYes, let's do that.  A sharper edge, a sturdier hilt... I like the sound of that.\n\nI'll need you to gather a few things for me.You will receive:", objectives = "" }
WordHunterWoW_QuestEN[9654] = { title = "Deprecated: A Well Rounded Defense", description = "Offensive magic was my area of expertise... that much I can remember.  I'll do my best to add my arcane channeling powers to yours.\n\nI'll need more raw power than I possess right now, however.  The arcane anomalies that roam the upper levels of the guardian's library would make excellent targets.  Gather their arcane residue, we'll need lots of it.You will receive:", objectives = "The Facet of Keanna stored inside Keanna's Will wants you to gather 20 Arcane Residues from the Arcane Anomalies in Karazhan." }
WordHunterWoW_QuestEN[9655] = { title = "Deprecated: Healing Amplification", description = "Offensive magic was my area of expertise... that much I can remember.  I'll do my best to add my arcane channeling powers to yours.\n\nI'll need more raw power than I possess right now, however.  The arcane anomalies that roam the upper levels of the guardian's library would make excellent targets.  Gather their arcane residue, we'll need lots of it.You will receive:", objectives = "The Facet of Keanna stored inside Keanna's Will wants you to gather 20 Arcane Residues from the Arcane Anomalies in Karazhan." }
