WordHunterWoW_QuestEN[9661] = { title = "Deprecated: A Well Rounded Defense", description = "Offensive magic was my area of expertise... that much I can remember.  I'll do my best to add my arcane channeling powers to yours.\n\nI'll need more raw power than I possess right now, however.  The arcane anomalies that roam the upper levels of the guardian's library would make excellent targets.  Gather their arcane residue, we'll need lots of it.You will receive:", objectives = "The Facet of Keanna stored inside Keanna's Will wants you to gather 20 Arcane Residues from the Arcane Anomalies in Karazhan." }
WordHunterWoW_QuestEN[9662] = { title = "Deprecated: Keanna's Freedom", description = "My memories... I remember everything now!  My mind feels like a puzzle falling into place all of a sudden.\n\nI was one of the first sent to investigate Karazhan after it changed.  The demon Malchezaar discovered my intrusion.\n\nI quickly realized that I was no match for him.  I began to feel my soul become trapped by his magic.\n\nAt the last moment I hid a fraction of myself... of my memories inside the only place I could think of: my weapon.  Malchezaar has my soul.  You must help me recover it!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat Malchezar in Karazhan while equipped with Keanna's Will. Facet of Keanna must survive." }
WordHunterWoW_QuestEN[9663] = { title = "The Kessel Run", description = "You're just in time, {name}. Blood elf activity in this area has doubled in the past week. Our agents have informed us that the blood elves that call themselves Sunhawks plan to launch an offensive upon Azuremyst soon. I need you to get a warning out to our allies and compatriots.\n\nWarn High Chief Stillpine at Stillpine Hold, Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus' Landing.\n\nTime is of the essence so I am lending you my elekk. Be sure to keep it out of water.", objectives = "Kessel at Kessel's Crossing wants you to warn High Chief Stillpine at Stillpine Hold, Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus' Landing of the imminent blood elf invasion. Return to Kessel when you complete this task. You have 15 minutes. (Be sure to keep it out of water.)", progress = "This is no time to relax!", completion = "Well done, <name>. This was a difficult test of your abilities, but you have passed with flying colors. To become a soldier of the Hand of Argus, you must pass many such tests." }
WordHunterWoW_QuestEN[9664] = { title = "Establishing New Outposts", description = "Welcome to the Plaguelands, <name>. As you know, the Forsaken and their allies hold the lands to the west of here against our best efforts. The Alliance commanders have decided that here in the east, we will establish new fortifications to tighten the noose around our enemies.\n\nTowers long abandoned since the days of Lordaeron are to be seized and rebuilt for this purpose. These lands are dangerous, and we could use your help.", objectives = "Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Whitebeard at Light's Hope Chapel.", completion = "Very good, <name>. It will be important for us to hold these towers against future attacks, and for that we may need your assistance until reinforcements can be brought in to secure the area." }
WordHunterWoW_QuestEN[9665] = { title = "Bolstering Our Defenses", description = "Agents of the Forsaken uncovered an Alliance plot to establish new bases here in the Eastern Plaguelands, at abandoned towers throughout the area.\n\nIt is imperative that we not allow them to establish a significant presence on our eastern borders, and so we must stave off this Alliance incursion. Our current plans are to drive them out of any towers they may have already seized, and occupy those that we have under our control against further attacks.", objectives = "Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Gormok at Light's Hope Chapel.", completion = "This is good news, <name>. It will be a constant struggle here in the Plaguelands until we have fully driven back the forces of the Alliance.\n\nUntil that day, I hope that we will have your continued assistance." }
WordHunterWoW_QuestEN[9666] = { title = "Declaration of Power", description = "Have you seen the serpent men? The ones that call themselves naga?\n\n<Kessel spits.>\n\nThey dared make an advance upon this camp under cover of darkness only three nights ago. Can you believe the audacity of those primitive beasts?\n\nI need you to deliver a message to their leadership, {name}. To the northeast is Wrathscale Lair, home to Lord Xiz. Find him, slay him where he stands and drive this banner through his corpse.\n\nLet them know fear whenever they should see our standard!", objectives = "Kessel at Kessel's Crossing on Bloodmyst Isle wants you to kill Lord Xiz at Wrathscale Lair and drive the Draenei Banner through his dead body.", progress = "Is it done?", completion = "I am sorry that you had to do that, <name>. Heavy-handed violence is not the draenei way, but sometimes it is the only way.\n\nThis is one of life's truths that many do not understand until it is too late. So it was for our people, when we were slaughtered at the hands of the orcs.\n\nBecoming a Hand of Argus is a process of rebirth. And with birth comes pain..." }
WordHunterWoW_QuestEN[9667] = { title = "Saving Princess Stillpine", description = "Help me, {name}! The Bristlelimb captured me and are planning to sacrifice me to their foul gods!\n\nHigh Chief Bristlelimb holds the key that opens the cage. To force him to appear, you must slaughter the evil Bristlelimb furbolgs that inhabit the enclave, just two camps to the west of this camp. If you kill enough of them, he will surely come for vengeance! When he shows up, kill him and get the key!\n\nMy father will richly reward you if you can save me!", objectives = "Release Princess Stillpine from her cage and then speak with Stillpine Ambassador Frasaboo at Blood Watch.\n\nYou must kill High Chief Bristlelimb for the key that opens the cage.", completion = "Once again you have proven yourself to be all that was prophesied. You have the eternal gratitude of the high chief <name> -- and these Stillpine relics to choose from..." }
WordHunterWoW_QuestEN[9668] = { title = "Report to Exarch Admetius", description = "A Hand of Argus soldier is many things: Obedient, brave, intelligent, and above all, honorable. You may yet exhibit some of these traits, {class}.\n\nReport to Exarch Admetius at Blood Watch if you are still interested in joining the Hand. He and his subordinates will further train you in the ways of the draenei soldier.\n\nAnd remember this, {name}: Honorable people do not always perform honorably. Sometimes they cannot.\n\nYou will find Blood Watch just up this road, to the north.", objectives = "Speak with Exarch Admetius at Blood Watch.", completion = "I had a feeling that you would make it this far, <class>. If you are willing to go further, I am willing to teach you..." }
WordHunterWoW_QuestEN[9669] = { title = "The Missing Expedition", description = "About a week ago, my research team and I were out exploring the western wilds of Bloodmyst when we were attacked by bloodthirsty spiders. The effect of the crystal contamination was clearly evident as these spiders were massive and extremely aggressive.\n\nI managed to escape but my team wasn't so lucky. We must not let the same fate befall others. Go west to the Amberweb Pass and destroy the spiders and their matriarch, Zarakh.", objectives = "Kill 8 Myst Spinners, 8 Myst Leechers and their leader, Zarakh. Return to Achelus at Blood Watch when the task is complete.", completion = "Incredible! Did you find any survivors?\n\n<Achelus lowers his voice to a whisper.>\n\nI'll be honest, <name>; nobody else was willing to take on this mission. You are a brave <class>..." }
WordHunterWoW_QuestEN[9670] = { title = "They're Alive! Maybe...", description = "It was a bloody mess, {name}. We were ambushed by a large pack of these spiders. Their progenitor descended upon us with incredible speed and wrapped us up in cocoons.\n\nAfter we were webbed, she began to lay eggs near us. We were to be food for her young! FOOD!\n\nI managed to cut my way out and escape but I will not leave the others behind. So far I've been unsuccessful in nearing the pass. Would you lend a hand?\n\nDestroy those cocoons! Hopefully some of our team is still alive!\n", objectives = "Researcher Cornelius has asked that you free 5 Expedition Researchers.", progress = "Any luck?", completion = "You rescued over half the team! Word of your deed will definitely get back to Blood Watch and the exarch. Thanks again, <name>." }
WordHunterWoW_QuestEN[9671] = { title = "Urgent Delivery", description = "", objectives = "Are you <name>? It's about time! I'd just about given up on finding you!\n\nThere's an urgent message waiting for you at the mailbox. The person that gave it to me was a human admiral from Azuremyst. Admiral Odesy-something... the name escapes me. He said you would know who he was." }
WordHunterWoW_QuestEN[9672] = { title = "The Bloodcurse Legacy", description = "Dear friend,\n\nMy hand trembles as I ink this letter. I pray that it reaches you in time.\n\nLast night, Edward Hanes, captain of the ship 'Lost Hope', appeared before me in my tent. The same Edward Hanes that died of scurvy 20 years ago.\n\nThis apparition told me a tale that made my heart tremble. A tale that I need you to hear and a mission that I need you to accomplish. Will you do it? Will you seek out Edward on Wyrmscar Island, northeast of your base?\n\nRegards,\n\nAdmiral Odesyus\n", objectives = "Admiral Odesyus has asked that you find and speak with Captain Edward Hanes.", completion = "Have you heard of the bloodcurse, landlubber? No, of course you haven't. The bloodcurse is what sunk all these ships. The spoiled, desecrated part of the water here is known as Bloodcursed Reef - a part of the world you never want to visit. I've been here myself for 20 years.\n\nScurvy my foot! I died on these wild shores as food for the dragons... Ah, but that's another story for another time. Right now, we have to help the poor souls that are trapped in that reef." }
WordHunterWoW_QuestEN[9673] = { title = "Beast Training", description = "Beyond bonding with your chosen pet, there remains the intricacies of caring and training it.  For this, Halthenis the beast trainer of Silvermoon City can show you the way.\n\nHe always shows the utmost respect for my students, if they do the same for him.  Do not disappoint me.You will also receive:", objectives = "Speak with Halthenis in Silvermoon City.Beyond bonding with your chosen pet, there remains the intricacies of caring and training it. For this, Halthenis the beast trainer of Silvermoon City can show you the way.\n\nHe always shows the utmost respect for my students, if they do the same for him. Do not disappoint me.You will also receive:" }
WordHunterWoW_QuestEN[9674] = { title = "The Bloodcursed Naga", description = "They say when the world was sundered, this land cried the loudest. It was here that thousands of night elves faded into oblivion and in their place rose terrible creatures of hate - the naga.\n\nObedient to their twisted queen, Azshara, they would destroy all that would dare pass through their sea. It would remain this way for thousands of years - until now.\n\nThe first order of business is to remove the bloodcursed naga from the reef.", objectives = "Captain Edward Hanes on Wyrmscar Island wants you to kill 10 Bloodcursed Naga.", progress = "They're nasty creatures...", completion = "A good start, but there's much more to be done!" }
WordHunterWoW_QuestEN[9675] = { title = "Beast Training", description = "Oh, one more thing!  You'll want to speak with Ganaar at the Exodar.  He'll be able to teach you the last bits of knowledge necessary to care for your pet and train it.\n\nYou can find him in the southwest corner of the Traders Tier.You will also receive:", objectives = "Speak with Ganaar at the Traders Tier of the Exodar.Oh, one more thing!  You'll want to speak with Ganaar at the Exodar. He'll be able to teach you the last bits of knowledge necessary to care for your pet and train it.\n\nYou can find him in the southwest corner of the Traders Tier.You will also receive:" }
WordHunterWoW_QuestEN[9676] = { title = "Paladin Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young paladins here on Sunstrider Isle, your trainer is Jesthenis Sunstriker. Speak with Jesthenis and see what training he has available for you.  The things he will teach do have a cost, so bring some coin with you.\n\nYour trainer - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", objectives = "Speak with Jesthenis Sunstriker - the Paladin class trainer - inside the Sunspire on Sunstrider Isle.", completion = "I see the pride swelling in your chest. Already you fancy yourself one of the Blood Knights.\n\nIn time, you will earn your place among us. But first you must learn to harness and master the powers of the Light, hone your skills at arms, and prove your worthiness.\n\nYou must be prepared to endure the derision, fear, and revulsion of those you're sworn to defend. So it is among those who can't comprehend the price of the great power that safeguards them. Keep your head high and your blade at the ready, <name>." }
WordHunterWoW_QuestEN[9677] = { title = "Summons from Knight-Lord Bloodvalor", description = "<name>, you have excelled in your early training and distinguished yourself among those who would become Blood Knights. You are ready to undertake the next phase of your training and, to that end, Knight-Lord Bloodvalor himself has asked to speak with you.\n\nI have no doubt that Knight-Lord Bloodvalor wishes to set a trial for you to test your abilities and training. You will find him in the Blood Knight headquarters in Silvermoon City's Farstriders' Square. I wish you well, <name>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Knight-Lord Bloodvalor in Farstriders' Square in Silvermoon City.<name>, you have excelled in your early training and distinguished yourself among those who would become Blood Knights. You are ready to undertake the next phase of your training and, to that end, Knight-Lord Bloodvalor himself has asked to speak with you.\n\nI have no doubt that Knight-Lord Bloodvalor wishes to set a trial for you to test your abilities and training. You will find him in the Blood Knight headquarters in Silvermoon City's Farstriders' Square. I wish you well, <name>.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9678] = { title = "The First Trial", description = "You have learned much of combat and bloodshed, initiate, but there is much more to our order.\n\nMastery of the Light requires a focused mind and tremendous willpower. Without these, you are little better than a street thug.\n\nThere is an island in the northeastern reaches of the Ghostlands, called the Isle of Tribulations, that we use to hone these skills. You will find a brazier within a shallow cave there. Kneel before the brazier, light it, and focus on what you see before your eyes.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Travel to the island Knight-Lord Bloodvalor described, find the cave, and light the brazier. When the First Trial is over, return to Knight-Lord Bloodvalor in Silvermoon City." }
WordHunterWoW_QuestEN[9680] = { title = "Digging Up the Past", description = "Kamsis was right!  This information is extremely important.\n\nIf Medivh weaved his own essence into the magic he used to defeat the dragon, it is quite possible we could retrieve even a faint residue of that essence from the dragon's remains.  What great insight may lie beneath the ashes of Deadwind Pass, awaiting discovery.\n\nGo to the mountains south of Karazhan and bring me back a bone fragment of seemingly draconic origin.", objectives = "Archmage Alturus wants you to go to the mountains south of Karazhan in Deadwind Pass and retrieve a Charred Bone Fragment.", progress = "Have you retrieved the bone fragment I require, <name>?", completion = "Excellent!  Though small in size, this fragment is teeming with energy, I can feel it!" }
WordHunterWoW_QuestEN[9681] = { title = "A Study in Power", description = "Do not think me unduly harsh, <name>. Stillblade knew well what he was being sent to do. He understood and accepted his duty and is an example for all aspiring Blood Knights.\n\nMy words are no eulogy, <name>. Stillblade's service to us is far from over and you will be the instrument of his resurrection.\n\nYour education in the order's ways has just begun. With the betrayal of Kael'thas and the loss of our power source, you must learn new methods of wielding the Light. Seek out Magister Astalor Bloodsworn.Upon completion of this quest you will gain:", objectives = "Speak with Magister Astalor Bloodsworn in the hidden chamber beneath Blood Knight headquarters.Do not think me unduly harsh, <name>. Stillblade knew well what he was being sent to do. He understood and accepted his duty and is an example for all aspiring Blood Knights.\n\nMy words are no eulogy, <name>. Stillblade's service to us is far from over and you will be the instrument of his resurrection.\n\nYour education in the order's ways has just begun. With the betrayal of Kael'thas and the loss of our power source, you must learn new methods of wielding the Light. Seek out Magister Astalor Bloodsworn.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9682] = { title = "The Hopeless Ones...", description = "On a ledge of the reef, deeper than where you found the bloodcursed naga, you will find the hopeless ones: The bloodcursed voyagers, ghosts of those taken by the bloodcurse.\n\nIt is regrettable, what I ask of you now... but they must be destroyed and their cursed shells brought back to me.\n\nTheir souls must be put to rest. Return to me when you have done as asked and I shall give you one final task.", objectives = "Captain Edward Hanes on Wyrmscar Island wants you to recover 4 Bloodcursed Souls.", progress = "Do not mourn their demise, <name>.", completion = "You have done the hopeless ones a great service, <name>. There is but one final task: Destroy the leader of the Bloodcursed." }
WordHunterWoW_QuestEN[9683] = { title = "Ending the Bloodcurse", description = "To the south you will find Bloodcurse Isle. Atop the island you will find a shrine dedicated to the beloved queen of the naga, Azshara. Destroy the statue - burn it in effigy! This will surely draw the ire of Atoph, the Bloodcursed leader.\n\nSlay Atoph and return to me!", objectives = "Captain Edward Hanes on Wyrmscar Island wants you to destroy the Statue of Queen Azshara and kill Atoph the Bloodcursed.", progress = "Atoph must be lured out!", completion = "You did it! Hundreds of souls are grateful for all that you have done.\n\nAllow me to make an offering..." }
WordHunterWoW_QuestEN[9684] = { title = "Claiming the Light", description = "Take this vessel, <name>. The enchantment it bears will allow you to draw the last vestiges of the Light surrounding these magisters. They once tended the captive naaru and some of its energy yet remains within them.\n\nIt will be just enough to restore your comrade to life.\n\nDo not worry about the magisters, <name>. I have seen to their care, and Lord Solanar assures me that Lady Liadrin seeks a new source of power even now.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Shimmering Vessel on the Blood Elf Magisters to fill it and return to Knight-Lord Bloodvalor in Silvermoon City." }
WordHunterWoW_QuestEN[9685] = { title = "Redeeming the Dead", description = "While you were preparing the vessel, I sent a group of initiates to retrieve Sangrias Stillblade. You will find him on the top level of Silvermoon's inn with an attendant. Make your way there with all haste and unleash the vessel's magic to restore him to life.\n\nTime is of the essence, <name>. Once he has been dead for too long, not even the Light can bring him back to us. Return to me once you have resurrected Stillblade.You will learn:", objectives = "Take the Filled Shimmering Vessel to Silvermoon City's inn and use its magic to resurrect Sangrias Stillblade." }
WordHunterWoW_QuestEN[9686] = { title = "The Second Trial", description = "You stand on the verge of adept status in the order, <name>. First, you must prove your worthiness by undertaking another trial.\n\nThe Second Trial differs from the first in that there will be no surprises this time. The challenge before you is simple; you must face and best four Blood Knight champions in combat.\n\nWhen you accept the challenge, a crystal will appear in the middle of the pavilion. Touch it to begin your trial and do not stray far from the building.\n\nAre you prepared?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Complete the Second Trial by defeating Champion Bloodwrath, Champion Lightrend, Champion Swiftblade, and Champion Sunstriker in the pavilion near Master Kelerun Bloodmourn." }
WordHunterWoW_QuestEN[9687] = { title = "Restoring Sanctity", description = "Not long ago, the once tranquil owlkin of the region appeared on the shores of this island. One by one they would come to steal the bones of the fallen dragons. I do not know what would cause these creatures such distress or why they would want the bones of the deceased, but the spirits of the brood have grown restless due to this sacrilege.\n\nTo the west, across the Crimson Reach, you will find Ragefeather Ridge. Venture to the owlkin encampments and recover the pilfered dragon bones.", objectives = "Prince Toreth on Wyrmscar Island wants you to recover 8 Dragon Bones.", progress = "The dragon wars have long since passed. All that remains are bones and the agitated remnants of Ysera's brood.", completion = "A ritual? The owlkin had lived in harmony with the land for thousands of years. Such a thing is an aberration!\n\nSuch a pity..." }
WordHunterWoW_QuestEN[9688] = { title = "Into the Dream", description = "The whelps that you see on this island are the agitated spirits of the green dragonflight. Like me, they are bound to the land, unable to ascend to their final resting place in the Dream.\n\nRecovering the bones of the fallen has settled them somewhat but you must take further action.\n\nDestroy their ethereal manifestations. I cannot leave this place until it is done. They must be released!", objectives = "Prince Toreth at Wyrmscar Island has asked that you slay 5 Veridian Whelps and 5 Veridian Broodlings.", completion = "As reprehensible as your task was, it had to be done. Now you must look into the face of evil." }
WordHunterWoW_QuestEN[9689] = { title = "Razormaw", description = "Many of the black dragonflight were slain during the attacks. One of them, a lieutenant of Deathwing himself, still haunts this place. If you look to the heavens, you can see his spectral countenance circling the skies. His hatred is so great that he remains even in death.\n\nTake the bones that you gathered for me earlier to the top of the mountain on this island and place them in the ever-burning pyre. This act should signal Razormaw to descend. When he does, slay his undead form.", objectives = "Prince Toreth at Wyrmscar Island has asked that you slay Razormaw.", progress = "I recommend that you bring allies, <name>.", completion = "How long has it been? A thousand years? Ten-thousand perhaps? You have done me and the memory of my people a great service, <name>. Please accept this item of power as a token of appreciation from Loreth'Aran - in honor of your deeds." }
WordHunterWoW_QuestEN[9690] = { title = "The Second Trial", description = "Initiate <name>, you have worked hard to master the powers of the Light won by our magisters. You have learned the source of our abilities and of the duties of a Blood Knight.\n\nThe time has come for you to undergo the Second Trial, and contest for status as an adept among the Blood Knights. The trial will be administered by Master Kelerun Bloodmourn at a location north of the city. Travel north through the Ruins of Silvermoon and take the east path immediately before the bridge to Sunstrider Isle.Upon completion of this quest you will gain:", objectives = "Report to Master Kelerun Bloodmourn.Initiate <name>, you have worked hard to master the powers of the Light won by our magisters. You have learned the source of our abilities and of the duties of a Blood Knight.\n\nThe time has come for you to undergo the Second Trial, and contest for status as an adept among the Blood Knights. The trial will be administered by Master Kelerun Bloodmourn at a location north of the city. Travel north through the Ruins of Silvermoon and take the east path immediately before the bridge to Sunstrider Isle.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9691] = { title = "Return to Silvermoon", description = "Return to Silvermoon City and report to Knight-Lord Bloodvalor promptly. Your arrival will tell him all he needs to know about the outcome of the trial.\n\nHe will tell you of your remaining tasks on the road to becoming an adept. Hold your head high, <name>. Many undertake this trial, but very few return to tell of their success.You will learn:", objectives = "Return to Knight-Lord Bloodvalor in Silvermoon City.Return to Silvermoon City and report to Knight-Lord Bloodvalor promptly. Your arrival will tell him all he needs to know about the outcome of the trial.\n\nHe will tell you of your remaining tasks on the road to becoming an adept. Hold your head high, <name>. Many undertake this trial, but very few return to tell of their success.You will learn:" }
WordHunterWoW_QuestEN[9692] = { title = "The Path of the Adept", description = "Before a newly-minted adept can be accepted into the ranks of the Blood Knights, <he/she> must procure the resources  to create our order's distinctive weapon, the blood-tempered ranseur.\n\nYou must also earn the right to wear our order's insignia. When the order was founded, a set number were forged and distributed, so each new adept inherits <his/hers> from a veteran. Your insignia will come from a fallen knight who bravely led an assault on Deatholme.\n\nI have prepared a set of notes to guide you.Upon completion of this quest you will gain:", objectives = "Bring a Corrupted Kor Gem, a Crate of Bloodforged Ingots, a quantity of Blood of the Wrathful, and a Blood Knight Insignia to Knight-Lord Bloodvalor in Silvermoon City." }
WordHunterWoW_QuestEN[9693] = { title = "What Argus Means to Me", description = "What does Argus mean to you, {name}? Many draenei probably do not know or remember our home planet. It is there that we split from the man'ari: the twisted demonic reflections of ourselves that were 'gifted' by Sargeras. Or as they call themselves, eredar.\n\nEredar... this word once held meaning.\n\n<Admetius smacks his lips as if to taste the word.>\n\nDisgusting.\n\nLet us not waste anymore time. Find Vindicator Boros to begin your training.", objectives = "Exarch Admetius at Blood Watch has told you to speak with Vindicator Boros.", completion = "Ah, <name>... I've heard about you. You're the one that made the Kessel Run in under 15 minutes, right? Bah, probably not.\n\nAre you ready to spill some blood in the name of the Light? For Velen? For Argus?\n\n\n\nI'll slow down." }
WordHunterWoW_QuestEN[9694] = { title = "Blood Watch", description = "Blood Watch is one of two forward bases operated by the Hand of Argus. You have already been to the other base, Azure Watch; things are completely different in Bloodmyst. When we first got here, the land was as beautiful as Azuremyst. We even called it Silvergale but now sickness is spreading across the land, worse yet, the blood elves that we were battling on the Exodar survived the crash. This brings me to your assignment: Venture northwest into Bladewood and terminate any blood elves that you find.", objectives = "Vindicator Boros at Blood Watch wants you to slay 10 Sunhawk Spies.", completion = "You have returned - and in one piece!\n\nI have some good news, <name>. We have received some new information about the possible location of more survivors. A new crash site has been discovered! When I am done attending to those matters, I will call for you." }
WordHunterWoW_QuestEN[9695] = { title = "The Sun King's Command", description = "This document looks to be important. Unfortunately, it is written in Thalassian, a language that you cannot understand.\n\nPerhaps Vindicator Boros will know what to do with the letter.", objectives = "Take the Sun King's Command to Vindicator Boros at Blood Watch." }
WordHunterWoW_QuestEN[9696] = { title = "Translations...", description = "Our chief interrogator, Elysia, is fluent in Thalassian. Take the document to her and see what she has to say.", objectives = "Take the Sunhawk Missive to Interrogator Elysia at Blood Watch.", progress = "I'm a bit busy here, agent <name>. This better be important.", completion = "<Elysia reads from the document.>\n\nIf what this document says is true, the blood elves have opened a portal to the Outland! It would certainly explain their seemingly endless numbers..." }
WordHunterWoW_QuestEN[9697] = { title = "Watcher Leesa'oh", description = "There's important research to be conducted into the ecology of the local creatures, especially the sporelings and bog lords of the marsh.  And trust me, once you get out into the field, you'll find the work to be challenging.\n\nSeek out Watcher Leesa'oh at the Cenarion Watchpost in the western region of the marsh toward the south.  Follow the path west and you will eventually find her.  She can be a bit -- studious -- but don't let that get to you.\n\nOh, and watch out for her cat.", objectives = "Speak with Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh.", completion = "Oh, good... help finally!  There's just so much to do, and I need to stay here to organize it all.\n\nI hope that you're ready to get your hands dirty." }
WordHunterWoW_QuestEN[9698] = { title = "Audience with the Prophet", description = "I need you to deliver the translated documents to Velen personally, {name}. I don't trust that deranged messenger.\n\nExplain to the Prophet that the blood elves are receiving reinforcements from the Outland and that they have a spy amongst the draenei at the Exodar. Velen resides in the Vault of Lights inside the Exodar.\n\nMake haste!\n", objectives = "Take the Translated Sunhawk Missive to Prophet Velen at the Exodar.", progress = "<Velen smiles.>\n\nGreetings, <name>. I have been expecting you.", completion = "<Velen begins to read the document.>\n\nInteresting... This does indeed explain much." }
WordHunterWoW_QuestEN[9699] = { title = "Truth or Fiction", description = "I thank you for the timely delivery, {name}. You are turning out to be one of the Hand's better agents.\n\nIf only we knew who they reported to in Bloodmyst and more importantly, where this sun portal was... They seem to have it tightly guarded - wherever it may be.\n\nWould you be interested in some reconnaissance work?\n\nIf so, take these orders back to Vindicator Boros. He will give you your next mission.", objectives = "Take Velen's Orders to Vindicator Boros at Blood Watch.", progress = "Well?", completion = "It's a good plan, but a dangerous one. I'm sure you'll be fine." }
WordHunterWoW_QuestEN[9700] = { title = "I Shoot Magic Into the Darkness", description = "Velen states that if the blood elves have been opening rifts between this island and the Outland, there will be residue or anomalies left in the areas where the portals have been opened. You must search the island for locations that exhibit or display these anomalies.\n\nBe warned, {name}; some of these anomalies will be creatures from the void itself. Should you find void anomalies, slay them! Report back to me with any new information that you may find. Begin your search to the north, near the Warp Piston.\n", objectives = "Vindicator Boros at Blood Watch wants you to locate the Sun Portal Site and slay 5 Void Anomalies.", completion = "How many did you say you saw at the Warp Piston? Just how many times have they opened up this sun portal? This is very bad news...\n\nAlas, you have learned all that I am able to teach you, <name>. Kuros will call for you when it is time." }
WordHunterWoW_QuestEN[9701] = { title = "Observing the Sporelings", description = "We need to learn all that we can of the sporelings at Sporeggar and their relationship to the creatures around them.  One way to do that is what I'm doing; passive observation while making a note of their interactions.\n\nI need you to head over to the Spawning Glen to the west.  Investigate the whole area and then return to tell me what you saw.", objectives = "Investigate the Spawning Glen in Zangarmarsh, and then report back to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh with your findings.", completion = "What?!  The bog lords of Quagg Ridge are EATING the sporelings' pods?  This isn't good!" }
WordHunterWoW_QuestEN[9702] = { title = "A Question of Gluttony", description = "I was wondering why the bog lords were crossing the road to go to the Spawning Glen - they must be starving for some reason.  This just will not do!\n\nI mean, normally I wouldn't get involved, but if they continue to eat all of the sporeling pods they'll wipe them out!\n\nHere's what we'll do: I'll stay here and you head to the Quagg Ridge to the east and look for dietary clues as to why they're raiding the sporelings.", objectives = "Collect 10 pieces of Discarded Nutriment and then return to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh.", progress = "Be sure that you collect all of the evidence carefully, <class>!  We're fitting the pieces of a giant puzzle together here.  A mistake on your part could lead us to the wrong conclusions.\n\nThen where would we be in our understanding of Zangarmarsh's ecology?", completion = "This is what you found?  That's odd.  These husked mushroom remains are both unusual and somehow look familiar.\n\nI have to think on this a moment.  Don't go anywhere!" }
WordHunterWoW_QuestEN[9703] = { title = "The Cryo-Core", description = "We have others pursuing leads on the sun portals, {name}. I need you to focus on the task at hand.\n\nBoros has received new reports of another crash site. What we've since discovered is that the crash site is actually the Exodar's cryo-core. This is a pod holding area that houses pods exactly like the ones we draenei crawled out of in Ammen Vale.\n\nThis area also holds medical supplies. Head to the Cryo-Core, directly west of Blood Watch. Search for supplies and search for survivors.\n", objectives = "Vindicator Kuros at Blood Watch wants you to recover 12 boxes of Medical Supplies.", progress = "Was the information accurate?", completion = "Just blood elves? No survivors? This is troubling. I'll need some time to think this through, <name>. Perhaps Aesom or Boros have an assignment for you to complete." }
WordHunterWoW_QuestEN[9704] = { title = "Slain by the Wretched", description = "It's hard work being an outrunner between Sunstrider Isle and Falconwing Square.  Tight deadlines, long hours and worst of all... the Wretched!\n\nThe road south goes through the ruins of Silvermoon... the place is crawling with Wretched ready to kill you for a few mana crystals.  Unfortunately, I think that's what happened to the last outrunner we sent with one of Erona's packages.\n\nI see you're eager to prove yourself.  Venture into Dawning Lane and see if you can find any traces of our outrunner.", objectives = "Go south into the ruins of Silvermoon and look for the Slain Outrunner in Dawning Lane.", completion = "The outrunner's belongings have all been stolen with the exception of one package.  It seems to match Alarion's description of Erona's package." }
WordHunterWoW_QuestEN[9705] = { title = "Package Recovery", description = "You take the package and confirm that indeed it comes from Magistrix Erona.  Alarion would probably want you to bring it to her.", objectives = "Return to Outrunner Alarion with Erona's Package.", progress = "What did you find, <name>?", completion = "By the Sunwell!  That's the third outrunner we've lost this month.\n\nI appreciate your courage in venturing into Dawning Street.  The guards need to keep a closer eye on these blasted Wretched." }
WordHunterWoW_QuestEN[9706] = { title = "Galaen's Journal - The Fate of Vindicator Saruan", description = "Your hands tremble as you pick up the book. Kuros must be told about this tragedy. Return the book to him.", objectives = "Take Galaen's Journal to Vindicator Kuros at Blood Watch.", progress = "What have you got there, <name>? Is that a journal?", completion = "<Kuros' face turns pale as he reads the journal; tears stream down his face.>\n\nSaruan was my master... my teacher... my mentor... I took his place among the Triumvirate only recently - after we had given up searching for him.\n\n<Kuros' face contorts in anger.>\n\nMatis..." }
WordHunterWoW_QuestEN[9707] = { title = "Forging the Weapon", description = "Once again, you have proven yourself worthy before the order and your peers. It is with great pleasure that I bestow upon you the rank of adept, <name>. Prince Kael'thas himself would be proud of you.\n\nAny of us would be honored to fight by your side on the field of battle. Continue to serve as an example for those who aspire to join us. Show neither mercy nor weakness, defend your people and your brothers tirelessly, and hone your mastery of the Light.\n\nNow, claim the weapon befitting your new rank.Upon completion of this quest you will gain:", objectives = "Take the Crate of Materials to Bemarrin in Silvermoon City." }
WordHunterWoW_QuestEN[9708] = { title = "Familiar Fungi", description = "Yes, that's it, I knew I had seen this particular phylum of mushroom elsewhere in the marsh!\n\nTo the north is a place known as the Hewn Bog.  Odd name for the place if you ask me, but I've never been there.  I'll need samples of those mushrooms to confirm my hypothesis.\n\nJust be careful, {class}.  I'd heard that ogres have moved in to the area, so you'll have to get the samples from them.  Could that be why the bog lords are no longer going there for their food?", objectives = "Collect 15 Mushroom Samples and return them to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh.", progress = "Do you have those samples yet?", completion = "We definitely have a match here.  And the presence of the ogres and what they were doing there explains everything.  Now I get why it's called the Hewn Bog, duh!\n\nWe have to do something about this situation, but what?  We can't just wipe out all of those ogres; they have every bit as much a right to be here as any of the other creatures in the marsh!" }
WordHunterWoW_QuestEN[9709] = { title = "Stealing Back the Mushrooms", description = "{class}, I've got an idea.   I want you to head north again, this time into the heart of ogre territory!\n\nNorthwest of the Hewn Bog there is a place named Ango'rosh Stronghold, which sits on a floating island across a large mushroom bridge.\n\nThe ogres must be storing the harvested mushrooms there.  I bet you'll find them all over the place, and probably on the ogres themselves, too!\n\nBring me a sufficient number and I will try to do something about providing the bog lords with a new source of nourishment.", objectives = "Collect 10 Boxes of Mushrooms and return them to Watcher Leesa'oh at the Cenarion Watchpost in Zangarmarsh.", progress = "You have all of the mushrooms that we need to create a new garden for the bog lords?", completion = "These are perfect!  Oh, thank you, <class>!\n\nYou've been ever so careful not to disturb the natural order of things, and we've gathered so much information in such a short amount of time!\n\nNow, let's see if our little plan to grow a new food supply for the bog lords is going to work." }
WordHunterWoW_QuestEN[9710] = { title = "The Blood-Tempered Ranseur", description = "I've got everything prepared, <name>. Very soon you will have a weapon befitting your new status.You will receive:", objectives = "Wait while Bemarrin forges your weapon.I've got everything prepared, <name>. Very soon you will have a weapon befitting your new status.You will receive:" }
WordHunterWoW_QuestEN[9711] = { title = "Matis the Cruel", description = "Matis will be brought to justice, {name}; and I want you to be the one to find him and bring him back to the Triumvirate.\n\nScour the island for this killer. Should you find him, use this flare gun. When my trackers see the flare, they'll come and assist in capturing Matis. Return to me after he's been captured.", objectives = "Vindicator Kuros at Blood Watch wants you to capture Matis the Cruel.", completion = "The Triumvirate has decided to try Matis immediately. You have brought an arch-criminal to justice on this day, young <race>.\n\nYou have performed admirably for two of three; only Aesom remains." }
WordHunterWoW_QuestEN[9712] = { title = "The Thalassian Warhorse", description = "You have distinguished yourself in the service of the order, <name>. Your skill in wielding the Light energies granted by Magister Astalor and his fellows has proven you worthy to receive a new kind of knowledge.\n\nWith the Light at your command, it is possible to summon a fearsome warhorse that will serve as your faithful mount.\n\nContinue to serve with dedication and honor, <name>, and even greater boons await you.You will learn:", objectives = "Talk to Knight-Lord Bloodvalor to learn how to summon your Thalassian Warhorse.You have distinguished yourself in the service of the order, <name>. Your skill in wielding the Light energies granted by Magister Astalor and his fellows has proven you worthy to receive a new kind of knowledge.\n\nWith the Light at your command, it is possible to summon a fearsome warhorse that will serve as your faithful mount.\n\nContinue to serve with dedication and honor, <name>, and even greater boons await you.You will learn:" }
WordHunterWoW_QuestEN[9713] = { title = "Glowcap Harvesting Enabling Flag", description = "", objectives = "" }
WordHunterWoW_QuestEN[9714] = { title = "Bring Me Another Shrubbery!", description = "", objectives = "We can still use more of the sanguine hibiscus from the shamblers, bog giants and underbats of the Underbog at Coilfang Reservoir.  Bring them to me in bunches of five and I will be most grateful.", progress = "We can still use more of the sanguine hibiscus from the shamblers, bog giants and underbats of the Underbog at Coilfang Reservoir.  Bring them to me in bunches of five and I will be most grateful.", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?" }
WordHunterWoW_QuestEN[9715] = { title = "Bring Me A Shrubbery!", description = "We must replenish our supply of sanguine hibiscus, which we use for a number of purposes.  They used to grow thick as shrubs, but the lowering of the marsh's water levels means that they can only be found now in the Underbog at Coilfang Reservoir, under Serpent Lake.\n\nIt is said that the shamblers, bog giants, and underbats there consider them a delicacy.  So, if you are to help us, you must retrieve the flowers from them.", objectives = "Collect 5 Sanguine Hibiscus and return them to Gzhun'tt at Sporeggar in Zangarmarsh.", progress = "Do you have all of the hibiscus that I asked you to gather?", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?" }
WordHunterWoW_QuestEN[9716] = { title = "Disturbance at Umbrafen Lake", description = "We came to Outland expecting to find small pockets of life.  What we discovered in Zangarmarsh was a lush environment with a thriving ecosystem.\n\nOur initial assessment of the area was deceiving, however.  The water levels at the lakes and marshes have consistently been going down since we started taking measurements.\n\nThe impact this could have on the local animal and plant life is disastrous.  Go to Umbrafen Lake, southwest of here, and look for clues related to this water depletion.", objectives = "Investigate the cause of the water depletion at Umbrafen Lake. Then return to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", completion = "The naga are behind this!  But why?  From what you describe, that steam pump must be part of the cause for the water levels dropping in the marsh!\n\nNo matter - this explains their open hostility towards us.  Let's not waste any time, I need you to perform another task for us." }
WordHunterWoW_QuestEN[9717] = { title = "Oh, It's On!", description = "While we are a peaceful people, we are at war with the spore giants, whether we like it or not.  And there is a saying amongst us that all is fair in mushrooms and war!\n\nOne of the leaders of the spore giants, Hungerfen, has been tending a very special plant, known as the Underspore, to perfection for millennia.  It would break his spirit if something were to happen to that plant.\n\nTravel to the Underbog in Coilfang Reservoir and steal a frond off of it for us.  Trust me, he'll notice.", objectives = "Gather an Underspore Frond and return it to T'shu at Sporeggar in Zangarmarsh.", progress = "The Underbog is a very dangerous place.  I would not consider you a coward if you were to balk at going there.  I also wouldn't be appreciative of you if you did not return with what I've asked for.", completion = "<The sporeling makes a sound that is vaguely reminiscent of snorting laughter.>\n\nPerfect!  No doubt the morale of the spore giants will be at an all time low once they realize what you've done.\n\nEither that, or they'll be so incensed that they'll attack us again soon.\n\n<T'shu makes a shrugging motion.>" }
WordHunterWoW_QuestEN[9718] = { title = "As the Crow Flies", description = "We must determine how widespread the naga's activity truly is and react accordingly.\n\nExploring each body of water in Zangarmarsh could be a lengthy undertaking.  If you allow me to, I will use my magic to mold your shape to one more suited to scouting the marsh.\n\nHold this amulet above the balcony near me when you're ready to begin.  I will guide your way back to safety after we're done.", objectives = "Ysiel Windsinger wants you to use the Stormcrow Amulet to explore the major lakes in Zangarmarsh.", progress = "Hail, <name>.", completion = "It is as I suspected.  The naga have set up pumping stations at all the major lakes in Zangarmarsh. \n\nThey must be stopped if the marsh is to have a future." }
WordHunterWoW_QuestEN[9719] = { title = "Stalk the Stalker", description = "Historically the greatest danger to my people has been from the marsh walkers.  With the new problems we are facing from spore giants, we cannot afford another attack from our ancient enemies.\n\nYou have proven yourself to be capable, <class>.  Do you think that you'd be able to journey to the Underbog in Coilfang Reservoir and eliminate the great mother of the marsh walkers, known as The Black Stalker?!\n\nBring me her brain as proof.", objectives = "Bring the Brain of the Black Stalker to Khn'nix at Sporeggar in Zangarmarsh.", progress = "You have returned.  Does this mean that The Black Stalker is no more?", completion = "The Black Stalker is dead!  Normally I would not revel in such butchery, but the pain that the great mother and her brood have put my people through over the centuries is unspeakable.\n\nIt is unfortunate that now another of her progeny will transform to replace her, but that will take time and give us some breathing room so that we will not have to worry about the marsh walkers for a while." }
WordHunterWoW_QuestEN[9720] = { title = "Balance Must Be Preserved", description = "I cannot begin to comprehend why the naga would drain the water out of their own habitat.  What I do understand is a need to put a stop to their operations.\n\nThese seeds carry with them the rage of the earth.  Take them to the steam pumps operated by the naga and use them on their controls.\n\nThe vines that grow from the seeds will be as thick as your arm and as strong as iron.  Go, {name}.  Restore the balance that the naga have upset.", objectives = "Ysiel Windsinger wants you to use the Ironvine Seeds on the Steam Pump Controls at Serpent Lake, Umbrafen Lake, Marshlight Lake and the Lagoon. Then return to her at the Cenarion Refuge in Zangarmarsh with any leftover seeds you have.", progress = "Is it done, <class>?", completion = "It is done, then.  The marsh has been saved for now.\n\nDon't think for a second that this will be the last we hear of the naga.  We must remain vigilant of our enemy as we continue with our mission in Outland." }
WordHunterWoW_QuestEN[9721] = { title = "A Summons from Lord Solanar", description = "Your dedication to our order and advancement through the ranks has not gone unnoticed. In fact, Lord Solanar Bloodwrath, Lady Liadrin's right hand and a hero in his own right, has asked to speak with you.\n\nThis is a rare honor, <name>. Normally, Lord Solanar leaves the management of the order's rank-and-file to me, but he has taken a personal interest in you. Do not tarry, <name>.Upon completion of this quest you will gain:", objectives = "Speak with Lord Solanar Bloodwrath in Silvermoon City.Your dedication to our order and advancement through the ranks has not gone unnoticed. In fact, Lord Solanar Bloodwrath, Lady Liadrin's right hand and a hero in his own right, has asked to speak with you.\n\nThis is a rare honor, <name>. Normally, Lord Solanar leaves the management of the order's rank-and-file to me, but he has taken a personal interest in you. Do not tarry, <name>.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9722] = { title = "The Master's Path", description = "Within the ranks of our order, there exists an inner circle of elite knights. Members of the circle represent the most dedicated, skilled, and trustworthy of all Blood Knights and are handpicked by the leadership. Most simply know the masters by their thalassian charger mounts.\n\nEach candidate for membership must have a sponsor within the circle and must demonstrate their dedication to the order's central tenets.\n\nI have chosen to sponsor you for standing as a Blood Knight master, if this is your wish.Upon completion of this quest you will gain:", objectives = "Speak with Lord Solanar Bloodwrath again to accept his offer of sponsorship.Within the ranks of our order, there exists an inner circle of elite knights. Members of the circle represent the most dedicated, skilled, and trustworthy of all Blood Knights and are handpicked by the leadership. Most simply know the masters by their thalassian charger mounts.\n\nEach candidate for membership must have a sponsor within the circle and must demonstrate their dedication to the order's central tenets.\n\nI have chosen to sponsor you for standing as a Blood Knight master, if this is your wish.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9723] = { title = "A Gesture of Commitment", description = "A Blood Knight's loyalty does not stop at the end of <his/her> blade, <name>. The order asks more of its members than mere drilling and combat. A true knight contributes to all of the order's activities, even the ones that may not seem glorious on the surface.\n\nThis first task is neither combat intensive, nor glorious, but without such contributions, the order would fall apart. I will give you a list of items Magister Astalor Bloodsworn's men require to keep us supplied with Light energy for our magics.Upon completion of this quest you will gain:", objectives = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Sungrass, 5 Dark Runes, and 150 Gold to Lord Solanar Bloodwrath in Silvermoon City." }
WordHunterWoW_QuestEN[9724] = { title = "Warning the Cenarion Circle", description = "The Cenarion Expedition has become a large organization with a good degree of autonomy.  These events are important enough that we need to warn the Cenarion Circle.\n\nDo not worry, I will not ask you to travel back to Moonglade; we have emissaries as nearby as Hellfire Peninsula.", objectives = "Speak to Amythiel Mistwalker at Cenarion Post in Hellfire Peninsula.", completion = "The news you bring about the naga activity in Zangarmarsh is dire.  Ysiel was wise in sending word to us.  She hasn't forgotten that the Expedition cannot exist without the Circle's support." }
WordHunterWoW_QuestEN[9725] = { title = "A Demonstration of Loyalty", description = "We Blood Knights are bound to defend Quel'Thalas, <name>. This is a central part of your training. Our enemies are fierce and unrelenting. Silvermoon and its people remain free by our efforts and the support of our allies.\n\nI have received some disturbing reports of a renewed Scourge presence to the southeast of our border with the Eastern Plaguelands. A company of Scourge siege engineers and their equipment appear to be staging for an attack on the Ghostlands. They must not be permitted to succeed.Upon completion of this quest you will gain:", objectives = "Lord Solanar Bloodwrath in Silvermoon City wants you to destroy 3 Scourge Meat Wagons and kill 15 Scourge Siege Engineers." }
WordHunterWoW_QuestEN[9726] = { title = "Now That We're Friends...", description = "The naga of the Bloodscale Enclave to the northeast have begun to kill our people.  We cannot allow this to continue, {class}!\n\nWe suggest that you teach them a lesson as proof of our friendship.", objectives = "Kill 12 Bloodscale Slavedrivers and 6 Bloodscale Enchantresses, and then return to Gzhun'tt at Sporeggar in Zangarmarsh.", completion = "<Gzhun'tt nods to you.>\n\nWe are pleased that you have affirmed our friendship, <name>.  Perhaps the naga heathens will think twice about harassing us in the future now that we have such a powerful ally?" }
WordHunterWoW_QuestEN[9727] = { title = "Now That We're Still Friends...", description = "Reports have come in that the naga of the Bloodscale Enclave to the northeast continue to kill our people.  We thought that you had dealt with this, <class>!\n\nI suggest that you to teach them a lesson as proof of our continued friendship.", objectives = "Kill 12 Bloodscale Slavedrivers and 6 Bloodscale Enchantresses, and then return to Gzhun'tt at Sporeggar in Zangarmarsh.", completion = "<Gzhun'tt nods to you.>\n\nWe are pleased that you have reaffirmed our friendship, <name>.  Surely now that you have made our point clear multiple times, their senseless attacks upon our people will cease?" }
WordHunterWoW_QuestEN[9728] = { title = "A Warm Welcome", description = "While the druids from the expedition have made themselves busy studying plants and researching the lakes, I've made it my business to deal with the hostiles in the area.\n\nEver since we set foot in Zangarmarsh, the naga have launched lethal attacks against us without warning.  We've done our best to keep them at bay, but our resources are limited.\n\nI want you to go to the various naga strongholds in Zangarmarsh and show them that we're not to be crossed.  Bring me their claws as proof of your victories.", objectives = "Warden Hamoot at the Cenarion Refuge wants you to bring him 30 Naga Claws.", progress = "It's good to see you again, <name>.  How's your hunt for the naga going?", completion = "Good job, <name>.  You'd do well to shed any feelings of remorse you might harbor.  These naga are vicious creatures - even more so than the Azerothian ones." }
WordHunterWoW_QuestEN[9729] = { title = "Fhwoor Smash!", description = "Little naga make Fhwoor angry!  Sporelings good friend to Fhwoor, so Fhwoor get naga ark.\n\nWe go into nearby naga village. You help?", objectives = "Escort Fhwoor into the area of the Marshlight steam pump to retrieve the Ark of Ssslith. Bring Fhwoor and the ark back safely and then report back to Gzhun'tt at Sporeggar in Zangarmarsh.", progress = "Is Fwhoor alright?  Have you recovered the ark?", completion = "Fhwoor's a good giant.  We saved him from the naga a while ago and he's stayed here helping us with things ever since.\n\nWe can only hope that the naga will take the hint and realize that if we can infiltrate their village and steal their most prized possession, we can do much worse.  Perhaps now they will return to their reservoir and leave us in peace?" }
WordHunterWoW_QuestEN[9730] = { title = "Leader of the Darkcrest", description = "A bounty is hereby declared by the Cenarion Expedition on Rajah Haghazed, leader of the Darkcrest naga.  Haghazed was last sighted by Cenarion scouts at the Lagoon, in the central southern region of Zangarmarsh.\n\nThe Darkcrest have been linked to numerous attacks against the Cenarion Expedition and their leader is considered extremely dangerous.\n\nThose seeking to claim the bounty are advised to report to Warden Hamoot.", objectives = "Slay Rajah Haghazed at the Lagoon and return to Warden Hamoot at the Cenarion Refuge in Zangarmarsh for a reward.", completion = "I didn't like the naga in Azeroth and I like them less here.  It's a real shame our mission could not remain a peaceful one, but you won't see me shedding tears for dead naga.\n\nHere's your reward for taking care of the Darkcrest leader, <name>." }
WordHunterWoW_QuestEN[9731] = { title = "Drain Schematics", description = "The schematics you've obtained show an underground system of drains and pumps that connect the lakes in the region to Serpent Lake.\n\nIf the schematics are correct, there is a giant drain in the center of Serpent Lake.  Confirm this and bring the news to Cenarion Refuge.", objectives = "Search Serpent Lake for signs of a drain. Return to Ysiel Windsinger at the Cenarion Refuge with news of your discovery.", progress = "What news do you bring, <name>?", completion = "The naga have turned Serpent Lake into a giant water sink for the rest of Zangarmarsh.  What could they possibly be doing?\n\nYou've done well in bringing this news to us, <name>.  We will send a team to investigate this drain you've discovered.  I have a different task for you in the meanwhile." }
WordHunterWoW_QuestEN[9732] = { title = "Return to the Marsh", description = "Return to Ysiel and let her know that help will be extended to her as soon as it is possible.\n\nAffairs in Moonglade and Silithus have kept our members occupied, but we will do our best to send the necessary resources to the Cenarion Refuge.  ", objectives = "Return to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", completion = "You are a welcome sight, <name>.  Matters at the Cenarion Refuge have only gotten worse since you left." }
WordHunterWoW_QuestEN[9733] = { title = "Warning the Cenarion Circle", description = "The Cenarion Expedition has become a large organization with a good degree of autonomy.  These events are important enough that we need to warn the Cenarion Circle.\n\nDo not worry, I will not ask you to travel back to Moonglade; we have emissaries as nearby as Hellfire Peninsula.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Mahuram Stouthoof at Thrallmar in Hellfire Peninsula.The Cenarion Expedition has become a large organization with a good degree of autonomy. These events are important enough that we need to warn the Cenarion Circle.\n\nDo not worry, I will not ask you to travel back to Moonglade; we have emissaries as nearby as Hellfire Peninsula.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9734] = { title = "Return to the Marsh", description = "Return to Ysiel and let her know that help will be extended to her as soon as it is possible.\n\nAffairs in Moonglade and Silithus have kept our members occupied, but we will do our best to send the necessary resources to the Cenarion Refuge.Upon completion of this quest you will gain:", objectives = "Return to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.Return to Ysiel and let her know that help will be extended to her as soon as it is possible.\n\nAffairs in Moonglade and Silithus have kept our members occupied, but we will do our best to send the necessary resources to the Cenarion Refuge.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9735] = { title = "True Masters of the Light", description = "A Blood Knight master possesses incredible skill at wielding and weaving the Light in a way that other so-called 'paladins' can never comprehend. It doesn't stop them from despising us for unleashing the Light's true potential.\n\nWe must send them a message and show them that we are not to be trifled with. What I have in mind will be neither brief nor easy, but if you are committed, the first step will be to infiltrate the library wing of the Tyr's Hand Abbey and procure a vial of Tyr's Hand holy water.Upon completion of this quest you will gain:", objectives = "Lord Solanar Bloodwrath in Silvermoon City wants you to bring him a vial of Tyr's Hand Holy Water." }
WordHunterWoW_QuestEN[9736] = { title = "True Masters of the Light", description = "Now that we have the water, we're going to need a number of reagents in precise quantities. Some of these substances are rare and expensive, <name>, but I have located sources for two.\n\nYou should be able to purchase some arcane catalyst from Zalle, the reagent vendor in one of the shops on the plaza near the Dead Scar. Darlia, the poison merchant near the rogue trainers on Murder Row, stocks crepuscular powder.\n\nTo complete my mixture, I'll also need an azerothian diamond and a pristine black diamond.Upon completion of this quest you will gain:", objectives = "Lord Solanar Bloodwrath in Silvermoon City wants you to bring him 1 Arcane Catalyst, 1 Crepuscular Powder, 1 Azerothian Diamond, and 1 Pristine Black Diamond." }
WordHunterWoW_QuestEN[9737] = { title = "True Masters of the Light", description = "Ours is the true way of utilizing the Light, <name>. To show others that would call themselves 'paladins' the folly of their ways, I intend to send an unmistakable message.\n\nThe Alonsus Chapel, where the Order of the Silver Hand was founded, seems immune to the destruction of Stratholme. The chapel's eternal flame affords it the Light's protection, but when you use this mixture to extinguish the flame, that protection will be no more. It will burn, and our dominion over the Light will be proven to the world.You will learn:", objectives = "Use the Extinguishing Mixture near the eternal flame in the Alonsus Chapel to remove the Light's protection. Be prepared to fight anyone who may attempt to defend the chapel." }
WordHunterWoW_QuestEN[9738] = { title = "Lost in Action", description = "You have to help me!  We were sent here by Ysiel to investigate the mystery of the steam pumps and why they're being used to drain the water from the marsh.  But my friends split up and went on recklessly without me.\n\nThose four can be such jerks sometimes, but I love them anyway.\n\nThat is why I need you to discover what became of them, though I fear the worst.  Seek them in both the Slave Pens and the Underbog.\n\nThank you, <class>.", objectives = "Discover what happened to Earthbinder Rayge, Naturalist Bite, Weeder Greenthumb, and Windcaller Claw. Then, return to Watcher Jhang at Coilfang Reservoir in Zangarmarsh.", completion = "I'm glad that some of my friends yet live, but it breaks my heart to hear of the fate of others.  <sigh>\n\nAt least they died doing what they loved most in life.  You have my eternal gratitude for helping me with this, <name>.\n\nPlease, take one of these as a sign of gratitude." }
WordHunterWoW_QuestEN[9739] = { title = "The Sporelings' Plight", description = "You there!  You must help us!\n\nThe fungal giants are devouring all of our spore sacs!  You must do something, or we'll lose our young!\n\nThe spore sacs start out large and become smaller as the air inside them is depleted.  Look for the small, mature spore sacs and save as many of them as you can!", objectives = "Fahssn at the Spawning Glen wants you to collect 10 Mature Spore Sacs.", progress = "The spore sacs!  Did you get them?", completion = "You've done it!  You have my people's thanks.\n\nI hope you understand... this is where our young ones come from.  We can't let these beasts devour the sacs!" }
WordHunterWoW_QuestEN[9740] = { title = "The Sun Gate", description = "Thanks to you and the work you did, my scouts were able to find the sun gate. The elves keep the portal location mobile so that they can move it at a moment's notice. That's why the site you investigated was empty.\n\nThe strength of such a system is also its greatest weakness. The sun gate is stabilized by portal controllers. If we can take down the controllers, the portal will be ours to destroy. The current sun gate location can be found west of here, south of the Vector Coil. Find it and destroy it!", objectives = "Vindicator Aesom at Blood Watch wants you to destroy the Sun Gate.", completion = "Smashing! We've cut off their supply line. Now all that we need to do is finish them off!" }
WordHunterWoW_QuestEN[9741] = { title = "Critters of the Void", description = "Aesom sent my squad out on a reconnaissance mission to search for the sun gate a few days ago. Needless to say, we found it...\n\n<Loryi points at Jorli.>\n\nWhatever those fool elves are transporting through that portal is causing void energy to be released. The area is teaming with void critters. \n\nWe must destroy them before they have a chance to grow into void anomalies. You'll find the source of the creatures southwest of here, near the sun gate. Kill them and report back to Aesom when you're done.", objectives = "Kill 12 Void Critters and report to Vindicator Aesom at Blood Watch.", completion = "It's a real mess up there, eh? You've done well, <name>. I'll send some anchorites out to help Loryi and Jorli." }
WordHunterWoW_QuestEN[9742] = { title = "More Spore Sacs", description = "", objectives = "Have you rescued any more spore sacs, <race>?", progress = "Have you rescued any more spore sacs, <race>?", completion = "Yes!  You've saved more spore sacs.\n\nYou're different than the other outsiders.  I'll let my people know about your deeds!\n\n<This quest is repeatable up to friendly reputation.>" }
WordHunterWoW_QuestEN[9743] = { title = "Natural Enemies", description = "Us sporelings and the bog lords have never gotten along well.  In the past, we've managed to keep them at bay with spears and stones.  Lately they seem to have become more aggressive... or more desperate.  They do not fear us or our weapons.\n\nYou are much scarier and better armed than us.  If you were to fight the boglords for us, we'd be forever in your debt!  Bring me their tendrils so I know how many you've killed.", objectives = "Fahssn at the Spawning Glen in Zangarmarsh wants you to bring him 6 Bog Lord Tendrils.", progress = "How's the bog lord slaying going?  Teach those brutes not to come into sporeling territory!", completion = "You made it back alive!  I'll let the other sporelings know about you!  <name>, the giant slayer!" }
WordHunterWoW_QuestEN[9744] = { title = "More Tendrils!", description = "", objectives = "You killed many giants, but there are still many more left.  And they're still attacking our spore sacs!", progress = "You killed many giants, but there are still many more left.  And they're still attacking our spore sacs!", completion = "Unbelievable!  It would take hundreds of sporelings to slay as many giants as you have.  I will make sure to let everyone know of your feats!\n\n<This quest is repeatable up to friendly reputation.>" }
WordHunterWoW_QuestEN[9745] = { title = "<DEPRECATED>Suppressing the Flame", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[9746] = { title = "Limits of Physical Exhaustion", description = "Victory is close at hand, {name}. With the discovery of the sun gate, it won't be long until their supply lines are completely closed off. Now is the time to strike at their numbers.\n\nTo the west you will find numerous Sunhawk camps. The Sunhawk pyromancers and defenders occupy the vast majority of the area. Find them, kill them and return to me.", objectives = "Vindicator Aesom at Blood Watch wants you to slay 10 Sunhawk Pyromancers and 10 Sunhawk Defenders.", progress = "Their leader can't hide from us forever. We will systematically eliminate every possible hiding place until Sironas is found.", completion = "This will surely soften up their defenses and make them think twice before rushing foolishly into our ranks!" }
WordHunterWoW_QuestEN[9747] = { title = "The Umbrafen Tribe", description = "The naga are terrible, yes.  But even more terrible are the traitor tribes of Broken and Lost Ones that helped them!\n\nThe worst of all are the Lost Ones of the Umbrafen tribe; they use dark magic to trap and enslave others. They're especially cruel to escaped slaves and would slit my throat if I left the refuge even for a day.\n\nTravel to Umbrafen Village south of here and kill them and their leader, Kataru.  Until then I will fear for my life every single day.", objectives = "Ikeyen at the Cenarion Refuge wants you to travel to Umbrafen Village and slay Kataru, 8 Umbrafen Seers, 6 Umbrafen Witchdoctors and 6 Umbrafen Oracles.", completion = "Thank you, <name>.  I will finally sleep comfortably at night.  Were I not so old and weakened I would deal with my own enemies.\n\nTake this gold.  It is not much, but your kindness cannot go unpaid." }
WordHunterWoW_QuestEN[9748] = { title = "Don't Drink the Water", description = "Our shaman claim that the elements of water have become greatly agitated by the pollution of the water source. We know that the Exodar's power core is lodged into the mountain to the west. It must be leaking volatile fluids into the water supply! I need you to get me more information.\n\n<Aesom points to a flask and nods.>\n\nYou are to take this flask and follow the beach north until you reach the area where the rivers of Bloodmyst drain into the ocean. Take a sample from that location and return to me.", objectives = "Vindicator Aesom at Blood Watch wants you to use the Water Sample Flask to get a Bloodmyst Water Sample.", progress = "Don't drink the water, <name>!", completion = "As I suspected, the water has turned red due to contamination from leaking core fluid.\n\nI hope you didn't swim in any of that contaminated water." }
WordHunterWoW_QuestEN[9749] = { title = "They're Alive! Maybe...", description = "It was a bloody mess, {name}. We were ambushed by a large pack of these spiders. Their progenitor descended upon us with incredible speed and wrapped us up in cocoons.\n\nAfter we were webbed, she began to lay eggs near us. We were to be food for her young! FOOD!\n\nI managed to cut my way out and escape but I will not leave the others behind. So far I've been unsuccessful in nearing the pass. Would you lend a hand?\n\nDestroy those cocoons! Hopefully some of our team is still alive!\n", objectives = "Researcher Cornelius has asked that you free 5 Expedition Researchers." }
WordHunterWoW_QuestEN[9750] = { title = "UNUSED Urgent Delivery", description = "", objectives = "" }
WordHunterWoW_QuestEN[9751] = { title = "The Bloodcurse Legacy", description = "Last night, Edward Hanes, captain of the ship 'Lost Hope', appeared before me in my tent. The same Edward Hanes that died of scurvy 20 years ago.\n\nThis apparition told me a tale that made my heart tremble. A tale that I need you to hear and a mission that I need you to accomplish. Will you do it? Will you seek out Edward on Wyrmscar Island, northeast of Blood Watch?\n", objectives = "Admiral Odesyus has asked that you find and speak with Captain Edward Hanes.", completion = "Have you heard of the bloodcurse, landlubber? No, of course you haven't. The bloodcurse is what sunk all these ships. The spoiled, desecrated part of the water here is known as Bloodcursed Reef - a part of the world you never want to visit. I've been here myself for 20 years.\n\nScurvy my foot! I died on these wild shores as food for the dragons... Ah, but that's another story for another time. Right now, we have to help the poor souls that are trapped in that reef." }
WordHunterWoW_QuestEN[9752] = { title = "Escape from Umbrafen", description = "You must help me get out of here!\n\nI was gathering herbs nearby when a handful of these little savages abducted me.  I tried to fight them off, but there were too many of them.\n\nHelp me return to the Cenarion Refuge and away from these cruel wretches and their vile magic!", objectives = "Escort Kayra Longmane to the Cenarion Refuge in Zangarmarsh. Report to Ysiel Windsinger when you've completed this task.", completion = "You rescued one of my druids.  We could never repay you, <name>.\n\nYou have my thanks as well as that of the expedition." }
WordHunterWoW_QuestEN[9753] = { title = "What We Know...", description = "We've learned much of our enemies in recent days. The blood elves are led by a being known as Sironas and plot to destroy us. Ultimately, they seek to enslave O'ros and regain control of the Exodar.\n\nLight be praised, we have stopped their supply line by destroying the sun gate. Unfortunately, they continue to use the contaminant of the Vector Coil to poison the land, using the mutagenic properties of the fallout to their advantage.\n\nWith this knowledge, Admetius has devised a plan. Seek him out.", objectives = "Speak to Exarch Admetius at Blood Watch.", completion = "I am in need of your services, <name>. I have a plan to topple the entire Sunhawk army, but before we can progress, we need to gather some vital information.\n\nWe need to identify the weaknesses in their primary defense. Unfortunately, we have been unable to get close enough to the Vector Coil to gauge their defenses. If we could get the prisoner to talk, we could get the information that we needed to break through the line and destroy the Vector Coil.\n\nYou heard me, I want to blow the damned thing up." }
WordHunterWoW_QuestEN[9756] = { title = "What We Don't Know...", description = "Our attempts at interrogation have failed miserably, {name}. Torture is - of course - out of the question. What we need is a {race} on the inside.\n\nI can cast a spell upon you that would make you appear blood elf and adjust your language. Through subterfuge, we may be able to get the information we need out of the captured agent.\n\nUnder this guise, I want you to get whatever information you can out of the prisoner.\n\nAnd {name}, do not leave Blood Watch while disguised as the spell will fail.", objectives = "Speak to a Captured Sunhawk Agent at Blood Watch and recover Sunhawk Information. Return to Exarch Admetius when the task is complete.", progress = "Do not return until you have succeeded!", completion = "A-ha! Well done, <name>. Well done, indeed. Are you ready to eradicate the blood elf menace from our island forever?" }
WordHunterWoW_QuestEN[9757] = { title = "Seek Huntress Kella Nightbow", description = "Huntress Kella Nightbow seeks the audience of all eligible hunters.  She is the one to teach you the skill of taming wild beasts, a lesson you should learn above all else at this point in your training.\n\nKella can be found near Valaar's Berth, the docks west of the Exodar.Upon completion of this quest you will gain:", objectives = "Speak with Huntress Kella Nightbow near Valaar's Berth.Huntress Kella Nightbow seeks the audience of all eligible hunters. She is the one to teach you the skill of taming wild beasts, a lesson you should learn above all else at this point in your training.\n\nKella can be found near Valaar's Berth, the docks west of the Exodar.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[9758] = { title = "Return to Arcanist Vandril", description = "Now my friend, if you would be so kind as to return to Arcanist Vandril, I know that he is very anxious to send you out on your first mission here in the Ghostlands.\n\nWe're counting on you, {name}.  Don't let us down.", objectives = "Return to Arcanist Vandril at Tranquillien in the Ghostlands.", completion = "Oh good, there you are!  And just in time... there is much to be done!" }
WordHunterWoW_QuestEN[9759] = { title = "Ending Their World", description = "Don't accept this assignment if you value your life. You see that gigantic power core jutting out of the mountain side over yonder? Whoever takes on this burden will need to fight their way through that mountain, battling an army of Sunhawks while protecting me as I rig the core up for demolition. Sironas the eredar is somewhere up there as well.\n\nI won't think less of you if you just walk away, {name}.\n\nBut maybe you're the one - the one to destroy the Vector Coil and take down Sironas. Well, are you?", objectives = "Follow and protect Demolitionist Legoso as he attempts to destroy the Vector Coil and slay Sironas. Return to Exarch Admetius at Blood Watch should you complete the mission.", completion = "You have saved the whole of Bloodmyst and Azuremyst, securing the <race> way of life on Azeroth, <name>! For this, there can be no amount of thanks, no reward, nothing large enough in scope to truly express our appreciation.\n\nYet, there are still so many that were left behind on Draenor who cannot be here for this historic event. You must find your way back. Find your way back to the Outland, Hero of Argus. Bring our people home. Home to the land that you saved. Home to Azeroth..." }
WordHunterWoW_QuestEN[9760] = { title = "Vindicator's Rest", description = "I would not ask you to single-handedly bear the burden of destroying the Vector Coil and slaying Sironas, {name}; however, I believe that you can be of some help in clearing the way for others that might take on such a dangerous assignment.\n\nTake the road going north out of Blood Watch and follow it until you get to the fork. Once there, take the left road and follow it until you see Vindicator's Rest - it will be slightly west of the road itself. Corin will be waiting for you.", objectives = "Speak with Vindicator Corin at Vindicator's Rest on Bloodmyst Isle.", completion = "Perhaps you will be the one to deliver our people into a new age of prosperity and peace." }
WordHunterWoW_QuestEN[9761] = { title = "Clearing the Way", description = "Only the most battle hardened, noble and positively fearless will submit to Legoso's mission. The exarch will not order any agent of the Hand to take on the task of destroying the Vector Coil and dispatching Sironas. He refuses to send any draenei to their death - which is what the mission is: suicide...\n\n<Corin sighs.>\n\nMy job is to soften up the Sunhawk defenses. You are to slay Sunhawks near the Vector Coil and keep the path clear for our champion - whoever that may be.", objectives = "Vindicator Corin at Vindicator's Rest wants you to slay 8 Sunhawk Saboteurs and 8 Sunhawk Agents.", completion = "Hopefully a hero arrives before they are able to call forth reinforcements to guard the area you just secured." }
WordHunterWoW_QuestEN[9762] = { title = "The Unwritten Prophecy", description = "", objectives = "These islands will serve as the home to thousands. Most of these people will remain here their entire lives. If you so desired, you could do the same. But that's not what you want, is it, <name>?\n\n\n\nYou will do many more great things before you pass. You must embrace your destiny and meet it head on!\n\nBefore you leave, I present you with two gifts: This tabard is worn by only the most revered of the Hand of Argus and this signet ring worn by our wisest sages. Wear them both with pride, <name>." }
WordHunterWoW_QuestEN[9763] = { title = "The Warlord's Hideout", description = "There are benefits to hiding very, very quietly at the entrance of your enemy's hideout.\n\nJust hours ago I saw a group of naga go through the stone archway on the second tunnel from the left.  I'm not well versed in their language, yet I clearly understood one word: Kalithresh.\n\nThat must be the entrance to the steam vaults, where Warlord Kalithresh has been commanding his troops from.  You must find him and stop him.  I am too weak to be of any assistance.", objectives = "Watcher Jhang wants you to find and slay Warlord Kalithresh inside Coilfang Reservoir.", completion = "Our biggest enemy in the region is finally dead.  You've done the expedition a great favor, <name>.\n\nWe shall be forever in your debt." }
WordHunterWoW_QuestEN[9764] = { title = "Orders from Lady Vashj", description = "This letter contains detailed orders to the Coilfang naga operating the steam vaults.  It warns of the arrival of Cenarion druids into the region and orders them to be slain on sight.  The rate of water redirection from other lakes into Coilfang Reservoir is to be doubled.  The orders bear the seal of the infamous Lady Vashj.\n\nThis letter would be of great interest to the druids of the Cenarion Expedition.  Take it to their leader, Ysiel Windsinger.", objectives = "Deliver the Orders from Lady Vashj to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", progress = "What's that you have there, <name>?", completion = "Vashj!\n\nThis is much more than we bargained for.  Our small victories here and there against the naga mean nothing.\n\nIf Lady Vashj is involved in this, then forces much greater than us are at work. \n\nYou've done well in bringing this to us, <name>.  Now, we must prepare for war." }
WordHunterWoW_QuestEN[9765] = { title = "Preparing for War", description = "The Cenarion Expedition began as a peaceful venture, yet we now face the prospect of all out war with the naga.\n\nWe have many among us who are willing to fight but are ill equipped.  Bring me the naga's own weapons so that we may reforge them into glaives and arrowheads.\n\nOnly the best armaments will have materials useful to us, <name>.  You will have to seek out the naga of Coilfang Reservoir.", objectives = "Obtain Coilfang Armaments from naga at Coilfang Reservoir and return them to Ysiel Windsinger at the Cenarion Refuge in Zangarmarsh.", progress = "Have you obtained the armaments I seek, <name>?", completion = "These will do perfectly, <name>.  Bring any more armaments you find.  Our need is great and our resources are scarce." }
WordHunterWoW_QuestEN[9766] = { title = "Coilfang Armaments", description = "", objectives = "We will forge the naga's own steel into weapons to use against them.  Bring me all the armaments you manage to salvage from Coilfang Reservoir.", progress = "We will forge the naga's own steel into weapons to use against them.  Bring me all the armaments you manage to salvage from Coilfang Reservoir.", completion = "Excellent work, <name>.  The naga will learn not to underestimate us." }
WordHunterWoW_QuestEN[9767] = { title = "Know Your Enemy", description = "Defeating an enemy requires more than superior power or numbers.  Victory often hinges on knowledge of an opponent's weaknesses, the anticipation of their plans or the recognition of a behavior pattern.\n\nWe know much about the naga, yet much of their magical practices remain foreign to us.\n\nI seek to learn of the Hydromancy used by the naga of Coilfang Reservoir.  Bring me one of their spellbooks so I may learn more about it.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Obtain a Coilfang Spellbook from the naga inside of Coilfang Reservoir and bring it to Ashyen at the Cenarion Refuge in Zangarmarsh." }
WordHunterWoW_QuestEN[9768] = { title = "Coilfang Spellbooks", description = "", objectives = "" }
WordHunterWoW_QuestEN[9769] = { title = "There's No Explanation for Fashion", description = "<Magasha chuckles softly to herself.>\n\nI bet if they knew they were wearing bug parts, the fashion trend would end very quickly.\n\nWe first started killing the bugs 'round here 'cause they were getting in the way of our construction. Some enterprising merchant stops here, spends the night, and next thing you know he's buyin' up all the bug wings we have!\n\nSays he makes clothes out of 'em. I be stickin' to my armor, thanks. But if you gather the wings of any of the fireflies, I'll gladly buy 'em.", objectives = "Bring 8 Diaphanous Wings from any species of Zangarmarsh fireflies to Magasha in Swamprat Post.", progress = "What's that, there? Been bitten by the wing bug, have ya?\n\n<Magasha chuckles at her own joke.>", completion = "These be fine ones, <name>. Here's your payment.\n\n\n\nNope, not my thing, but who'm I to complain?\n\n\n\nCoin speaks." }
WordHunterWoW_QuestEN[9770] = { title = "Menacing Marshfangs", description = "Sometimes I wish Denjai had sent a shaman with us, or at least given us a totem to keep the marshfang rippers at bay.\n\nThe whole place is crawling with the pests! It's just not right. Shouldn't something be eating these despicable things?\n\nWe've all been taking turns playing exterminator. You showed up at just the right time, {name}. Congratulations! Now get out there and mop up some marshfangs!", objectives = "Reavij at Swamprat Post wants you to kill 10 Marshfang Rippers.", completion = "Had your fill already?\n\n<Reavij laughs.>\n\nThere's a reason why our visitors don't stay long.\n\nIf I had a choice, I'd find a more agreeable spot for the post, but I'll take marshfangs over Denjai's temper any day." }
WordHunterWoW_QuestEN[9771] = { title = "Searching for Scout Jyoba", description = "Now that you're familiar with the terrain, I'd like to ask your help with something else. The Dead Mire, we've taken to calling the area to the northwest, is an eerie place. No one has ever reported seeing anything alive there, but they didn't stay for very long, either.\n\nScout Jyoba volunteered to investigate the area and report on his findings. He left the post three days ago and hasn't returned. It's not like him to be gone that long without sending some kind of report. Will you search for him, {name}?", objectives = "Search for Scout Jyoba at the Dead Mire in Zangarmarsh.", completion = "The battered corpse matches Zurai's description perfectly. Whatever killed the scout appears to have taken him by surprise, as his weapon is sheathed and the contents of a small inkwell stain the nearby ground." }
WordHunterWoW_QuestEN[9772] = { title = "Jyoba's Report", description = "Flecks of withered fungus dot the body of Scout Jyoba. Whatever killed him must've been made of the same dying fungus as the giant wilting mushrooms of the Dead Mire. Perhaps one of the withered giants caught him by surprise as he sat writing his report.\n\nWithout the text of the report, it's nearly impossible to tell what the scout discovered. If the report can be found, it should be returned to Zurai.", objectives = "Retrieve Scout Jyoba's Report from the Withered Giants and return it to Zurai at Swamprat Post.", progress = "You're back, but Jyoba's not with you. What became of him?", completion = "<Zurai accepts the report from you and glances over it.>\n\nMuch of this is information we already know. Everything in the area seems to be dried or wilting, but here's something new.\n\nHe says the fungal giants seem to have gone berserk from the lack of moisture. From your description, that must be what killed him.\n\nI'll instruct my men to avoid the area. We can't afford any more casualties." }
WordHunterWoW_QuestEN[9773] = { title = "No More Mushrooms!", description = "Mushroom soup, mushroom stew, mushroom sauce!\n\nMushroom, mushroom, mushroom! It's all there is to eat around here. If you say you're hungry, the cook hands you an axe and tells you to go chop down your dinner!\n\nWell, I'm tired of mushrooms. I've seen fish in the lakes around here. Sure, they look like a nasty piece of work, but they've got to be better than mushrooms!\n\nHow much will it cost me to hire you to bring me my first decent meal in weeks?", objectives = "Gather 8 Eel Filets from Umbrafen Eels and bring them to Magasha at Swamprat Post.", progress = "Tell me you haven't come back empty-handed. <name>.", completion = "Finally, a break from the monotony of mushrooms! If you didn't smell like fish, I'd hug you.\n\nLet's see how jealous the others get when they smell the meat cooking over the fire." }
WordHunterWoW_QuestEN[9774] = { title = "Thick Hydra Scales", description = "Reavij was wise to bring leather armor. This swamp will render my mail useless before long.\n\nI've been replacing the scales bit by bit as I'm able. The hydra in the marsh have thick, protective scales that stand up well to the dampness of their home.\n\nFinding suitable ones is a tedious process, though. All too often, the best scales are torn or worn too thin for use in armor. Bring me any good ones that you might get from the hydra in the larger lakes.", objectives = "Zurai at Swamprat Post wants you to bring him 12 Thick Hydra Scales.", progress = "I see you smirking. Yes, my armor's going to look a bit odd until I've replaced all the old metal, but it's better this than unprotected.", completion = "Thank you, <name>. Every little bit helps.\n\nI've still got a long way to go, but let's face it, what else am I going to do between patrols?" }
WordHunterWoW_QuestEN[9775] = { title = "Report to Shadow Hunter Denjai", description = "Shadow Hunter Denjai will no doubt expect to receive a report about my progress in establishing our outpost. I've prepared a short summary of what we've accomplished here already, but with the loss of Scout Jyoba, I can't spare a runner to take the report to Denjai's base of Zabra'jin to the west.\n\nIf you're headed that way, would you mind bringing this to him? Shadow Hunter Denjai can be a little intimidating at first, but once you get used to him, he's not so bad.", objectives = "Bring Zurai's Report to Shadow Hunter Denjai at Zabra'jin in Zangarmarsh.", progress = "You don't look like one of my men. Speak your piece, <race>.", completion = "Why didn't you say you had a report from Zurai? I've been waiting to hear from him.\n\nI sent him out there to give us a presence on the eastern border, not sit on his hands. Let's see what he has to say." }
WordHunterWoW_QuestEN[9776] = { title = "The Orebor Harborage", description = "As you know, many of Telredor's inhabitants are refugees from the war that decimated the draenei. It is my goal to maintain Telredor as a safe haven for all of our allies in this struggle. There are some who desire to join us, but feel they are not yet ready.\n\nWe owe them whatever help we can provide, {name}. A group of Broken under the leadership of Ikuti have taken shelter in the ruins of an old temple to the northwest of Serpent Lake. Seek them out and extend your hand in friendship to them.", objectives = "Speak to Ikuti at the Orebor Harborage in Zangarmarsh.", completion = "If Anchorite Ahuurn counts you a friend, then you may prove trustworthy. Please forgive my wariness, <race>, but it is often all that stands between my people and death. You are welcome to shelter among us, and perhaps our mutual trust will grow." }
WordHunterWoW_QuestEN[9777] = { title = "Fulgor Spores", description = "There is little in this swamp that will burn, {race}, so we must resort to other means for lighting Telredor. Many of the creatures and plants in the marsh emit a soft glow.\n\nIt's difficult and cruel to confine the glowing creatures, so we've turned to a species of mushroom for our light source.\n\nWe pick and cultivate the fulgor mushroom here, but our needs require us to gather new crops occasionally. The small green mushrooms often grow at the base of larger ones near Telredor.", objectives = "Bring 6 Fulgor Spores to Ruam at Telredor.", progress = "From the looks of things, we'll need to replenish our spores soon.", completion = "These are good spores and they should keep us going for quite some time. Thank you for helping us to replenish our supplies, <name>." }
WordHunterWoW_QuestEN[9778] = { title = "Warden Hamoot", description = "Before you leave Cenarion Refuge, make sure you speak with Warden Hamoot.  He's in charge of the expedition's security.\n\nHe would never forgive me if I didn't send a seasoned adventurer like you his way.", objectives = "Report to Warden Hamoot at the Cenarion Refuge in Zangarmarsh.", completion = "Ysiel sent you?  Of course I can use someone like you!  We're always in need of a little muscle." }
WordHunterWoW_QuestEN[9779] = { title = "Intercepting the Message", description = "It is good to see you again, {name}. I have a quandary that you might be able to solve.\n\nOur agents situated behind Sunhawk lines have reported seeing Sunhawk soldiers parsing an unusual document.\n\nUnfortunately, we have been unsuccessful in acquiring a copy of the document for ourselves. I need you to go out in the field and try to recover the document. I am certain that if you apply enough pressure, a Sunhawk agent will turn over the information we seek. I leave the use of force to your discretion.", objectives = "Kill Sunhawk elves until you find the Sunhawk Missive, then return it to Vindicator Boros at Blood Watch.", progress = "Back so soon? Have you found the missive?", completion = "<Vindicator Boros eyes the document.>\n\nThis is in Thalassian. Fortunately, I know just the person that can translate it..." }
WordHunterWoW_QuestEN[9780] = { title = "Umbrafen Eel Filets", description = "It's good to see another fresh face here. When Haalrun and I first came to Telredor, we were the only outsiders, but that seems like a lifetime ago.\n\nStill, we try to welcome newcomers and ensure that there's always enough food and supplies. We can never fully repay the kindness of the Telredor anchorites, but we can follow their example and extend it to others.\n\nIf you would like to help, the nearby lakes are populated with a fish called the Umbrafen eel, whose meat is a staple of our diet.", objectives = "Noraani at Telredor wants you to bring her 8 Eel Filets.", progress = "Have you any fish to contribute to our stores?", completion = "Thank you for your help, <name>. Your generosity will not be forgotten." }
WordHunterWoW_QuestEN[9781] = { title = "Too Many Mouths to Feed", description = "On my last hunting trip, I caught sight of a new outpost being built by a group of trolls. No doubt they've begun hunting these lands, too.\n\nIf they establish a permanent presence out here, the competition for food will be fierce. We cannot take direct action against them without provocation, but we can remove some of the natural competition for food.\n\nFor each mire hydra you kill, that's three fewer mouths to feed!", objectives = "Kill 10 Mire Hydra and return to Haalrun at Telredor.", completion = "Well done. That should ease the demand on the food supply around here for the immediate future, although we're going to need to find new sources of food. Fish and mushrooms suffice, but variety can never be underestimated." }
WordHunterWoW_QuestEN[9782] = { title = "The Dead Mire", description = "I have lived among the anchorites of Telredor for some time, {name}, and in that time I've come to know the marsh quite well. Recently, I've started to notice a disturbing change in the land to the northeast.\n\nVirtually all life there has begun to wither and die, seemingly without explanation. I have a few ideas as to what might be happening, but they are little more than speculation. If you were to bring me a sample of the soil in that area, I may be able to get to the bottom of this mystery.", objectives = "Bring a Dead Mire Soil Sample to Vindicator Idaar at Telredor.", progress = "Were you able to get a sample of the soil in the Dead Mire?", completion = "Hmm... The soil seems to be depleted, so it can't be the cause of the problem, as I'd thought. What's the common link here? Why is everything suddenly dying?" }
WordHunterWoW_QuestEN[9783] = { title = "An Unnatural Drought", description = "The soil sample you brought me is nearly devoid of moisture, {name}. If the soil itself is losing moisture, then the creatures that live in the Dead Mire must be suffering terribly.\n\nI've seen what happens when the region's fungal giants begin to wither and die. The pain drives them mad, causing them to attack anything in their path.\n\nThese creatures have no idea what's happening to them. They're beyond our ability to save, so the best we can do is to end their suffering.", objectives = "Vindicator Idaar at Telredor wants you to kill 12 Withered Giants.", completion = "Thank you for helping with this difficult task, <name>. Our work in the Dead Mire is not yet done, but now our efforts will focus on doing what we can to restore balance to the area." }
WordHunterWoW_QuestEN[9784] = { title = "Identify Plant Parts", description = "", objectives = "I could still use some more plant parts.  With the lakes losing their water, I've a feeling the number of invasive species is on the rise.  I need more numbers to back up my theory, however.", progress = "I could still use some more plant parts.  With the lakes losing their water, I've a feeling the number of invasive species is on the rise.  I need more numbers to back up my theory, however.", completion = "Excellent.  Keep bringing me more plant parts if you find any.\n\n<This quest is repeatable up to Honored reputation.>" }
WordHunterWoW_QuestEN[9785] = { title = "Blessings of the Ancients", description = "You've earned the trust of the Cenarion Expedition, {name}.  It is time you spoke to the ancients allied with our cause, Ashyen and Keleth, and asked for their blessing.\n\nCarrying the mark of an ancient will fill you with great power.  These boons will become more powerful as your renown among us increases.\n\nGo, {name}, and ask the ancients for their blessing. ", objectives = "Windcaller Blackhoof wants you to speak to the ancients Ashyen and Keleth at Cenarion Refuge and obtain their blessings.", completion = "You've returned.  Did you receive the ancients' blessings?" }
WordHunterWoW_QuestEN[9786] = { title = "The Boha'mu Ruins", description = "Before my people were decimated by the orcs, Telredor served as a retreat for draenei anchorites and spiritualists. A small order of anchorites and vindicators maintained a number of shrines in this region.\n\nDuring the war, we lost contact with the anchorites assigned to the shrines, particularly the Boha'mu temple to the southwest. I've heard reports that a tribe of Lost Ones has settled in the area and may even be using the ruins. Visit the Boha'mu Ruins and tell me of what you find there.", objectives = "Anchorite Ahuurn at Telredor wants you to explore the Boha'mu Ruins.", progress = "Have you examined the Boha'mu Ruins? Can you imagine what they were like in their full splendor?", completion = "So, the Feralfen Lost Ones have taken over the ruins? Most intriguing. They must remember something of their heritage and the significance of the site. We must learn more, <name>. This temple could hold the key to redeeming the Lost Ones and reuniting the many threads of draenei." }
WordHunterWoW_QuestEN[9787] = { title = "Idols of the Feralfen", description = "From what you've told me about your observations at the Boha'mu Ruins, it seems this tribe of Lost Ones has reverted to the worship of animal spirits. Before we can approach them, we must know more of their beliefs.\n\nReturn to Feralfen Village and discreetly gather some of their idols so that I may study them. Try to avoid angering them, {name}, as it may hurt our chances of making contact with them.", objectives = "Gather 6 Feralfen Idols and return them to Anchorite Ahuurn at Telredor.", progress = "Do you have the idols?", completion = "These should be more than sufficient, <name>. They seem to be fixated on birds, which is odd, because there aren't any bird species native to Zangarmarsh. What could this mean?\n\nCould they have encountered the arakkoa? To a shamanistic people, they might seem like the embodiment of a powerful bird spirit." }
WordHunterWoW_QuestEN[9788] = { title = "A Damp, Dark Place", description = "Soon after I escaped the Umbrafen tribe, I holed up in a cave south of their village.  Little did I know that the cave was being fought over by marsh beasts and spore men!\n\nI had to leave in a hurry and left behind a box containing my only worldly possessions.\n\nAfter managing to sneak out of Umbrafen with my belongings it was terrible irony that I would lose them so soon after.  If you're willing to bring them back to me I'll give you one of my very own personal items.  What do you say, {name}?", objectives = "Look for Ikeyen's Belongings inside a cave south of Umbrafen. Return them to Ikeyen at Cenarion Refuge in Zangarmarsh.", progress = "Did you find my belongings, <name>?  The cave is not far from Umbrafen, near the border with Nagrand.", completion = "My things!  They're all here!\n\nI thank you, <name>.  As promised, I'll let you pick one of the items for yourself.  I don't have much to offer, but my people have always shared what little we have." }
WordHunterWoW_QuestEN[9789] = { title = "Clefthoof Mastery", description = "You want to earn a place in this safari?  You'll have to prove yourself.\n\nI don't care what you've hunted before, you haven't hunted until you hunt what we hunt here.  Start with the clefthoof if you're man enough.\n\nI know that I've seen them in the immediate area around the safari and also close by to the south.", objectives = "Hunt down 12 Clefthoof and return to Hemet Nesingwary at Nesingwary's Safari in Nagrand to prove yourself.", completion = "A fair start.  But that's just the beginning.\n\nThe lesser clefthoof prove nothing.  Let's move you up to a bigger challenge." }
WordHunterWoW_QuestEN[9790] = { title = "Diaphanous Wings", description = "Living in such a remote location has taught us to make use of everything available. Of course, you have to learn to stop thinking about where some of these materials come from first.\n\nI've found that the wings of the umbraglow stingers are very helpful for waterproofing. They're strong, thin, and flexible.\n\n<Haalrun chuckles.>\n\nI see the look on your face. Like I said, it takes time to get used to the idea. If you're going to be out and about, would you mind bringing me some of the wings?", objectives = "Haalrun at Telredor wants you to bring him 8 Diaphanous Wings from any of the firefly species in Zangarmarsh.", progress = "Did you manage to gather any diaphanous wings?", completion = "Thank you, <name>.\n\n\n\nAt least you don't have to clean them. That's the worst job of the lot, but once it's done, you'd never know they were attached to a giant insect." }
WordHunterWoW_QuestEN[9791] = { title = "Menacing Marshfangs", description = "During the orcs' war against my people, gatherers rarely left Telredor for fear of being attacked or captured. Now, we venture out more often, but the marsh is no less perilous.\n\nIt seems that the nether rays have grown bolder in recent months. I don't know if it has something to do with more competition for their normal prey, but they've been attacking our foraging parties on a regular basis. If we can thin their ranks in the area around Telredor, perhaps they would learn to leave us alone.", objectives = "Kill 10 Marshfang Rippers and return to Noraani at Telredor.", completion = "Thank you for your help in clearing out some of the marshfang rippers, <name>. If they had any intelligence, perhaps they'd learn that it's best to live and let live.\n\n\n\nGiant, overgrown bugs with intelligence. I wonder what that would be like..." }
WordHunterWoW_QuestEN[9792] = { title = "A Message to Telaar", description = "You've been honorable in our dealings, {name}, at a time when trust is hard to win among my people.\n\nA large group of my brethren have made their home in the old draenei city of Telaar in Nagrand, to the south. To reach Telaar, take the road south into Nagrand, then continue southeast until you find yourself in the cliffs east of Oshu'gun.\n\nAnyone who has aided us, as you have, would be welcome among the people of Telaar.\n\nSeek out Warden Moi'bff Jill and tell him you have earned my trust.", objectives = "Speak with Warden Moi'bff Jill at Telaar in Nagrand.", completion = "Ikuti is like a brother to me. A friend of his is a friend of mine. You are welcome here, <name>, and you have our thanks for assisting our people." }
WordHunterWoW_QuestEN[9793] = { title = "The Fate of Tuurem", description = "Prophet Velen's search for allies has emboldened those draenei remaining in Outland to begin a search of their own. The Legion's war on my people drove us from our cities and temples, but they have not destroyed the traces of our civilization.\n\nTuurem, my former home in the Terokkar Forest, was one of the first cities overrun by the orcs. It's been too long since I've received news of its status. Take this letter to Andarl in the Allerian Stronghold within Terokkar and see what you can find out.", objectives = "Take Vindicator Idaar's Letter to Andarl at the Allerian Stronghold in Terokkar Forest.", progress = "How may I help you?", completion = "Hmm... I remember hearing our scouts speak of the ruins of a draenei settlement in the forest's northern reaches. I don't know much about the ruins, personally, but you're welcome to talk to some of the scouts." }
WordHunterWoW_QuestEN[9794] = { title = "No Time for Curiosity", description = "{name}, I have a favor to ask of you. Normally, I would do this myself, but my hands are already beyond full.\n\nI have an associate named Kialon at Sylvanaar in the Blade's Edge Mountains to the north. He's expecting to hear from me in the near future, although I suspect he won't like what I have to say.\n\nIf you would deliver my response to him, you would have my gratitude. I must insist, and this is very important, that you not attempt to read the letter. It is for Kialon's eyes alone.", objectives = "Deliver Timothy's Letter to Kialon at Sylvanaar in the Blade's Edge Mountains.", progress = "<Kialon eyes you suspiciously.>\n\nI don't know you, <race>. Do you have business with me?", completion = "So you've brought Timothy's response?\n\n<Kialon pauses a moment to read the letter, then laughs.>\n\nHe's got everything under control, he says. Doesn't need help, he says. I could've predicted that!\n\nSome people never change. Look, he even took the time to correct my spelling.\n\n<Kialon lets out a half-hearted sigh.>\n\nI shouldn't have sent the letter. I forgot. The specialist always has the situation under control. Always." }
WordHunterWoW_QuestEN[9795] = { title = "The Ogre Threat", description = "As if the naga and their allies weren't enough, the ogres are extending their reach in the marsh. They've already conquered most of the area to the northwest and there isn't much of a buffer left.\n\nFor each one we kill, several more take their place. I'm not sure how long we'll be able to hold Zabra'jin once they decide to attack. Make your way north into the mountains, to the orcish stronghold of Thunderlord Stronghold and let Nekthar know of our plight. Any help he can spare would be most welcome.", objectives = "Travel to Thunderlord Stronghold in the Blade's Edge Mountains and speak with Nekthar.", completion = "Denjai seeks help?  I'd send him reinforcements, but we're spread thin here as it is.  We've got trouble of our own with the ogres up here.\n\nWhen I can, I'll give him what information we have on the local ogre tribes and their tactics.  Perhaps if he can survive long enough, we'll be able to launch a two-pronged assault on the vile scum." }
WordHunterWoW_QuestEN[9796] = { title = "News from Zangarmarsh", description = "Shadow Hunter Denjai isn't the only one expecting a report from me. Mokasa at Stonebreaker Hold in Terokkar is eager to hear of our progress, especially since most of her messengers travel through here.\n\nShe asked me to send word once Swamprat Post was completed. If you wouldn't mind delivering the news, I'd be very grateful. We may be up and running, but there is still much to be done.\n\nTo get to Stonebreaker Hold, follow the road south out of Zangarmarsh, into Terokkar Forest and beyond Tuurem.", objectives = "Speak with Mokasa at Stonebreaker Hold in Terokkar Forest.", completion = "It's about time he got that outpost up and running. We've lost far too many runners to Alliance outriders." }
WordHunterWoW_QuestEN[9797] = { title = "Reinforcements for Garadar", description = "<Still catching his breath, the messenger gestures for you to sit.>\n\nThey may not survive, {race}! Get to Garadar as quickly as your legs will carry you.\n\n<In response to your blank stare, the messenger elaborates.>\n\nThe home of the Mag'har, lies to the south, in Nagrand. Take the southern road out of the marsh, then turn east at the first fork and look for a large settlement on the lake.\n\nFind our commander, Captain Kroghan, there and offer him what assistance you can. Garadar must not fall!", objectives = "Speak with Captain Kroghan at Garadar in Nagrand.", completion = "<Even though he endeavors to hide it, a look of relief spreads over Kroghan's face.>\n\nIt's about time you got here! Granted, you're not an army, but any able-bodied <race> than can wield a weapon or chant a spell is welcome here. The people of Garadar are kin to all the Horde and we are proud to shed our blood in their defense." }
WordHunterWoW_QuestEN[9798] = { title = "Blood Elf Plans", description = "These plans seem important.  You should take them to Vindicator Aldar at the crash site.", objectives = "Take the Blood Elf Plans to Vindicator Aldar at the Crash Site in Ammen Vale.", progress = "What have you got there?", completion = "Here, let me read those plans.\n\nThe blood elves have followed us here?  They are evil to the core and should be wiped from existence!\n\n<The vindicator takes a moment to regain his composure.>\n\nI apologize, that was uncalled for.  We are indebted to you for uncovering this information, <name>." }
WordHunterWoW_QuestEN[9799] = { title = "Botanical Legwork", description = "The Ammen Fields to the west are the primary breeding ground of the local lasher population. With the corruption of the water table from the nearby lake, Botanist Taerix is worried that the lashers will not be able to repopulate themselves once we've cleansed the lake.\n\nGo to the Ammen Fields and pick some of the corrupted flowers for me so that I might take a look at them and see what can be done. You should be able to identify them by their uncharacteristic red petals.", objectives = "Gather 3 Corrupted Flowers and return them to Apprentice Vishael at the Crash Site in Ammen Vale.", progress = "Hello, <class>.  Do you have those flowers yet?", completion = "These look like fine specimens.  Thank you for performing the field work.  Once I can find the time to analyze these, I should be able to tell what it will take to restore the fields." }
WordHunterWoW_QuestEN[9800] = { title = "A Rare Bean", description = "You are ill-equipped to face the restless elements of Nagrand. Before you can help the Earthen Ring, you must help yourself.\n\nTo the west you will find dung heaps left behind by the wildlife of Nagrand. You must search the dung for the digested remnants of the Nagrand caracoli. From this bean I am able to make a tablet that will aid you in your battle against the restless forces of nature.\n\nReturn to me when you have collected no less than two fists worth of caracoli... Ogre sized fists.", objectives = "Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to bring him 8 Digested Caracoli.", progress = "<Elementalist Lo'ap makes two fists and shakes his head in disapproval.>\n\nOgre sized...", completion = "Please do not wash yourself in the sacred waters of the Throne.\n\n<Elementalist Lo'ap holds a prepared caracoli tablet up.>\n\nYou place this under your tongue and allow it ample time to dissolve. Once it has dissolved, you will be able to breathe water as if it were air." }
WordHunterWoW_QuestEN[9801] = { title = "Gathering the Reagents", description = "I have a feeling that these Lost Ones may not respond well to a draenei, but would welcome an arakkoa. I can create a potion that will allow you to take on the form of an arakkoa for a short time. It requires a couple of reagents which cannot be stored and must be used within hours of being gathered.\n\nYou will need to bring me a handful of sporebat eyes and some fen strider tentacles. Both species dwell in the wilderness surrounding Telredor.", objectives = "Anchorite Ahuurn at Telredor wants you to bring him 4 Sporebat Eyes and 4 Fen Strider Tentacles.", progress = "Have you gathered the reagents?", completion = "These will do quite nicely. Allow me a moment to mix up the potion." }
WordHunterWoW_QuestEN[9802] = { title = "Plants of Zangarmarsh", description = "The lakes of Zangarmarsh are slowly being drained of their water.  We don't quite know why, but we do know that many plants species are in danger of becoming extinct.\n\nAs the expedition's cataloguer, it is my job to track and identify these plants so we can better understand what's happening to them.\n\nIf you'd like to help, bring me unidentified plant parts.  They can be picked right from the ground if you're an herbalist, and the indigenous creatures of the swamp may also carry plant parts on them.", objectives = "Bring 10 Unidentified Plant Parts to Lauranna Thar'well at the Cenarion Refuge in Zangarmarsh.", progress = "Did you find any plant parts, <name>?", completion = "The decrease in native species is certainly a cause for concern.  The increase in invasive species could be related to the recent disturbance in the ecosystem.  I don't have enough information to make a conclusion, yet.\n\n<Lauranna jots down some notes on a journal as she goes through the plant parts.>\n\nTake these, <name>.  They might be of some use to you.\n\nBring me any other plant parts you find.  I'll incorporate them into my statistics." }
WordHunterWoW_QuestEN[9803] = { title = "Messenger to the Feralfen", description = "The time has come for us to embrace the Feralfen and teach them that the Light has not forsaken them. Take the potion I've prepared and carry it with you to the Boha'mu Ruins.\n\nOnce you arrive at the ruins, drink the potion to assume the form of one of their bird spirits. Speak with Elder Kuruti and let him know the draenei are ready to welcome his people as our long lost brothers.", objectives = "Drink Ahuurn's Elixir while standing in the Boha'mu Ruins. Speak to Elder Kuruti while you are in the form of an arakkoa.", progress = "Did you speak with the Feralfen elder?", completion = "They refused? They are welcome to choose their own path, of course, but their choice surprises me. I would think that all the draenei, including the Broken and Lost Ones, would still remember that we're all a part of the same people.\n\nI suppose he is right about the folly of deceiving them, but still, could he not see that our intentions were friendly?" }
WordHunterWoW_QuestEN[9804] = { title = "Agitated Spirits of Skysong", description = "The disturbance in the ebb and flow of the waters of Nagrand has greatly agitated the water spirits of Skysong Lake. They have in turn begun sowing destruction throughout the waterways of the area.\n\nWatoosun of the Water has come to us in a vision and granted us permission to remedy the problem - so long as the source of the disturbance is also dealt with...\n\nWe will get to the source, but first you must deal with the problems immediate to the Throne. Destroy the agitated lake spirits and return to me.", objectives = "Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to destroy 8 Lake Spirits.", completion = "<Elementalist Lo'ap kneels in the water and says a prayer.>\n\nThe Earthen Ring takes no pride in what was done. We do what we must to heal the land." }
WordHunterWoW_QuestEN[9805] = { title = "Blessing of Incineratus", description = "The wretched Lost Ones, heretofore banished to the swamps of Zangarmarsh, are seeking to spread their filth to other parts of our world.\n\nI have sought the wisdom of the furies and gained their blessing. To stop the source, we must unleash the elements upon them!\n\nI give you living fire, plucked from the fiery essence of Incineratus himself. Travel to Windyreed Village, southeast of here, and unleash the living fire upon their huts! Let them see the fury of the elements!", objectives = "Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to destroy the Large Hut, the Western Hut, the Southern Hut and the Eastern Hut at Windyreed Village.\n\nReturn the Living Fire to Elementalist Lo'ap when the task is complete.", completion = "Your efforts have stifled the spread of pollution but other troubles have surfaced." }
WordHunterWoW_QuestEN[9806] = { title = "Fertile Spores", description = "Spore bats and marsh walkers accumulate fertile spores on their appendages from wandering around the tallstalk mushrooms in the marsh.\n\nAs you can see, we're a short people so our options for gathering these spores are limited.  Seek out the spore bats and marsh walkers and gather the fertile spores.  All of Sporeggar will be in your debt.", objectives = "Gshaff wants you to gather 6 Fertile Spores from the various Zangarmarsh Spore Bats and Marsh Walkers. Return to Gshaff at Sporeggar when you've completed this task.", progress = "You're back, <name>.  Did you obtain the fertile spores?", completion = "These are great spores, <name>!  Tallstalks are vital to rebuilding our town.  And after all the bog lord attacks we've suffered, we're in quite the short supply." }
WordHunterWoW_QuestEN[9807] = { title = "More Fertile Spores", description = "", objectives = "We can always use more fertile spores, <race>.  Tallstalks are incredibly useful mushrooms.  Being able to grow them lets us do many things with them.", progress = "We can always use more fertile spores, <race>.  Tallstalks are incredibly useful mushrooms.  Being able to grow them lets us do many things with them.", completion = "Your help is appreciated, <name>.  You will keep it up, yes?" }
WordHunterWoW_QuestEN[9808] = { title = "Glowcap Mushrooms", description = "I've seen your kind use shiny round pieces of metal to trade for things that you need.  We're not so different from you.  We use shiny round mushrooms as our currency.\n\nGlowcap mushrooms grow everywhere in the marsh, you just have to know how to pick them from the ground without wrecking them.  I'll teach you how to do it, if you promise to bring us some for our reserves.  What do you say, {name}?", objectives = "Bring 10 Glowcaps to Msshi'fn at Sporeggar in Zangarmarsh.", progress = "Did you find any glowcaps, <name>?  They're literally everywhere in the marsh.\n\nYou can spot their bright glow from far away if you pay attention.", completion = "This will help us trade with other sporelings for food and supplies.  Sporeggar thanks you, <name>!" }
WordHunterWoW_QuestEN[9809] = { title = "More Glowcaps", description = "", objectives = "I'll take more glowcaps if you have them.  Our village can always use more of them.", progress = "I'll take more glowcaps if you have them.  Our village can always use more of them.", completion = "Thank you, <name>.  As Sporeggar's elder, I must ensure my people have adequate supplies.  You make my task that much easier." }
WordHunterWoW_QuestEN[9810] = { title = "The Spirit Polluted", description = "Watoosun was able to shed the stink of corruption; but in doing so, created a twisted spirit essence. A spirit essence composed of the vilest corruption found amongst the elements!\n\nYou will find this polluted spirit of the swamp southwest of here, hidden in the depths of Lake Sunspring.\n\nFind and destroy the polluted essence of Watoosun and any corrupt offspring that it may have created.", objectives = "Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to destroy Watoosun's Polluted Essence and 8 Lake Surgers.", completion = "The elements sang of your victory the moment the disturbed essence was destroyed! The Earthen Ring thanks you and wishes for you to choose a reward." }
WordHunterWoW_QuestEN[9811] = { title = "Friend of the Sin'dorei", description = "This is the beginning of a new chapter in blood elf history, {name}.  You've helped cement the bond between my race and yours, {race}.\n\nTake the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City.  He'll be eager to hear the news.", objectives = "Take Dar'Khan's Head to Lor'themar Theron in Silvermoon City.", progress = "You seek audience with me, <class>?  I do not recall hearing of an appointment.", completion = "So you killed Dar'Khan, <race>?  Impressive.  I've a feeling my people and yours will soon get to be very good friends." }
WordHunterWoW_QuestEN[9812] = { title = "Envoy to the Horde", description = "There were doubts about our capabilities among our potential new allies.  Of what use could we be to them when perceived as unable to deal with our problems at home?\n\nThis changes everything.  No longer will our power be questioned.  We'll be able to join the Horde as equals.\n\nTake this letter to Sylvanas, ruler of the Forsaken.  She's already on our side but the news of Dar'Khan's death will be music to her ears.  Prepare for a long trip, {name}.  If all goes well she will send you to Orgrimmar.", objectives = "Bring the Letter from Lor'themar Theron to Lady Sylvanas Windrunner in Undercity, the Forsaken capital in Tirisfal Glades.", progress = "I was told a visitor from Quel'Thalas was coming. I was expecting a blood elf, to tell you the truth.\n\nWhat news do you bring?", completion = "It is done then. The foul traitor got what he deserved.\n\nYou've been of great service to the blood elves and to the Horde. Dar'khan was Thrall's excuse to deny them entry into our alliance. You've cleared the way for a new Horde, <class>.\n\nI also see that Lor'themar has additional news that will greatly improve his relations with Thrall. Excellent!" }
WordHunterWoW_QuestEN[9813] = { title = "Meeting the Orcs", description = "I haven't lost any love for my homeland or its people, as you know. I've fought tooth and nail for Silvermoon to be allowed a place beside Undercity and Orgrimmar at the negotiating table.\n\nThis should silence any opposition. Take this letter to Saurfang in Orgrimmar. As leader of the orcs, he must have a say in accepting the sin'dorei's pledge.\n\nI've added my own seal to the letter as a personal endorsement. Go northwest of the city and board the zeppelin bound for Durotar at the tower.", objectives = "Lady Sylvanas Windrunner wants you to take the Letter Sealed by Sylvanas to High Overlord Saurfang in Orgrimmar, capital of Durotar.", progress = "Yes, <class>?", completion = "<The Warchief begins to read the letter.>\n\nSo the blood elves finally took care of their little problem.  It is no surprise that it took your help as well as that of an entire Forsaken regiment to get the job done.\n\n<The Warchief breaks into laughter.>\n\nI suppose there's no stopping this.  In the end we need them just as much as they need us." }
WordHunterWoW_QuestEN[9814] = { title = "Burstcap Mushrooms, Mon!", description = "You like mushrooms, mon? There be a powerful one here in Zangarmarsh, growin' real close to Zabra'jin.\n\nYou gotta be careful, though, mon. They be callin' it the burstcap for a reason. If you be gettin' too close without takin' the proper precautions, it'll blow right up on you! Poof! Right into a cloud o' toxic spores.\n\nI been usin' them for readin' the omens, but they be almost gone now.", objectives = "Bring Witch Doctor Tor'gash 6 Burstcap Mushrooms.", progress = "Have you got the mushrooms, mon?", completion = "These be excellent, mon!\n\nI'll tell you what. Since you been a good sport and helped with the mushrooms, I'll let you in on the fun!" }
WordHunterWoW_QuestEN[9815] = { title = "Muck Diving", description = "The most affected elements of water can be found in the Halaani Basin, southwest of here, beneath the abandoned city of Halaa. While some distressed elements can be destroyed without any impact upon the environment, spawns of muck must be physically removed from the world once destroyed.\n\nYou see, muck spawns leave behind globules of tainted debris that if left untouched will spread and further contaminate the environment.\n\nDestroy these muck spawns and bring back their muck-ridden cores.", objectives = "Elementalist Lo'ap at the Throne of the Elements in Nagrand wants you to retrieve 5 Muck-ridden Cores.", progress = "Do not leave any tainted muck behind!", completion = "The Earthen Ring thanks you, <name>. The elements also give their thanks. Your continued efforts in cleansing our world are appreciated and noted." }
WordHunterWoW_QuestEN[9816] = { title = "Have You Ever Seen One of These?", description = "This marsh be missin' one thing, mon! There be no murlocs here.\n\nDon't worry, mon, I got a plan to fix the problem. See Gargle 'n' Gurgle over there? I plan to give the gift o' murlocs to the Lost Ones!\n\nTake this cage with you to Daggerfen Village an' release 'em in the northeastern cluster of huts. Now you know I can't be riskin' Gargle 'n' Gurgle with you, but I'll give you a cage full o' colorful young murlocs. Just set it on the flat rock you be findin' up there and open the door!", objectives = "Take the Murloc Cage and place it on the flat rock near Daggerfen Village.", completion = "Excellent work, mon! I do hope they had a good time!" }
WordHunterWoW_QuestEN[9817] = { title = "Leader of the Bloodscale", description = "A bounty is hereby declared by the Cenarion Expedition on Rajis Fyashe, leader of the Bloodscale naga.  The naga sorceress was last sighted at Serpent Lake, in the northern region of Zangarmarsh.\n\nThe Bloodscale are to be considered extremely dangerous and their leader is to be approached with extreme caution.\n\nThose seeking to claim the bounty are advised to report to Warden Hamoot at Cenarion Refuge.", objectives = "Slay Rajis Fyashe at Serpent Lake and return to Warden Hamoot at the Cenarion Refuge in Zangarmarsh for a reward.", completion = "I'll bet the Bloodscale will think twice about attacking expedition scouts again.  Take this as a reward, <name>.  You've earned it." }
WordHunterWoW_QuestEN[9818] = { title = "The Underneath", description = "Something rails the underneath. It beats the ground as if to punish.\n\n*Thud*\n\n<Untrag beats his chest with his fist.>\n\nIt makes this sound a hundred-thousand times. Endlessly it beats. The earth reels. It is calling out to us now.\n\nGordawg speaks to me. Gordawg knows that something forces the elements out. Something from the underneath.\n\nGo now and speak to Gordawg. No, listen to Gordawg, do not speak. Hear Gordawg...", objectives = "Communicate with Gordawg.", completion = "<Gordawg appears to be nodding at you.>\n\nSit." }
WordHunterWoW_QuestEN[9819] = { title = "The Tortured Earth", description = "Bring up the usurper. You will find him. Follow earthen path. First you put to rest tortured earth spirits. Must sleep once more.\n\n<Gordawg smashes his fist into the ground and brings up very foul smelling soil.>\n\nMust sleep!\n\n<Gordawg points southeast.>\n\nFind spirits near mountains. Near hills. Near rocks. Near earth.\n\nPut to sleep.\n\nTelaari Basin... Southeast.\n", objectives = "Gordawg at the Throne of the Elements in Nagrand has asked that you destroy 10 Tortured Earth Spirits.", progress = "Do they sleep?", completion = "<Gordawg nods in approval.>\n\nGood. Spirits sleep now." }
WordHunterWoW_QuestEN[9820] = { title = "WANTED: Boss Grog'ak", description = "Wanted - Dead or Alive: Boss Grog'ak, overseer of the Ango'rosh mushroom-cutting operation.\n\nThis brute and his axe-wielding cronies are responsible for chopping down the mushrooms to the north of town. Unless he is stopped, he and his band will cut a path to the walls of Zabra'jin.\n\nHe who presents the head of Boss Grog'ak to Shadow Hunter Denjai shall be well-rewarded.", objectives = "Bring Boss Grog'ak's Head to Shadow Hunter Denjai in Zabra'jin.", progress = "What do you have there, <name>?", completion = "Well done, <name>. The presence of these ogres so close to our outpost does have me worried, though. It seems like they've been filtering down from the northern mountains for some time." }
WordHunterWoW_QuestEN[9821] = { title = "Eating Damnation", description = "<Gordawg picks up a rock and begins to chew on it.>\n\nGordawg tastes. Gordawg knows where this earth has been.\n\n<Gordawg raises one of his massive legs and stomps the ground.>\n\nLook. See Nagrand.\n\n<Gordawg directs you to the imprint of his foot. Within the imprint you see what appears to be a perfect geological map of Nagrand, marked with the locations of where you can find the elementals Gordawg wants you to destroy.>\n\nBREAK THEM! Bring Gordawg the pieces to eat.\n\nTake the map.", objectives = "Gordawg at the Throne of the Elements in Nagrand has asked that you bring him 10 Enraged Crusher Cores.", progress = "Gordawg eats this rock. Gordawg finds usurper. Bring rock!", completion = "<Gordawg spits out the chewed up rock, pelting you with a hail of rubble.>\n\nPoison. These rocks are not Nagrand. These rocks are from poison. You destroy poison rock. You find usurper." }
WordHunterWoW_QuestEN[9822] = { title = "Impending Attack", description = "The position of the ogres' mushroom-cutting operation can't be an accident. I can't escape the suspicion that they're preparing for an attack on Zabra'jin.\n\nI must know for certain, {name}. The ogres have another outpost to the northwest, the Ango'rosh Grounds. If they're staging for an attack, there will be evidence of their plans there. Go there, {name} and search the camp for signs of their intentions. Return to me with anything that might be suspicious.", objectives = "Bring the Ango'rosh Attack Plans to Shadow Hunter Denjai in Zabra'jin.", progress = "Have you found proof of the ogres' intentions?", completion = "<Shadow Hunter Denjai examines the plans.>\n\nI knew it! The stench of ogres always carries an implicit threat. Now that we have proof of their intentions, we must act before they do." }
WordHunterWoW_QuestEN[9823] = { title = "Us or Them", description = "In order to end the Ango'rosh threat, we must kill their leader, Overlord Gorefist. We'll do better than that, though. We'll make an example of the overlord and his followers.\n\nGo to the Ango'rosh Stronghold and deal with our foes. The stronghold is located in a cave on a small island to the northwest of Zabra'jin. You'll see a bridge made from a fallen mushroom beyond the Ango'rosh Camp.\n\nShow no mercy, {name}. They certainly wouldn't spare any of us.", objectives = "Kill Overlord Gorefist, 10 Ango'rosh Maulers, and 10 Ango'rosh Souleaters and report back to Shadow Hunter Denjai in Zabra'jin.", completion = "Your victory over the Ango'rosh is to be celebrated, <name>. I wonder how long it will be before those ogre brutes find themselves another bloodthirsty chieftain.\n\nNo matter, we'll be ready for them." }
WordHunterWoW_QuestEN[9824] = { title = "Arcane Disturbances", description = "I'm trying to obtain an imprint of Karazhan's energy... for a personal project, of course.  Unfortunately, I'm not getting anything up here.  If I could get near an underground water source, my crystal would pick up the signals much more clearly.\n\nI've heard of an underground pond as well as a well in a cellar below us.  This whole place is crawling with ghosts however, and venturing there would be hazardous for someone my age.  What do you say; will you help an old man and perform the scrying for me?", objectives = "Use the Violet Scrying Crystal near underground sources of water in the Master's Cellar and return to Archmage Alturus outside of Karazhan.", progress = "The readings, <name>.  Did you complete them?", completion = "These readings do not bode well, <name>.  Karazhan should be emanating all manner of arcane currents... instead it has become a huge energy vacuum.  No signals.  Nothing.  Except for a very faint demonic echo.\n\nThis is bad news, <name>." }
WordHunterWoW_QuestEN[9825] = { title = "Restless Activity", description = "As you may have noticed, the outside of Karazhan is crawling with ghostly beings. The reason for their existence is unknown and unknowns bother me!\n\nBring me their ghostly essence so that I may study their nature.  Karazhan has many secrets, <name>.  I'm determined to uncover all of them.", objectives = "Bring 10 Ghostly Essences to Archmage Alturus outside of Karazhan.", progress = "Have you obtained the ghostly essences I require, <class>?", completion = "Fascinating.  I will study these essences, <name>.  I thank you for your help." }
WordHunterWoW_QuestEN[9826] = { title = "Contact from Dalaran", description = "These signs do not bode well for us, <name>.  I've never been one for secrecy so I will tell you a bit about my organization, the Violet Eye.\n\nWe are agents of the Kirin Tor, the Magus Senate of Dalaran.  We were assigned to keep an eye on Karazhan and Medivh, in case things got out of hand.\n\nWhich they did... very quickly, after Medivh disappeared.\n\nThis report details my findings.  Take it to Archmage Cedric, also from the Violet Eye; you will find him in the outskirts of Dalaran Crater.", objectives = "Bring Alturus's Report to Archmage Cedric in the outskirts of Dalaran Crater.", progress = "You know of the Violet Eye?  You do not look familiar.", completion = "Alturus entrusted you with this information?  That old fool.\n\nI suppose the damage is done, we might as well make use of you.  I suppose you will cooperate?" }
WordHunterWoW_QuestEN[9827] = { title = "Withered Basidium", description = "A close inspection of the basidium reveals a number of indentations that might have once held something. The alien mass of fungus presents something of a puzzle. It's far from healthy, but you have little clue as to what function it might normally perform.\n\nPerhaps someone more familiar with the denizens of Zangarmarsh would be able to tell you more about the basidium.", objectives = "Take the Withered Basidium to Ruam in Telredor in Zangarmarsh.", progress = "What is it you have there, <name>?", completion = "It looks like the basidium of a bog giant, but I haven't seen one in this condition before. I'd heard that the giants in the Dead Mire had begun to wither, but it's far more advanced than I expected.\n\nThe Dead Mire was once a lake like the others in the marsh, and it served as the spawning ground for the giants. With the waters receding, it seems the changes are preventing the giants from sporing. If this continues, the giants may disappear entirely." }
WordHunterWoW_QuestEN[9828] = { title = "Withered Basidium", description = "A close inspection of the basidium reveals a number of indentations that might have once held something. The alien mass of fungus presents something of a puzzle. It's far from healthy, but you have little clue as to what function it might normally perform.\n\nPerhaps someone more familiar with the denizens of Zangarmarsh would be able to tell you more about the basidium.", objectives = "Bring the Withered Basidium to Reavij at Swamprat Post in Zangarmarsh.", progress = "What is it you have there, <name>?", completion = "It looks like the basidium of a boglord, but I haven't seen one in this condition before. I'd heard that the giants in the Dead Mire had begun to wither, but it's far more advanced than I expected.\n\nThe Dead Mire was once a lake like the others in the marsh, and it served as the spawning ground for the giants. With the waters receding, it seems the changes are preventing the giants from sporing. If this continues, the giants may disappear entirely." }
WordHunterWoW_QuestEN[9829] = { title = "Khadgar", description = "Alturus's report is unsettling.  We thought it was bad when Karazhan sealed itself off to the outside world.  We had agents inside; we never heard from any of them again.  Now this... demonic emanation.  We must investigate it.\n\nThe only people who can reopen Karazhan were presumed dead: Khadgar and Medivh.\n\nWhile we hope that the latter is indeed gone, we recently learned that his apprentice, Khadgar, is alive and well in a place called Shattrath City.  Find him and give him Alturus's report.", objectives = "Deliver Alturus's Report to Khadgar in Shattrath City in Terokkar Forest.", completion = "The Violet Eye?  You don't say.\n\nShow me this report you speak of." }
WordHunterWoW_QuestEN[9830] = { title = "Stinger Venom", description = "When I speak to draenei, I often get the sense that they consider themselves removed from their environment. Many seem to pity my brethren, the Broken, who they say have lost something.\n\nWe Broken may have lost our inclination toward the Light, but our experiences have brought us closer to the land.\n\nMy people see opportunities where few draenei do. Take, for example, the venom of the marshlight bleeders that live to the south and west. It has a wide variety of uses from hunting to healing.", objectives = "Bring 6 Marshlight Bleeder Venom to Puluu at the Orebor Harborage.", progress = "I hope to demonstrate the uses of bleeder venom to Anchorite Ahuurn and the others at Telredor. That's going to require me to double my supply.", completion = "Thank you for bringing this venom, <name>. It will go a long way toward making my demonstration possible without depleting my personal stores." }
WordHunterWoW_QuestEN[9831] = { title = "Entry Into Karazhan", description = "I am deeply troubled by the news in this report, <name>.  Gaining entry into Karazhan will be difficult, however.\n\nYou see, when it became apparent that I was stranded here I split the key into three fragments.\n\nI placed the keys inside enchanted containers, and in turn placed those in places that were safe at the time.\n\nWith the dark changes Outland has endured this no longer is the case.  The first fragment is in a section of Auchindoun taken over by the Shadow Council.  Return this fragment to me.", objectives = "Khadgar wants you to enter the Shadow Labyrinth at Auchindoun and retrieve the First Key Fragment from an Arcane Container hidden there.", progress = "Have you obtained the fragment, <class>?  You would do well not to waste any time in this matter.", completion = "You've done well, <name>.  I wasn't sure you would succeed.\n\nThe containers are enchanted with a potent spell that masks their presence from unworthy eyes.  I'm glad to see they did not elude you." }
WordHunterWoW_QuestEN[9832] = { title = "The Second and Third Fragments", description = "I hid the second fragment at the bottom of Serpent Lake, long before it was called that.  The giant drain installed there after the naga took over has likely pulled the container into the depths of Coilfang Reservoir.\n\nThe third fragment will prove the most trying, as I left it inside Tempest Keep back when it was controlled by the naaru.  Kael'thas now rules it and the chamber where I left it has become a prison.\n\nBring me these remaining fragments, <name>.  Much depends on your success.", objectives = "Obtain the Second Key Fragment from an Arcane Container inside Coilfang Reservoir and the Third Key Fragment from an Arcane Container inside Tempest Keep. Return to Khadgar in Shattrath City after you've completed this task.", progress = "How goes your search for the key fragments, <name>?", completion = "You have the fragments.  This is most impressive, <name>.  You're certainly worthy of holding the key to Karazhan.\n\nA small problem remains." }
WordHunterWoW_QuestEN[9833] = { title = "Lines of Communication", description = "One of the reasons Ikuti led us to Zangarmarsh was to help open the lines of communication between the draenei and the Kurenai home city of Telaar in Nagrand. In order for messengers to pass swiftly between Telaar and Telredor, the roads must be secured.\n\nOn our way here, we were attacked repeatedly by marshfang slicers. We were able to fight them off, but they would pose a formidable threat to a solitary messenger. Reducing their numbers will help ensure the safety of our messengers.", objectives = "Puluu at the Orebor Harborage wants you to kill 12 Marshfang Slicers.", completion = "That's excellent news. The way is still far from perfectly safe, but the messengers are clever and resourceful." }
WordHunterWoW_QuestEN[9834] = { title = "Natural Armor", description = "Maktu can always see a draenei approaching in his shiny armor from a mile away, even in this murky swamp!\n\nMaktu wants to laugh at them, but then he remembers that they have been kind to the Kurenai and he wants to teach them about how Kurenai make armor.\n\nThe dark, scaly hides of the fenclaw thrashers make some of the best armor Maktu has ever worn. If {name} can bring Maktu some of these hides from the fenclaw thrashers deep in Serpent Lake, he'll be happy to share some of his armor.", objectives = "Bring 8 Fenclaw Hides to Maktu at the Orebor Harborage.", progress = "Does <name> have hides for Maktu?", completion = "These are good hides, Maktu thinks. They will make very good armor.\n\nWho knows? There might even be enough left over for Maktu to make some armor for the draenei." }
WordHunterWoW_QuestEN[9835] = { title = "Ango'rosh Encroachment", description = "The small band of Broken you see here is a mission from a larger settlement in Nagrand. The Kurenai, as we call ourselves, are Broken who desire to reunite with our draenei brothers.\n\nMy group has come here to strengthen Kurenai ties to the draenei of Telredor.\n\nIf the Ango'rosh ogres have their way, this temple will not stand much longer. They have cleared the Hewn Bog of its towering mushrooms and draw ever closer to our refuge. If you would call yourself our friend, aid us in fighting this enemy.", objectives = "Kill 10 Ango'rosh Ogres and 5 Ango'rosh Shaman and return to Ikuti at the Orebor Harborage.", completion = "The Ango'rosh threat is contained for the moment, but I'm certain they won't give up that easily. I've forgotten many things since the end of my life as a draenei, but the stubbornness of the ogres is an enduring memory." }
WordHunterWoW_QuestEN[9836] = { title = "The Master's Touch", description = "I've put together the very key I used as an apprentice.  It looks completely functional as far as keys go.  In regards to opening Karazhan, however, this might as well be a piece of scrap metal.\n\nWithout Medivh's consent, the key is worthless.  Yes, of course I know Medivh is dead.  This merely makes things difficult, not impossible.\n\nThere is a place in Azeroth called the Caverns of Time, guarded by the bronze dragonflight.  Find a way inside, travel back in time and get Medivh to enable the key.", objectives = "Go into the Caverns of Time and convince Medivh to enable your Restored Apprentice's Key.", progress = "Who are you and what do you want?", completion = "That key, I recognize it.  That is Khadgar's key... of course I haven't given it to him yet." }
WordHunterWoW_QuestEN[9837] = { title = "Return to Khadgar", description = "I seem to have memories about future events surrounding you and this key.\n\n<Medivh looks at you like he's just seen a ghost.>\n\nYou have trying times ahead of you, <name>.  Let us hope your strength does not fail you.\n\nRegarding the key, I am to hand it to Khadgar when he's sent to me.  I couldn't hope for a better apprentice.\n\nI suppose you will need a key of your own.\n\n<Medivh reaches into his robe and hands you his own key.>\n\nGo on then.  And best of luck, <class>.", objectives = "Return to Khadgar in Shattrath City and show him the Master's Key.", completion = "His own key?  That's incredible!\n\nI do not sense any disturbances in our timeline, so I suppose it was meant to occur all along.  There's no turning back now, <name>.  The key is yours and only yours." }
WordHunterWoW_QuestEN[9838] = { title = "The Violet Eye", description = "A great responsibility has been bestowed upon you, <name>.  If the signs that the Violet Eye has observed are to be trusted, then you must help them.\n\nFor all my disagreements with Cedric, the work that men like Alturus do is still important.  Beware that they do not use you, however.  Remember it is you who the key is bound to, not them.  But if the danger in Karazhan is real, then it is they who are best prepared to guide you in dealing with it.  Go back to Alturus and help him in any way that you can.", objectives = "Speak to Archmage Alturus outside Karazhan.", completion = "I sent you to deliver a report and you come back with a key to this place?  There must be more to you than meets the eye, <name>." }
WordHunterWoW_QuestEN[9839] = { title = "Overlord Gorefist", description = "The centerpiece of any ogre tribe is its leader. Without leadership, the Ango'rosh's organization will disappear and they'll resort to infighting to determine who will lead next.\n\nAlthough we've seen the ogres out and about in this area, their true strength is concentrated in their Ango'rosh Stronghold to the northwest. It's located in a cave on a small island connected to the marsh by a fallen mushroom.\n\nGo there and defeat Overlord Gorefist. That should provide us with a well-deserved respite.", objectives = "Ikuti wants you to kill Overlord Gorefist and 10 Ango'rosh Maulers. Return to the Orebor Harborage once you have completed the task.", progress = "Is it done? Have you dealt with Overlord Gorefist?", completion = "At last! You have our thanks for your help in securing our position at the Orebor Harborage. I will send word of your deeds to the Kurenai city of Telaar in Nagrand. There will be many more opportunities for our peoples to work together." }
WordHunterWoW_QuestEN[9840] = { title = "Assessing the Situation", description = "Now that we've found a way back into Medivh's Tower - or rather you have - the first thing we need to do is try to get a sense of what the situation inside is.\n\nOne of our agents who had managed to infiltrate Karazhan kept an encoded log of her observations.  Unfortunately her death was confirmed shortly before Karazhan was shut down.  Koren, Karazhan's blacksmith, was under our pay.  Though not a member of the Violet Eye, he should be able to help us find Keanna's log.  Look for him inside.", objectives = "Find Koren inside Karazhan.", completion = "<Koren looks at you with an uncertain look.>\n\nI know nothing of this Violet Eye you speak of.  A blacksmith is all I am." }
WordHunterWoW_QuestEN[9841] = { title = "Stinging the Stingers", description = "It's impossible to work with all this infernal buzzing! Do you hear it?\n\nI can't get it out of my head! I know exactly what's making the noise, too. It's those damnable marshlight bleeders! The noise always comes from the south and west of the village.\n\nThey're too big to swat, crush underfoot, or wave away. The only way to stop that unholy droning is to kill them. I don't care how you do it, {name}, just quiet them!", objectives = "Kill 8 Marshlight Bleeders and return to Gambarinka at Zabra'jin.", completion = "I thought so. I can hear the difference already. I'll finally be able to get back to work, thanks to you. If you ever find yourself in need of tradeskill supplies, don't forget ol' Gambarinka!" }
WordHunterWoW_QuestEN[9842] = { title = "The Sharpest Blades", description = "The damp atmosphere of the marsh has taken a toll on my metal tools. It's made woodworking a lot more difficult than it ought to be, so I've given up on metal blades.\n\nIt turns out that the marshfang slicers living to the south and west of town grow blades that are sharper than any steel I've ever owned. They're also resistant to rust and wear. It's just a little tricky to attach them to a handle, but I think I've got it figured out. I'd appreciate any blades you could bring me.", objectives = "Bring 10 Marshfang Slicer Blades to Gambarinka at Zabra'jin.", progress = "Have you managed to scare up some of those marshfang blades?", completion = "These should keep me supplied for some time to come! I think some of the others have begun to take notice. I've had several offers to buy my blades already. Selling them on the side might provide better business than my customary goods." }
WordHunterWoW_QuestEN[9843] = { title = "Keanna's Log", description = "Who did you say you were looking for again?  Keanna?\n\nI once met someone with that name.  She was staying up at the guest chambers.  I was supposed to keep that a secret now, wasn't I?\n\nDid you say you were with the Violet Eye?  No, I've never heard of them.\n\nI need to return to my work now, if you don't mind.\n\n<Koren seems to have forgotten about you already.>", objectives = "Search the Guest Chambers inside Karazhan for Keanna's Log and bring it to Archmage Alturus outside Karazhan.", progress = "Keanna's log... did you find it?", completion = "You found the log.  I sure hope the information we need is in here, <name>." }
WordHunterWoW_QuestEN[9844] = { title = "A Demonic Presence", description = "Keanna's last few entries confirm our suspicions of a demonic presence inside Karazhan.\n\nShe detected the arrival of a Burning Legion agent whose location she describes as coming from the top of the tower.\n\nHer entries stop there.\n\nKarazhan is a very important place, <class>.  It is a portal into the nether, a beacon shining into other worlds.  The possible repercussions of it falling into the wrong hands are unthinkable.  This demonic intrusion must be stopped.  And you, <name>, are the only one with a key.", objectives = "Archmage Alturus wants you to destroy the Demonic Presence at the top of Karazhan.", completion = "You did it!  Yes, the readings are becoming normal once again!\n\nWe must give this news to Cedric.  He's going to be very impressed with your achievement." }
WordHunterWoW_QuestEN[9845] = { title = "Angling to Beat the Competition", description = "It's a relief to be in someplace with water after trekking through the wasteland of Hellfire Peninsula. I was worried there might not be any respectable fishing holes in Outland.\n\nNow I'm glad I lugged my fishing supplies along. For the most part, the fishing's been good, except for those no good fenclaw thrashers in Serpent Lake.\n\nNot only do they scare the fish away, but they're bold enough to snap the bait right off my hook. I spend more time re-baiting the hook than I do catching anything!", objectives = "Kill 10 Fenclaw Thrashers and return to Zurjaya at Zabra'jin.", completion = "I can't wait to return to fishing! Now I'll be able to return to town with some real fish in my bucket and Gambarinka won't be able to make fun of me anymore!" }
WordHunterWoW_QuestEN[9846] = { title = "Spirits of the Feralfen", description = "The most powerful tribe of Lost Ones in the marsh, the Feralfen, are said to possess powerful medicine. There may be no truth to such rumors, but anything that might help me channel the spirits of this world cannot be ignored.\n\nFind the Feralfen mystics, hunters and druids, {name}, and capture their totems. Everything I need to know should be apparent from the carvings.", objectives = "Bring 10 Feralfen Protection Totems to Seer Janidi at Zabra'jin.", progress = "Have you gathered those totems?", completion = "Hmm... They seem to be divided between images of a serpent spirit and a bird spirit. No self-respecting Darkspear troll engages in bird worship. Their spirits are weak, capricious, and best left to the Amani.\n\nBut the serpent, <name>, the serpent wields considerable power and this is the spirit I shall study." }
WordHunterWoW_QuestEN[9847] = { title = "A Spirit Ally?", description = "We must find out how much power this Feralfen snake spirit possesses and whether it can be bent to our will. Imagine what I could do with the powers of an Outland spirit at my command!\n\nTake this totem with you and make your way to the foot of the stairs leading to the Boha'mu Ruins. Plant the totem in the ground and it should do the rest. The spirit should not be able to tell who has used the totem until it has manifested.", objectives = "Take the Feralfen Totem to the foot of the stairs at the Boha'mu Ruins and plant it in the ground. Report your findings to Seer Janidi at Zabra'jin.", progress = "Were you able to summon the Feralfen spirit?", completion = "<You tell Seer Janidi about what happened when you used the totem.>\n\nThe spirit attacked you? It must have a higher affinity for those Lost Ones than I'd thought. There's no way to compel it to serve me without expending considerable effort. I'll have to search for a new source of power in this wretched world." }
WordHunterWoW_QuestEN[9848] = { title = "Secrets of the Daggerfen", description = "Bugs, bugs, bugs! The marsh is full of them and my companions here seem obsessed with them.\n\nWell, I've had it with the bugs! Something far more intriguing has captured my interest. To the west, there is a village of Lost Ones who call themselves the Daggerfen.\n\nThe whole tribe consists of highly specialized assassins. I've noticed them mixing and using a particularly potent kind of poison. I'm dying to know more about the poison, but that's going to require a copy of the recipe and a sample vial.", objectives = "Bring the Daggerfen Poison Manual and a Daggerfen Poison Vial to Timothy Daniels at the Orebor Harborage.", progress = "Did your search of Daggerfen Village yield the information I need in order to get to the bottom of this poison puzzle?", completion = "<Timothy leafs through the manual.>\n\nThey're using ragveil as a base for the poison? No, that can't be right. Ragveil has no toxic properties.\n\nIncluding ragveil in a poison is like a rogue wielding two maces. Sure, you can do it, but it isn't true to the essence of your calling! I just can't understand...\n\n<Timothy clears his throat.>\n\nI mean, thank you for fetching these for me. I'll try out the poison as soon as time permits." }
WordHunterWoW_QuestEN[9849] = { title = "Shattering the Veil", description = "<Gordawg breaks off a piece of ebon rock from his back.>\n\nYou are granted a piece of the fury of the earth. Take the boulder of Gordawg and hurl it at the poison rock. Shatter their shells to discover the truth. Destroy the minions of the usurper and return to Gordawg with the name.\n\nYou find the shattered elements at the edge of the world. Southwest.", objectives = "Gordawg at the Throne of the Elements in Nagrand has asked that you slay 30 Minions of Gurok.", progress = "Gordawg wants the boulder returned.", completion = "GUROK! Gurok betrayed the elements!" }
WordHunterWoW_QuestEN[9850] = { title = "Clefthoof Mastery", description = "You've proved to me that you can find and take down a regular clefthoof, but far more dangerous are the clefthoof bulls.\n\nBag yourself twelve of those.  Then you can talk to me of your hunting prowess.\n\nLook for them all along the middle region of Nagrand to the west and south.", objectives = "Kill 12 Clefthoof Bulls and then speak to Hemet Nesingwary at Nesingwary's Safari in Nagrand about your prowess.", completion = "Impressive.  Most impressive.\n\nYou've got potential, kid.  Now I'm going to give you the chance to have some real fun!" }
WordHunterWoW_QuestEN[9851] = { title = "Clefthoof Mastery", description = "Banthar is the fiercest and most elusive of all the clefthoof in Outland.  She's also the hairiest.\n\nIt is said that she roams with her clefthoof herd in the Spirit Fields near Oshu'gun.\n\nYou want to truly prove your hunting mastery?  Bring me her horn!", objectives = "Acquire the Horn of Banthar and return it to Hemet Nesingwary at the Nesingwary Safari in Nagrand.", progress = "A warm fire and a woman at your side for idle chit-chat is something you can get at home.  Here we hunt big game or die trying.", completion = "You did it!  You took down Banthar!  I never had a doubt, <name>.\n\nHere, I think you've more than earned this." }
WordHunterWoW_QuestEN[9852] = { title = "The Ultimate Bloodsport", description = "The queen of all that dwell in Nagrand is known as Tusker.  She's a giant elekk the likes of which you won't see anywhere else!\n\nYou're right to be fearful of that name.  Bach'lor, Gutripper, and Banthar are nothing when compared to her.  It is said that she can be found on a huge bluff far to the southwest overlooking Oshu'gun.  Bring me her massive heart if you dare.\n\nDo you want to leave a letter with me so that I can have it delivered to your next of kin in the likely event that you don't return?", objectives = "Bring the Heart of Tusker to Hemet Nesingwary at Nesingwary's Safari in Nagrand.", progress = "There's no shame in admitting that you haven't the spine to hunt the mightiest of animals this land has to offer, <name>.", completion = "<name>!  You bring joy to this old dwarf's heart.\n\nYou have now proven yourself; you've joined the ranks of the elite!  Others ran away in fear, or died, trampled under the foot of the beast.  You used your mind, your cunning, your determination to prove your mastery of the hunt.\n\nTake this and know that you are always welcome to hunt at my side!" }
WordHunterWoW_QuestEN[9853] = { title = "Gurok the Usurper", description = "Gurok must be summoned. You summon Gurok and you destroy.\n\nYou must go to Warmaul Hill to the northwest and find where ogre worships Gurok. You put ogre skull from Warmaul ogres on Gurok's earthen brand. Only then will Gurok come. Seven skulls.\n\nIf you live, bring Gordawg back Gurok earthen head. Gordawg crushes head.\n\n<Gordawg bites down hard, shaking the earth beneath your feet.>", objectives = "Gordawg at the Throne of the Elements in Nagrand has asked that you destroy Gurok the Usurper and bring back Gurok's Earthen Head.", progress = "Gordawg eat Gurok power.", completion = "<Gordawg chomps down hard on Gurok's earthen head, nearly disintegrating the stone formation.>\n\nGurok's reign has come to an end. The earthen elements are free. All sleep now. Champion gets reward!" }
WordHunterWoW_QuestEN[9854] = { title = "Windroc Mastery", description = "Do you live for the hunt as I do, {class}?  Do you seek the quietude that comes as you stalk your prey?  Would you know what it is to honor the last heartbeats of your fallen quarry?  I will help you to achieve this.\n\nNagrand is a lush land, full of life in the midst of this broken world.  Bring down a handful of the windrocs and then we will speak more.\n\nYou can find them in many places nearby in all directions around our camp.", objectives = "Kill 12 Windrocs and then return to Fitz at the Nesingwary Safari in Nagrand.", completion = "Every day is a gift.  Make the most of it.  For tomorrow we shall stride swifter over the plains than today.  We will spread our arms further and strain to achieve that which tonight we can only dream of, though it may ever elude us." }
WordHunterWoW_QuestEN[9855] = { title = "Windroc Mastery", description = "You must always push yourself if you are to one day stalk the mightiest of prey!  While you are not yet ready, I will point you in the right direction.\n\nThere is another breed of windroc even deadlier.  Seek out the ravenous windroc to test your mettle against.  You will find them in the heart of Nagrand to the west and southwest.", objectives = "Hunt down 12 Ravenous Windrocs and then return to Fitz at the Nesingwary Safari in Nagrand.", completion = "You have proven your skill once more, <class>.  Now you must go on to stalk the fiercest of the windrocs." }
WordHunterWoW_QuestEN[9856] = { title = "Windroc Mastery", description = "You are ready, {class}.  Ready to face the mother of all windrocs, Gutripper!  Honor demands that after hunting so many of her children that you give her the chance to defeat you!  Seek her out amongst the greater windroc far to the west.\n\nShould you survive, bring her eye to me.", objectives = "Bring the Eye of Gutripper to Fitz at the Nesingwary Safari in Nagrand.", progress = "Have you faced Gutripper yet?", completion = "Her eye looks as if it is still alive.  Do you think that she can still see into your soul?\n\n<name>, you can now count yourself as one of the elite safari hunters.  And you are another step closer to stalking the ultimate prey of this land, Tusker!\n\nYou've earned the right to have this.  May it serve you well." }
WordHunterWoW_QuestEN[9857] = { title = "Talbuk Mastery", description = "I don't think that I'm up to the hunt today.  Do you think that you might take my place?\n\nI told Hemet that I was going to see about bagging us some of those talbuk that seem to be all over the place.  The stags are especially nice to hunt.  You can find them congregated around the nearby trees.\n\nThink that you could take care of that for me?", objectives = "Kill 12 Talbuk Stags and then return to Harold Lane at the Nesingwary Safari in Nagrand.", completion = "That's a good tale... <cough>...of how you bagged all of those stags, <class>.  But I think that you can do better.  I've got something else in mind for you." }
WordHunterWoW_QuestEN[9858] = { title = "Talbuk Mastery", description = "This darned scratch is getting the worst of me it would seem.  So, are you up to filling...<cough>... in for me again?\n\nThis time you're going to bag yourself some thorngrazers.  They're tougher and wilier than the stags, so keep your wits about you.  Look for them... <cough>... sheltered under the trees in the middle of Nagrand to the west and south.\n\nGo on, get out there and...<cough>... show Hemet what you're made of.  I'll be fine.", objectives = "Hunt down 12 Talbuk Thorngrazers and then return to Harold Lane at the Nesingwary Safari in Nagrand.", completion = "<cough>, <cough>... <name>!  You did it.  There's only...... one thing left to...... do then." }
WordHunterWoW_QuestEN[9859] = { title = "Talbuk Mastery", description = "<Wracking cough.>\n\nDon't worry about...<cough>... me.  I'll be fine.  It's just a...<cough>... scratch.\n\nJust the same, I think you'll... <cough>... have to fill in for me one more... <cough>... time.\n\nYou must seek out the great Bach'lor, king of...<cough>... the stags.\n\nBring me one of his hooves...<cough>, <cough>... as confirmation.\n\nLook for him...<cough>... leading his herd in the far west of Nagrand.", objectives = "Obtain the Hoof of Bach'lor and return it to Harold Lane at the Nesingwary Safari in Nagrand.", progress = "<Harold looks up at you weakly, but manages a smile.>\n\nYou have...<cough>... the hoof?", completion = "Wow!  You did it!  That's really Bach'lor's hoof!\n\nUm, I'm starting to feel much better it would seem.  Here, let me give you something in celebration of your proven hunting prowess!" }
WordHunterWoW_QuestEN[9860] = { title = "The New Directive", description = "Return to Cedric at once, <name>.  The aid you've given the Violet Eye will not go unrewarded.\n\nThink what you want of us and our organization, <class>, but gaining the favor of the archmages of Dalaran will not be something you regret.", objectives = "Speak to Archmage Cedric in the outskirts of Dalaran Crater.", completion = "Alturus told me all about what happened, <name>.  This is not the end of it, however.  With Karazhan remaining sealed to outsiders, it's only a matter of time until the Legion renews its attacks while we stand powerless in the sidelines.\n\nUnless you accept the responsibility that fate has bestowed upon you, that is.\n\n\n\nWhat do you say, <name>?" }
WordHunterWoW_QuestEN[9861] = { title = "The Howling Wind", description = "This amorphous mass of elemental air is speaking to you in a language that you cannot understand. You believe the language to be the tongue of the elements: Kalimag. Perhaps someone at the Throne of the Elements could shed some insight on this unusual find.", objectives = "Find someone at the Throne of the Elements that knows how to speak Kalimag and show them the Howling Wind.", progress = "Give it here! Quickly!", completion = "It is a distress call, <race>. An outside force is attempting to subvert the elements." }
WordHunterWoW_QuestEN[9862] = { title = "Murkblood Corrupters", description = "Murkblood are capturing and torturing the spirits of air! Murkblood are my kin: A tribe of the Broken who serve the vile Musel'ek, beast lord of Coilfang.\n\nThe air spirit states that the Murkblood putrefiers are capturing other spirits of air and using them to sow chaos into the ranks of the elements. It would seem that the Murkblood have recently sacked an orc village to the southwest known as Sunspring and are using powerful elemental magic to disturb the lake. Find the putrefiers and destroy them.", objectives = "Elementalist Morgh at the Throne of the Elements in Nagrand wants you to slay 5 Murkblood Putrefiers.", completion = "You saw them controlling the elements? The wind bent to their will?\n\n<Morgh is lost in thought for a moment.>\n\nThis is troubling, <name>. I must consult with the others.\n\nWe thank you for your efforts, <name>. Perhaps you should return to your village and see if they have any other information about the Murkbloods and their nefarious goals." }
WordHunterWoW_QuestEN[9863] = { title = "Vile Idolatry", description = "With our leadership in ruin, we are left open to attacks from all sides. The foul Murkblood tribe could not have picked a better time to attack us!\n\nIn recent days, we have been subject to no less than 5 assaults from the Broken. They have even taken over our only other territorial holding in the area: Sunspring Post.\n\nWe must strike and show them that we are not powerless! Strike down the vile idolaters and bring me their twisted idols of worship so that they may ride the lightning.", objectives = "Farseer Kurkush at Garadar in Nagrand wants you to bring him 10 Murkblood Idols.", progress = "Do this for us because we cannot do it for ourselves.", completion = "You have given the Lightning Sons hope, <name>. If our leader will not protect us, perhaps there are others that are capable - like you." }
WordHunterWoW_QuestEN[9864] = { title = "The Missing War Party", description = "After the last Murkblood raid, a group of younglings decided to act. We tried to stop them but the rage had taken hold. It has now been one week since we last saw our beloved younglings.\n\nPlease, {race}, you must find them! They have just barely reached adolescence. How can they expect to defeat such savages?\n\nThey took the road leading west out of town. Follow that road around and look for signs of our younglings.\n\nAnd {name}, avoid Halaa if you value your life. It is a war-zone.", objectives = "Try and find the missing Garadar war party.", completion = "I have been told stories of my people. They say that once, we were warriors..." }
WordHunterWoW_QuestEN[9865] = { title = "Once Were Warriors", description = "I do not know you, stranger, but I ask for your help. I feel shame for this, but I am only one orc.\n\nEmotions have surfaced that I have never felt. I... I seek vengeance. Blood for blood. Do your people ever feel this? I wish to pick up my axe and split my enemies in two. To swing the weapon until my arms fall lifelessly at my sides, exhausted.\n\nSunspring Post is directly south of this procession. It is there that you will find our enemies... Kill them... Kill them all...", objectives = "Kill 20 Murkblood Scavengers and 10 Murkblood Raiders.", completion = "<Saurfang turns to face you.>\n\nIs it blood that I smell? I regret being unable to lend assistance. How proud you must be. My chest swells just knowing what you have done.\n\nAre there others like you? Where you come from, do more heroes exist?" }
WordHunterWoW_QuestEN[9866] = { title = "He Will Walk The Earth...", description = "Will you do me one last honor, {name}? I do not wish to return to Garadar. I believe that my destiny lies elsewhere - that I will serve a greater purpose someday.\n\nPlease, return to Farseer Corhuk and tell him that I will not be returning. That I cannot return. I must walk the earth... He will understand.", objectives = "Deliver the news to Farseer Corhuk at Garadar.", completion = "<Farseer Corhuk stares at the ground, lost in contemplation. He nods his head affirmatively.>\n\n<Farseer Corhuk wipes a tear away.>\n\nThe son is the father... May the spirits have mercy on those that stand in his way." }
WordHunterWoW_QuestEN[9867] = { title = "Murkblood Leaders...", description = "We have lost many friends in recent weeks.\n\nFor decades we have dealt with the ogres of Nagrand but now a new threat has arisen. The Broken tribe of Murkblood attacked our fishing village to the southwest, Sunspring Post, and managed to kill or evict all of the orcs that inhabited the town.\n\nWhile the others feel that the best course of action is to kill indiscriminately, I know that we must destroy their leadership. I do not know who their leader is but I suspect that you will know when you find him.", objectives = "Farseer Margadesh at Garadar in Nagrand wants you to bring him the Head of Ortor of Murkblood.", progress = "Bring me their leader's head, <name>.", completion = "So, this is the face of our enemy? I will have this put upon a pike and placed outside of Garadar, near the gates. Should they think to attack us again, they will see the consequences for their actions looking down upon them..." }
WordHunterWoW_QuestEN[9868] = { title = "The Totem of Kar'dash", description = "Thank you, stranger. They would have surely killed me had it not been for you.\n\nI was kidnapped by these Murkbloods 3 nights ago during a nighttime raid on Garadar. What I have since uncovered may very well shake the foundation of the Outland: these savages seek to recover the totem of Kar'dash! We cannot allow the totem to fall into the hands of the Murkbloods!\n\nYou must help me escape. And stranger, if I do not make it back to Garadar, you must tell Garrosh what happened here... ", objectives = "Escort the Mag'har Captive out of Sunspring Post. Speak to Garrosh at Garadar if you succeed.", completion = "What does it matter? The Greatmother is dying. Life is not worth living..." }
WordHunterWoW_QuestEN[9869] = { title = "The Throne of the Elements", description = "Greetings, {race}. I am Ioki, elementalist of the Earthen Ring. I have come to Telaar to inform the Kurenai of the state of the elements.\n\nCould I ask a favor of you? Would you travel to the Throne of the Elements in the northern hills of Nagrand, beyond Skysong Lake, and tell elementalist Sharvak that I have arrived at Telaar safely? She will surely reward you for this small deed.", objectives = "Elementalist Ioki wants you to travel to the Throne of the Elements and speak with Elementalist Sharvak.", completion = "Ah, thank you for the message. Perhaps you would not mind helping out the Earthen Ring? The elements are in flux. We can use all of the assistance that we can get." }
WordHunterWoW_QuestEN[9870] = { title = "The Throne of the Elements", description = "Greetings, {race}. I am Yal'hah, elementalist of the Earthen Ring. I have come to Garadar to inform the Mag'har of the state of the elements.\n\nCould I ask a favor of you? Would you travel to the Throne of the Elements in the northern hills of Nagrand, beyond Skysong Lake, and tell elementalist Sharvak that I have arrived at Garadar safely? She will surely reward you for this small deed.", objectives = "Elementalist Yal'hah wants you to travel to the Throne of the Elements and speak with Elementalist Sharvak.", completion = "Ah, thank you for the message. Perhaps you would not mind helping out the Earthen Ring? The elements are in flux. We can use all of the assistance that we can get." }
WordHunterWoW_QuestEN[9871] = { title = "Murkblood Invaders", description = "The parchment holds a crudely painted map of Nagrand. There is a big red 'X' where Telaar would be on the map. It would seem that these savages are planning an attack on the city. Take the Murkblood invasion plans to Arechron in Telaar.\n", objectives = "Take the Murkblood Invasion Plans to Arechron at Telaar in Nagrand.", progress = "What is it?", completion = "<Arechron slams his fist into his hand.>\n\nOrtor... Treacherous fiend!" }
WordHunterWoW_QuestEN[9872] = { title = "Murkblood Invaders", description = "The parchment holds a crudely painted map of Nagrand. There is a big red 'X' where Garadar would be on the map. It would seem that these savages are planning an attack on the city. Take the Murkblood invasion plans to Garrosh in Garadar.", objectives = "Take the Murkblood Invasion Plans to Garrosh.", progress = "What is it?", completion = "<Garrosh crumples up the map and throws it into the fire.>\n\nWhat's the use? They've been attacking us for weeks. This is nothing new.\n\nDon't you understand? We're done for... Greatmother Geyah is dying." }
WordHunterWoW_QuestEN[9873] = { title = "Ortor My Old Friend...", description = "These invasion plans were written by someone I once knew. Ortor of Murkblood, once a noble Broken, versed in the way of the elements, now a muck addled yes-man of Musel'ek the bog lord.\n\nThe plans state that they have taken over an orc village northwest of here known as Sunspring.\n\nTravel to Sunspring Post and rid the world of Ortor of Murkblood. What you do, you do for the good of us all...", objectives = "Arechron at Telaar in Nagrand wants you to kill Ortor of Murkblood.", progress = "Remember, <name>, Ortor is a shaman of great power.", completion = "A thousand dead orcs you say? What could have triggered such an audacious advance into orc lands? It is good that he is dead but there is more to this than what meets the tentacle." }
WordHunterWoW_QuestEN[9874] = { title = "Stopping the Spread", description = "I have just gotten word of a catastrophe of epic proportions, {name}. The foul Murkblood have sacked the orc village of Sunspring Post, northwest of here, and murdered its residents. To make matters worse, they have begun dumping the bodies into Sunspring Lake. Should those bodies rot, our primary source of water in the region will be compromised.\n\nIt's a gruesome task that I give you next but it must be done. Take this enchanted torch and return to Sunspring. Burn all of the rotting orc corpses...", objectives = "Otonbu the Sage at Telaar in Nagrand wants you to use the Torch of Liquid Fire to destroy 10 Sunspring Villager corpses. Return the Torch of Liquid Fire when the task is complete.", progress = "The orcs will not understand what we are doing but it must be done. For the good of both orc and Broken.", completion = "<Otonbu sighs.>\n\nThis will set back any chance of peace with the orcs another 10 years. At least we will be around to see those years as opposed to what could have happened had those corpses been allowed to rot." }
WordHunterWoW_QuestEN[9875] = { title = "Uncatalogued Species", description = "Lauranna must've missed this particular plant.  You're certain you've discovered a species not yet catalogued by Lauranna's work.  You'd best show it to her to see what she makes of it.", objectives = "Bring the Uncatalogued Species to Lauranna Thar'well at the Cenarion Refuge in Zangarmarsh.", progress = "You have something to show me?", completion = "A new species!  Are you sure?\n\n<Lauranna flips through pages of notes and diagrams.>\n\nNice job, <name>.  We'll have to add this one to our list.  How does \"Purple Leafed Aelarathrium\" sound to you?  It does have a ring to it." }
WordHunterWoW_QuestEN[9876] = { title = "Failed Incursion", description = "I sent a small group of our druids to investigate the drain you discovered inside of Serpent Lake.  They were expected to return shortly after.  Needless to say, they did not.\n\nYou are amongst our most capable allies; I ask you to seek them and find out what became of them.", objectives = "Ysiel Windsinger wants you to look for signs of Cenarion Expedition Druids near the entrance to Coilfang Reservoir in Zangarmarsh.", completion = "Thank Cenarius you showed up.  My injuries prevented me from going back to the outside for help." }
WordHunterWoW_QuestEN[9877] = { title = "A Restorative Draught", description = "The battle against the Scourge is not one without casualties.  Many are slain every day yet many more meet a worse fate.\n\nIt is not uncommon for the Scourge to take prisoners.  Death would be preferable to what awaits them in Deatholme.  They're interrogated and tortured while under the effects of horrible will-breaking poisons.\n\nApothecary Renzithen in Tranquillien has developed a remedy; go to him and retrieve this restorative draught.", objectives = "Speak to Apothecary Renzithen in Tranquillien.", completion = "Janeda's sending you to rescue the Deatholme prisoners?  She must think very highly of you, <name>." }
WordHunterWoW_QuestEN[9878] = { title = "Solving the Problem", description = "The appearance of the Murkblood in Nagrand has had a profound negative impact on our environment. The elementals are all in flux which has, in turn, greatly disturbed the wildlife. Worse yet, the razing of Sunspring Post has reignited the hatred that the orcs held for our people.\n\nWhile the Kurenai are a different tribe than the Murkblood, all an orc sees is Broken.\n\nWe must make an effort to solve this dilemma. Travel to Sunspring Post, northwest of here, and resolve the Murkblood problem.", objectives = "Poli'lukluk the Wiser at Telaar in Nagrand wants you to kill 10 Murkblood Scavengers and 5 Murkblood Raiders.", completion = "It is doubtful that the orcs will understand or appreciate what you just did but Nagrand is better off for the deed. Thank you, problem solver..." }
WordHunterWoW_QuestEN[9879] = { title = "The Totem of Kar'dash", description = "I would have been killed had you not come along, stranger. They have already murdered so many Kurenai in their search for a lost relic.\n\nWhat they seek is the totem of Kar'dash. Why they think that we would know anything about this totem, I cannot understand. Is a totem not an orcish implement by nature?\n\nThis information must be taken back to Arechron. Perhaps he knows why Murkblood are kidnapping Kurenai and torturing them for information regarding an orcish device.\n\nLet's go before more come.", objectives = "Escort the Kurenai Captive out of Sunspring Post. Speak to Arechron at Telaar if you succeed.", completion = "Yes, I know of the totem... but there is much more to this story. Alas, I lack the authority to reveal this information to you. Only the chosen may be privy to such knowledge." }
WordHunterWoW_QuestEN[9880] = { title = "Hellfire Penninsula: -pn - A - ToWoW - Hellfire Turnin Cap", description = "", objectives = "" }
WordHunterWoW_QuestEN[9881] = { title = "Hellfire Penninsula: -pn - H - ToWoW - Hellfire Turnin Cap", description = "", objectives = "" }
WordHunterWoW_QuestEN[9882] = { title = "Stealing from Thieves", description = "Nexus Prince Haramad has ordered us to not begin work inside of Oshu'gun as it might anger a certain powerful naaru.  Sort of puts a damper on our operation.\n\nI think I might've found a loophole, however.\n\nYou see, we're not the only ethereals drawn to this colossal diamond.  A thief called Gava'xi has led a band of rogue ethereals into Oshu'gun and they've begun to dislodge large fragments from it.\n\nYour job, {race}, is to go there and retrieve what is rightfully ours.", objectives = "Obtain 10 Oshu'gun Crystal Fragments and bring them to Gezhe at Aeris Landing in Nagrand.", progress = "Have you retrieved the crystal fragments I asked of you, <name>?", completion = "Color me impressed.  These are in excellent condition, for the most part.\n\nI will make sure to put in a good word for you with our people." }
WordHunterWoW_QuestEN[9883] = { title = "More Crystal Fragments", description = "", objectives = "You've got more crystal fragments?  Make sure you're not taking any that are still attached to the mountain; we wouldn't want to stir up trouble with the naaru.", progress = "You've got more crystal fragments?  Make sure you're not taking any that are still attached to the mountain; we wouldn't want to stir up trouble with the naaru.", completion = "Keep the crystal fragments coming, <name>.  We cannot let these thieves take our property.\n\nEven if it's not ours just quite yet.  A technicality, of course." }
WordHunterWoW_QuestEN[9884] = { title = "Membership Benefits", description = "", objectives = "The Consortium is well known for taking good care of its friends. At the beginning of each month I'll have some gems ready for you as payment for your services.\n\nThe quality of the gems you get will depend on how loyal you've been to us. Here's to hoping you do the smart thing and stay with us." }
WordHunterWoW_QuestEN[9885] = { title = "Membership Benefits", description = "", objectives = "The Consortium is well known for taking good care of its friends. At the beginning of each month I'll have some gems ready for you as payment for your services.\n\nThe quality of the gems you get will depend on how loyal you've been to us. Here's to hoping you do the smart thing and stay with us." }
WordHunterWoW_QuestEN[9886] = { title = "Membership Benefits", description = "", objectives = "The Consortium is well known for taking good care of its friends. At the beginning of each month I'll have some gems ready for you as payment for your services.\n\nThe quality of the gems you get will depend on how loyal you've been to us. Here's to hoping you do the smart thing and stay with us." }
WordHunterWoW_QuestEN[9887] = { title = "Membership Benefits", description = "", objectives = "The Consortium is well known for taking good care of its friends. At the beginning of each month I'll have some gems ready for you as payment for your services.\n\nThe quality of the gems you get will depend on how loyal you've been to us. Here's to hoping you do the smart thing and stay with us." }
WordHunterWoW_QuestEN[9888] = { title = "The Impotent Leader", description = "I have escaped certain death, surviving a cowardly nighttime attack by Boulderfist ogres upon my village.\n\nBut I ask you, stranger: For what?\n\n<Jorin points to Garrosh.>\n\nHe has refused to give us assistance. Ogres are rampaging through my town and he sits here, weeping into a fire. What has become of us? What will become of us?\n\nI've sent a scout, Kilrath, to the village, now the Bleeding Hollow Ruins. Will you find him and give him your assistance? He hides on the border of Nagrand and Terokkar.", objectives = "Jorin Deadeye has asked that you find and speak with Kilrath.", completion = "<Kilrath speaks in a hushed tone.>\n\nThese ogres are extremely peculiar. They are also extremely stupid. Look how the fat one makes the, um, lesser fat ones dance. It's mesmerizing." }
WordHunterWoW_QuestEN[9889] = { title = "Don't Kill the Fat One", description = "I have been watching these beasts for days. The fat one says that he is waiting for something. What he is waiting for, however, is a mystery.\n\nI have a plan but it is going to involve some violence on your part. You will need to kill several of his subordinates and then beat him within an inch of his life. Do this and I am certain he will tell us everything that we need to know.", objectives = "Kilrath in Terokkar Forest has asked that you kill 10 Boulderfist Invaders and beat Unkor the Ruthless until he talks.", progress = "I submit! I submit!", completion = "Let me live and I'll tell you whatever you want to know!" }
WordHunterWoW_QuestEN[9890] = { title = "Success!", description = "For many years, Boulderfist ruled all ogres in the Outland. The ogres were united under Krol and content with the lands that they were given. In the past few months, we have lost many ogres to a new clan known as Warmaul. Warmaul has taken most of our land in Nagrand and killed many of our people.\n\nWe had no choice but to take this town. We are being exterminated...\n\nKrol has gone missing and Boulderfist is in turmoil. Lantresor of the Blade rules in his absence.\n", objectives = "Take the information that you beat out of Unkor back to Kilrath in Terokkar Forest.", completion = "Slow down, <name>. I am but a lowly rogue. I have no idea what to do with such information." }
WordHunterWoW_QuestEN[9891] = { title = "Because Kilrath is a Coward", description = "Take what you have learned and tell Jorin at Garadar. I can assure you that he won't be happy to know that our village was destroyed and many of our people killed because the ogres needed more space.\n\nMay the ancestors watch over you... I will be hiding in the bushes if you need me for anything else.", objectives = "Take the information that you beat out of Unkor to Jorin Deadeye at Garadar in Nagrand.", completion = "So they think that they are within their rights to displace and slaughter orcs on a whim, eh? I'm sure that this had nothing to do with our leader being an impotent whelp... If only he'd gotten a fraction of the passion that his father had..." }
WordHunterWoW_QuestEN[9892] = { title = "More Obsidian Warbeads", description = "", objectives = "Have you obtained any more warbeads?  You'll find plenty of ogres to the far north, near the border with Zangarmarsh.", progress = "Have you obtained any more warbeads?  You'll find plenty of ogres to the far north, near the border with Zangarmarsh.", completion = "We'll make a good profit on these, <name>.  I'll make sure Khoraazi hears about your work here." }
WordHunterWoW_QuestEN[9893] = { title = "Obsidian Warbeads", description = "All this waiting around for Oshu'gun to be ready for digging is eating into our profits, {name}.\n\nFortunately, I've devised an alternate source of income.  The ogres of Nagrand wear warbeads made of obsidian, a mineral that commands a hefty price in many other worlds.\n\nZerid already has had to take care a few of the brutes as a matter of security.  Think of the warbeads as an added bonus.  Or better yet, don't think about it too much and just bring them to me.", objectives = "Bring 10 Obsidian Warbeads to Gezhe at Aeris Landing in Nagrand.", progress = "How are those ogres treating you, <name>?  Tough bunch, aren't they?", completion = "Excellent.  This will keep us in business while we wait for the Sha'tar to finish whatever housekeeping it is they need to do inside Oshu'gun." }
WordHunterWoW_QuestEN[9894] = { title = "Safeguarding the Watchers", description = "In your travels, you might have encountered some of the expedition's watchers. They do the majority of the field work: documenting the unique inhabitants of the marsh, collecting samples, and making contact with sentient species.\n\nThe safety of the watchers is paramount, {class}. We've had to recall the watchers we sent to explore Funggor Cavern to the south, because of marshbeast attacks. Warden Hamoot believes that killing their leader, Lord Klaq, will bring a swift end to the attacks. ", objectives = "Kill Lord Klaq and return to Windcaller Blackhoof at the Cenarion Refuge.", progress = "Have you located and dealt with Lord Klaq?", completion = "You have my gratitude, <name>, and that of the watchers. They will be heartened to hear that they can continue their work to the south without fear of attack." }
WordHunterWoW_QuestEN[9895] = { title = "The Dying Balance", description = "Have you observed your surroundings closely, {name}? This is an ailing landscape, struggling to keep itself in balance and losing the fight.\n\nIf you know where to look, you can see the symptoms. Members of some species rapidly outgrow their peers and become more aggressive.\n\nA good example of this uncontrolled growth is the marshtrekker Boglash. If you wish to see it for yourself, look no further than the waterways south of the refuge.\n\nBe prepared to defend yourself. The creature knows no mercy.", objectives = "Locate and deal with Boglash, then return to Lethyn Moonfire at Cenarion Refuge.", progress = "Have you encountered Boglash?", completion = "Now that you've seen the symptoms of imbalance with your own eyes, be mindful of them in your travels." }
WordHunterWoW_QuestEN[9896] = { title = "Blacksting's Bane", description = "By Khaz'goroth's flaming navel, it's hot here! I can't blame the first party for leaving, but everyone knows 'twasn't the heat that drove them away. No, it was Blacksting, although they won't admit it.\n\nThey were camped just to the south of the glowing draenei towers to the west, just north of the Feralfen Village, when the giant wasp appears out of nowhere and attacks! I can't wait to see the looks on their faces when I bring the creature's stinger back to Ironforge and show it to them!", objectives = "Bring Blacksting's Stinger to Prospector Conall at Telredor.", progress = "Did you manage to get the stinger? Remember, it's useless to me if it's damaged.", completion = "I can't thank you enough, lad. I'm going to enjoy this..." }
WordHunterWoW_QuestEN[9897] = { title = "I'm Saved!", description = "I don't mind sharing.  I'm just glad to be saved from that creep, Gankly!  And I collected tons of skins from Zangarmarsh, so it's no problem at all!", objectives = "Give the Bundle of Skins to Harold Lane at the Nesingwary Safari in Nagrand.", progress = "Kristen is a very nice...<cough>... person to share her skins, wouldn't you agree?", completion = "Well, I couldn't see if you helped out with saving Kristen, or not.  But if she handed you one of her bundles of skins then you're alright in my book.\n\nHere's your reward." }
WordHunterWoW_QuestEN[9898] = { title = "The Respect of Another", description = "Magasha is the fiercest troll in the Marsh, but she only respects mighty hunters. \n\nI tried to prove myself to her, but the one beast that could impress her is beyond my skill. Maybe you could help me out? It's the giant bog wasp known as Blacksting that roams the area south of the glowing draenei towers to the west. If you bring me its stinger maybe she'll give me a chance to join her hunters.\n\nI know it's a little sneaky, but I promise to learn under her and do ya both proud.", objectives = "Bring Blacksting's Stinger to Reavij at Swamprat Post.", progress = "My luck is about to change - I can feel it.", completion = "Fantastic! I'll never forget how you helped me to win her heart. In fact, you can be a guest of honor at our wedding." }
WordHunterWoW_QuestEN[9899] = { title = "A Job Undone", description = "Someone needs to find a way to make Reavij come to his senses! He's ignoring his duty and instead, he's devoting all his energy to getting my attention. I've tried ignoring him and telling him to stop. Nothing seems to work.\n\nUntil he gets over this, I'm left cleaning up after him. He was supposed to have dealt with Sporewing, but I'll bet the monster is alive and well. If you have time, would you mind going to the western part of the Dead Mire and killing the bat? I'll deal with Reavij in the meantime.", objectives = "Magasha at Swamprat Post wants you to kill Sporewing.", completion = "At least someone is pulling his weight around here. Thank you for taking care of that matter, <name>. I need to have a word with Zurai about Reavij. His scheming and daydreaming have gone on long enough." }
WordHunterWoW_QuestEN[9900] = { title = "Gava'xi", description = "The presence of rogue ethereals in this area might amuse Gezhe, who sees nothing but opportunity wherever we go, but it's a true threat to the security of our operations.\n\nTheir leader, Gava'xi, is a dangerous criminal and I've made it my top priority to see to it that he is neutralized.\n\nIf you're looking to make yourself useful, go and take care of Gava'xi.  I will see to it that you're rewarded properly.", objectives = "Slay Gava'xi near Oshu'gun and return to Zerid at Aeris Landing in Nagrand.", completion = "We won't have to worry about Gava'xi anymore, thanks to you.  Let us arrange for your reward now." }
WordHunterWoW_QuestEN[9901] = { title = "Unfinished Business", description = "The first expedition the league sent reported encountering a gigantic spore bat they'd taken to calling Sporewing. They had to leave in a hurry, so they didn't have the chance to kill him while they were here, so I figured I'd finish the job for them.\n\nWhat's left of their report suggests that the creature can be found in the southwestern parts of the Dead Mire. I think Vindicator Idaar mentioned that it's to the northeast of Telredor.", objectives = "Prospector Conall at Telredor wants you to kill Sporewing.", completion = "Well done, <name>. I think you and I have managed to outshine a whole team of prospectors. When I get back to Ironforge, I'm sure I'll get my choice of assignments." }
WordHunterWoW_QuestEN[9902] = { title = "The Terror of Marshlight Lake", description = "Traveling through naga-infested lands has shown me the cruel truth about how my less fortunate brethren are treated. At Marshlight Lake, to the southwest, I observed a particularly malicious taskmaster playing a deadly game. He orders his slaves out to the islands in Marshlight Lake when he knows that Terrorclaw, a giant bogstrok, is ready to feed.\n\nI needn't describe what results. We are too few to take on the naga directly, but we can deprive them of their amusement by killing their pet.", objectives = "Slay Terrorclaw and return to Puluu at the Orebor Harborage.", completion = "Thank you, <name>. Perhaps with the help of the draenei, this marsh will one day be free of naga. I can't imagine what it must be like to be forced to serve them.\n\nHe doesn't talk about it often, but Maktu was once a slave." }
WordHunterWoW_QuestEN[9903] = { title = "The Biggest of Them All", description = "You've dealt with most of the little hydra, but I doubt Mragesh was impressed by your display. He's a cunning, ferocious beast and he's dogged many an angler in his time.\n\nI intend to be the last one he'll ever bother. He's bound to be hiding deep in the waters of Serpent Lake, to the northeast. He's a has-been; he just doesn't know it yet.", objectives = "Slay Mragesh and return to Zurjaya in Zabra'jin.", completion = "I'm sure the old boy must've seen his days coming to an end. With all these new arrivals, the old order couldn't stand. It's just as well his spirit is at rest now." }
WordHunterWoW_QuestEN[9904] = { title = "Pursuing Terrorclaw", description = "I've caught every kind of fish that lives in the marsh, but there's one that eludes me. Sure, I've caught eels and mudfin frenzies. But the last time I was out on one of the islands in Marshlight Lake, I hooked a gigantic bogstrok that snapped my line and got away.\n\nTerrorclaw, he's called, and I won't rest until he's dead. He's too big for any fisherman to catch, so I suppose we'll just have to kill him the old-fashioned way.", objectives = "Kill Terrorclaw and return to Zurjaya at Zabra'jin.", completion = "At last! They say every great fisherman has a story of \"the one that got away,\" but I haven't yet met a creature I couldn't beat one way or another." }
WordHunterWoW_QuestEN[9905] = { title = "Maktu's Revenge", description = "Last time Maktu was out hunting hydras for hides at Serpent Lake, he was attacked by the biggest hydra he's ever seen. Maktu reached for his spear, but it was too late. He had just enough time to escape becoming hydra food.\n\nWho knows? Maybe next time, Maktu not be so lucky. Maktu wants to be there so there won't be a next time. Will you help Maktu get his revenge on Mragesh?", objectives = "Locate and kill Mragesh, then return to Maktu at the Orebor Harborage.", completion = "<Maktu nods approvingly.>\n\nMaktu is thankful for your help. Maktu's pride is satisfied. He will not be caught off guard again." }
